window.__D("text/zohar-hebrew-translation/c014",{"p":[[9522011609,"<p>וַיָּסַר אֵת אֹפַן מַרְכְּבתָיו. רַבִּי שִׁמְעוֹן פָּתַח, (יחזקאל א) וָאֵרֶא הַחַיּוֹת וְהִנֵּה אוֹפַן אֶחָד בָּאָרֶץ אֵצֶל הַחַיּוֹת. פָּסוּק זֶה פֵּרְשׁוּהוּ וְנִתְבָּאֵר, אֲבָל בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא בַּכֹּל מַרְאֶה אֶת שִׁלְטוֹנוֹ, וְשִׁלְטוֹנוֹ זֶה לֹא יַעֲבֹר לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים.</p>\n<p>וְעָשָׂה שִׁלְטוֹן בָּאָבוֹת. נָטַל אֶת אַבְרָהָם וְהֶעֱמִיד בּוֹ אֶת הָעוֹלָם, שֶׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, וּפֵרְשׁוּהָ. נָטַל אֶת יִצְחָק וְשָׁתַל בּוֹ אֶת הָעוֹלָם, שֶׁהוּא קַיָּם לְעוֹלָמִים. זֶהוּ שֶׁכָּתוּב וְאֶת בְּרִיתִי אָקִים אֶת יִצְחָק. נָטַל אֶת יַעֲקֹב, וְהוֹשִׁיבוֹ לְפָנָיו וְהִשְׁתַּעֲשַׁע עִמּוֹ, וְהִתְפָּאֵר בּוֹ. זֶהוּ שֶׁכָּתוּב (ישעיה מט) יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר.</p>\n<p>וּבֹא רְאֵה, יַעֲקֹב אָחַז בְּעֵץ הַחַיִּים שֶׁאֵין בּוֹ מָוֶת לְעוֹלָמִים, שֶׁכָּל הַחַיִּים נִתְקְנוּ בְּאוֹתוֹ הָעֵץ, וְנוֹתֵן חַיִּים לְכָל אוֹתָם שֶׁאֲחוּזִים בּוֹ, וְלָכֵן יַעֲקֹב לֹא מֵת. וּמָתַי מֵת? בְּשָׁעָה שֶׁכָּתוּב (בראשית מט) וַיֶּאֱסֹף רַגְלָיו אֶל הַמִּטָּה. הַמִּטָּה, כְּמוֹ שֶׁנֶּאֱמַר (שיר ג) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה, מִשּׁוּם שֶׁבְּמִטָּה זוֹ כָּתוּב רַגְלֶיהָ יֹרְדוֹת מָוֶת, וְלָכֵן כָּתוּב וַיֶּאֱסֹף רַגְלָיו אֶל הַמִּטָּה, וְאָז וַיִּגְוַע וַיֵּאָסֶף אֶל עַמָּיו. וְעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יַעֲקֹב לִבְחִיר הָאָבוֹת, זֶהוּ שֶׁכָּתוּב (ישעיה מא) יַעֲקֹב אֲשֶׁר בְּחַרְתִּיךְ.</p>\n<p>בֹּא רְאֵה, כָּל הַמַּחֲנוֹת שֶׁלְּמַעְלָה וְכָל אוֹתָן הַמֶּרְכָּבוֹת, כֻּלָּם אֲחוּזִים אֵלֶּה בְּאֵלֶּה, דְּרָגוֹת בִּדְרָגוֹת. אֵלֶּה עֶלְיוֹנִים וְאֵלֶּה תַחְתּוֹנִים, וְחַיּוֹת ל ל הַקֹּדֶשׁ עֲלֵיהֶם, וְכָל הָאוּכְלוּסִים וְהַמַּחֲנוֹת, כֻּלָּם נוֹסְעִים תַּחַת יָדֶיהָ. עַל מַאֲמָרָהּ נוֹסְעִים וְעַל מַאֲמָרָהּ חוֹנִים.</p>\n<p>וְזוֹהִי הַחַיָּה (העליונה הקדושה) שֶׁכָּל שְׁאָר הַחַיּוֹת אֲחוּזוֹת בָּהּ, וְהִשְׁתַּלְשְׁלוּ (ונתקנו) בִּשְׁבִילָהּ כַּמָּה חַיּוֹת לְחַיּוֹת (אלו יורדות ואלו יורדות). וְנֶאֱחָזוֹת דְּרָגוֹת בִּדְרָגוֹת, וְכָל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים הוֹלְכִים וְשָׁטִים בַּיָּם. זֶהוּ שֶׁכָּתוּב (תהלים קד) זֶה הַיָּם גָּדוֹל וּרְחַב יָדַיִם שָׁם רֵמֶשׂ וְאֵין מִסְפָּר וְגוֹ'.</p>\n<p>וּכְשֶׁמַּעָֹלֶה הַיָּם אֶת גַּלָּיו, כָּל הָאֳנִיּוֹת עוֹלוֹת וְיוֹרְדוֹת, וְנִמְצָא זַעַף, וְרוּחַ קָשָׁה הוֹלֶכֶת עָלָיו בְּחֹזֶק, וּדְגֵי הַיָּם מִתְפַּזְּרִים לְכָל צַד, אֵלֶּה לַמִּזְרָח וְאֵלֶּה לַמַּעֲרָב, אֵלֶּה לַצָּפוֹן וְאֵלֶּה לַדָּרוֹם. וְכָל אוֹתָם בְּנֵי הָעוֹלָם שֶׁרוֹאִים אֶת הָרֹשֶׁם עֲלֵיהֶם, לוֹקְחִים אוֹתָם וּבוֹלְעִים אוֹתָם בִּמְעָרוֹת הֶעָפָר.</p>\n<p>וְכָל הָאֳנִיּוֹת לֹא נוֹסְעוֹת מִמְּקוֹמָם, וְלֹא עוֹלוֹת וְיוֹרְדוֹת, פְּרָט לְאוֹתָהּ שָׁעָה שֶׁבָּא מַנְהִיג אֶחָד שֶׁל הַיָּם וְיוֹצֵא לְהַשְׁלִים רוּחַ שֶׁל זַעַף הַיָּם. כֵּיוָן שֶׁזֶּה עוֹלֶה עַל הַיָּם, שׁוֹכֵךְ מֵרָגְזוֹ, וְנִמְצֵאת מְנוּחָה. וְאָז כָּל הָאֳנִיּוֹת הוֹלְכוֹת בְּדֶרֶךְ יָשָׁר, וְלֹא סוֹטוֹת לְיָמִין וְלִשְׂמֹאל. זֶהוּ שֶׁכָּתוּב שָׁם אֳנִיּוֹת יְהַלֵּכוּן לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ. זֶה דַּוְקָא. וְכָל דְּגֵי הַיָּם מִתְכַּנְּסִים לִמְקוֹמָם, וְכָל אוֹתָן הַחַיּוֹת שְׂמֵחוֹת עָלֶיהָ, וְחַיּוֹת הַשָּׂדֶה הָעֶלְיוֹנוֹת שְׂמֵחוֹת. זֶהוּ שֶׁכָּתוּב (איוב מ) וְכָל חַיַּת הַשָּׂדֶה יְשַׂחֲקוּ שָׁם.</p>\n<p>בֹּא רְאֵה, כְּמוֹ שֶׁלְּמַעְלָה יֵשׁ לְמַטָּה, כְּמוֹ שֶׁלְּמַטָּה יֵשׁ בַּיָּם. כְּמוֹ שֶׁלְּמַעְלָה יֵשׁ לְמַעְלָה בַּיָּם הָעֶלְיוֹן. כְּגוֹן שֶׁלְּמַעְלָה יֵשׁ לְמַטָּה. כְּגוֹן שֶׁלְּמַטָּה יֵשׁ בַּיָּם הַתַּחְתּוֹן.</p>\n<p>הַגּוּף שֶׁל אוֹתוֹ הַיָּם, הֲרֵי הִתְעוֹרַרְנוּ לַחֲבֵרֵינוּ, אֹרֶךְ וָרֹחַב, רֹאשׁ וּזְרוֹעוֹת וְשַּׂעֲרוֹת הַגּוּף, הַכֹּל כְּמוֹ שֶׁצָּרִיךְ, וְהַכֹּל נִקְרָא בִשְׁמוֹ. וּכְמוֹ זֶה לְמַטָּה לַיָּם שֶׁלְּמַטָּה, כָּךְ גַּם הָרֹאשׁ שֶׁל הַיָּם וּזְרוֹעוֹת הַיָּם וְגוּף הַיָּם.</p>\n<p>כָּתוּב (בראשית מט) זְבוּלֻן לְחוֹף יַמִּים יִשְׁכֹּן. וַהֲרֵי יָם אֶחָד הָיָה בְּגוֹרָלוֹ, אֶלָּא מַה זֶּה לְחוֹף יַמִּים? וַדַּאי שֶׁבֵּאֲרוּהָ הַחֲבֵרִים בְּסוֹד עֶלְיוֹן. וְיַרְכָתוֹ עַל צִידן, כַּנֶּאֱמַר (שמות א) יצְאֵי יֶרֶךְ יַעֲקֹב. זְבוּלוּן הָיָה שׁוֹק הַיָּמִין שֶׁל הַגּוּף, וְיָם כִּנֶּרֶת הָיָה בְּגוֹרָלוֹ, וּמִכָּאן נִמְצָא הַחִלָּזוֹן שֶׁל הַתְּכֵלֶת.</p>\n<p>בֹּא רְאֵה, כַּמָּה מֶרְכָּבוֹת עַל מֶרְכָּבוֹת נִמְצְאוּ, וְגַלְגַּלֵּי הַמֶּרְכָּבָה רָצִים בְּחִפָּזוֹן, וְלֹא מִתְעַכְּבִים אוֹתָם תּוֹמְכֵי הַמֶּרְכָּבָה לִנְסֹעַ עֲלֵיהֶם, וְכֵן כֻּלָּם (וכאן וינהגהו בכבדת, בחפזון). בֹּא רְאֵה, הַמֶּרְכָּבָה הַמְמֻנָּה עַל הַמִּצְרִים, (אם תאמר) פֵּרְשׁוּהָ, לֹא נִמְצֵאת מֶרְכָּבָה שְׁלֵמָה, שֶׁהֲרֵי כָּתוּב וַיָּסַר אֶת אֹפַן מַרְכְּבֹתָיו. כַּמָּה מֶרְכָּבוֹת הָיוּ שֶׁהָיוּ נוֹסְעִים עַל תּוֹמֵךְ גַּלְגַּל אֶחָד, שֶׁנִּפְקְדוּ עֲלֵיהֶם. כֵּיוָן שֶׁזֶּה הָעֳבַר מִשִּׁלְטוֹנוֹ, כָּל הַמֶּרְכָּבוֹת הָעָבְרוּ מִשִּׁלְטוֹנָם וְלֹא נָסְעוּ. אָז כֻּלָּם לְמַטָּה הָעָבְרוּ מִשִּׁלְטוֹנָם, שֶׁכָּתוּב עַל מִצְרַיִם (ירמיה מו) וְעַל פַּרְעֹה וְעַל הַבּטְחִים בּוֹ.</p>\n<p>וּבְאוֹתוֹ זְמַן הַשַּׁלִּיט שֶׁל מִצְרַיִם שָׁלַט עַל כָּל שְׁאָר הָעַמִּים. כֵּיוָן שֶׁהָעֳבַר כֹּחַ מִצְרַיִם, נִשְׁבַּר כֹּחַ שְׁאָר הָעַמִּים. מִנַּיִן לָנוּ? שֶׁכָּתוּב אָז נִבְהֲלוּ אַלּוּפֵי אֱדוֹם וְגוֹ', וְכָתוּב שָׁמְעוּ עַמִּים יִרְגָּזוּן וְגוֹ'. מִשּׁוּם שֶׁכֻּלָּם הָיוּ אֲחוּזִים בַּפֻּלְחָן שֶׁל הַמִּצְרִים, וַאֲחוּזִים בְּמִצְרַיִם לַסִּיּוּעַ שֶׁלָּהֶם. וּבְאוֹתוֹ זְמַן כֻּלָּם בִּקְשׁוּ אֶת הַסִּיּוּעַ שֶׁל מִצְרַיִם לְהִתְחַזֵּק. וְעַל זֶה, כֵּיוָן שֶׁשָּׁמְעוּ אֶת הַגְּבוּרוֹת שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם, רָפוּ יְדֵיהֶם וְלֹא יָכְלוּ לַעֲמֹד, וְכֻלָּם הִזְדַּעְזְעוּ וְנִשְׁבְּרוּ מִשִּׁלְטוֹנָם.</p>\n<p>וַדַּאי שֶׁכְּשֶׁנִּשְׁבַּר כֹּחָם לְמַעְלָה, שֶׁנִּשְׁבַּר כֹּחַ שֶׁל כָּל אוֹתָם שֶׁאֲחוּזִים בּוֹ. כֵּיוָן שֶׁנִּשְׁבַּר הַכֹּחַ שֶׁל כֻּלָּם לְמַעְלָה, כָּל אֵלֶּה שֶׁלְּמַטָּה נִשְׁבְּרוּ מִשּׁוּם (אותו) הַכֹּחַ הַזֶּה שֶׁנִּשְׁבַּר בַּתְּחִלָּה, וּמִשּׁוּם כָּךְ וַיָּסַר אֵת אֹפַן מַרְכְּבתָיו כָּתוּב. וַיְנַהֲגֵגוּ בִּכְבֵדוּת, שֶׁהֲרֵי כְּשֶׁזֶּה נִשְׁבַּר, לֹא הָיוּ הוֹלְכִים.</p>\n<p>בֹּא וּרְאֶה שֶׁכָּךְ הוּא, שֶׁלֹּא כָתוּב וַיָּסַר אֵת אוֹפַנֵּי מַרְכְּבוֹתָיו, אוֹ אוֹפַן מֶרְכַּבְתּוֹ, אֶלָּא וַיָּסַר אֵת אֹפַן מַרְכְּבתָיו, מִשּׁוּם שֶׁכֹּחַ זֶה שֶׁכֻּלָּם הָיוּ נִדְבָּקִים בּוֹ.</p>\n<p>וְעוֹד וַיָּסַר אֵת אֹפַן מַרְכְּבתָיו - בֹּא רְאֵה, אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם לְהִדָּבֵק בָּהֶם וְלִהְיוֹת לָהֶם חֵלֶק, וְשֶׁהֵם יִהְיוּ בְחֶלְקוֹ. זֶהוּ שֶׁכָּתוּב (דברים יג) וּבוֹ תִדְבָּקוּן. וְכָתוּב (שם ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם. בַּה' מַמָּשׁ. וְכָתוּב (תהלים קלה) כִּי יַעֲקֹב בָּחַר לוֹ יָהּ. וְכָתוּב כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ. שֶׁהוֹצִיא אוֹתָם מִזֶּרַע קָדוֹשׁ לִהְיוֹת חֶלְקוֹ, וְעַל זֶה נָתַן לָהֶם תּוֹרָה קְדוֹשָׁה עֶלְיוֹנָה גְּנוּזָה אַלְפַּיִם שָׁנִים עַד שֶׁלֹּא נִבְרָא הָעוֹלָם, וַהֲרֵי זֶה נֶאֱמַר. וּמִשּׁוּם אַהֲבָתוֹ נָתַן אוֹתָהּ לְיִשְׂרָאֵל לָלֶכֶת אַחֲרֶיהָ וְלִדְבּק בָּהּ.</p>\n<p>בֹּא רְאֵה, כָּל הַמַּחֲנוֹת הָעֶלְיוֹנִים, וְכָל אוֹתָן מֶרְכָּבוֹת, כֻּלָּם אֲחוּזִים אֵלֶּה בְּאֵלֶּה, דְּרָגוֹת בִּדְרָגוֹת. אֵלּוּ עֶלְיוֹנִים, וְאֵלּוּ תַחְתּוֹנִים, וַהֲרֵי פֵּרְשׁוּהָ, שֶׁכָּתוּב (תהלים קד) זֶה הַיָּם גָּדוֹל. וְחַיָּה קְדוֹשָׁה עָלָיו, וְכָל הָאוּכְלוּסִים וְהַמַּחֲנוֹת, כֻּלָּם נוֹסְעִים תַּחַת יָדֶיה. עַל מַאֲמָרָהּ נוֹסְעִים וְעַל מַאֲמָרָהּ חוֹנִים. בִּזְמַן שֶׁהִיא נוֹסַעַת, כֻּלָּם נוֹסְעִים, מִשּׁוּם שֶׁכֻּלָּם אֲחוּזִים בָּהּ.</p>\n<p>וּבֹא רְאֵה, בְּשָׁעָה שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִיר אֶת אוּכְלוּסֵי פַרְעֹה לְמַטָּה, הֶעֱבִיר בַּתְּחִלָּה אֶת אוֹתוֹ כֹּחַ שֶׁלָּהֶם כְּמוֹ שֶׁהֵקַמְנוּ. מֶה עָשָׂה? הֶעֱבִיר וְסִלֵּק אוֹתוֹ מָקוֹם קָדוֹשׁ עֶלְיוֹן שֶׁהָיָה מַנְהִיג אֶת כָּל אוֹתָן הַמֶּרְכָּבוֹת. כֵּיוָן שֶׁזֶּה הִסְתַּלֵּק, כָּל הַמַּחֲנוֹת הַלָּלוּ לֹא יָכְלוּ לְהִתְנַהֵג. וְכֵיוָן שֶׁלֹּא יָכְלוּ, הָעֳבַר מִשִּׁלְטוֹנוֹ אוֹתוֹ הַמְמֻנֶּה שֶׁל מִצְרַיִם וְהָעֳבַר בְּאֵשׁ דּוֹלֶקֶת, וְאָז הַשַּׁלִּיט שֶׁל הַמִּצְרִים הוּזַז, וְעַל זֶה אָנוּסָה מִפְּנֵי יִשְׂרָאֵל. מָה הַטַּעַם? מִשּׁוּם שֶׁרָאוּ אֶת הַמְמֻנֶּה שֶׁל מִצְרַיִם נִשְׂרָף בָּאֵשׁ.</p>\n<p>רַבִּי יִצְחָק אָמַר, בְּשָׁעָה שֶׁקָּרְבוּ יִשְׂרָאֵל לַיָּם, קָרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לַמְמֻנֶּה הַגָּדוֹל שֶׁעַל הַיָּם וְאָמַר לוֹ: בְּשָׁעָה שֶׁעָשִׂיתִי אֶת הָעוֹלָם, מִנִּיתִי אוֹתְךְ עַל הַיָּם, וּתְנַאי יֵשׁ לִי עַל הַיָּם - שֶׁיִּקְרַע אֶת מֵימָיו מִלִּפְנֵי בָנַי, הִגִּיעַ הַזְּמַן עַכְשָׁו שֶׁיַּעַבְרוּ בָנַי בְּתוֹךְ הַיָּם. מַה כָּתוּב אַחַר כָּךְ? וַיָּשָׁב הַיָּם לִפְנוֹת בֹּקֶר לְאֵיתָנוֹ. מַה זֶּה לְאֵיתָנוֹ? לִתְנָאוֹ שֶׁהָיָה לוֹ עִם הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁבָּרָא אֶת הָעוֹלָם.</p>\n<p>וְהָיוּ יִשְׂרָאֵל חוֹנִים עַל הַיָּם, וְהָיוּ יִשְׂרָאֵל רוֹאִים אֶת גַּלֵּי הַיָּם עוֹלִים וְיוֹרְדִים. הֵרִימוּ עֵינֵיהֶם, וְרָאוּ אֶת פַּרְעֹה וְהָאוּכְלוּסִים שֶׁלּוֹ, וּפָחֲדוּ וְצָעֲקוּ, וַהֲרֵי נִתְבָּאֵר. הַיָּם רָאָה - מָה רָאָה הַיָּם? הוּא רָאָה אֶת אֲרוֹנוֹ שֶׁל יוֹסֵף, וּבָרַח מִלְּפָנָיו. מָה הַטַּעַם? (משום) שֶׁכָּתוּב (בראשית לט) וַיָּנָס וַיֵּצֵא הַחוּצָה, וְעַל זֶה הַיָּם רָאָה וַיָּנָס, וְכָתוּב וַיָּסַר אֵת אֹפַן מַרְכְּבֹתָיו וְגוֹ' אָנוּסָה מִפְּנֵי יִשְׂרָאֵל. מָה הַטַּעַם? מִשּׁוּם שֶׁרָאוּ אֶת אֶרֶץ מִצְרַיִם כְּאִלּוּ עוֹלָה בָּאֵשׁ, וְאָז אָמְרוּ אָנוּסָה מִפְּנֵי יִשְׂרָאֵל.</p>\n<p>רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּמִּדְבָּר. אָמַר רַבִּי חִיָּיא לְרַבִּי יוֹסֵי, בּא וְאֹמַר לְךְ, שֶׁכְּשֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִיר שִׁלְטוֹן שֶׁל הָאָרֶץ, אֵינוֹ עוֹשֶׂה עַד שֶׁמַּעֲבִיר הַשַּׁלִּיט שֶׁלָּהֶם בָּרָקִיעַ, וְלֹא מַעֲבִיר אֶת הַשַּׁלִּיט שֶׁלָּהֶם עַד שֶׁמְּמַנֶּה אַחֵר בִּמְקוֹמוֹ, כְּדֵי שֶׁלֹּא יִגָּרַע (השלטון) הַשִּׁמּוּשׁ שֶׁלָּהֶם בָּרָקִיעַ, כְּדֵי לְקַיֵּם מַה שֶּׁכָּתוּב (דניאל ד) וּלְמִי שֶׁיַּחְפֹּץ יִתְּנֶנָּה. אָמַר רַבִּי יוֹסֵי, וַדַּאי כָּךְ הוּא.</p>\n<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, (תהלים ח) ה' אֲדנֵינוּ מָה אַדִּיר שִׁמְךְ בְּכָל הָאָרֶץ. ה' אֲדנֵינוּ - כְּשֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁבֹּר אֶת כֹּחַ הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, מְחַזֵּק דִּינוֹ עֲלֵיהֶם וְשׁוֹבֵר אוֹתָם, וּמַעֲבִיר מִלְּפָנָיו אֶת הַשַּׁלִּיט שֶׁלָּהֶם.</p>\n<p>אַשֶׁר תְּנָה הוֹדְךְ עַל הַשָּׁמָיִם, אֲשֶׁר נָתַתָּ הָיָה צָרִיךְ, אוֹ תְּנָה הוֹדְךְ. מַהוּ אֲשֶׁר תְּנָה הוֹדְךְ? אֶלָּא זֶהוּ סוֹד שֶׁל הַנָּהָר הֶעָמֹק שֶׁל הַכֹּל, וְדָוִד בִּקֵּשׁ בַּקָּשָׁתוֹ לְהַשְׁפִּיעַ מִמֶּנּוּ עַל הַשָּׁמַיִם, וְזֶהוּ אֲשֶׁר, כַּנֶּאֱמַר (שמות ג) אֶהְיֶה אֲשֶׁר אֶהְיֶה.</p>\n<p>בְּשָׁעָה שֶׁהַנָּהָר הַזֶּה הֶעָמֹק שֶׁל הַכֹּל שׁוֹפֵעַ וְיוֹצֵא עַל הַשָּׁמַיִם, אָז הַכֹּל בְּשִׂמְחָה, וְהַגְּבִירָה מִתְעַטֶּרֶת בַּמֶּלֶךְ, וְכָל הָעוֹלָמוֹת בְּשִׂמְחָה. וְהַשִּׁלְטוֹן שֶׁל הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת מָעֳבָר מִלִּפְנֵי הַגְּבִירָה, וְאָז זוֹקְפִים רֹאשׁ כָּל הָאֲחוּזִים בָּהּ.</p>\n<p>בֵּין כָּךְ רָאוּ אִישׁ אֶחָד שֶׁהָיָה בָּא, וּמַשָּׂא אֶחָד לְפָנָיו. אָמַר רַבִּי חִיָּיא, נֵלֵךְ, אוּלַי הָאִישׁ הַזֶּה עוֹבֵד עֲבוֹדַת כוֹכָבִים וּמַזָּלוֹת הוּא, אוֹ עַם הָאָרֶץ הוּא, וְאָסוּר לְהִשְׁתַּתֵּף עִמּוֹ בַּדֶּרֶךְ. אָמַר רַבִּי יוֹסֵי, נֵשֵׁב כָּאן וְנִרְאֶה, אוּלַי הוּא אִישׁ גָּדוֹל.</p>\n<p>בֵּין כָּךְ עָבַר לִפְנֵיהֶם, וְאָמַר לָהֶם, בַּסִּבּוּב שֶׁל הַמַּעֲבָר הַמְסֻכָּן הַזֶּה צָרִיךְ לִוּוּי, וַאֲנִי יוֹדֵעַ דֶּרֶךְ אַחֶרֶת, וְנִסְטֶה מִכָּאן, וַאֲנִי רָצִיתִי לוֹמַר לָכֶם, שֶׁלֹּא אֶחֱטָא בָכֶם וְלֹא אֶעֱבר עַל מַה שֶּׁכָּתוּב (ויקרא יט) וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשׁוֹל, וְאַתֶּם כְּמוֹ סוּמִים בַּדֶּרֶךְ הַזּוֹ, וְלֹא תִסְתַּכְּנוּ בְנַפְשְׁכֶם. אָמַר רַבִּי יוֹסֵי, בָּרוּךְ הָרַחֲמָן שֶׁחִכִּינוּ כָּאן. הִתְחַבְּרוּ עִמּוֹ. אָמַר לָהֶם, לֹא לְדַבֵּר שׁוּם דָּבָר כָּאן עַד שֶׁנַּעֲבֹר בָּזֶה. סָטוּ לְדֶרֶךְ אַחֶרֶת.</p>\n<p>אַחַר שֶׁיָּצְאוּ מֵאוֹתוֹ מָקוֹם, אָמַר לָהֶם, בְּאוֹתָהּ הַדֶּרֶךְ הָאַחֶרֶת הָיוּ הוֹלְכִים פַּעַם אֶחָד כֹּהֵן חָכָם, וְכֹהֵן עַם הָאָרֶץ אֶחָד עִמּוֹ. קָם אוֹתוֹ עַם הָאָרֶץ עָלָיו בְּאוֹתוֹ מָקוֹם וַהֲרָגוֹ. מֵאוֹתוֹ יוֹם, כָּל מִי שֶׁעוֹבֵר בְּאוֹתוֹ מָקוֹם, מְסַכֵּן אֶת נַפְשׁוֹ, וַהֲרֵי מִתְחַבְּרִים שָׁם שׁוֹדְדֵי הָרִים וְהוֹרְגִים וּמְקַפְּחִים אֶת בְּנֵי הָאָדָם, וְאֵלֶּה שֶׁיּוֹדְעִים לֹא עוֹבְרִים שָׁם, וּמְבַקֵּשׁ הַקָּדוֹשׁ בָּרוּךְ הוּא דַּם אוֹתוֹ הַכֹּהֵן בְּכָל יוֹם.</p>\n<p>פָּתַח (ישעיה י) וְאָמַר, עוֹד הַיּוֹם בְּנֹב לַעֲמֹד וְגוֹ'. הֲרֵי בֵּאֲרוּהָ אוֹתָם רָאשֵׁי הַיְשִׁיבָה, אֲבָל אֲנִי לֹא אוֹמֵר לָכֶם כָּךְ, אֶלָּא שֶׁסּוֹד הַדָּבָר לָמַדְנוּ. עוֹד הַיּוֹם - אֵיזֶה יוֹם זֶה? אֶלָּא כָּךְ כָּתוּב, (שמות ו) וַיִּקַּח אַהֲרֹן אֶת אֱלִישֶׁבַע בַּת עַמִּינָדָב. וְסוֹד הוּא עַל כְּנֶסֶת יִשְׂרָאֵל, שֶׁאַהֲרֹן הוּא שׁוֹשְׁבִינָהּ, לְתַקֵּן אֶת בֵּיתָהּ וּלְשַׁמֵּשׁ אוֹתָהּ וּלְהַכְנִיסָהּ לַמֶּלֶךְ לְהִזְדַּוֵּג כְּאֶחָד. מִכָּאן וָהָלְאָה, כָּל כֹּהֵן שֶׁמְּשַׁמֵּשׁ בַּמִּקְדָּשׁ, הוּא כְּמוֹ אַהֲרֹן.</p>\n<p>אֲחִימֶלֶךָ הָיָה כֹּהֵן גָּדוֹל עֶלְיוֹן, וְכָל אוֹתָם הַכֹּהֲנִים עִמּוֹ הָיוּ שׁוֹשְׁבִינֵי הַגְּבִירָה. כֵּיוָן שֶׁנֶּהֶרְגוּ, נִשְׁאֲרָה הַגְּבִירָה לְבַדָּהּ, וְאָבַד הַשּׁוֹשְׁבִין שֶׁלָּהּ, וְלֹא נִמְצָא מִי שֶׁמְּשַׁמֵּשׁ לְפָנֶיהָ וִיתַקֵּן בֵּיתָהּ וִישַׂמַּח אוֹתָהּ לְהִזְדַּוֵּג עִם הַמֶּלֶךְ. וְאָז מֵאוֹתוֹ יוֹם הִיא עָבְרָה לִשְׂמֹאל, וְעוֹמֶדֶת עַל הָעוֹלָם, אוֹרֶבֶת לַכֹּל. הָרְגָה אֶת שָׁאוּל וּבָנָיו, וְאִבְּדָה מֵהֶם אֶת הַמְּלוּכָה, מֵתוּ מִיִּשְׂרָאֵל כַּמָּה אֲלָפִים וְכַמָּה רְבָבוֹת. וְעַד עַכְשָׁו הָיָה אוֹתוֹ הַחֵטְא תָּלוּי, עַד שֶׁבָּא סַנְחֵרִיב וְהִרְגִּיז אֶת הַכֹּל.</p>\n<p>וְזְהִוּ עוֹד הַיּוֹם בְּנֹב, זֶהוּ יוֹם עֶלְיוֹן, וּמִיהוּ? זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁאִבְּדָה אֶת הַשּׁוֹשְׁבִינִים שֶׁלָּהּ, אוֹתָהּ שֶׁנִּשְׁאֲרָה לְלֹא יָמִין (שהיה לו) לְהִדָּבֵק בַּשְּׂמֹאל, שֶׁהַכֹּהֵן הוּא יָמִין, (ומשום כך היה לו להתדבק בשמאל) וּמִשּׁוּם כָּךְ עוֹד הַיּוֹם בְּנֹב לַעֲמֹד.</p>\n<p>בֹּא רְאֵה, כָּתוּב גִּבְעַת שָׁאוּל נָסָה. לָמָּה כָּאן שָׁאוּל? אֶלָּא מִשּׁוּם שֶׁהוּא הָרַג אֶת הַכֹּהֲנִים וְגָרַם שֶׁתֵּעָקֵר מִן הָעוֹלָם זְרוֹעַ יָמִין - אַף כָּאן מֵאוֹתוֹ יוֹם לֹא עָבַר אִישׁ בְּאוֹתוֹ מָקוֹם, כְּדֵי שֶׁלֹּא יִסְתַּכֵּן בְּנַפְשׁוֹ. אָמַר לוֹ רַבִּי יוֹסֵי לְרַבִּי חִיָּיא, וְלֹא אָמַרְתִּי לְךְ אוּלַי הוּא אִישׁ גָּדוֹל?</p>\n<p>פָּתַח וְאָמַר, (משלי ג) אַשְׁרֵי אָדָם מָצָא חָכְמָה. אַשְׁרֵי אָדָם - כְּמוֹ אָנוּ שֶׁמָּצָאנוּ אוֹתְךְ וְיָדַעְנוּ מִמְּךְ דְּבַר חָכְמָה. וְאָדָם יָפִיק תְּבוּנָה - כְּמוֹ אָנוּ שֶׁחִכִּינוּ לְךְ לְהִתְחַבֵּר עִמְּךְ, וְזֶהוּ אָדָם שֶׁמְּזַמֵּן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מַתָּנָה בַּדֶּרֶךְ, פְּנֵי הַשְּׁכִינָה, וְעַל זֶה כָּתוּב (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ. הָלְכוּ.</p>\n<p>פָּתַח אוֹתוֹ הָאִישׁ וְאָמַר, (תהלים כב) לְדָוִד מִזְמוֹר לַה' הָאָרֶץ וּמְלֹאָהּ וְגוֹ'. לְדָוִד מִזְמוֹר בְּמָקוֹם אֶחָד, וּבְמָקוֹם אַחֵר מִזְמוֹר לְדָוִד. מַה בֵּין זֶה לָזֶה? אֶלָּא לְדָוִד מִזְמוֹר - הַשִּׁירָה שֶׁאָמַר דָּוִד עַל כְּנֶסֶת יִשְׂרָאֵל. מִזְמוֹר לְדָוִד - הַשִּׁירָה שֶׁדָּוִד אָמַר עַל עַצְמוֹ.</p>\n<p>לַה' הָאָרֶץ וּמְלֹאָהּ. לַה' - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. הָאָרֶץ וּמְלֹאָהּ - זוֹ כְּנֶסֶת יִשְׂרָאֵל וְכָל הָאוּכְלוּסִין שֶׁלָּהּ שֶׁמִּתְחַבְּרִים עִמָּהּ, וְנִקְרָאִים מְלֹאָהּ וַדַּאי הוּא, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ו) מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ. תֵּבֵל וְיֹשְׁבֵי בָהּ - זוֹהִי אֶרֶץ שֶׁל מַטָּה שֶׁנִּקְרֵאת תֵּבֵל, וַאֲחוּזָה בַּדִּין (של עולם) שֶׁל מַעְלָה. זֶהוּ שֶׁכָּתוּב (תהלים ט) וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק. בֵּין לְאֶחָד, בֵּין לְעַם אֶחָד, בֵּין לְכָל הָעוֹלָם - מֵהַדִּין הַזֶּה הוּא נִדּוֹן.</p>\n<p>בֹּא רְאֵה, פַּרְעֹה יָנַק מֵהַדִּין הַזֶּה עַד שֶׁאָבְדוּ הוּא וְכָל עַמּוֹ. כֵּיוָן שֶׁדִּין זֶה הִתְעוֹרֵר עָלָיו, אוֹתוֹ מְמֻנֶּה שֶׁהִתְמַנָּה עֲלֵיהֶם בַּשִּׁלְטוֹן, הוּזַז וְהָעֳבַר, וְאָז כָּל אֵלֶּה שֶׁלְּמַטָּה נֶאֶבְדוּ, שֶׁכָּתוּב וַיָּסַר אֵת אֹפַן מַרְכְּבתָיו. מַה זֶּה אֹפַן מַרְכְּבֹתָיו? מֶרְכְּבוֹתָיו שֶׁל פַּרְעֹה. וּמִי הוּא אוֹתוֹ אוֹפַן שֶׁלָּהֶם? אוֹתוֹ מְמֻנֶּה שֶׁשּׁוֹלֵט עֲלֵיהֶם, וְעַל זֶה מֵתוּ כֻלָּם בַּיָּם. לָמָּה בַּיָּם? אֶלָּא הַיָּם הָעֶלְיוֹן הִתְעוֹרֵר עֲלֵיהֶם וְנִמְחוּ (ונמסרו) בְּיָדֶיהָ, וְלָכֵן כָּתוּב טֻבְּעוּ בְּיַם סוּף. אָמַר רַבִּי יוֹסֵי, וַדַּאי כָּךְ הוּא! וְעַל זֶה כָּתוּב טֻבְּעוּ בְּיַם סוּף, סוֹף כָּל הַדְּרָגוֹת.</p>\n<p>רַבִּי חִיָּיא אָמַר, וַיְנַהֲגֵהוּ בִּכְבֵדֻת, מַה זֶּה בִּכְבֵדֻת? אֶלָּא מִכָּאן לָמַדְנוּ, שֶׁבְּדֶרֶךְ שֶׁאָדָם הוֹלֵךְ מוֹלִיכִים אוֹתוֹ. כָּתוּב בְּפַרְעֹה וַיִּכְבַּד לֵב פַּרְעֹה, וּבְאוֹתוֹ דָבָר הִנְהִיג אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בִּכְבֵדוּת מַמָּשׁ. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: רָשָׁע, אַתָּה מַכְבִּיד אֶת לִבְּךְ? אֲנִי אַנְהִיג אוֹתְךְ בָּזֶה. וְעַל כָּךְ וַיְנַהֲגֵהוּ בִּכְבֵדֻת.</p>\n<p>וַיֹּאמֶר מִצְרַיִם אָנוּסָה מִפְּנֵי יִשְׂרָאֵל וְגוֹ'. וַיֹּאמֶר מִצְרַיִם - זֶהוּ הַמְמֻנֶּה שֶׁהִתְמַנָּה עַל הַמִּצְרִים. אָמַר רַבִּי יוֹסֵי, דָּבָר זֶה קָשֶׁה, כֵּיוָן שֶׁהֶעֱבִירוּ אוֹתוֹ מִשִּׁלְטוֹנוֹ, אֵיךְ יָכֹל הוּא לִרְדֹּף אַחֲרֵי יִשְׂרָאֵל?</p>\n<p>אֶלָּא וַדַּאי הוּא כָּךְ! אֲבָל זֶה וַיֹּאמֶר מִצְרַיִם - מִצְרַיִם שֶׁלְּמַטָּה. כִּי ה' נִלְחָם לָהֶם בְּמִצְרָיִם - מִצְרַיִם שֶׁלְּמַעְלָה. שֶׁכֵּיוָן שֶׁנִּשְׁבָּר כֹּחָם מִלְמַעְלָה, אָז נִשְׁבָּר הַכֹּחַ וְהַתֹּקֶף שֶׁלָּהֶם לְמַטָּה. זֶהוּ שֶׁכָּתוּב כִּי ה' נִלְחָם לָהֶם בְּמִצְרָיִם. בְּמִצְרַיִם דַּוְקָא. זֶהוּ הַתֹּקֶף שֶׁלָּהֶם שֶׁלְּמַעְלָה. וְזֶהוּ שֶׁבֵּאֲרוּהָ מֶלֶךְ מִצְרַיִם סְתָם. כָּאן וַיֹּאמֶר מִצְרַיִם אָנוּסָה מִפְּנֵי יִשְׂרָאֵל, שֶׁרָאוּ שֶׁהֲרֵי נִשְׁבַּר כֹּחָם וְהַתֹּקֶף שֶׁלָּהֶם שֶׁלְּמַעְלָה.</p>\n<p>בֹּא רְאֵה, כְּשֶׁמִּתְעוֹרֶרֶת כְּנֶסֶת יִשְׂרָאֵל הַזּוֹ, מִתְעוֹרְרִים כָּל אוֹתָם שֶׁאֲחוּזִים בָּהּ, וְכָל הָאֲחֵרִים שֶׁלְּמַטָּה, וְיִשְׂרָאֵל מֵעַל כֻּלָּם, שֶׁהֲרֵי הֵם נוֹטְלִים אוֹתָהּ בְּגוּף הָאִילָן, וַהֲרֵי פֵּרְשׁוּהָ. וְלָכֵן יִשְׂרָאֵל אֲחוּזִים בָּהּ יוֹתֵר מִכָּל עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת. וּכְשֶׁהֵם מִתְעוֹרְרִים, (כל עמים עכו\"ם) נִשְׁבָּר תָּקְפָּם מֵאוֹתָם שֶׁשּׁוֹלְטִים עֲלֵיהֶם.</p>\n<p>בֹּא רְאֵה, הַמְמֻנֶּה הַזֶּה הַשַּׁלִּיט עַל הַמִּצְרִים, דָּחַק אֶת יִשְׂרָאֵל בְּכַמָּה שִׁעְבּוּדִים, כְּמוֹ שֶׁבֵּאֲרוּהָ. אַחַר שֶׁהוּא נִשְׁבַּר בַּתְּחִלָּה, נִשְׁבְּרוּ אוֹתָן מַלְכֻיּוֹת (מלמטה). זֶהוּ שֶׁכָּתוּב כִּי ה' נִלְחָם לָהֶם בְּמִצְרָיִם. נִלְחָם לָהֶם וַדַּאי.</p>"],[9522011610,"<p>וַיִּסַּע מַלְאַךְ הָאֱלֹהִים וְגוֹ'. (משנה) טֶרֶם (שנשקע) שֶׁנִּמְצָא אֲוִיר טָהוֹר, וְלֹא מְאִירִים, הָאֲבָנִים הַנְּקוּבוֹת הָיוּ סְתוּמוֹת. שָׁלֹשׁ רוּחוֹת שֶׁכְּלוּלוֹת בְּשָׁלֹשׁ הָיוּ שְׁקוּעוֹת, וּמַיִם סְתוּמִים תַּחַת הַנְּקָבִים בְּשִׁבְעִים וּשְׁתַּיִם אוֹתִיּוֹת חָזְרוּ לִמְקוֹמָם אוֹתָם אֲבָנִים (דורות).</p>\n<p>אַחַר שִׁבְעִים וּשְׁתַּיִם דְּרָגוֹת, וְכֵן שָׁלֹשׁ פְּעָמִים, הִתְבַּקְּעוּ וְנִנְקְבוּ הָאֲבָנִים תַּחַת צְרוֹר שֶׁהָיָה חָקוּק, וְהִתְכַּנְּסוּ הַדְּרָגוֹת וְנַעֲשׂוּ כִנּוּס אֶחָד. (נחלק ונעשו כגוס אחד).</p>\n<p>אַחַר כָּךְ הִתְחַלְּקוּ וְנַעֲשׂוּ שְׁתֵּי דְרָגוֹת, חֲצִי מַיִם קָפְאוּ, וַחֲצִי שָׁקְעוּ. אֵלֶּה עָלוּ וְאֵלֶּה יָרְדוּ. מִכָּאן הִתְחִיל הָעוֹלָם לְהִתְחַלֵּק.</p>\n<p>צְרוֹר אַחֵר (אחד) יֵשׁ לְמַעְלָה (למעלה), וְהוּא חָקוּק בְּשִׁבְעִים וּשְׁתַּיִם חוֹתָמוֹת שֶׁל חוֹתֶמֶת תַּקִּיפָה, וּבָהֶם שְׁקוּעִים גַּלֵּי הַיָּם. כְּשֶׁנּוֹסְעִים, נֶחֱלָקִים לְאַרְבַּע זָוִיּוֹת. מַחֲצִית אַחַת עוֹלָה, וּמַחֲצִית שְׁנִיָּה יוֹרֶדֶת. מַחֲצִית אַחַת לְצַד צָפוֹן, וּמַחֲצִית אַחַת לְצַד דָּרוֹם. כְּשֶׁמִּתְחַבְּרִים כְּאֶחָד, גֶּחָלִים שֶׁלּוֹהֲטִים קַיָּמִים בְּלַהַט שְׁנִינוּת הַחֶרֶב הַמִּתְהַפֶּכֶת.</p>\n<p>עַמּוּד אֶחָד נָעוּץ בְּתוֹךְ הַיָּם, דַּרְגָּה שֶׁשְּׁלוּחָה שֶׁל שַׂר עֶלְיוֹן עוֹלֶה בְּאוֹתוֹ עַמּוּד לְמַעְלָה מַעְלָה, נִתְקָן (מסתכל) לְמֵרָחוֹק עַל קִיטוֹר הָאֳנִיּוֹת שֶׁשָּׁטוֹת בַּיָּם. מִי רָאָה אֵיזֶה גַלִּים שֶׁעוֹלִים וְיוֹרְדִים וְהָרוּחַ נוֹשֶׁבֶת בָּהֶם, וּדְגֵי הַיָּם מוֹשְׁכִים אֶת כָּל הָאֳנִיּוֹת הַלָּלוּ לְכָל צִדְדֵי הָעוֹלָם.</p>\n<p>אוֹתָהּ דַּרְגָּה, כְּשֶׁיּוֹרֶדֶת מֵהַהוּא, עוֹמְדִים אֶלֶף מִימִינוֹ וְאֶלֶף מִשְּׂמֹאלוֹ. הָיָה שָׁב וְיוֹשֵׁב בִּמְקוֹמוֹ כְּמֶלֶךְ בְּכִסְאוֹ, אוֹתָהּ דַּרְגָּה שֶׁכְּשֶׁשָּׁט הַיָּם לְאַרְבָּעָה צִדְדֵי הָעוֹלָם, יוֹצֵאת עִמּוֹ, בּוֹ חוֹזֶרֶת, וְהוּא שָׁב בְּקִיּוּם הַמֶּלֶךְ.</p>\n<p>וְאָז יוֹצְאִים הַכָּרוֹזִים: מִי מִבַּעֲלֵי הָעֵינַיִם יִזְקֹף אוֹתָם לְמַעְלָה לְמַעְלָה. בַּעֲלֵי הַכְּנָפַיִם יַעַמְדוּ בְקִיּוּמָם. בַּעֲלֵי הַפָּנִים מְכַסִּים אוֹתָם, עַד שֶׁנּוֹסֵעַ בְּמַסְעוֹתָיו. וְאָז וַיִּסַּע מַלְאַךְ הָאֱלֹהִים.</p>"],[9522011611,"<p>רַבִּי חִיָּיא פָּתַח, (משלי לא) הָיְתָה כָּאֳנִיּוֹת סוֹחֵר מִמֶּרְחָק תָּבִיא לַחְמָהּ. הָיְתָה כָּאֳנִיּוֹת סוֹחֵר - זוֹ כְּנֶסֶת יִשְׂרָאֵל. מִמֶּרְחָק תָבִיא לַחְמָהּ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ל) הִנֵּה שֵׁם ה' בָּא מִמֶּרְחָק. תָּבִיא לַחְמָהּ - בְּדַרְגָּה אַחַת שֶׁשּׁוֹרָה עָלֶיהָ, וּבָהּ נִמְשְׁכוּ כָּל הַנְּחָלִים וְהַמַּעְיָנוֹת הַלָּלוּ שֶׁהוֹלְכִים לַיָּם, כְּמוֹ שֶׁנֶּאֱמַר (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם וְגוֹ'.</p>\n<p>אֶל מְקוֹם שֶׁהַנְּחָלִים הֹלְכִים. אַף עַל גַּב שֶׁכָּל הַנְּחָלִים נִמְשָׁכִים לְאוֹתָהּ דַּרְגָּהּ, וְאוֹתָהּ דַּרְגָּה מוֹרִידָה (מושכת) אוֹתוֹ לְאוֹתוֹ יָם - אַל תֹּאמַר, שֶׁהֲרֵי הֵרִיק אוֹתָם, וְלֹא שׁוֹרִים בּוֹ אֲחֵרִים, וְלֹא שׁוֹפְעִים בּוֹ כְּבַתְּחִלָּה, חָזַר וְאָמַר אֶל מְקוֹם שֶׁהַנְּחָלִים הוֹלְכִים שָׁם הֵם שָׁבִים. אֶלָּא מְקוֹם אוֹתָהּ דַּרְגָּה שֶׁהַנְּחָלִים הוֹלְכִים פַּעַם אַחַת, שָׁם הֵם שָׁבִים לָלֶכֶת - שָׁם הֵם שָׁבִים מֵאוֹתוֹ מָקוֹם עֶלְיוֹן, וְלֹא פוֹסְקִים לְעוֹלָמִים, וְכֻלָּם מִתְכַּנְּסִים לְאוֹתוֹ מָקוֹם. וְלָמָּה? לָלֶכֶת. לָלֶכֶת לְאוֹתוֹ מָקוֹם שֶׁל הַיָּם, כְּמוֹ שֶׁנֶּאֱמַר. מַה שֵּׁם אוֹתָהּ הַדַּרְגָּה? נִקְרֵאת צַדִּיק.</p>\n<p>רַבִּי יְהוּדָה אָמַר, כָּתוּב (תהלים קד) שָׁם אֳנִיּוֹת יְהַלֵּכוּן לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ. שָׁם אֳנִיּוֹת יְהַלֵּכוּן - בְּאוֹתוֹ הַיָּם שֶׁהוֹלְכִים וְשָׁטִים עַד שֶׁבָּאִים לְהִתְחַבֵּר בְּאוֹתָהּ דַּרְגָּה, אָז כָּתוּב לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ.</p>\n<p>רַבִּי יִצְחָק אָמַר, לְמַעְלָה לְמַעְלָה יוֹתֵר, יֵשׁ זִוּוּג אַחֵר שֶׁשּׁוֹרֶה בַּחֲבִיבוּת וְלֹא נִפְרָד לְעוֹלָמִים. אָמַר רַבִּי יְהוּדָה, מִי זוֹכֶה לְאוֹתוֹ זִוּוּג? אָמַר לוֹ, מִי שֶׁיֵּשׁ לוֹ חֵלֶק לָעוֹלָם הַבָּא. דַּוְקָא בָּעוֹלָם הַבָּא. אָמַר לוֹ, וַהֲרֵי מִכָּאן לָמַדְנוּ, שֶׁכָּתוּב לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ,</p>\n<p>אָמַר לוֹ, וַהֲרֵי מִכָּאן לָמַדְנוּ, שֶׁכָּתוּב לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ, מַשְׁמָע שֶׁאָמַר זֶה, וְזֶה וְזֹּאת הֵם יְדוּעִים. אָמַר רַבִּי אַבָּא, שְׁנֵיכֶם יָפֶה אֲמַרְתֶּם, וְזֶה שֶׁל רַבִּי יְהוּדָה דַּוְקָא יָפֶה, וְהַכֹּל עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְעַנֵּג בָּהֶם לַצַּדִּיקִים. זֶהוּ שֶׁכָּתוּב (ישעיה נח) אָז תִּתְעַנַּג עַל ה'.</p>\n<p>אָמַר רַבִּי אַבָּא, כַּמָּה אֲלָפִים וְכַמָּה רְבָבוֹת שֶׁל מַחֲנוֹת קְדוֹשִׁים יֵשׁ לַקָּדוֹשׁ-בָּרוּךְ-הוּא: בַּעֲלֵי פָּנִים עֶלְיוֹנִים, בַּעֲלֵי עֵינַיִם, בַּעֲלֵי כְּלֵי זַיִן, בַּעֲלֵי הַיְלָלָה, בַּעֲלֵי הַיְבָבָה, בַּעֲלֵי רַחֲמִים, בַּעֲלֵי דִין, וּמֵעַל כֻּלָּם הִפְקִיד אֶת הַגְּבִירָה לְשַׁמֵּשׁ בַּהֵיכָל שֶׁלְּפָנָיו.</p>\n<p>כְּנֶגֶד אֵלֶּה יֵשׁ לַגְּבִירָה מַחֲנוֹת מְזֻיָּנִים. בְּשִׁשִּׁים (בששה) פָּנִים נִמְצָאִים מַחֲנוֹת מְזֻיָּנִים, וְכֻלָּם חֲגוּרֵי חֶרֶב עוֹמְדִים סְבִיבָהּ. כַּמָּה יוֹצְאִים וְכַמָּה נִכְנָסִים. בְּשֵׁשׁ כְּנָפַיִם טָסִים אֶת כָּל הָעוֹלָם. לִפְנֵי כָּל אֶחָד וְאֶחָד גַּחֲלֵי אֵשׁ בּוֹעֵר. לְבוּשׁוֹ אֵשׁ לוֹהֵט. בְּגַבּוֹ חֶרֶב שְׁנוּנָה לוֹהֶטֶת בְּכָל הָעוֹלָם לִשְׁמֹר לְפָנֶיהָ. זֶהוּ שֶׁכָּתוּב (בראשית ג) וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת לִשְׁמֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים.</p>\n<p>מַה זֶּה דֶּרֶךְ עֵץ הַחַיִּים? זוֹהִי הַגְּבִירָה הַגְּדוֹלָה, שֶׁהִיא דֶרֶךְ לְאוֹתוֹ עֵץ גָּדוֹל חָזָק, עֵץ הַחַיִּים, שֶׁכָּתוּב (שיר ג) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבֹּרִים סָבִיב לָהּ מִגִּבֹּרֵי יִשְׂרָאֵל. יִשְׂרָאֵל שֶׁלְּמַעְלָה, כֻּלָּם אֲחֻזֵי חֶרֶב.</p>\n<p>כְּשֶׁנּוֹסַעַת הַגְּבִירָה, כֻּלָּם נוֹסְעִים עִמָּהּ, זֶהוּ שֶׁכָּתוּב וַיִּסַּע מַלְאַךְ הָאֱלֹהִים. וְכִי מַלְאַךְ הָאֱלֹהִים הוּא נִקְרָא? אָמַר רַבִּי אַבָּא, כֵּן. בֹּא רְאֵה, כָּךְ אָמַר רַבִּי שִׁמְעוֹן, הִתְקִין הַקָּדוֹשׁ בָּרוּךְ הוּא לְפָנָיו הֵיכָל קָדוֹשׁ, הֵיכָל עֶלְיוֹן (קדוש), קִרְיָה קְדוֹשָׁה, קִרְיָה עֶלְיוֹנָה, שֶׁנִּקְרֵאת יְרוּשָׁלַיִם עִיר הַקֹּדֶשׁ. מִי שֶׁנִּכְנָס לַמֶּלֶךְ - לֹא נִכְנָס אֶלָּא מֵאוֹתָהּ קִרְיָה קְדוֹשָׁה, נוֹטֵל דֶּרֶךְ לַמֶּלֶךְ, שֶׁהַדֶּרֶךְ מְתֻקֶּנֶת מִכָּאן.</p>\n<p>זֶהוּ שֶׁכָּתוּב (תהלים קיח) זֶה הַשַּׁעַר לַה' צַדִּיקִים יָבֹאוּ בוֹ. כָּל שְׁלִיחוּת שֶׁרוֹצֶה הַמֶּלֶךְ, יוֹצֵאת מִבֵּית הַגְּבִירָה. וְכָל שְׁלִיחוּת מִלְּמַטָּה לַמֶּלֶךְ, (שרוצה המלך) נִכְנֶסֶת קֹדֶם לְבֵית הַגְּבִירָה, וּמִשָּׁם לַמֶּלֶךְ. נִמְצָא שֶׁהַגְּבִירָה הִיא הַשְּׁלִיחָה שֶׁל הַכֹּל, מִלְמַעְלָה לְמַטָּה, וּמִלְּמַטָּה לְמַעְלָה. וְעַל זֶה הִיא שְׁלִיחָה שֶׁל הַכֹּל. זֶהוּ שֶׁכָּתוּב וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל - יִשְׂרָאֵל שֶׁלְּמַעְלָה. מַלְאַךְ הָאֱלֹהִים - זֶהוּ שֶׁכָּתוּב בּוֹ וַה' הֹלֵךְ לִפְנֵיהֶם וְגוֹ'. וְזֶה לָלֶכֶת יוֹמָם וָלַיְלָה, כְּמוֹ שֶׁבֵּאֲרוּהָ.</p>\n<p>וְכִי כְּבוֹד הַמֶּלֶךְ הוּא שֶׁהַגְּבִירָה תֵּלֵךְ, וְהִיא תַּעֲרֹךְ קְרָב, וְהִיא הוֹלֶכֶת כְּשָׁלִיחַ? אֶלָּא לְמֶלֶךְ שֶׁהִזְדַּוֵּג בִּגְבִירָה עֶלְיוֹנָה. רָאָה הַמֶּלֶךְ אֶת כְּבוֹדָהּ עַל כָּל שְׁאָר גְּבִירוֹת הָעוֹלָם, וְאָמַר: כֻּלָּם נֶחְשָׁבוֹת לְפִילַגְשִׁים (לחפה) כְּנֶגֶד הַגְּבִירָה הַזּוֹ שֶׁלִּי, הִיא עוֹלָה עַל כֻּלָּן, מָה אֶעֱשֶׂה לָהּ? אֶלָּא כָּל הַבַּיִת שֶׁלִּי יִהְיֶה בְּיָדֶיהָ. הוֹצִיא הַמֶּלֶךְ כְּרוּז: מִכָּאן כָּל דִּבְרֵי הַמֶּלֶךְ יִמָּסְרוּ בִּידֵי הַגְּבִירָה. מֶה עָשָׂה? הִפְקִיד הַמֶּלֶךְ בְּיָדֶיהָ כָּל כְּלֵי זֵינוֹ, כָּל אוֹתָם בַּעֲלֵי עוֹרְכֵי קְרָבוֹת, וְכָל אוֹתָם אֲבָנִים יְקָרוֹת שֶׁל הַמֶּלֶךְ וְכָל גִּנְזֵי הַמֶּלֶךְ. אָמַר: מִכָּאן, כָּל מִי שֶׁיִּצְטָרֵךְ לְדַבֵּר עִמִּי, לֹא יוּכַל לְדַבֵּר עִמִּי עַד שֶׁיּוֹדִיעַ לַגְּבִירָה.</p>\n<p>כָּךָ הַקָּדוֹשׁ בָּרוּךְ הוּא, מֵרֹב חֲבִיבוּתוֹ וְאַהֲבָתוֹ לִכְנֶסֶת יִשְׂרָאֵל הִפְקִיד הַכֹּל בִּרְשׁוּתָהּ. אָמַר: כָּל הַשְּׁאָר לֹא נֶחְשָׁבִים כְּלוּם לְפָנֶיהָ. אָמַר: (שיר ו) שִׁשִּׁים הֵמָּה מְלָכוֹת וְגוֹ', אַחַת הִיא יוֹנָתִי תַמָּתִי. מָה אֶעֱשֶׂה לָהּ? אֶלָּא הֲרֵי כָּל בֵּיתִי בְּיָדֶיהָ. הוֹצִיא הַמֶּלֶךְ כְּרוּז: מִכָּאן וָהָלְאָה כָּל דִּבְרֵי הַמֶּלֶךְ יִמָּסְרוּ בִּידֵי הַגְּבִירָה. הִפְקִיד בְּיָדֶיהָ כָּל כְּלֵי זֵינוֹ, רְמָחִים, סְיָפִים, קְשָׁתוֹת, חִצִּים וַחֲרָבוֹת, בַּלִּיסְטְרָאוֹת, מוֹשְׁלִים, עֵצִים, אֲבָנִים, וְכָל אוֹתָם בַּעֲלֵי (כלי) עֲרִיכַת קְרָב (לוחמים). זֶהוּ שֶׁכָּתוּב הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבֹּרִים וְגוֹ', כֻּלָּם אֲחֻזֵי חֶרֶב מְלֻמְּדֵי וְגוֹ'.</p>\n<p>אָמַר הַמֶּלֶךְ, מִכָּאן וָהָלְאָה הַקְּרָב שֶׁלִּי נִמְסָר בְּיָדֵךְ, כְּלֵי הַזַּיִן שֶׁלִּי, בַּעֲלֵי עֲרִיכַת קְרָב בְּיָדֵךְ. מִכָּאן וָהָלְאָה אַתְּ תִּהְיִי שׁוֹמֶרֶת שֶׁלִּי. זֶהוּ שֶׁכָּתוּב (תהלים קכא) שׁוֹמֵר יִשְׂרָאֵל. מִכָּאן וָהָלְאָה, כָּל מִי שֶׁצָּרִיךְ אוֹתִי, לֹא יָכוֹל לְדַבֵּר עִמִּי עַד שֶׁמּוֹדִיעַ לַגְּבִירָה. זֶהוּ שֶׁכָּתוּב (ויקרא טז) בְּזאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. שְׁלִיחַ הַמֶּלֶךְ בַּכֹּל, כְּמוֹ שֶׁבֵּאַרְנוּ. נִמְצָא שֶׁהַכֹּל בְּיָדֶיהָ, וְזֶהוּ כְּבוֹד הַגְּבִירָה. זֶהוּ שֶׁכָּתוּב וַיִּסַּע מַלְאַךְ הָאֱלֹהִים וְגוֹ', כְּמוֹ שֶׁנֶּאֱמַר.</p>\n<p>וַיֵּלֶךָ מֵאַחֲרֵיהֶם. מָה הַטַּעַם מֵאַחֲרֵיהֶם? כְּדֵי שֶׁיִּמָּצְאוּ לְפָנֶיהָ (אצלה) בַּעֲלֵי עֲרִיכַת הַקְּרָב, בַּעֲלֵי בַלִּיסְטְרָאוֹת, בַּעֲלֵי רְמָחִים וַחֲרָבוֹת, וְנִתְגַּלִּים לְפָנֶיהָ, שֶׁהֲרֵי הָיוּ בָאִים מַחֲנוֹת אֲחֵרִים לַעֲרֹךְ קְרָב בְּיִשְׂרָאֵל מִלְמַעְלָה, וְעַל כֵּן וַיֵּלֶךְ מֵאַחֲ רֵיהֶם.</p>\n<p>וְשָׁנִינוּ, שֶׁבְּאוֹתָהּ שָׁעָה בָּא שַׁלִּיט הַמְמֻנֶּה עַל הַמִּצְרִים, וְכִנֵּס שֵׁשׁ מֵאוֹת (רבבות) מֶרְכְּבוֹת מְקַטְרְגִים, וְעַל כָּל מֶרְכָּבָה וּמֶרְכָּבָה שֵׁשׁ מֵאוֹת שַׁלִּיטִים מְמֻנִּים קָטֵגוֹרִים. זֶהוּ שֶׁכָּתוּב וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר וְגוֹ'. וְכִי שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר לֹא הָיוּ רִכְבֵי מִצְרַיִם? מָה הַטַּעַם וְכֹל רֶכֶב מִצְרָיִם? אֶלָּא כָּךְ שָׁנִינוּ, הָיָה סמא\"ל מַלְוֶה לוֹ שֵׁשׁ מֵאוֹת מֶרְכָּבוֹת שֶׁל מְקַטְרְגִים לְסַיֵּעַ לוֹ. זֶהוּ שֶׁכָּתוּב וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר.</p>\n<p>מָתַי הִשְׁלִים הַקָּדוֹשׁ בָּרוּךְ הוּא לְסמא\"ל? בַּקְּרָב עִם סִיסְרָא, שֶׁעִקֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת כָּל אוֹתָן מֶרְכָּבוֹת, וְנִמְסְרוּ בִּידֵי הַגְּבִירָה. זֶהוּ שֶׁכָּתוּב (שופטיםה) נַחַל קִישׁוֹן גְּרָפָם נַחַל קְדוּמִים וְגוֹ'. וְלֶעָתִיד לָבֹא כֻּלָּם יִמָּסְרוּ. זֶהוּ שֶׁכָּתוּב (ישעיהסג) מִי זֶה בָּא מֵאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה וְגוֹ'. וְעַל זֶה וַיֵּלֶךְ מֵאַחֲרֵיהֶם, שֶׁעֲתִידָה הַשְּׁכִינָה בְּסוֹף הַיָּמִים לַעֲקֹר אוֹתָם מִן הָעוֹלָם.</p>\n<p>וַיִּסַּע עַמּוּד הֶעָנָן מִפְּנֵיהֶם, מִי זֶה עַמוּד הֶעָנָן? רַבִּי יוֹסֵי אָמַר, זֶהוּ הֶעָנָן שֶׁנִּרְאֶה תָמִיד עִם הַשְּׁכִינָה, וְזֶהוּ הֶעָנָן שֶׁנִּכְנַס מֹשֶׁה לְתוֹכוֹ. רַבִּי אַבָּא אָמַר, כָּתוּב וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם. אֶלָּא סִיּוּעַ שֶׁל הַצַּדִּיק הוּא, וּפְרִישָׁה שֶׁל הָרֹשֶׁם שֶׁלּוֹ, וְעַל זֶה הָלַךְ הֶעָנָן הַזֶּה יוֹמָם, וְכָתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ. וּמִצַּד שֶׁל חֶסֶ\"ד בָּא הֶעָנָן הַזֶּה, וְזֶה נִקְרָא חֶסֶד, וְעָנָן אַחֵר הוֹלֵךְ בַּלַּיְלָה, וְנִקְרָא עַמּוּד אֵשׁ.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, עַמּוּד הֶעָנָן יוֹמָם - זֶה אַבְרָהָם. וְעַמּוּד הָאֵשׁ לַיְלָה - זֶה יִצְחָק. וּשְׁנֵיהֶם נִמְצְאוּ בַּשְּׁכִינָה. וּמַה שֶּׁאָמַר רַבִּי אַבָּא, כָּךְ הוּא וַדַּאי, שֶׁעַל יְדֵי זוֹ (שבזו) הַדַּרְגָּה נִמְצְאוּ.</p>\n<p>וְזְהִ וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל וַיֵּלֶךְ מֵאַחֲרֵיהֶם. וַיִּסַּע - שֶׁנָּסַע מִצַּד שֶׁל חֶסֶ\"ד, וְנִדְבַּק בְּצַד הַגְּבוּרָה, מִשּׁוּם שֶׁהֲרֵי הִגִּיעַ הַזְּמַן לְהִתְלַבֵּשׁ בְּדִין.</p>"],[9522011612,"<p>בֹּא רְאֵה, בְּאוֹתָהּ שָׁעָה נִשְׁלְמָה הַלְּבָנָה מֵהַכֹּל, וְיָרְשָׁה שִׁבְעִים וּשְׁנַיִם שֵׁמוֹת קְדוֹשִׁים בִּשְׁלֹשָׁה צְדָדִים. צַד אֶחָד הִתְלַבֵּשׁ בַּעֲטֶרֶת הַחֶסֶד הָעֶלְיוֹן בְּשִׁבְעִים חֲקִיקוֹת שֶׁל אוֹר שֶׁל הָאַבָּא הָעֶלְיוֹן שֶׁמֵּאִיר לָהּ.</p>\n<p>הַצַד הַשֵּׁנִי הִתְלַבֵּשׁ בְּרָמְחֵי הַגְּבוּרָ\"ה, בְּשִׁשִּׁים מַכּוֹת אֵשׁ, וַעֲשָׂרָה שֶׁלָּהּ שֶׁיָּרְדוּ מִצַּד הָאִמָּא הָעֶלְיוֹנָה בְּמִנְהָגִים חֲקוּקִים.</p>\n<p>צַד שְׁלִישִׁי הִתְלַבֵּשׁ בִּלְבוּשֵׁי אַרְגָּמָן שֶׁלּוֹבֵשׁ הַמֶּלֶךְ הָעֶלְיוֹן הַקָּדוֹשׁ, שֶׁנִּקְרָאִים תִּפְאֶרֶ\"ת, שֶׁיּוֹרֵשׁ הַבֵּן הַקָּדוֹשׁ בְּשִׁבְעִים עֲטָרוֹת עֶלְיוֹנוֹת מִצַּד שֶׁל הָאָב וְהָאֵם, וְהוּא כּוֹלֵל אֶת הַצַּד הַזֶּה וְהַצַּד הַזֶּה.</p>\n<p>(ושתי עטרות מצד של אבא ואמא, והם שבעים ושנים שמות.) וְשָׁנִינוּ, מִצַּד הַחֶסֶ\"ד שִׁבְעִים וּשְׁנַיִם עֵדִים. מִצַּד הַגְּבוּרָה שִׁבְעִים וּשְׁנַיִם סוֹפְרִים. מִצַּד הַתִּפְאֶרֶת שִׁבְעִים וּשְׁנַיִם גְוָנִים לְהִתְפָּאֵר.</p>\n<p>וּבְמָקוֹם זֶה נֶחְקַק אֶחָד בְּאֶחָד, וְהִתְעַלָּה הַשֵּׁם הַקָּדוֹשׁ, סוֹד הַמֶּרְכָּבָה, וְכָאן נֶחְקְקוּ הָאָבוֹת לְהִתְחַבֵּר בְּאֶחָד, וְהוּא הַשֵּׁם הַקָּדוֹשׁ חָקוּק בְּאוֹתִיּוֹתָיו.</p>\n<p>צֵרוּף הָאוֹתִיּוֹת הַלָּלוּ, אוֹתִיּוֹת רִאשׁוֹנוֹת, רְשׁוּמוֹת כַּסְּדָרִים בְּסֵדֶר יָשָׁר, מִשּׁוּם שֶׁכָּל הָאוֹתִיּוֹת הָרִאשׁוֹנוֹת נִמְצְאוּ בְּחֶסֶ\"ד, לָלֶכֶת בְּדֶרֶךְ יָשָׁר בְּסִדּוּר מְתֻקָּן.</p>\n<p>אוֹתִיּוֹת שְׁנִיּוֹת רְשׁוּמוֹת בְּגִלְגּוּל לְמַפְרֵעַ, מִשּׁוּם שֶׁכָּל הָאוֹתִיּוֹת הַשְּׁנִיּוֹת נִמְצָאוֹת בִּגְבוּרָה (מגבורה), לְגַלּוֹת דִּינִים וּמִינִים שֶׁבָּאִים מִצַּד הַשְּׂמֹאל.</p>\n<p>אוֹתִיּוֹת שְׁלִישִׁיּוֹת הֵן אוֹתִיּוֹת רְשׁוּמוֹת, לְהַרְאוֹת גְּוָנִים, לְהִתְעַטֵּר בַּמֶּלֶךְ הַקָּדוֹשׁ. וְהַכֹּל מִתְחַבְּרִים וְנִקְשָׁרִים בּוֹ, וְהוּא מִתְעַטֵּר בְּעַטְרוֹתָיו בְּדֶרֶךְ יָשָׁר, וְרוֹשֵׁם אֶת הַצַּד הַזֶּה וְאֶת הַצַּד הַזֶּה, כְּמוֹ מֶלֶךְ שֶׁמִּתְעַטֵּר בַּכֹּל.</p>\n<p>כָּאן נִרְשָׁם הַשֵּׁם הַקָּדוֹשׁ חָקוּק בְּשִׁבְעִים וּשְׁתַּיִם תֵּבוֹת שֶׁמִּתְעַטְּרוֹת בָּאָבוֹת, הַמֶּרְכָּבָה הַקְּדוֹשָׁה הָעֶלְיוֹנָה. וְאִם תֹּאמַר, מָה הַטַּעַם אֵינָן כְּתוּבוֹת הָאוֹתִיּוֹת הַשְּׁלִישִׁיּוֹת הַלָּלוּ, מֵהֶם בְּסֵדֶר יָשָׁר כְּסִדְרָם, וּמֵהֶם לְמַפְרֵעַ, לְיַשֵּׁר אֶת הַצַּד הַזֶּה וְאֶת הַצַּד הַזֶּה, שֶׁהֲרֵי שָׁנִינוּ, אַתָּה כּוֹנַנְתָּ מֵישָׁרִים - הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה מֵישָׁרִים לִשְׁנֵי הַצְּדָדִים, וְכָתוּב (שמות כו) וְהַבְּרִיחַ הַתִּיכוֹן בְּתוֹךְ הַקְּרָשִׁים וְגוֹ', זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. רַבִּי יִצְחָק אָמַר, זֶה יַעֲקֹב. וְהַכֹּל אֶחָד.</p>\n<p>הַמֶּלֶךְ וַדַּאי הוּא שָׁלֵם, שָׁלֵם מֵהַכֹּל, שָׁלֵם בְּדַעְתּוֹ, אֲנִי רוֹאֶה שֶׁבְּאוֹתוֹ הָאוֹר יוֹשֵׁב בְּדִין וְנִתְכַּסֶּה, אַף עַל גַּב שֶׁלֹּא נִרְאֶה, שֶׁאִם לֹא כָּךְ, לֹא יִהְיֶה מֶלֶךְ שָׁלֵם, וְלָכֵן צָרִיךְ לְהִשָּׁמֵר.</p>\n<p>כָּךָ הַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלֵם תָּמִיד בְּגָוֶן זֶה וּבְגָוֶן זֶה, אֲבָל לֹא נִרְאֶה, אֶלָּא בְּפָנִים מְאִירוֹת. וְלָכֵן אוֹתָם רְשָׁעִים הַטִּפְּשִׁים לֹא נִשְׁמָרִים מִמֶּנּוּ. אוֹתָם חֲכָמִים צַדִּיקִים אוֹמְרִים: מֶלֶךְ שָׁלֵם הוּא. אַף עַל פִּי שֶׁפָּנָיו נִרְאִים מְאִירוֹת, הַדִּין מְכֻסֶּה בְתוֹכוֹ, וְלָכֵן צָרִיךְ לְהִשָּׁמֵר מִמֶּנּוּ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, מִכָּאן (מלאכי ג) אֲנִי ה' לֹא שָׁנִיתִי. לֹא דִלַּגְתִּי לְמָקוֹם אַחֵר, בִּי נִכְלָל הַכֹּל. שְׁנֵי הַגְּוָנִים הַלָּלוּ נִכְלְלוּ בִי. מִשּׁוּם כָּךְ הַכֹּל נִרְאֶה בְּדֶרֶךְ יָשָׁר, וְאַף עַל גַּב שֶׁהָאוֹתִיּוֹת אֲחוּזוֹת לְצַד זֶה וּלְצַד זֶה, הֵן כְּתוּבוֹת כְּסִדְרָן.</p>\n<p>וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל וַיֵּלֶךְ מֵאַחֲרֵיהֶם וַיִּסַּע עַמּוּד הֶעָנָן מִפְּנֵיהֶם וַיַּעֲמֹד מֵאַחֲרֵיהֶם. עַד כָּאן צַד אֶחָד, חֶסֶד לְאַבְרָהָם. אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר בְּנִי, בֹּא רְאֵה הַסּוֹד הַזֶּה. כְּשֶׁהָעַתִּיק הַקָּדוֹשׁ מֵאִיר לַמֶּלֶךְ, מֵאִיר לוֹ (מעטר אותו ומוריש לו בכתרים וכו') וּמְעַטֵּר אוֹתוֹ בִּכְתָרִים קְדוֹשִׁים עֶלְיוֹנִים. כְּשֶׁמַּגִּיעִים אֵלָיו, מִתְעַטְּרִים הָאָבוֹת. וּבְשָׁעָה שֶׁהָאָבוֹת מִתְעַטְּרִים, אָז הוּא שְׁלֵמוּת הַכֹּל, אָז הַגְּבִירָה נוֹסַעַת בְּמַסָּעֶיהָ (באותה) (בשלטון בזה) שְׁלֵמוּת שֶׁל הָאָבוֹת. וּכְשֶׁמִּתְעַטֶּרֶת מִכֻּלָּם, אָז מִתְבָּרֶכֶת, וּרְשׁוּת שֶׁל הַכֹּל בְּיָדֶיהָ.</p>\n<p>וְסָתוּם בּוֹ כְּמוֹ זֶה הַשֵּׁם הַקָּדוֹשׁ חָקוּק בְּאוֹתִיּוֹת רְשׁוּמוֹת בַּמֶּרְכָּבָה הַקְּדוֹשָׁה הָעֶלְיוֹנָה, עִטּוּר הָאָבוֹת.</p>\n<p>אָמַר רַבִּי יֵיסָא, מָצָאנוּ בְּסוֹד זֶה בִּתְקִיעַת הַשּׁוֹפָר (של רב בבבל) שֶׁל רַב הַמְנוּנָא סָבָא שָׁלֹשׁ וּבְכֵן וּבְכֵן וּבְכֵן, כְּנֶגֶד שָׁלֹשׁ אֵלֶּה, וְכָךְ הַסֵּדֶר. אָמַר רַבִּי יוֹסֵי, הַכֹּל נִכְלָל בַּשֵּׁם (שליח) הַקָּדוֹשׁ הַזֶּה וּמִסְתַּיֵּם בּוֹ, נִמְצָא שֶׁשְּׁלֵמוּת הַמֶּרְכָּבָה הַקְּדוֹשָׁה יֵשׁ בּוֹ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, זֶהוּ הַשֵּׁם הַקָּדוֹשׁ, עִטּוּר שֶׁל הָאָבוֹת שֶׁמִּתְעַטְּרִים בַּחֲקִיקוֹתֵיהֶם בְּחִבּוּר כְּאֶחָד. שְׁלֵמוּת הַמֶּרְכָּבָה הַקְּדוֹשָׁה. וְנִכְלָל בְּאַרְבָּעִים וּשְׁמוֹנֶה תֵבוֹת, שֶׁהוּא שְׁלֵמוּת הַכֹּל וְעִקַּר הַשָּׁרָשִׁים.</p>\n<p>בֹּא רְאֵה, גּוּף הָעֵץ - אֲנִ\"י, אָלֶ\"ף נוּ\"ן יוֹ\"ד. רֹאשׁ שֶׁל כָּל עַנְפֵי הָעֵץ - וָה\"וּ. וַהֲרֵי הִתְעוֹרְרוּ הַחֲבֵרִים, כְּלָל שֶׁל עֲנָפִים וְנוֹף וְשֹׁרֶשׁ בְּאַרְבָּעִים וּשְׁמוֹנֶה תֵבוֹת. וַהֲרֵי נִרְשָׁם בִּשְׁלֹשָׁה עוֹלָמוֹת עֶלְיוֹנִים וּבִשְׁלֹשָׁה עוֹלָמוֹת תַּחְתּוֹנִים.</p>\n<p>כְּנֶגְדּוֹ - קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ ה' צְבָאוֹת. קָדוֹשׁ לְמַעְלָה, קָדוֹשׁ בָּאֶמְצַע, קָדוֹשׁ לְמַטָּה. קָדוֹשׁ חֶסֶד, קָדוֹשׁ גְּבוּרָה, קָדוֹשׁ תִּפְאֶרֶת. וְכֻלָּם נֶחְקְקוּ בְּשִׁבְעִים וּשְׁתַּיִם, כְּמוֹ שֶׁנֶּאֱמַר. בָּרוּךְ הוּא, בָּרוּךְ שְׁמוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים אָמֵן.</p>\n<p>אָמַר רַבִּי יִצְחָק, בְּשָׁעָה שֶׁהָיוּ יִשְׂרָאֵל שְׁרוּיִים עַל הַיָּם, רָאוּ כַּמָּה אוּכְלוּסִים, כַּמָּה חֲיָלוֹת, וְכַמָּה מַחֲנוֹת מִלְמַעְלָה וּמִלְּמַטָּה, וְכֻלָּם בְּכִנּוּס עַל יִשְׂרָאֵל. הִתְחִילוּ בִּתְפִלָּה מִתּוֹךְ צָרָתָם.</p>\n<p>בְּאוֹתָהּ הַשָּׁעָה רָאוּ יִשְׂרָאֵל צָרוֹת מִכָּל הַצְּדָדִים: הַיָּם בְּגַלָּיו שֶׁעוֹלִים לִפְנֵיהֶם. מֵאֲחוֹרֵיהֶם כָּל אוֹתָם אוּכְלוּסִים, כָּל אוֹתָם מַחֲנוֹת מִצְרַיִם. מֵעֲלֵיהֶם כַּמָּה קָטֵגוֹרִים. הִתְחִילוּ צוֹוְחִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא.</p>\n<p>אָז כָּתוּב, וַיֹּאמֶר ה' אֶל מֹשֶׁה מַה תִּצְעַק אֵלָי. וְשָׁנִינוּ בְּסִפְרָא דִצְנִיעוּתָא, אֵלַי דַּוְקָא, הַכֹּל תָּלוּי בָּעַתִּיק. בְּאוֹתָהּ הַשָּׁעָה נִגְלָה הָעַתִּיק הַקָּדוֹשׁ, וְנִמְצָא רָצוֹן בְּכָל הָעוֹלָמוֹת הָעֶלְיוֹנִים, וְאָז הָאוֹר שֶׁל הַכֹּל הֵאִיר.</p>\n<p>אָמַר רַבִּי יִצְחָק, אָז, כְּשֶׁהַכֹּל מֵאִיר כְּאֶחָד, וְעָשָׂה הַיָּם מִנְהָגִים עֶלְיוֹנִים, וְנִמְסְרוּ בְיָדוֹ עֶלְיוֹנִים וְתַחְתּוֹנִים. וְלָכֵן קָשֶׁה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הַכֹּל כְּמוֹ קְרִיעַת יַם סוּף. וְהַכֹּל כָּךְ פֵּרְשׁוּהָ. מָה הַטַּעַם? מִשּׁוּם שֶׁקְּרִיעַת יַם סוּף תְּלוּיָה בָּעַתִּיק.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, יֵשׁ אַיֶּלֶת אַחַת בָּרָקִיעַ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה הַרְבֵּה בִּשְׁבִילָהּ. בְּשָׁעָה שֶׁהִיא צוֹוַחַת, הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵעַ אֶת הַצָּרָה שֶׁלָּהּ וּמְקַבֵּל קוֹלָהּ, וּכְשֶׁהָעוֹלָם צָרִיךְ לְרַחֲמִים, הִיא נוֹתֶנֶת קוֹלוֹת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵעַ אֶת קוֹלָהּ, וְאָז חָס עַל הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (תהלים מב) כְּאַיָּל תַּעֲרֹג עַל אֲפִיקֵי מָיִם.</p>\n<p>וּכְשֶׁרוֹצָה לְהוֹלִיד, הִיא נִסְתֶּרֶת מִכָּל הַצְּדָדִים, וְאָז בָּאָה וְשָׂמָה רֹאשָׁהּ בֵּין בִּרְכֶּיהָ, וְצוֹוַחַת וּמְרִימָה קוֹלוֹת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עָלֶיהָ, וּמְזַמֵּן כְּנֶגְדָּהּ אוֹתָהּ נָחָשׁ אֶחָד, וְנוֹשֵׁךְ בְּעֶרְוָתָהּ, וּפוֹתֵחַ אוֹתָהּ וְקוֹרֵעַ לָהּ אוֹתוֹ מָקוֹם, וּמוֹלִידָה מִיָּד. אָמַר רַבִּי שִׁמְעוֹן, בַּדָּבָר הַזֶּה אַל תִּשְׁאַל וְאַל תְּנַסֶּה אֶת ה', וְכָךְ דַּוְקָא.</p>\n<p>וַיּוֹשַׁע ה' בַּיּוֹם הַהוּא אֶת יִשְׂרָאֵל וְגוֹ', וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת. אוֹתוֹ שַׁלִּיט מְמֻנֶּה עַל הַמִּצְרִים הֶרְאָה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁמַּעֲבִיר אוֹתוֹ בִּנְהַר דִּינוּר, שֶׁהָיָה בִּשְׂפַת הַיָּם הַגָּדוֹל. מֵת, מָה הַטַּעַם מֵת? כְּמוֹ שֶׁבֵּאֲרוּהוּ, שֶׁהֶעֱבִירוּ אוֹתוֹ מִשִּׁלְטוֹנוֹ.</p>"],[9522011613,"<p>וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדלָה וְגוֹ'. רַבִּי חִיָּיא אָמַר, כָּאן הִשְׁתַּלְּמָה הַיָּד וְכָל הָאֶצְבָּעוֹת, וְנִשְׁתַּלְּמָה הַיָּד, שֶׁנִּכְלְלָה בּוֹ בַּיָּמִין. שֶׁכָּךְ שָׁנִינוּ, הַכֹּל נִכְלָל בַּיָּמִין וְתָלוּי בַּיָּמִין, זֶהוּ שֶׁכָּתוּב יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ יְמִינְךְ ה' תִּרְעַץ אוֹיֵב.</p>\n<p>וְאָמַר רַבִּי יִצְחָק, לֹא מָצָאתִי מִי חִזֵּק לִבּוֹ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ פַרְעֹה. אָמַר רַבִּי יוֹסֵי, סִיחוֹן וְעוֹג גַּם כָּךְ. אָמַר לוֹ, לֹא כָּךְ! הֵם הִתְחַזְּקוּ כְּנֶגֶד יִשְׂרָאֵל, אֲבָל לְגַבֵּי הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא כְּמוֹ שֶׁפַּרְעֹה חִזֵּק אֶת רוּחוֹ כְּנֶגְדּוֹ, וְהָיָה רוֹאֶה כָּל יוֹם אֶת הַגְּבוּרוֹת שֶׁלּוֹ וְלֹא הָיָה שָׁב.</p>\n<p>אָמַר רַבִּי יְהוּדָה אָמַר רַבִּי יִצְחָק, פַּרְעֹה הָיָה חָכָם מִכָּל מְכַשְּׁפָיו וּבְכָל אוֹתָם הַכְּתָרִים, וּבְכָל אוֹתָן הַיְדִיעוֹת הִסְתַּכֵּל. וּבְכָל הַצַּד שֶׁלָּהֶם לֹא רָאָה אֶת גְּאֻלַּת יִשְׂרָאֵל, וְלֹא הָיָה תּוֹלֶה בְּאֶחָד מֵהֶם. וְעוֹד, שֶׁהֲרֵי בְּכֻלָּם קָשְׁרוּ קֶשֶׁר עַל יִשְׂרָאֵל, וּפַרְעֹה לֹא סָבַר שֶׁיֵּשׁ קֶשֶׁר אֱמוּנָה אַחֵר שֶׁשּׁוֹלֵט עַל הַכֹּל, וְלָכֵן הָיָה מְחַזֵּק אֶת לִבּוֹ.</p>\n<p>רַבִּי אַבָּא אָמַר, רַק הַשֵּׁם הַזֶּה חִזֵּק אֶת לֵב פַּרְעֹה. שֶׁכְּשֶׁהָיָה מֹשֶׁה אוֹמֵר כֹּה אָמַר ה' - הַדָּבָר הַזֶּה מַמָּשׁ חִזֵּק אֶת לִבּוֹ. זֶהוּ שֶׁכָּתוּב וַיְחַזֵּק ה' אֶת לֵב פַּרְעֹה. שֶׁהֲרֵי בְּכָל הַחָכְמָה שֶׁלּוֹ לֹא נִמְצָא שֶׁהַשֵּׁם הַזֶּה שׁוֹלֵט בָּאָרֶץ. וְעַל זֶה אָמַר, מִי ה'? וְאַחַר כָּךְ אָמַר, ה' הַצַּדִּיק. אָמַר רַבִּי יוֹסֵי, אַחַר כָּךְ אָמַר (שמות י) חָטָאתִי לַה'. אוֹתוֹ פֶּה שֶׁאָמַר זֶה - אָמַר זֶה.</p>\n<p>רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, (איוב ט) אַחַת הִיא עַל כֵּן אָמַרְתִּי תָּם וְרָשָׁע הוּא מְכַלֶּה. פָּסוּק זֶה הִתְבָּאֵר בְּסוֹד הַחָכְמָה. אַחַת הִיא, מַה זֶּה אַחַת הִיא? זֶהוּ שֶׁכָּתוּב (שיר ו) אַחַת הִיא יוֹנָתִי תַמָּתִי אַחַת הִיא לְאִמָּהּ. וּבָזֶה הַקָּדוֹשׁ בָּרוּךְ הוּא דָּן דִּינָיו לְמַטָּה, וְדָן דִּינָיו לְמַעְלָה בַּכֹּל.</p>\n<p>וּכְשֶׁהַקָּדוֹשׁ בָּרוּךָ הוּא מְעוֹרֵר דִּינָיו, הוּא דָּן אֶת דִּינָיו בַּכֶּתֶר הַזֶּה, וְאָז כָּתוּב תָּם וְרָשָׁע הוּא מְכַלֶּה. מִשּׁוּם שֶׁאוֹתָם הַצַּדִּיקִים נִתְפָּסִים בַּחֲטָאֵי הָרְשָׁעִים, שֶׁכָּתוּב וַיֹּאמֶר ה' לַמַּלְאָךְ הַמַּשְׁחִית בָּעָם רַב וְגוֹ'. וְעַל זֶה אָמַר (ר' יוסי) אִיּוֹב אֶת הַדָּבָר הַזֶּה, (אמר) וְלֹא פֵרַשׁ אֶת הַדָּבָר, וּפֵרְשׁוּהָ - טֹל הָרַב. רַבִּי יֵיסָא אָמַר, אַחַת הִיא - זוֹ כְּנֶסֶת יִשְׂרָאֵל בְּגָלוּת מִצְרַיִם, שֶׁבִּשְׁבִילָה הָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם וְעָשָׂה בָהֶם נְקָמוֹת. זֶהוּ שֶׁכָּתוּב תָּם וְרָשָׁע הוּא מְכַלֶּה.</p>\n<p>רַבִּי חִיָּיא אָמַר, אִיּוֹב לֹא נִלְקָה, אֶלָּא בִּזְמַן שֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם. אָמַר אִיּוֹב, אִם כָּךְ, כָּל הַפָּנִים שָׁוִים, תָּם וְרָשָׁע הוּא מְכַלֶּה. פַּרְעֹה הֶחֱזִיק בְּיִשְׂרָאֵל וְאָמַר (שמות ה) מִי ה' אֲשֶׁר אֶשְׁמַע בְּקֹלוֹ, וַאֲנִי לֹא הֶחֱזַקְתִּי בָהֶם וְלֹא עָשִׂיתִי דָבָר - תָּם וְרָשָׁע הוּא מְכַלֶּה?! זֶהוּ שֶׁכָּתוּב (שם ט) הַיָּרֵא אֶת דְּבַר ה' מֵעַבְדֵי פַּרְעֹה, זֶה אִיּוֹב.</p>\n<p>רַבִּי יְהוּדָה אָמַר, אוֹתָם אַבְנֵי בָרָד שֶׁהָיוּ יוֹרְדִים, הִתְעַכְּבוּ עַל יְדֵי מֹשֶׁה, וְאַחַר כָּךְ עָשׂוּ נְקָמוֹת בִּימוֹת יְהוֹשֻׁעַ, וְלֶעָתִיד לָבֹא עֲתִידִים לָרֶדֶת אוֹתָם שֶׁנִּשְׁאֲרוּ עַל אֱדוֹם וּבְנוֹתֶיהָ. אָמַר רַבִּי יוֹסֵי, זֶהוּ שֶׁכָּתוּב (מיכה ז) כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת.</p>\n<p>דָּבָר אַחֵר וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדלָה וְגוֹ' - פָּסוּק זֶה אֵין רֹאשׁוֹ סוֹפוֹ, וְאֵין סוֹפוֹ רֹאשׁוֹ. בַּתְּחִלָּה וַיַּרְא יִשְׂרָאֵל, וְאַחַר כָּךְ וַיִּירְאוּ הָעָם אֶת ה'. אֶלָּא אָמַר רַבִּי יְהוּדָה, אוֹתוֹ זָקֵן שֶׁיָּרַד עִם בָּנָיו לַגָּלוּת וְסָבַל עָלָיו אֶת הַגָּלוּת וְהִכְנִיס אֶת בָּנָיו לַגָּלוּת, הוּא רָאָה מַמָּשׁ אֶת כָּל אוֹתָן נְקָמוֹת וּגְבוּרוֹת שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם. זֶהוּ שֶׁכָּתוּב וַיַּרְא יִשְׂרָאֵל, יִשְׂרָאֵל מַמָּשׁ.</p>\n<p>וְאָמַר רַבִּי יְהוּדָה, הֶעֱלָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אוֹתוֹ זָקֵן וְאָמַר לוֹ, קוּם תִּרְאֶה אֶת בָּנֶיךְ יוֹצְאִים מִתּוֹךְ עַם חָזָק. קוּם תִּרְאֶה אֶת הַגְּבוּרוֹת שֶׁעָשִׂיתִי בִּשְׁבִיל בָּנֶיךְ בְּמִצְרַיִם.</p>\n<p>וְהַיְנוּ מַה שֶּׁאָמַר רַבִּי יֵיסָא, בְּשָׁעָה שֶׁנָּסְעוּ יִשְׂרָאֵל לָרֶדֶת לְגָלוּת מִצְרַיִם, פַּחַד וְאֵימָה חֲזָקָה נָפְלוּ עָלָיו. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַעֲקֹב, לָמָּה אַתָּה פּוֹחֵד? (בראשית מו) אַל תִּירָא מֵרְדָה מִצְרַיְמָה. מִמַּה שֶּׁכָּתוּב אַל תִּירָא, מַשְׁמָע שֶׁפַּחַד הָיָה פּוֹחֵד.</p>\n<p>אָמַר לוֹ, כִּי לְגוֹי גָּדוֹל אֲשִׂימְךְ שָׁם. אָמַר לוֹ, אֲנִי פּוֹחֵד שֶׁיִּכְלוּ בָנַי. אָמַר לוֹ, אָנֹכִי אֵרֵד עִמְּךְ מִצְרַיְמָה. אָמַר לוֹ, עוֹד אֲנִי פּוֹחֵד - שֶׁלֹּא אֶזְכֶּה לְהִקָּבֵר בֵּין אֲבוֹתַי וְלֹא אֶרְאֶה אֶת גְּאֻלַּת בָּנַי וְהַגְּבוּרוֹת שֶׁתַּעֲשֶׂה לָהֶם. אָמַר לוֹ, וְאָנֹכִי אַעַלְךְ גַם עָלֹה. אַעַלְךְ - לְהִקָּבֵר בְּקִבְרֵי אֲבוֹתֶיךְ. גַם עָלֹה - לִרְאוֹת אֶת גְּאֻלַּת בָּנֶיךְ וְהַגְּבוּרוֹת שֶׁאֶעֱשֶׂה לָהֶם.</p>\n<p>וְאוֹתוֹ יוֹם שֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, הֶעֱלָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יַעֲקֹב וְאָמַר לוֹ, קוּם תִּרְאֶה בִּגְאֻלַּת בָּנֶיךְ, שֶׁכַּמָּה חֲיָלוֹת וּגְבוּרוֹת עָשִׂיתִי לָהֶם. וְיַעֲקֹב הָיָה שָׁם וְרָאָה אֶת הַכֹּל. זֶהוּ שֶׁכָּתוּב וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדֹלָה.</p>\n<p>רַבִּי יִצְחָק אָמַר, מִכָּאן, (דברים ד) וַיּוֹצִאֲךְ בְּפָנָיו בְּכֹחוֹ הַגָּדֹל מִמִּצְרָיִם. מַה זֶּה בְּפָנָיו? בְּפָנָיו זֶה יַעֲקֹב, שֶׁהִכְנִיס לְשָׁם אֶת כֻּלָּם. רַבִּי חִזְקִיָּה אָמַר, וַיּוֹצִאֲךְ בְּפָנָיו - בְּפָנָיו זֶה אַבְרָהָם, שֶׁכָּתוּב (בראשית יז) וַיִּפֹּל אַבְרָהָם עַל פָּנָיו.</p>\n<p>בֹּא רְאֵה, אַבְרָהָם אָמַר, הַלְּבֶן מֵאָה שָׁנָה יִוָּלֵד וְגוֹ'. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, חַיֶּיךְ, אַתָּה תִּרְאֶה כַּמָּה אוּכְלוּסִים וְכַמָּה חֲיָלוֹת שֶׁיֵּצְאוּ מִמְּךְ. בְּשָׁעָה שֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, כָּל אוֹתָם שְׁבָטִים, כָּל אוֹתָם רְבָבוֹת, הֶעֱלָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אַבְרָהָם וְרָאָה אוֹתָם. זֶהוּ שֶׁכָּתוּב וַיּוֹצִאֲךְ בְּפָנָיו. רַבִּי אַבָּא אָמַר, כָּל הָאָבוֹת הִזְדַּמְּנוּ לְשָׁם בְּכָל אוֹתָהּ הַגְּאֻלָּה. זֶהוּ שֶׁכָּתוּב וַיּוֹצִאֲךְ בְּפָנָיו. מַה זֶּה בְּפָנָיו? אֵלּוּ הָאָבוֹת.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, וַיּוֹצִאֲךְ בְּפָנָיו - זֶה יַעֲקֹב. בְּכֹחוֹ - זֶה יִצְחָק. הַגָּדֹל - זֶה אַבְרָהָם. אָמַר רַבִּי שִׁמְעוֹן, וְכֵן בִּשְׁבִיל הָאָבוֹת מִזְדַּמֶּנֶת תָּמִיד גְּאֻלָּה לְיִשְׂרָאֵל, שֶׁכָּתוּב (ויקרא כו) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב וְאַף אֶת בְּרִיתִי יִצְחָק וְאַף אֶת בְּרִיתִי אַבְרָהָם אֶזְכֹּר וְהָאָרֶץ אֶזְכֹּר. הָאָבוֹת מֵילָא, אֲבָל מַה זֶּה וְהָאָרֶץ אֶזְכֹּר? אֶלָּא לְהַכְלִיל עִמָּם אֶת דָּוִד הַמֶּלֶךְ, שֶׁהוּא מֶרְכָּבָה עִם הָאָבוֹת, וְהֵם מְעוֹרְרִים תָּמִיד גְּאֻלָּה לְיִשְׂרָאֵל.</p>\n<p>וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדלָה אֲשֶׁר עָשָׂה ה' בְּמִצְרַיִם. וְכִי עַכְשָׁו עָשָׂה, וַהֲרֵי מִקֹּדֶם לָכֵן זֶה נַעֲשָׂה? מַה זֶּה אֶת הַיָּד הַגְּדֹלָה אֲשֶׁר עָשָׂה ה'? אֶלָּא יָד לֹא נִקְרֵאת פָּחוֹת מֵחָמֵשׁ אֶצְבָּעוֹת. הַגְּדלָה - שֶׁכְּלוּלִים בָּהּ חָמֵשׁ אֶצְבָּעוֹת אֲחֵרוֹת, וְאָז נִקְרָאִים גְּדוֹלָה. וְכָל אֶצְבַּע וְאֶצְבַּע עוֹלָה לְחֶשְׁבּוֹן גָּדוֹל, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה בָהֶם (כעת נסים) נִסִּים וּגְבוּרוֹת, וּבָזֶה נֶעֶקְרוּ כָּל הַדְּרָגוֹת מֵהִשְׁתַּלְשְׁלוּתָם.</p>\n<p>מִכָּאן לָמַדְנוּ זֶה, שֶׁבַּחֲמֵשׁ הָאֶצְבָּעוֹת הָרִאשׁוֹנוֹת כָּתוּב וַיֶּחֱזַק לֵב פַּרְעֹה. כֵּיוָן שֶׁנִּשְׁלְמוּ אוֹתָן חָמֵשׁ, שׁוּב לֹא הָיָה דָּבָר בִּרְשׁוּת פַּרְעֹה, וְאָז כָּתוּב וַיְחַזֵּק ה' אֶת לֵב פַּרְעֹה.</p>\n<p>וְעַל זֶה וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדלָה וְגוֹ', וַיַּאֲמִינוּ בַּה'. וְכִי עַד עַכְשָׁו לֹא הֶאֱמִינוּ בַּה', וַהֲרֵי כָּתוּב (שמות ד) וַיַּאֲמֵן הָעָם וַיִּשְׁמְעוּ וְגוֹ'? וַהֲרֵי רָאוּ כָּל אוֹתָם גְּבוּרוֹת שֶׁעָשָׂה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם. אֶלָּא מַה זֶּה וַיַּאֲמִינוּ? אוֹתוֹ הַדָּבָר שֶׁאָמַר, וַיֹּאמֶר מֹשֶׁה אֶל הָעָם אַל תִּירָאוּ הִתְיַצְּבוּ וּרְאוּ וְגוֹ'.</p>\n<p>רַבִּי יֵיסָא שָׁאַל וְאָמַר, כָּתוּב וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת, וְכָתוּב לֹא תֹסִפוּ לִרְאֹתָם עוֹד עַד עוֹלָם. אָמַר רַבִּי יוֹסֵי, רָאוּ אוֹתָם מֵתִים. אָמַר לוֹ, אִם כָּתוּב לֹא תוֹסִיפוּ לִרְאוֹתָם חַיִּים - הָיִיתִי אוֹמֵר כָּךְ. אָמַר לוֹ רַבִּי אַבָּא, יָפֶה שָׁאַלְתָּ.</p>\n<p>אֶלָּא בּא רְאֵה, כָּתוּב מִן הָעוֹלָם וְעַד הָעוֹלָם, וְשָׁנִינוּ - עוֹלָם לְמַעְלָה וְעוֹלָם לְמַטָּה. עוֹלָם שֶׁלְּמַעְלָה - מִשָּׁם הִיא הָרֵאשִׁית לְהַדְלִיק מְנוֹרוֹת. הָעוֹלָם שֶׁלְּמַטָּה - שָׁם הַסִּיּוּם, וְנִכְלָל מֵהַכֹּל. וּמֵעוֹלָם הַזֶּה שֶׁלְּמַטָּה מִתְעוֹרְרוֹת גְּבוּרוֹת לַתַּחְתּוֹנִים.</p>\n<p>וּבְעוֹלָם זֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹת לְיִשְׂרָאֵל וְהִרְחִישׁ לָהֶם נִסִּים, וּכְשֶׁהִתְעוֹרֵר עוֹלָם זֶה לַעֲשׂוֹת לָהֶם נִסִּים, כָּל הַמִּצְרִים נִשְׁקְעוּ בַיָּם עַל יְדֵי עוֹלָם זֶה, וְהִתְרַחֵשׁ לָהֶם לְיִשְׂרָאֵל נִסִּים בְּעוֹלָם זֶה. וְעַל זֶה כָּתוּב לֹא תֹסִפוּ לִרְאֹתָם עוֹד עַד עוֹלָם, עַד שֶׁיִּתְעוֹרֵר אוֹתוֹ עוֹלָם וְיִמָּסְרוּ לְדִינָיו. וְכֵיוָן שֶׁנִּמְסְרוּ לוֹ לִדּוֹן, אָז כָּתוּב וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת עַל שְׂפַת הַיָּם. זֶהוּ שֶׁכָּתוּב מִן הָעוֹלָם וְעַד הָעוֹלָם. עַד הָעוֹלָם דַּוְקָא. וְאָז כָּתוּב וַיַּאֲמִינוּ בַּה' וּבְמֹשֶׁה עַבְדּוֹ.</p>"],[9522011614,"<p>אָז יָשִׁיר מֹשֶׁה. רַבִּי יְהוּדָה פָּתַח, (ירמיה א) בְּטֶרֶם אֶצָּרְךְ בַבֶּטֶן יְדַעְתִּיךְ וְגוֹ'. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם יוֹתֵר מִכָּל שְׁאָר הָעַמִּים, וּמֵרֹב הָאַהֲבָה שֶׁהוּא אוֹהֵב אוֹתָם, הֵקִים עֲלֵיהֶם נְבִיא אֱמֶת וְרוֹעֶה נֶאֱמָן, וְעוֹרֵר עָלָיו רוּחַ הַקֹּדֶשׁ יוֹתֵר מִכָּל שְׁאָר הַנְּבִיאִים הַנֶּאֱמָנִים. וְהוֹצִיאוֹ מֵחֶלְקוֹ מַמָּשׁ מִמַּה שֶּׁהִפְרִישׁ יַעֲקֹב מִבָּנָיו לְהַקָּדוֹשׁ בָּרוּךְ הוּא - שֵׁבֶט לֵוִי. וְכֵיוָן שֶׁהָיָה לֵוִי שֶׁלּוֹ, לָקַח אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וְעִטֵּר אוֹתוֹ בְּכַמָּה עֲטָרוֹת, וּמָשַׁח אוֹתוֹ בְּשֶׁמֶן מִשְׁחַת קֹדֶשׁ הָעֶלְיוֹן, וְאָז הוֹצִיא מִבָּנָיו רוּחַ קֹדֶשׁ לַעוֹלָם, וְזֵרַז אוֹתוֹ בְּאַבְנֵטָיו הַקְּדוֹשִׁים, הָאֱמוּנָה הַגְּדוֹלָה.</p>\n<p>לָמַדְנוּ, בְּאוֹתָהּ הַשָּׁעָה שֶׁהִגִּיעַ זְמַנּוֹ שֶׁל מֹשֶׁה הַנָּבִיא הַנֶּאֱמָן לָרֶדֶת לָעוֹלָם, הוֹצִיא הַקָּדוֹשׁ בָּרוּךְ הוּא רוּחַ קֹדֶשׁ מִמַּחְצַב הַסַּפִּיר שֶׁל אֶבֶן טוֹבָה, שֶׁהָיָה גָּנוּז בְּמָאתַיִם אַרְבָּעִים וּשְׁמוֹנָה (אורות, והאיר עליו. ועטרו בשס\"ה) עֲטָרוֹת שֶׁעוֹמְדוֹת לְפָנָיו, וְהִפְקִיד אוֹתוֹ עַל כָּל אֲשֶׁר לוֹ, וְנָתַן לוֹ מֵאָה וְשִׁבְעִים וּשְׁלֹשָׁה מַפְתְּחוֹת. (גנוז שם, ועטר אותו בשלש מאות וששים וחמש עטרות, והאיר עליו מאתים ארבעים ושמונה אורות, והעמיד לפניו, והפקיד אותו בכל ביתו, ונתן לו מאה ושבעים ושלשה מפתחות. נ\"א מאתים ושבעים וחמשה) וְעִטְּרוֹ בְּחָמֵשׁ עֲטָרוֹת, וְכָל עֲטָרָה וַעֲטָרָה עוֹלָה וּמְאִירָה בְּאֶלֶף עוֹלָמוֹת שֶׁמְּאִירִים, וּמְנוֹרוֹת שֶׁגְּנוּזִים בְּגִנְזֵי הַמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן.</p>\n<p>וְאָז הֶעֱבִיר אוֹתוֹ בְּכָל הַמְּנוֹרוֹת (הבשמים) שֶׁבְּגַן עֵדֶן, וְהִכְנִיסוֹ לְהֵיכָלוֹ, וְהֶעֱבִירוֹ בְּכָל חֵילוֹתָיו וְגֵיסוֹתָיו. אָז כֻּלָּם הִזְדַּעְזְעוּ, פָּתְחוּ וְאָמְרוּ: הִסְתַּלְּקוּ מִסְּבִיבוֹ (צד הצדדים), שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹרֵר רוּחַ לִשְׁלֹט לְהַרְגִּיז עוֹלָמוֹת. יָצָא קוֹל וְאָמַר: מִי הוּא זֶה שֶׁכָּל הַמַּפְתְּחוֹת הַלָּלוּ בְּיָדוֹ? פָּתַח קוֹל אַחֵר וְאָמַר: קַבְּלוּ אוֹתוֹ בְּתוֹכֲכֶם! זֶהוּ שֶׁעָתִיד לָרֶדֶת בֵּין בְּנֵי אָדָם, וַעֲתִידָה תוֹרָה, גְּנִיזַת הַגְּנִיזוֹת, לְהִמָּסֵר בְּיָדוֹ, וּלְהַרְעִישׁ עוֹלָמוֹת שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה עַל יָדוֹ שֶׁל זֶה. בְּאוֹתָהּ שָׁעָה כֻּלָּם הִתְרַגְּשׁוּ וְנָסְעוּ אַחֲרָיו. פָּתְחוּ וְאָמְרוּ, (תהלים סו) הִרְכַּבְתָּ אֱנוֹשׁ לְרֹאשֵׁנוּ בָּאנוּ בָּאֵשׁ וּבַמַּיִם.</p>\n<p>אָז עָלְתָה אוֹתָהּ רוּחַ וְעָמְדָה לִפְנֵי הַמֶּלֶךְ. מ' פְּתוּחָה עָלְתָה וְהִתְעַטְּרָה בְּעַטְרוֹתֶיהָ, וְעִטְּרָה אוֹתוֹ בִּשְׁלֹשׁ מֵאוֹת וְעֶשְׂרִים וְחָמֵשׁ עֲטָרוֹת, וְהִפְקִיד מַפְתְּחוֹת בְּיָדוֹ. ש' שֶׁל הָאָבוֹת עִטְּרוּ אוֹתוֹ בְּשָׁלֹשׁ עֲטָרוֹת קְדוֹשׁוֹת, וְהִפְקִידוּ בְיָדוֹ אֶת כָּל מַפְתְּחוֹת הַמֶּלֶךְ, וְהִפְקִידוּ אוֹתוֹ בֶּאֱמוּנָה, לִהְיוֹת נֶאֱמַן הַבַּיִת. ה' עָלְתָה וְעִטְּרָה אוֹתוֹ בְּעַטְרוֹתֶיהָ, וְקִבְּלָה אוֹתוֹ מֵהַמֶּלֶךְ.</p>\n<p>וְאָז יָרַד אוֹתוֹ הָרוּחַ לָאֳנִיּוֹת שֶׁשָּׁטוֹת בְּאוֹת הַיָּם הַגָּדוֹל, וְקִבְּלָה אוֹתוֹ לְגַדֵּל אוֹתוֹ לַמֶּלֶךְ, וְנָתְנָה לוֹ מִשָּׁם כְּלֵי זַיִן לְהַלְקוֹת אֶת פַּרְעֹה וְאֶת כָּל אַרְצוֹ. וּבְשַׁבָּתוֹת וּבְרָאשֵׁי חֳדָשִׁים מַעֲלָה אוֹתוֹ אֶל הַמֶּלֶךְ, וְאָז נִקְרָא שְׁמוֹ בָּאוֹתִיּוֹת הָרְשׁוּמוֹת הַלָּלוּ.</p>\n<p>וּבְאוֹתָהּ שָׁעָה שֶׁיָּצָא לָרֶדֶת לָאָרֶץ בַּזֶּרַע שֶׁל לֵוִי, נִתְקְנוּ אַרְבַּע מֵאוֹת וְעֶשְׂרִים וְחָמֵשׁ מְנוֹרוֹת לַמֶּלֶךְ, וְאַרְבַּע מֵאוֹת וְעֶשְׂרִים וְחָמֵשׁ חֲקִיקוֹת מְמֻנִּים לִוּוּ אֶת אוֹתָהּ רוּחַ לִמְקוֹמָהּ. כְּשֶׁיָּצָא לָעוֹלָם, הֵאִירָה ה' בְּפָנָיו, וְהַבַּיִת הִתְמַלֵּא מִזִּיווֹ. בְּאוֹתָהּ שָׁעָה קָרָא עָלָיו הַקָּדוֹשׁ בָּרוּךְ הוּא, בְּטֶרֶם אֶצָּרְךְ בַבֶּטֶן יְדַעְתִּיךְ וּבְטֶרֶם תֵּצֵא מֵרֶחֶם הִקְדַּשְׁתִּיךְ נָבִיא לַגּוֹיִם נְתַתִּיךְ.</p>\n<p>רַבִּי יִצְחָק אָמַר, בְּאוֹתָהּ שָׁעָה הָרַג (הפיל) הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַשַּׂר הַמְמֻנֶּה הַגָּדוֹל שֶׁל מִצְרַיִם, וְרָאוּ אוֹתוֹ מֹשֶׁה וּבְנֵי יִשְׂרָאֵל, וְאָז אָמְרוּ שִׁירָה. זֶהוּ שֶׁכָּתוּב וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת, אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל.</p>\n<p>אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל וְגוֹ'. רַבִּי אַבָּא פָּתַח וְאָמַר, הִסְתַּכַּלְתִּי בְּכָל הַתִּשְׁבָּחוֹת שֶׁשִּׁבְּחוּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכֻלָּם פָּתְחוּ בְּאָז. (מלכים א ח) אָז אָמַר שְׁלֹמֹה. (יהושע י) אָז יְדַבֵּר יְהוֹשֻׁעַ. אָז יָשִׁיר יִשְׂרָאֵל. מָה הַטַּעַם?</p>\n<p>אֶלָּא כָּךְ שָׁנִינוּ, כָּל הַנִּסִּים וְהַגְּבוּרוֹת שֶׁנַּעֲשׂוּ לְיִשְׂרָאֵל, כְּשֶׁהֵאִיר אוֹר הָעַתִּיק הַקָּדוֹשׁ בְּעַטְרוֹתָיו, חֲקוּקִים רְשׁוּמִים בְּאָז, בְּא', וְא' בְּז', נָקַב בַּחֲשֵׁכָה וְהֵאִיר לְכָל עֵבֶר. וּכְשֶׁהִתְחַבֵּר הָאוֹר שֶׁל אָלֶ\"ף וְהִגִּיעַ לְזַיִ\"ן, מִי זוֹ זַיִ\"ן? זוֹ (ישעיה לד) חֶרֶב לַה' מָלְאָה דָּם. אָז עָשָׂה נִסִּים וּגְבוּרוֹת, מִשּׁוּם שֶׁהִתְחַבְּרָה א' בְּז'. וְזוֹ הִיא הַשִּׁירָה. שִׁירָה הִיא שֶׁל כָּל הַצְּדָדִים, וְזֶהוּ אָז יָשִׁיר.</p>\n<p>יָשִׁיר? שָׁר הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא דָּבָר זֶה תָּלוּי וּמַשְׁלִים אֶת אוֹתוֹ הַזְּמַן, וּמַשְׁלִים לֶעָתִיד לָבֹא, שֶׁעֲתִידִים יִשְׂרָאֵל לְשַׁבֵּחַ בַּשִּׁירָה הַזּוֹ מֹשֶׁה וּבְנֵי יִשְׂרָאֵל. מִכָּאן לָמַדְנוּ, שֶׁהַצַּדִּיקִים הָרִאשׁוֹנִים, אַף עַל גַּב שֶׁהִתְעַלּוּ לִדְרָגוֹת עֶלְיוֹנוֹת שֶׁלְּמַעְלָה, וְנִקְשְׁרוּ בַּקֶּשֶׁר שֶׁל צְרוֹר הַחַיִּים - עֲתִידִים כֻּלָּם לְהֵחָיוֹת בְּגוּף וְלִרְאוֹת אוֹתוֹת וּגְבוּרוֹת שֶׁיַּעֲשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל וְלוֹמַר שִׁירָה זוֹ. זֶהוּ שֶׁכָּתוּב אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר מִכָּאן, (ישעיה יא) יוֹסִיף ה' שֵׁנִית יָדוֹ לִקְנוֹת אֶת שְׁאָר עַמּוֹ. לִקְנוֹת - כְּמוֹ שֶׁנֶּאֱמַר (משלי ח) ה' קָנָנִי רֵאשִׁית דַּרְכּוֹ. אֶת שְׁאָר עַמּוֹ - אֵלּוּ הֵם הַצַּדִּיקִים שֶׁבָּהֶם שֶׁנִּקְרָאִים שְׁאַר, כְּמוֹ שֶׁנֶּאֱמַר (במדבר יא) וַיִּשָּׁאֲרוּ שְׁנֵי אֲנָשִׁים בַּמַּחֲנֶה. וְשָׁנִינוּ, אֵין הָעוֹלָם מִתְקַיֵּם אֶלָּא עַל אוֹתָם שֶׁעוֹשִׂים עַצְמָם שִׁירַיִם.</p>\n<p>וְאִם תֹּאמַר, הוֹאִיל וְנִקְשְׁרוּ בִּצְרוֹר הַחַיִּים וּמִתְעַנְּגִים בָּעֹנֶג הָעֶלְיוֹן, לָמָּה יוֹרִיד אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָרֶץ? צֵא וּלְמַד מִזְּמַן רִאשׁוֹן, שֶׁכָּל אוֹתָם רוּחוֹת וּנְשָׁמוֹת שֶׁהָיוּ בַּדַּרְגָּה הָעֶלְיוֹנָה שֶׁלְּמַעְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הוֹרִיד אוֹתָם לָאָרֶץ לְמַטָּה. כָּל שֶׁכֵּן עַכְשָׁו, שֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַשֵּׁר אֶת הֶעָקֹם, כְּמוֹ שֶׁנֶּאֱמַר (קהלת ז) כִּי אָדָם אֵין צַדִּיק בָּאָרֶץ אֲשֶׁר יַעֲשֶׂה טוֹב וְלֹא יֶחֱטָא. וְאִם תֹּאמַר, אוֹתָם שֶׁמֵּתוּ בְּעֶטְיוֹ שֶׁל נָחָשׁ, אֲפִלּוּ הֵם יָקוּמוּ וְיִהְיֶה בַּעֲלֵי עֵצָה לְמֶלֶךְ הַמָּשִׁיחַ.</p>\n<p>וְעַל זֶה שָׁנִינוּ, מֹשֶׁה עָתִיד לוֹמַר שִׁירָה לֶעָתִיד לָבֹא. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב (מיכה ז) כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרַיִם אַרְאֶנּוּ נִפְלָאוֹת. אַרְאֶנּוּ? אַרְאֶךְ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא אַרְאֶנּוּ מַמָּשׁ, לְמִי שֶׁרָאָה בַּתְּחִלָּה - אַרְאֶנּוּ פַּעַם שְׁנִיָּה. וְזֶהוּ אַרְאֶנּוּ. וְכָתוּב (תהלים נ) אַרְאֶנּוּ בְּיֵשַׁע אֱלֹהִים, וְאַרְאֵהוּ בִּישׁוּעָתִי. וְאָז, אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל אֶת הַשִּׁירָה הַ את לַה'.</p>\n<p>שִׁירָה שֶׁל הַגְּבִירָה לַקָּדוֹשׁ-בָּרוּךְ- הוּא. שָׁנִינוּ, כָּל אָדָם שֶׁאוֹמֵר שִׁירָה זוֹ בְּכָל יוֹם וּמְכַוֵּן בָּהּ, זוֹכֶה לְאָמְרָהּ לֶעָתִיד לָבֹא, שֶׁהֲרֵי יֵשׁ בָּהּ עוֹלָם שֶׁעָבַר, וְיֵשׁ בָּהּ עוֹלָם הַבָּא, וְיֵשׁ בָּהּ קִשְׁרֵי הָאֱמוּנָה, וְיֵשׁ בָּהּ יְמוֹת מֶלֶךְ הַמָּשִׁיחַ, וּתְלוּיִים עָלֶיהָ (אות למעלה) כָּל אוֹתָן תִּשְׁבָּחוֹת אֲחֵרוֹת שֶׁאוֹמְרִים עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>הַשִּׁירָה, ?, שִׁיר זֶה הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא הַשִּׁירָה שֶׁמְּשַׁבַּחַת הַגְּבִירָה לַמֶּלֶךְ. וּמֹשֶׁה אָמַר מִלְּמַטָּה לְמַעְלָה, וַהֲרֵי פֵּרְשׁוּהָ. לַה' - מִשּׁוּם שֶׁהַמֶּלֶךְ מֵאִיר לָהּ פָּנִים (שמאירים פני המלך כנגדה). רַבִּי יוֹסֵי אָמַר, כָּל אוֹתָם שְׁמָנִים שֶׁהָיוּ שׁוֹפְעִים, מָשַׁךְ הַמֶּלֶךְ הַקָּדוֹשׁ כְּנֶגְדָּהּ, מִשּׁוּם כָּךְ מְשַׁבַּחַת אוֹתוֹ הַגְּבִירָה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אִם כָּךְ, לָמָּה כָּתוּב מֹשֶׁה וּבְנֵי יִשְׂרָאֵל, וַהֲרֵי הַגְּבִירָה צְרִיכָה לְשַׁבֵּחַ? אֶלָּא אַשְׁרֵי חֶלְקָם שֶׁל מֹשֶׁה וְיִשְׂרָאֵל, שֶׁהֵם הָיוּ יוֹדְעִים לְשַׁבֵּחַ אֶת הַמֶּלֶךְ בִּשְׁבִיל הַגְּבִירָה כָּרָאוּי, מִשּׁוּם שֶׁכָּל אוֹתוֹ כֹּחַ וּגְבוּרָה שֶׁלָּהּ יָרְשָׁה מִן הַמֶּלֶךְ.</p>\n<p>רַבִּי חִיָּיא פָּתַח וְאָמַר, (איכה ב) קוּמִי רֹנִּי בַלַּיְלָה לְרֹאשׁ אַשְׁמֻרוֹת. קוּמִי רֹנִּי - זוֹ כְּנֶסֶת יִשְׂרָאֵל. בַּלַּיְלָה - בַּגָּלוּת. רַבִּי יוֹסֵי אָמַר, בַּלַּיְלָה - בִּזְמַן שֶׁשּׁוֹלֶטֶת וּמִתְעוֹרֶרֶת. לְרֹאשׁ אַשְׁמֻרוֹת?! בְּרֹאשׁ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא לְרֹאשׁ, כַּכָּתוּב (בראשית מז) עַל רֹאשׁ הַמִּטָּה. וּבֵאַרְנוּ, רֹאשׁ הַמִּטָּה זֶה יְסוֹד. אַף כָּאן לְרֹאשׁ - זֶה יְסוֹד, שֶׁהַגְּבִירָה מִתְבָּרֶכֶת בּוֹ. רֹאשׁ אַשְׁמֻרוֹת - זֶהוּ רֹאשׁ שֶׁל נֶצַח וְהוֹד.</p>\n<p>רַבִּי יוֹסֵי אָמַר, זֶהוּ רֹאשׁ שֶׁל כִּתְרֵי הַמֶּלֶךְ וְהַסִּיּוּם. רַבִּי אַבָּא אָמַר, לְרֹאשׁ אַשְׁמֻרוֹת כָּתוּב חָסֵר, וְזֶהוּ הָרֹאשׁ, רֹאשׁ הַמִּטָּה. וְהַכֹּל נֶאֱמַר בַּמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן, וְזֶהוּ לַה'.</p>\n<p>רַבִּי יֵיסָא אָמַר, הַשִּׁירָה הַזֹּאת לַה' - זֶהוּ הַנָּהָר שֶׁיּוֹצֵא מֵעֵדֶן, שֶׁכָּל שֶׁמֶן וּמִשְׁחָה יוֹצְאִים מִמֶּנּוּ לְהַדְלִיק מְנוֹרוֹת. וּמַשְׁמָע אַחַר כָּךְ שֶׁכָּתוּב אָשִׁירָה לַּה' - זֶה הַמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן, וְעַל זֶה לֹא כָתוּב אָשִׁירָה לּוֹ.</p>\n<p>וַיֹּאמְרוּ לֵאמֹר - (זהו) לְדוֹרֵי דוֹרוֹת, כְּדֵי שֶׁלֹּא יִשְׁתַּכַּח מֵהֶם לְעוֹלָמִים. שֶׁכָּל מִי שֶׁזּוֹכֶה לַשִּׁירָה הַזּוֹ בָּעוֹלָם הַזֶּה, זוֹכֶה לָהּ בָּעוֹלָם הַבָּא, וְזוֹכֶה לְשַׁבֵּחַ בָּהּ בִּימוֹת מֶלֶךְ הַמָּשִׁיחַ בְּחֶדְוַת כְּנֶסֶת יִשְׂרָאֵל בַּקָּדוֹשׁ- בָּרוּךְ-הוּא, שֶׁכָּתוּב לֵאמֹר - לֵאמֹר בְּאוֹתוֹ זְמַן. לֵאמֹר בָּאָרֶץ הַקְּדוֹשָׁה, בִּזְמַן שֶׁשָּׁכְנוּ יִשְׂרָאֵל בָּאָרֶץ. לֵאמֹר בַּגָּלוּת. לֵאמֹר בִּגְאֻלַּת יִשְׂרָאֵל. לֵאמֹר לָעוֹלָם הַבָּא.</p>\n<p>אָשִׁירָה לַּה'?! נָשִׁיר הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה אָשִׁירָה? אֶלָּא מִשּׁוּם שֶׁהָיוּ מְשַׁבְּחִים אֶת תִּשְׁבַּחַת הַגְּבִירָה. (הצטרכו לשבח) לַּה' - זֶה הַמֶּלֶךְ הַקָּדוֹשׁ. כִּי גָאֹה גָּאָה (קמה) - שֶׁעָלָה וְהִתְעַטֵּר בְּעַטְרוֹתָיו לְהוֹצִיא בְרָכוֹת וְכֹחוֹת וּגְבוּרוֹת לְהִתְעַלּוֹת בַּכֹּל. כִּי גָאֹה גָּאָה - גָּאֹה בָּעוֹלָם הַזֶּה, גָּאָה לָעוֹלָם הַבָּא. כִּי גָאֹה בְּאוֹתוֹ זְמַן, גָּאָה כְּדֵי שֶׁיִּתְעַטֵּר בְּעַטְרוֹתָיו בְּחֶדְוָה שְׁלֵמָה.</p>\n<p>סוּס וְרֹכְבוֹ רָמָה בַיָּם - הַשִּׁלְטוֹן שֶׁלְּמַטָּה וְהַשִּׁלְטוֹן שֶׁלְּמַעְלָה שֶׁאֲחוּזִים בָּהֶם, נִמְסְרוּ לְאוֹתוֹ הַיָּם הַגָּדוֹל וְהַשַּׁלִּיט הַגָּדוֹל לַעֲשׂוֹת בָּהֶם נְקָמוֹת. וְשָׁנִינוּ, לֹא עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא דִּין לְמַטָּה, עַד שֶׁיַּעֲשֶׂה בְּשַׁלִּיטֵיהֶם לְמַעְלָה. זֶהוּ שֶׁכָּתוּב (ישעיה כד) יִפְקֹד ה' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם וְעַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה.</p>\n<p>רָמָה בַיָּם - אָמַר רַבִּי יְהוּדָה, בּוֹ בַּלַּיְלָה הִתְעוֹרְרָה גְבוּרָה חֲזָקָה, שֶׁכָּתוּב בּוֹ וַיּוֹלֶךְ ה' אֶת הַיָּם בְּרוּחַ קָדִים עַזָּה כָּל הַלַּיְלָה. (שהתעוררה בו גבורה חזקה) בְּאוֹתוֹ זְמַן בִּקְשָׁה הַמַּלְכָּה מִן הַמֶּלֶךְ אֶת כָּל אוֹתָם אוּכְלוּסִים שֶׁלְּמַטָּה וְכָל אוֹתָם שַׁלִּיטִים שֶׁלְּמַעְלָה שֶׁיִּמָּסְרוּ בְיָדֶיהָ, וְכֻלָּם נִמְסְרוּ לְיָדֶיהָ לַעֲשׂוֹת בָּהֶם נְקָמוֹת. זֶהוּ שֶׁכָּתוּב סוּס וְרֹכְבוֹ רָמָה בַיָּם. בַּיָּם סְתָם, לְמַעְלָה וּלְמַטָּה.</p>"],[9522011615,"<p>עָזִּי וְזִמְרָת יָהּ. רַבִּי חִיָּיא פָּתַח וְאָמַר, (תהלים קלט) אָחוֹר וָקֶדֶם צַרְתָּנִי וַתָּשֶׁת עָלַי כַּפֶּכָה. כַּמָּה הִצְטָרְכוּ בְּנֵי אָדָם לְכַבֵּד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁכַּאֲשֶׁר בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, הִסְתַּכֵּל עַל הָאָדָם לִהְיוֹת שַׁלִּיט עַל הַכֹּל, (להיות שלם בכל, ונברא בשני פרצופים) וְהָיָה דוֹמֶה לָעֶלְיוֹנִים וְלַתַּחְתּוֹנִים. הוֹרִיד אוֹתוֹ בִּדְמוּת מְכֻבֶּדֶת, וְרָאוּ אוֹתוֹ הַבְּרִיּוֹת. אָז הִתְכַּנְּסוּ אֵלָיו וְהִשְׁתַּחֲווּ לְפָנָיו, וּפַחַד וְאֵימָה נָפְלוּ עֲלֵיהֶם מִפַּחְדּוֹ. זֶהוּ שֶׁכָּתוּב (בראשית ט) וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיֶה עַל כָּל חַיַּת הָאָרֶץ וְעַל כָּל עוֹף הַשָּׁמָיִם.</p>\n<p>הִכְנִיס אוֹתוֹ לְגַנּוֹ לְשָׁמְרוֹ, לִהְיוֹת לוֹ שִׂמְחָה עַל שִׂמְחָה וּלְהִשְׁתַּעֲשֵׁעַ בּוֹ. עָשָׂה לוֹ חֻפָּה מְכֻסָּה בַּאֲבָנִים יְקָרוֹת, וּמַלְאָכִים עֶלְיוֹנִים שְׂמֵחִים לְפָנָיו. אַחַר כָּךְ צִוָּה אוֹתוֹ עַל עֵץ אֶחָד, וְלֹא עָמַד בְּמִצְוַת רִבּוֹנוֹ.</p>\n<p>מָצָאנוּ בְּסִפְרוֹ שֶׁל חֲנוֹךְ, שֶׁלְּאַחַר שֶׁהֶעֱלָה אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וְהֶרְאָה לוֹ אֶת כָּל גִּנְזֵי הַמֶּלֶךְ, עֶלְיוֹנִים וְתַחְתּוֹנִים, הֶרְאָה לוֹ אֶת עֵץ הַחַיִּים וְהָעֵץ שֶׁהִצְטַוָּה עָלָיו אָדָם, וְהֶרְאָה לוֹ מְקוֹמוֹ שֶׁל אָדָם בְּגַן עֵדֶן. וְרָאָה, שֶׁאִלְמָלֵא שָׁמַר אָדָם מִצְוָה זוֹ, יָכוֹל לַעֲמֹד תָּמִיד וְלִהְיוֹת שָׁם תָּמִיד. הוּא לֹא שָׁמַר מִצְוַת רִבּוֹנוֹ - יָצָא בְּדִימוֹס וְנֶעֱנַשׁ.</p>\n<p>רַבִּי יִצְחָק אָמַר, אָדָם נִבְרָא דּוּ-פַרְצוּפִים, וַהֲרֵי בֵּאַרְנוּ, (שם ב) וַיִּקַּח אַחַת מִצַּלְעֹתָיו - נִסְּרוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וְנַעֲשׂוּ שְׁנַיִם, מִמִּזְרָח וּמִמַּעֲרָב. זֶהוּ שֶׁכָּתוּב (תהלים קלט) אָחוֹר וָקֶדֶם צַרְתָּנִי. אָחוֹר זֶה מַעֲרָב. וָקֶדֶם זֶה מִזְרָח.</p>\n<p>רַבִּי חִיָּיא אָמַר, מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? תִּקֵּן אוֹתָהּ נְקֵבָה, וְשִׁכְלֵל אֶת יָפְיָהּ עַל הַכֹּל, וְהִכְנִיסָהּ לָאָדָם. זֶהוּ שֶׁכָּתוּב וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע אֲשֶׁר לָקַח מִן הָאָדָם לְאִשָּׁה. בּא רְאֵה מַה כָּתוּב לְמַעְלָה? וַיִּקַּח אַחַת מִצַּלְעֹתָיו. מַה זֶּה אַחַת? כְּמוֹ שֶׁנֶּאֱמַר (שיר ו) אַחַת הִיא יוֹנָתִי תַמָּתִי אַחַת הִיא לְאִמָּהּ. מִצַּלְעֹתָיו - מִצְּדָדָיו, כְּמוֹ שֶׁנֶּאֱמַר (שמות כו) וּלְצֶלַע הַמִּשְׁכָּן.</p>\n<p>רַבִּי יְהוּדָה אָמַר, הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן נְשָׁמָה עֶלְיוֹנָה בָּאָדָם, וְכָלַל בָּהּ חָכְמָה וְהַשְׂכֵּל כְּדֵי לָדַעַת הַכֹּל. מֵאֵיזֶה מָקוֹם נָתַן בּוֹ נְשָׁמָה? רַבִּי יִצְחָק אָמַר, מִמָּקוֹם שֶׁשְּׁאָר הַנְּשָׁמוֹת הַקְּדוֹשׁוֹת בָּאוֹת.</p>\n<p>רַבִּי יְהוּדָה אָמַר, מִכָּאן, שֶׁכָּתוּב (בראשית א) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה. מִי זוֹ הָאָרֶץ? מֵאוֹתוֹ מָקוֹם שֶׁהַמִּקְדָּשׁ נִמְצָא בּוֹ. נֶפֶשׁ חַיָּה - נֶפֶשׁ חַיָּה סְתָם, זוֹ נֶפֶשׁ שֶׁל אָדָם הָרִאשׁוֹן שֶׁל הַכֹּל.</p>\n<p>רַבִּי חִיָּיא אָמַר, אָדָם הָיָה יוֹדֵעַ חָכְמָה עֶלְיוֹנָה יוֹתֵר מִמַּלְאֲכֵי הַשָּׁרֵת, וְהָיָה מִסְתַּכֵּל בַּכֹּל, וְיוֹדֵעַ וְנוֹדָע לְרִבּוֹנוֹ יוֹתֵר מִכָּל שְׁאָר בְּנֵי הָעוֹלָם. לְאַחַר שֶׁחָטָא נִסְתְּמוּ מִמֶּנּוּ מַעְיְנוֹת הַחָכְמָה. מַה כָּתוּב? (ממה שכתוב) (שם ג) וַיְשַׁלְּחֵהוּ ה' אֱלֹהִים מִגַּן עֵדֶן לַעֲבֹד אֶת הָאֲדָמָה.</p>\n<p>רַבִּי אַבָּא אָמַר, אָדָם הָרִאשׁוֹן מִזָּכָר וּנְקֵבָה נִמְצָא, זֶהוּ שֶׁכָּתוּב (שם א) וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ. וְעַל זֶה זָכָר וּנְקֵבָה נַעֲשׂוּ כְּאֶחָד, וְנִפְרְדוּ אַחַר כָּךְ. וְאִם תֹּאמַר, זֶה שֶׁאָמַר הָאֲדָמָה אֲשֶׁר לֻקַּח מִשָּׁם - כָּךְ הוּא וַדַּאי, וְזוֹהִי הַנְּקֵבָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִשְׁתַּתֵּף עִמָּהּ, וְזֶהוּ זָכָר וּנְקֵבָה, וְהַכֹּל דָּבָר אֶחָד.</p>\n<p>רַבִּי יוֹסֵי אָמַר, עָזִּי וְזִמְרָת יָהּ, אוֹתָם הַכְּלוּלִים זֶה בָּזֶה וְלֹא נִפְרָדִים זֶה מִזֶּה, וּלְעוֹלָמִים הֵם בַּחֲבִיבוּת, בְּרָצוֹן אֶחָד, שֶׁמִּשָּׁם נִמְצָאוֹת (נמשכו) מְשִׁיכוֹת הַנְּחָלִים וְהַמַּעְיָנוֹת לְסַפֵּק לַכֹּל וּלְבָרֵךְ אֶת הַכֹּל, לֹא מְכַזְּבִים מֵימֵי הַמַּעְיָנוֹת, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה נה) וּכְמוֹצָא מַיִם אֲשֶׁר לֹא יְכַזְּבוּ מֵימָיו, וְעַל זֶה וַיְהִי לִי לִישׁוּעָה, שֶׁבִּשְׁבִיל כָּךְ הַמֶּלֶךְ הַקָּדוֹשׁ מוֹשֵׁךְ וּמוֹרִישׁ לְמַטָּה, וּמִתְעוֹרֵר הַיָּמִין לַעֲשׂוֹת נִסִּים.</p>\n<p>זְהִ אֵלִי וְאַנְוֵהוּ - זֶה צַדִּיק, שֶׁמִּמֶּנּוּ יוֹצְאוֹת בְּרָכוֹת בְּזִוּוּג. וְאַנְוֵהוּ - בְּאוֹתוֹ מָקוֹם שֶׁנִּמְצֵאת בּוֹ חֲבִיבוּת, וְזֶהוּ הַמִּקְדָּשׁ. אֱלֹהֵי אָבִי וַאֲרֹמֲמֶנְהוּ - מֹשֶׁה אָמַר אֶת זֶה לַמָּקוֹם שֶׁהַלְוִיִּם בָּאִים מֵאוֹתוֹ צַד, וְעַל זֶה (היה) שְׁלֵמוּת הַכֹּל הוּא בְּאוֹתוֹ מָקוֹם (בזה הפסוק).</p>\n<p>רַבִּי יִצְחָק אָמַר, וַיְהִי לִי לִישׁוּעָה - זֶה הַמֶּלֶךְ הַקָּדוֹשׁ, וְכָךְ הוּא. וּמִנַּיִן לָנוּ? מִקְרָא אַחֵר מָצָאנוּ לוֹ, שֶׁכָּתוּב כִּי עָזִּי וְזִמְרָת יָהּ ה' וַיְהִי לִי לִישׁוּעָה. מִמַּשְׁמָע שֶׁאָמַר ה' וַיְהִי לִי לִישׁוּעָה - זֶה הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>עָזִּי וְזִמְרָת יָהּ וְגוֹ'. רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, בְּפָסוּק זֶה שֶׁכָּתוּב (משלי יז) בְּכָל עֵת אֹהֵב הָרֵעַ וְאָח לְצָרָה יִוָּלֵד, בְּכָל עֵת אֹהֵב הָרֵעַ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב בּוֹ רֵעֲךְ וְרֵעַ אָבִיךְ אַל תַּעֲזֹב.</p>\n<p>וְאָח לְצָרָה יִוָּלֵד - בְּשָׁעָה שֶׁיָּצִיקוּ לְךְ שׂוֹנְאֶיךְ, מָה אוֹמֵר הַקָּדוֹשׁ בָּרוּךְ הוּא? (תהלים קכב) לְמַעַן אַחַי וְרֵעָי אֲדַבְּרָה נָּא שָׁלוֹם בָּךְ, שֶׁיִּשְׂרָאֵל נִקְרָאִים אַחִים וְרֵעִים לַקָבָּ\"ה. יִוָּלֵד מַה זֶּה? וְכִי עַכְשָׁו יִוָּלֵד? אֶלָּא בְּשָׁעָה שֶׁנּוֹלֶדֶת צָרָה בָּעוֹלָם, יִהְיֶה אָח כְּנֶגְדְּךְ לְהַצִּיל אוֹתְךְ מִכָּל אוֹתָם שֶׁמְּצִיקִים לְךְ.</p>\n<p>רַבִּי יְהוּדָה אָמַר, יִוָּלֵד - שֶׁהַמֶּלֶךְ הַקָּדוֹשׁ יִתְעוֹרֵר בָּעֹז הַזֶּה לִנְקֹם לְךְ מֵהָאֻמּוֹת, לְהֵינִיק לְךְ מֵהָאֵם בְּאוֹתוֹ צַד, כְּמוֹ שֶׁנֶּאֱמַר עָזִּי וְזִמְרָת יָהּ וַיְהִי לִי לִישׁוּעָה. לְעוֹרֵר גְּבוּרוֹת כְּנֶגֶד אֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת.</p>\n<p>רַבִּי יֵיסָא פָּתַח וְאָמַר, כַּמָּה יֵשׁ לָאָדָם לֶאֱהֹב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי אֵין לְךְ עֲבוֹדָה לַקָּדוֹשׁ- בָּרוּךְ-הוּא (אלא) (כמו) אֶלָּא אַהֲבָה, וְכָל מִי שֶׁאוֹהֵב אוֹתוֹ וְעוֹשֶׂה עֲבוֹדָתוֹ בְּאַהֲבָה, קוֹרֵא לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא אָהוּב. אִם כָּךְ, בַּמֶּה בֵּאַרְנוּ פְסוּקִים אֵלּוּ - רֵעֲךְ וְרֵעַ אָבִיךְ אַל תַּעֲזֹב, וְכָתוּב (משלי כה) הֹקַר רַגְלְךְ מִבֵּית רֵעֶךְ?</p>\n<p>אֶלָּא, הֲרֵי בֵּאֲרוּהָ הַחֲבֵרִים, פָּסוּק זֶה (בעולות ושלמים, וזה בחטאות ואשמות, וכתוב וכו') נִכְתָּב בְּעוֹלוֹת. עַכְשָׁו, רֵעֲךְ וְרֵעַ אָבִיךְ אַל תַּעֲזב, לַעֲבֹד אוֹתוֹ וּלְהִדָּבֵק בּוֹ וְלַעֲשׂוֹת מִצְווֹתָיו. אַל תַּעֲזֹב, וַדַּאי. וְזֶה שֶׁנֶּאֱמַר הֹקַר רַגְלְךְ מִבֵּית רֵעֶךְ. כְּלוֹמַר, הוֹקַר יִצְרְךְ שֶׁלֹּא יִרְתַּח כְּנֶגְדְּךְ וְלֹא יִשְׁלֹט בְּךְ, וְלֹא תַעֲשֶׂה הִרְהוּר אַחֵר. מִבֵּית רֵעֶךְ, מִי זֶה בֵּית רֵעֶךְ? זוֹ הַנְּשָׁמָה הַקְּדוֹשָׁה שֶׁהִכְנִיס בְּךְ רֵעֶךְ וְנָתַן אוֹתָהּ בְּתוֹכְךְ.</p>\n<p>וְעַל זֶה עֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא - לֶאֱהֹב אוֹתוֹ בַּכֹּל, כְּמוֹ שֶׁכָּתוּב (דברים ו) וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ. זֶה אֵלִי וְאַנְוֵהוּ - שֶׁכָּל יִשְׂרָאֵל רָאוּ עַל הַיָּם מַה שֶּׁלֹּא רָאָה יְחֶזְקֵאל הַנָּבִיא, וַאֲפִלּוּ אוֹתָם הָעֻבָּרִים שֶׁבִּמְעֵי אִמָּם הָיוּ רוֹאִים וּמְשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכֻלָּם הָיוּ אוֹמְרִים זֶה אֵלִי וְאַנְוֵהוּ אֱלֹהֵי אָבִי וַאֲרֹמֲמֶנְהוּ, כְּמוֹ שֶׁנֶּאֱמַר אֱלֹהֵי אַבְרָהָם.</p>\n<p>אָמַר רַבִּי יוֹסֵי, אִם כָּךְ, לָמָּה וַאֲרֹמֲמֶנְהוּ, שֶׁהֲרֵי אֱלֹהֵי אַבְרָהָם הוּא לְמַעְלָה? אָמַר לוֹ, אֲפִלּוּ כָּךְ צָרִיךְ, וְהַכֹּל דָּבָר אֶחָד, וַאֲרֹמֲמֶנְהוּ בַּכֹּל, לְהַכְלִיל מִי שֶׁיּוֹדֵעַ לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ הַגָּדוֹל, שֶׁהֲרֵי זוֹהִי עֲבוֹדָה עֶלְיוֹנָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>רַבִּי יְהוּדָה הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן, וְהוּא קוֹרֵא, כָּתוּב (ישעיה נב) קוֹל צֹפַיִךְ נָשְׂאוּ קוֹל יַחְדָּו יְרַנֵּנוּ. קוֹל צֹפַיִךְ, מִי הֵם צֹפַיִךְ? אֶלָּא אֵלֶּה הֵם שֶׁמְּצַפִּים מָתַי יְרַחֵם הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְנוֹת אֶת בֵּיתוֹ. נָשְׂאוּ קוֹל? יִשְׂאוּ קוֹל הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה נָשְׂאוּ קוֹל? אֶלָּא כָּל אָדָם שֶׁבּוֹכֶה וּמֵרִים קוֹלוֹ עַל חֻרְבַּן בֵּיתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, זוֹכֶה לְמַה שֶּׁכָּתוּב אַחַר כָּךְ - יַחְדָּו יְרַנֵּנוּ, וְזוֹכֶה לִרְאוֹתוֹ מְיֻשָּׁב בְּחֶדְוָה.</p>\n<p>בְּשׁוּב ה' צִיּוֹן?! הָיָה צָרִיךְ לִהְיוֹת בְּשׁוּב ה' אֶל צִיּוֹן! מַה זֶּה בְּשׁוּב ה' צִיּוֹן? אֶלָּא בְּשׁוּב ה' צִיּוֹן וַדַּאי. בֹּא רְאֵה, בְּשָׁעָה שֶׁחָרְבָה יְרוּשָׁלַיִם לְמַטָּה וּכְנֶסֶת יִשְׂרָאֵל גֹּרְשָׁה, עָלָה הַמֶּלֶךְ הַקָּדוֹשׁ לְצִיּוֹן, וְנֶאֱנַח כְּנֶגְדּוֹ, מִשּׁוּם שֶׁכְּנֶסֶת יִשְׂרָאֵל גֹּרְשָׁה, (עתה שגתגלתה כנסת ישראל, מעלה אותה אליו) וּכְשֶׁתַּחֲזֹר כְּנֶסֶת יִשְׂרָאֵל לִמְקוֹמָהּ, אָז יָשׁוּב הַמֶּלֶךְ הַקָּדוֹשׁ לְצִיּוֹן לִמְקוֹמוֹ לְהִזְדַּוֵּג אֶחָד בְּאֶחָד, וְזֶהוּ בְּשׁוּב ה' צִיּוֹן. וְאָז עֲתִידִים יִשְׂרָאֵל לוֹמַר זֶה אֵלִי וְאַנְוֵהוּ, וְכָתוּב זֶה ה' קִוִּינוּ לוֹ נָגִילָה וְנִשְׂמְחָה בִּישׁוּעָתוֹ, בִּישׁוּעָתוֹ וַדַּאי.</p>"],[9522011616,"<p>ה' אִישׁ מִלְחָמָה ה' שְׁמוֹ. רַבִּי אַבָּא פָּתַח, (במדברכא) עַל כֵּן יֵאָמַר בְּסֵפֶר מִלְחֲמֹת ה' אֶת וָהֵב בְּסוּפָה וְאֶת הַנְּחָלִים אַרְנוֹן. כַּמָּה יֵשׁ לָנוּ לְהִסְתַּכֵּל בְּדִבְרֵי הַתּוֹרָה, כַּמָּה יֵשׁ לָנוּ לְעַיֵּן בְּכָל דְּבָרֶיהָ, שֶׁאֵין לְךְ דָּבָר בַּתּוֹרָה שֶׁלֹּא נִרְמָז בַּשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן, וְאֵין לְךְ דָּבָר בַּתּוֹרָה שֶׁאֵין בּוֹ כַּמָּה סוֹדוֹת, כַּמָּה טְעָמִים, כַּמָּה שָׁרָשִׁים, כַּמָּה עֲנָפִים.</p>\n<p>כָּאן יֵשׁ לְהִסְתַּכֵּל, עַל כֵּן יֵאָמַר בְּסֵפֶר מִלְחֲמֹת ה' - וְכִי סֵפֶר מִלְחֲמוֹת ה' הֵיכָן הוּא? אֶלָּא כָּאן הִתְעוֹרְרוּ הַחֲבֵרִים, שֶׁכָּל מִי שֶׁעוֹרֵךְ קְרָב בַּתּוֹרָה, זוֹכֶה לְהַרְבּוֹת שָׁלוֹם בְּסוֹף דְּבָרָיו. כָּל הַקְּרָבוֹת שֶׁבָּעוֹלָם - קְטָטָה וְחֻרְבָּן, וְכָל הַקְּרָבוֹת שֶׁל הַתּוֹרָה - שָׁלוֹם וְאַהֲבָה. זֶהוּ שֶׁכָּתוּב עַל כֵּן יֵאָמַר בְּסֵפֶר מִלְחֲמֹת ה' וְאֶת וָהֵב בְּסוּפָה, כְּלוֹמַר, אַהֲבָה בְּסוֹפָהּ. שֶׁאֵין לְךְ אַהֲבָה וְשָׁלוֹם פְּרָט לָזֶה.</p>\n<p>עוֹד קָשֶׁה בִּמְקוֹמוֹ. עַל כֵּן יֵאָמַר בְּסֵפֶר מִלְחֲמֹת ה' - בְּתוֹרַת מִלְחֲמוֹת ה' הָיָה צָרִיךְ לִהְיוֹת! מַהוּ בְּסֵפֶר? אֶלָּא סוֹד עֶלְיוֹן הוּא. מָקוֹם יֵשׁ לַקָּדוֹשׁ-בָּרוּךְ-הוּא שֶׁנִּקְרָא סֵפֶר (ומספר), כְּמוֹ שֶׁנֶּאֱמַר דִּרְשׁוּ מֵעַל סֵפֶר ה' וּקְרָאוּ. שֶׁכָּל הַכֹּחוֹת וְהַגְּבוּרוֹת שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, תְּלוּיִים בְּאוֹתוֹ סֵפֶר, (ומשם יוצאים.</p>\n<p>את והב בסופה ובו) וּכְשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹרֵךְ אֶת קְרָבוֹתָיו, בְּמָקוֹם אֶחָד שֶׁהוּא בְּסוֹף הַדְּרָגוֹת, וְנִקְרָא וָהֵב, כְּמוֹ שֶׁנֶּאֱמַר (משליל) לַעֲלוּקָה שְׁתֵי בָנוֹת הַב הַב. בְּסוּפָה - נִמְצָא בְּסוֹף הַדְּרָגוֹת. בְּסוּפָה - נִקְרֵאת יַם סוּף, יָם שֶׁהוּא סוֹף הַדְּרָגוֹת.</p>\n<p>וְאֶת הַנְּחָלִים אַרְנוֹן, וְעִם הַנְּחָלִים שֶׁנִּמְצְאוּ וְנִמְשְׁכוּ לוֹ מֵאוֹתוֹ מָקוֹם עֶלְיוֹן שֶׁנִּקְרָא אַרְנוֹן. (מהו ארנון, ') זִוּוּג עֶלְיוֹן שֶׁל חֲבִיבוּת, שֶׁלֹּא נִפְרָדִים לְעוֹלָמִים, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן. וּבָזֶה נִשְׁרָשִׁים שָׁרָשָׁיו וּמִתְרַבִּים עֲנָפָיו, לְהוֹשִׁיט קְרָבוֹתָיו בְּכָל מָקוֹם, לְהוֹשִׁיט כֹּחוֹת וּגְבוּרוֹת, וּלְהַרְאוֹת שִׁלְטוֹן גָּדוֹל וְנִכְבָּד שֶׁל הַכֹּל.</p>\n<p>בֹּא רְאֵה, כְּשֶׁמִּתְעוֹרְרוֹת הַגְּבוּרוֹת וְהַקְּרָבוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כַּמָּה בַּעֲלֵי דִין מִתְעוֹרְרִים לְכָל עֵבֶר, וְאָז רְמָחִים שְׁנוּנִים וַחֲרָבוֹת, וּמְעוֹרְרִים גְּבוּרוֹת, וְהַיָּם מִתְרַגֵּשׁ, וְגַלָּיו עוֹלִים וְיוֹרְדִים, וְהָאֳנִיּוֹת שֶׁהוֹלְכוֹת וְשָׁטוֹת בַּיָּם, מִסְתַּלְּקוֹת לְכָל עֵבֶר. קְרָב (חרב) שָׁנוּן בְּאַבְנֵי בַּלִּסְטְרָאוֹת, בַּעֲלֵי רְמָחִים וַחֲרָבוֹת. אָז (תהלים מא) חִצֶּיךְ שְׁנוּנִים (מתעוררים להושיט קרבות בכל מקום ולהושיט כחות וגבורות לכל עבר, ואז הים מתרגש וגליו עולים, והאניות שהולכות ושטות יורדות ועולות, והזעף נמצא. ואז מתעוררים עורכי הקרב באבני בליסטראות, בעלי רמחים וחרבות, חצים וקשתות, כמו שגאמר חציך שנונים), וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְחַזֵּק בְּכֹחוֹ וּלְעוֹרֵר קְרָב. אוֹי לְאוֹתָם שֶׁהַמֶּלֶךְ הַקָּדוֹשׁ יְעוֹרֵר עֲלֵיֶם קְרָב. אָז כָּתוּב ה' אִישׁ מִלְחָמָה.</p>\n<p>וּמִכָּאן, וּמֵאוֹתָן אוֹתִיּוֹת, וּמִפָּסוּק זֶה, יוֹצְאִים הָרֵי קְרָבוֹת לְאוֹתָם רְשָׁעִים, לְאוֹתָם בַּעֲלֵי מְרִיבָה שֶׁחָטְאוּ לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְהָאוֹתִיּוֹת מִתְגַּלּוֹת לְאוֹתָם בַּעֲלֵי אֱמֶת, וַהֲרֵי הַדְּבָרִים הִתְפָּרְשׁוּ וַהֲרֵי נִתְבָּאֵר.</p>\n<p>ה' אִישׁ מִלְחָמָה ה' שְׁמוֹ. כֵּיוָן שֶׁכָּתוּב ה' אִישׁ מִלְחָמָה, לֹא יָדַעְנוּ שֶׁה' שְׁמוֹ? אֶלָּא, כְּמוֹ שֶׁכָּתוּב (בראשית יט) וַה' הִמְטִיר עַל סְדם וְעַל עֲמֹרָה גָּפְרִית וָאֵשׁ מִן הַשָּׁמָיִם. וְהַכֹּל תָּלוּי בַּסֵּפֶר הַזֶּה, כַּנֶּאֱמַר (איובב) יְגַלּוּ שָׁמַיִם עֲונוֹ וְאֶרֶץ מִתְקוֹמָמָה לוֹ. (ועל זה).</p>"],[9522011617,"<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְעוֹרֵר קְרָב בָּעוֹלָם, נֶעֱקָרִים מִמְּקוֹמָם עֶלְיוֹנִים וְתַחְתּוֹנִים, כְּמוֹ שֶׁבֵּאַרְנוּ, זֶהוּ שֶׁכָּתוּב מַרְכְּבֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם. וְלֶעָתִיד לָבא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲרֹךְ קְרָב עֶלְיוֹן וְחָזָק בָּעַמִּים כְּדֵי לְכַבֵּד אֶת שְׁמוֹ. זֶהוּ שֶׁכָּתוּב (זכריה יד) וְיָצָא ה' וְנִלְחַם בַּגּוֹיִם הָהֵם כְּיוֹם הִלָּחֲמוֹ בְּיוֹם קְרָב, וְכָתוּב (יחזקאל לח) וְהִתְגַּדִּלְתִּי וְהִתְקַדִּשְׁתִּי וְנוֹדַעְתִּי וְגוֹ'. (מרכבת פרעה וחילו ירה בים. כאשר יעורר הקדוש ברוך הוא קרב, אז יתעוררו דרגות עליונות ודרגות תחתונות שלמטה, ואז מרכבת פרעה וחילו ירה בים).</p>\n<p>רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים עז) רָאוּךְ מַּיִם אֱלֹהִים רָאוּךְ מַּיִם יָחִילוּ וְגוֹ'. בְּשָׁעָה שֶׁעָבְרוּ יִשְׂרָאֵל אֶת הַיָּם, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לַמַּלְאָךְ הַמְמֻנֶּה עַל הַיָּם: חַלֵּק מֵימֶיךְ! אָמַר לוֹ: לָמָּה? אָמַר לוֹ: כְּדֵי שֶׁבָּנַי יַעַבְרוּ בְתוֹכְךְ. אָמַר לוֹ: מִדַּת הַגְּאֻלָּה הִיא אֱמֶת, אֲבָל מַה שּׁוֹנִים אֵלֶּה מֵאֵלֶּה?</p>\n<p>עַל תְּנַאי זֶה עָשִׂיתִי אֶת הַיָּם כְּשֶׁבָּרָאתִי אֶת הָעוֹלָם. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? עוֹרֵר אֶת גְּבוּרָתוֹ וְנִקְמְטוּ הַמַּיִם. זֶהוּ שֶׁכָּתוּב רָאוּךְ מַּיִם אֱלֹהִים רָאוּךְ מַּיִם יָחִילוּ. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: הֲרֹג אֶת כָּל הָאוּכְלוּסִים הַלָּלוּ, וְאַחַר כָּךְ זְרֹק אוֹתָם הַחוּצָה, אַחַר כָּךְ כַּסֵּה הַיָּם עֲלֵיהֶם. זֶהוּ שֶׁכָּתוּב מַרְכְּבֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, צֵא רְאֵה כַּמָּה מֶרְכָּבוֹת עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה, כַּמָּה אוּכְלוּסִים, כַּמָּה חֲיָלוֹת, וְכֻלָּם קְשׁוּרִים אֵלּוּ בְּאֵלּוּ, (והרילמדנו) כָּל הַמֶּרְכָּבוֹת אֵלּוּ לְאֵלּוּ, דְּרָגוֹת עַל דְּרָגוֹת, וּמִצַּד הַשְּׂמֹאל מִתְעוֹרְרוֹת מֶרְכָּבוֹת (שלא) קְדוֹשׁוֹת שֶׁשּׁוֹלְטוֹת, וְכֻלָּן דְּרָגוֹת יְדוּעוֹת לְמַעְלָה.</p>\n<p>וַהֲרֵי בֵּאַרְנוּ בִּבְכוֹר פַּרְעֹה, שֶׁהוּא אַחַת הַדְּרָגוֹת שֶׁהָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא (דרגהשלו, נ\"אחילותיו) וְשָׁבַר אוֹתוֹ מִשַּׁלְשַׁלְתּוֹ הַחֲזָקָה, (ודרגתו) תַּחַת שִׁלְטוֹנוֹ כַּמָּה מֶרְכָּבוֹת וְכַמָּה חֲיָלוֹת שֶׁל גִּבּוֹרִים מִצַּד הַשְּׂמֹאל, מֵהֶם אֲחוּזִים בְּמָקוֹם עֶלְיוֹן שֶׁל הַשִּׁלְטוֹן שֶׁלָּהֶם, וּמֵהֶם אֲחוּזִים בַּמַּלְכוּת הָעֶלְיוֹנָה. מֵהֶם אֲחוּזִים אַחַר אַרְבָּעָה כִּסְאוֹת (החיות) (רחים), כְּמוֹ שֶׁנֶּאֱמַר.</p>\n<p>וְכֻלָּם נִמְסְרוּ בְיָדוֹ, בְּדִין הַמַּלְכוּת, שֶׁנִּקְרֵאת הַיָּם הַגָּדוֹל, לִשְׁבֹּר אוֹתָם מִדַּרְגָּתָם. וּכְשֶׁנִּשְׁבָּרִים לְמַעְלָה, כָּל אוֹתָם שֶׁלְּמַטָּה נִשְׁבָּרִים וְנֶאֱבָדִים בַּיָּם הַתַּחְתּוֹן. זֶהוּ שֶׁכָּתוּב מַרְכְּבת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם. בַּיָּם סְתָם.</p>\n<p>וּמִבְחַר שָׁלִשָׁיו טֻבְּעוּ בְיַם סוּף. וּמִבְחַר שָׁלִשָׁיו, הֲרֵי נִתְבָּאֵר, וְשָׁלִשִׁם עַל כֻּלּוֹ. כָּל הַדְּרָגוֹת - שְׁנַיִם וְאֶחָד. אֵלֶּה עַל אֵלֶּה. כְּגוֹן עֶלְיוֹן כָּךְ נַעֲשׂוּ. וְכֻלָּם נִמְסְרוּ בְיָדֶיה לְהִשָּׁבֵר מִשִּׁלְטוֹנָם אֵלֶּה וָאֵלֶּה.</p>\n<p>בֹּא רְאֵה, הֲרֵי נֶאֱמַר שֶׁכָּל עֶשֶׂר הַמַּכּוֹת שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם, הַכֹּל הָיָה יָד אַחַת, שֶׁהַשְּׂמֹאל כְּלוּלָה בַּיָּמִין. שֶׁעֶשֶׂר הָאֶצְבָּעוֹת כְּלוּלוֹת זוֹ בָּזוֹ, כְּנֶגֶד עֶשֶׂר אֲמִירוֹת שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא בָהֶם אַחַר כָּךְ. כְּנֶגְדּוֹ שֶׁל הַכֹּל זֶה שֶׁל הַיָּם חָזָק וְגָדוֹל וְשׁוֹלֵט, כְּמוֹ שֶׁנֶּאֱמַר וְהָאַחֲרוֹן הִכְבִּיד. זֶהוּ שֶׁכָּתוּב מַרְכְּבֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם וְגוֹ'. וְלֶעָתִיד לָבא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לַהֲרֹג אוּכְלוּסִים וְקוּזְתוּרְנָטִין וְקוֹנְטִירִיסִין וְקָלְטִירוֹלְסִין שֶׁל אֱדוֹם. זֶהוּ שֶׁכָּתוּב (ישעיה סג) מִי זֶה בָּא מֵאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה.</p>\n<p>מַרְכְּבֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם. רַבִּי יִצְחָק פָּתַח, (ירמיהי) לְקוֹל תִּתּוֹ הֲמוֹן מַיִם בַּשָּׁמַיִם וַיַּעֲלֶה נְשִׂאִים מִקְצֵה הָאָרֶץ בְּרָקִים לַמָּטָר עָשָׂה וַיּוֹצֵא רוּחַ מֵאֹצְרֹתָיו. הֲרֵי שָׁנִינוּ, שִׁבְעָה רְקִיעִים עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבְכָל רָקִיעַ וְרָקִיעַ כּוֹכָבִים קְבוּעִים שֶׁרָצִים בְּכָל רָקִיעַ וְרָקִיעַ, וּמֵעַל כֻּלָּם עֲרָבוֹת.</p>\n<p>וְכָל רָקִיעַ וְרָקִיעַ הִלּוּכוֹ מָאתַיִם שָׁנָה, וְרוּמוֹ חֲמֵשׁ מֵאוֹת שָׁנָה, וּבֵין רָקִיעַ לְרָקִיעַ חֲמֵשׁ מֵאוֹת שָׁנָה. וְהָעֲרָבוֹת הַזֶּה הִלּוּכוֹ בְּאָרְכּוֹ אֶלֶף וַחֲמֵשׁ מֵאוֹת שָׁנָה, וְרָחְבּוֹ אֶלֶף וַחֲמֵשׁ מֵאוֹת שָׁנָה, וּמִזִּיווֹ מְאִירִים כָּל אוֹתָם רְקִיעִים.</p>\n<p>וַהֲרֵי שָׁנִינוּ, מֵעַל לָעֲרָבוֹת רְקִיעַ הַחַיּוֹת. הַפְּרָסוֹת שֶׁל הַחַיּוֹת הַקְּדוֹשׁוֹת וְרוּמָם - כְּכֻלָּם. מֵעֲלֵיהֶם קַרְסֻלֵּי הַחַיּוֹת כְּכֻלָּם. שׁוֹקֵי הַחַיּוֹת כְּכֻלָּם. אַרְכֻּבֵּי הַחַיּוֹת כְּכֻלָּם. יַרְכֵי הַחַיּוֹת כְּכֻלָּם. עַגְבֵי הַחַיּוֹת כְּכֻלָּם. וְגוּף הַחַיּוֹת כְּכֻלָּם. כַּנְפֵיהֶם כְּכֻלָּם, וְהַצַּוָּאר שֶׁלָּהֶם כְּכֻלָּם. רָאשֵׁי הַחַיּוֹת כְּכֻלָּם. מַה זֶּה כְּמוֹ כֻלָּם? כְּנֶגֶד כֻּלָּם.</p>\n<p>וְכָל אֵיבָר וְאֵיבָר שֶׁבַּחַיּוֹת כְּנֶגֶד שִׁבְעָה תְהוֹמוֹת, וּכְנֶגֶד שִׁבְעָה הֵיכָלוֹת, וּכְנֶגֶד מִן הָאָרֶץ לָרָקִיעַ, וּכְנֶגֶד מֵרָקִיעַ לְרָקִיעַ, וְהַשִּׁעוּר שֶׁל כֻּלָּם וְרוּמָם עֶשְׂרִים וַחֲמִשָּׁה אֶלֶף חֲלָקִים מִשִּׁעוּרוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁבֵּאַרְנוּ.</p>\n<p>וְעוֹד רָקִיעַ אֶחָד לְמַעְלָה מִן קַרְנֵי הַחַיּוֹת, שֶׁכָּתוּב (יחזקאל א) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ. מִלְּמַטָּה כַּמָּה מֶרְכָּבוֹת, בְּיָמִין וּבִשְׂמֹאל.</p>\n<p>מִתַּחַת לַיָּם שְׁרוּיִים כָּל דְּגֵי הַיָּם וְשָׁטִים, מִתְכַּנְּסִים בְּאַרְבַּע בְּזִיוָם, יוֹרְדִים בְּדַרְגוֹתֵיהֶם, וְכָל הַמֶּרְכָּבוֹת נִקְרָאוֹת בְּשֵׁמוֹת. מִתַּחַת אֵלֶּה הוֹלְכִים וְשָׁטִים אוֹתָם קְטַנִּים, דְּרָגוֹת עַל דְּרָגוֹת, שֶׁכָּתוּב (תהלים קד) זֶה הַיָּם גָּדוֹל וּרְחַב יָדַיִם שָׁם רֶמֶשׂ וְאֵין מִסְפָּר חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת. וַהֲרֵי בֵּאַרְנוּ הַדְּבָרִים.</p>\n<p>מִצַד שְׂמֹאל הַתַּחְתּוֹן מֶמְשֶׁלֶת הַצַּד הָאַחֵר, וַאֲחוּזִים מֵאוֹתָם שֶׁלְּמַעְלָה, וְיָרְדוּ לְהִשָּׁבֵר מִכֹּחַ הֶחָזָק הַקָּדוֹשׁ, כְּמוֹ שֶׁבֵּאַרְנוּ מַרְכְּבֹת פַּרְעֹה וְחֵילוֹ וְגוֹ'.</p>"],[9522011618,"<p>יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ. אָמַר רַבִּי שִׁמְעוֹן, בְּשָׁעָה שֶׁהַבֹּקֶר מֵאִיר וְהָאַיֶּלֶת עוֹמֶדֶת בִּמְקוֹמָהּ, מִתְעַבֶּרֶת בְּצִדָּהּ, וְנִכְנֶסֶת לְמָאתַיִם הֵיכָלוֹת שֶׁל הַמֶּלֶךְ. הָאָדָם שֶׁמִּשְׁתַּדֵּל בַּחֲצוֹת הַלַּיְלָה בַּתּוֹרָה, בְּשָׁעָה שֶׁמִּתְעוֹרֶרֶת רוּחַ צָפוֹן (ותשוקת האילת) וְכוֹאֶבֶת הָאַיֶּלֶת לְהִתְעוֹרֵר בָּעוֹלָם, בָּא עִמָּהּ לַעֲמֹד לִפְנֵי הַמֶּלֶךְ, בְּשָׁעָה שֶׁמֵּאִיר הַבֹּקֶר (ואותו אדם מתפלל תפלתו וליחד השם הקדוש כראוי) מוֹשְׁכִים עָלָיו חוּט שֶׁל חֶסֶד.</p>\n<p>מִסְתַּכֵּל בָּרָקִיעַ, שׁוֹרֶה עָלָיו אוֹר הַהַשְׂכָּלָה שֶׁל דַּעַת הַקְּדוֹשָׁה, וּמִתְעַטֵּר בּוֹ הָאָדָם, וְכֻלָּם פּוֹחֲדִים מִמֶּנּוּ. אָז הָאָדָם הַזֶּה נִקְרָא בֵּן לַקָּדוֹשׁ-בָּרוּךְ-הוּא, בֶּן הֵיכַל הַמֶּלֶךְ. נִכְנָס לְכָל שְׁעָרָיו, וְאֵין מוֹחֶה בְּיָדוֹ.</p>\n<p>בְּשָׁעָה שֶׁקּוֹרֵא לְהֵיכַל הַמֶּלֶךְ, כָּתוּב עָלָיו (תהלים קמה) קָרוֹב ה' לְכָל קֹרְאָיו לְכֹל אֲשֶׁר יִקְרָאֻהוּ בֶאֱמֶת. מַה זֶּה בֶּאֱמֶת? כְּמוֹ שֶׁבֵּאַרְנוּ, (מיכה ז) תִּתֵּן אֱמֶת לְיַעֲקֹב, שֶׁיּוֹדֵעַ לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ בִּתְפִלָּתוֹ (בעולם) כָּרָאוּי, וְזוֹ עֲבוֹדָתוֹ שֶׁל (השם) הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>וּמִי שֶׁיּוֹדֵעַ לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי, מַעֲמִיד אֻמָּה יְחִידָה בָּעוֹלָם, שֶׁכָּתוּב (שמואל ב ז) וּמִי כְעַמְּךְ יִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ. וְעַל זֶה בֵּאַרְנוּ, כָּל כֹּהֵן שֶׁלֹּא יוֹדֵעַ לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי, אֵין עֲבוֹדָתוֹ עֲבוֹדָה, שֶׁהֲרֵי הַכֹּל תָּלוּי בּוֹ, עֲבוֹדָה עֶלְיוֹנָה וַעֲבוֹדָה תַחְתּוֹנָה. וְצָרִיךְ לְכַוֵּן לֵב וְרָצוֹן כְּדֵי שֶׁיִּתְבָּרְכוּ עֶלְיםנִים וְתַחְתּוֹנִים.</p>\n<p>כָּתוּב (ישעיה א) כִּי תָבֹאוּ לֵרָאוֹת פָּנָי. כָּל אָדָם שֶׁבָּא לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ, וְלֹא מִתְכַּוֵּן בּוֹ בַּלֵּב וְרָצוֹן וְיִרְאָה כְּדֵי שֶׁיִּתְבָּרְכוּ בוֹ עֶלְיוֹנִים וְתַחְתּוֹנִים, זוֹרְקִים אֶת תְּפִלָּתוֹ הַחוּצָה, וְכֻלָּם מַכְרִיזִים עָלָיו לְרַע. וְהַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא עָלָיו, כִּי תָבֹאוּ לֵרָאוֹת פָּנָי.</p>\n<p>כִּי תָבאוּ לִרְאוֹת הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה לֵרָאוֹת פָּנָי? אֶלָּא כָּל פְּנֵי הַמֶּלֶךְ הַלָּלוּ גְּנוּזִים בְּעֹמֶק (במקום) אַחַר הַחֲשֵׁכָה (ישתחשך סתרו וכל וכו'), וְכָל אוֹתָם שֶׁיּוֹדְעִים לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי מִתְבַּקְּעִים כָּל אוֹתָם כָּתְלֵי הַחֲשֵׁכָה, וּפְנֵי הַמֶּלֶךְ נִרְאִים וּמְאִירִים לַכֹּל. וּכְשֶׁהֵם נִרְאִים וּמְאִירִים, כָּל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים מִתְבָּרְכִים, וְאָז נִמְצָאוֹת בְּרָכוֹת בְּכָל הָעוֹלָמוֹת, וְאָז כָּתוּב לֵרָאוֹת פָּנָי.</p>\n<p>מִי בִקֵּשׁ זֹאת מִיֶּדְכֶם, מַה זֶּה אוֹמֵר? אֶלָּא מִי שֶׁבָּא לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן, צָרִיךְ לְיַחֵד מִצַּד שֶׁל זאת, כְּמוֹ שֶׁכָּתוּב (ויקרא טז) בזאת יבא אהרן אל הקדש. כדי שיזדוגו כאחד אותם השנים, צדיק וצדק בזווג אחד, כדי שיתברכו הכל מהם, ואלה נקראים חצריך, ככתוב (תהלים סה) אשרי תבחר ותקרב ישכן חצריך.</p>\n<p>וְאִם הוּא בָּא לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ, וְלֹא מִתְכַּוֵּן בּוֹ בִּרְצוֹן הַלֵּב, בְּיִרְאָה וְאַהֲבָה - הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר, מִי בִקֵּשׁ זאת מִיֶּדְכֶם רְמֹס חֲצֵרָי. זֹאת וַדַּאי, שֶׁהֲרֵי לֹא נִמְצָא בָהֶם בְּרָכוֹת. וְלֹא דַי שֶׁלֹּא נִמְצָא בָהֶם בְּרָכוֹת, אֶלָּא שֶׁשָּׁרוּי בָהֶם הַדִּין וְנִמְצָא דִּין בַּכֹּל.</p>\n<p>בֹּא רְאֵה, מִימִינוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעוֹרְרִים כָּל הָאוֹרוֹת, כָּל הַבְּרָכוֹת וְכָל שִׂמְחָה. בּוֹ כָּלוּל הַשְּׂמֹאל, כְּמוֹ שֶׁיֵּשׁ בָּאָדָם יָמִין וּשְׂמֹאל, וְהַשְּׂמֹאל נִכְלָל בַּיָּמִין, וְהַיָּמִין כּוֹלֵל אֶת הַכֹּל. וּכְשֶׁמִּתְעוֹרֵר הַיָּמִין, מִתְעוֹרֵר עִמּוֹ הַשְּׂמֹאל, שֶׁהֲרֵי בּוֹ הוּא אָחוּז וְכָלוּל.</p>\n<p>וּבֹא רְאֵה, בְּשָׁעָה שֶׁאָדָם מֵרִים אֶת יָדָיו בַּתְּפִלָּה וּמְכַוֵּן בְּאֶצְבְּעוֹתָיו לְמַעְלָה, כַּכָּתוּב (שמות יז) וְהָיָה כַּאֲשֶׁר יָרִים מֹשֶׁה יָדוֹ וְגָבַר יִשְׂרָאֵל. שֶׁהֲרֵי בַּיָּמִין הַכֹּל תָּלוּי, וְכָתוּב (ויקראט) וַיִּשָּׂא אַהֲרֹן אֶת יָדָו, וְכָתוּב חָסֵר, וְאָז מִתְכַּוֵּן לְבָרֵךְ לְמַעְלָה.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךָ הוּא לֹא כָּךְ - בְּשָׁעָה שֶׁמֵּרִים יָמִין לְמַעְלָה, אוֹי לַתַּחְתּוֹנִים! שֶׁהֲרֵי כָּל הַסִּיּוּעַ, וְכָל הַבְּרָכוֹת מִסְתַּלְּקִים מֵהֶם. מִנַּיִן לָנוּ? שֶׁכָּתוּב נָטִיתָ יְמִינְךְ תִּבְלָעֵמוֹ אָרֶץ. מַה זֶּה נָטִיתָ יְמִינְךְ? כְּתַרְגּוּמוֹ, הֵרַמְתָּ יְמִינְךְ. מִיָּד תִּבְלָעֵמוֹ אָרֶץ. וּכְשֶׁיָּמִין נִמְצֵאת, הַשְּׂמֹאל נִמְצָא עִמּוֹ, וְאָז לֹא שׁוֹלְטִים הַדִּינִים בָּעוֹלָם. מָה הַטַּעַם? מִשּׁוּם שֶׁהַיָּמִין נִמְצָא עִמּוֹ, וְאִם הַיָּמִין מִסְתַּלֶּקֶת, הֲרֵי מִזְדַּמֶּנֶת הַשְּׂמֹאל, וְאָז מִתְעוֹרְרִים דִּינִים בָּעוֹלָם, וְהַדִּין שָׁרוּי בַּכֹּל.</p>\n<p>כְּשֶׁרַבִּי שִׁמְעוֹן הָיָה מַגִּיעַ לַפָּסוּק הַזֶּה, הָיָה בּוֹכֶה, שֶׁכָּתוּב (איכה ב) הֵשִׁיב אָחוֹר יְמִינוֹ. וְכִי אֶפְשָׁר שֶׁהֵשִׁיב אָחוֹר יְמִינוֹ? אֶלָּא מִשּׁוּם שֶׁהִקְדִּים הַשְּׂמֹאל לָרֶדֶת לָעוֹלָם, וְהַיָּמִין נִשְׁאֲרָה בְּמָקוֹם אַחֵר.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב (ישעיה נו) הַצַּדִּיק אָבָד. וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים, לֹא כָתוּב הַצַּדִּיק נֶאֱבַד, אֶלָּא הַצַּדִּיק אָבָד. מִכָּל אוֹתָם פְּנֵי הַמֶּלֶךְ לֹא נִמְצָא שֶׁאָבַד אֶלָּא צַדִּיק. אָבַד בִּשְׁנֵי צְדָדִים: אֶחָד - שֶׁלֹּא שׁוֹרוֹת בּוֹ בְּרָכוֹת כְּבַתְּחִלָּה, וְאֶחָד - שֶׁהִתְרַחֲקָה מִמֶּנּוּ בַּת זוּגוֹ שֶׁהִיא כְּנֶסֶת יִשְׂרָאֵל. נִמְצָא שֶׁהַצַּדִּיק אָבַד יוֹתֵר מִכֹּל, וְלֶעָתִיד לָבֹא כָּתוּב (זכריה ט) גִּילִי מְאֹד בַּת צִיּוֹן הָרִיעִי בַּת יְרוּשָׁלם הִנֵּה מַלְכֵּךְ יָבוֹא לָךְ צַדִּיק וְנוֹשָׁע הוּא. צַדִּיק וּמוֹשִׁיעַ לֹא כָתוּב, אֶלָּא צַדִּיק וְנוֹשָׁע הוּא. הוּא נוֹשָׁע וַדַּאי, וַהֲרֵי זֶה נִתְבָּאֵר.</p>\n<p>יְמִינְךָ ה' נֶאְדָּרִי בַּכֹּחַ. מַה זֶּה נֶאְדָּרִי? הָיָה צָרִיךְ לִהְיוֹת נֶאְדָּר! אֶלָּא בְּשָׁעָה שֶׁשְּׂמֹאל בָּא לְהִזְדַּוֵּג בַּיָּמִין, אָז כָּתוּב נֶאְדָּרִי, תִּרְעַץ, (בכח, שנים, ולעולם וכו') וּלְעוֹלָם זֶה כָּךְ, מִשּׁוּם שֶׁשְּׂמֹאל נִמְצָא בְּיָמִין וְנִכְלָל בּוֹ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כְּמוֹ שֶׁבֵּאַרְנוּ - כָּךְ זֶה, שֶׁאָדָם נִמְצָא שֶׁנֶּחֱלַק. מָה הַטַּעַם? כְּדֵי לְקַבֵּל עִמּוֹ בַּת זוּגוֹ שֶׁיֵּעָשׂוּ גוּף אֶחָד מַמָּשׁ. כְּשֶׁיְּמִינְךְ, נִמְצָא שֶׁנֶּחֱלַק. מָה הַטַּעַם? כְּדֵי לְקַבֵּל עִמּוֹ שְׂמֹאל. וְכָךְ זֶה הַכֹּל, אֶחָד בְּאֶחָד. וְעַל זֶה בְּאֶחָד מַכֶּה וּמְרַפֵּא. זֶהוּ שֶׁכָּתוּב יְמִינְךְ ה' תִּרְעַץ אוֹיֵב.</p>\n<p>בֹּא רְאֵה, שִׁירָה זוֹ נֶאֶמְרָה עַל אוֹתוֹ זְמַן וְעַל הַזְּמַן שֶׁיָּבא לֶעָתִיד, בַּיָּמִים שֶׁיִּתְעוֹרֵר מֶלֶךְ הַמָּשִׁיחַ, שֶׁכָּתוּב יְמִינְךְ ה' תִּרְעַץ אוֹיֵב. לֹא כָתַב רָעַצְתָּ, אֶלָּא תִּרְעַץ. מַה כָּתוּב בַּתְּחִלָּה? (איכה ב) הֵשִׁיב אָחוֹר יְמִינוֹ מִפְּנֵי אוֹיֵב. בְּאוֹתוֹ זְמַן הִיא תִּרְעַץ אוֹיֵב לֶעָתִיד לָבֹא.</p>\n<p>וְהַכֹּל כָּךְ הוּא. תַּהֲרֹס קָמֶיךְ - לֹא כָתוּב הָרַסְתָּ, אֶלָּא תַּהֲרֹס. תְּשַׁלַּח חֲרֹנְךְ יֹאכְלֵמוֹ כַּקַּשׁ. הַכֹּל לֶעָתִיד לָבא. יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ - בַּזְּמַן הַזֶּה, בָּעוֹלָם הַזֶּה. יְמִינְךְ ה' תִּרְעַץ אוֹיֵב - בִּזְמַן מֶלֶךְ הַמָּשִׁיחַ. וּבְרֹב גְּאֹנְךְ תַּהֲרֹס קָמֶיךְ - לְבִיאַת גּוֹג וּמָגוֹג. תְּשַׁלַּח חֲרֹנְךְ יֹאכְלֵמוֹ כַּקַּשׁ - לִתְחִיַּת הַמֵּתִים, שֶׁכָּתוּב (דניאל יב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת וּלְדִרְאוֹן עוֹלָם.</p>\n<p>בְּאוֹתוֹ זְמַן, אָמַר רַבִּי שִׁמְעוֹן, אַשְׁרֵי אוֹתָם שֶׁיִּשָּׁאֲרוּ בָּעוֹלָם. וּמִי הֵם? בּא רְאֵה, לֹא יִשָּׁאֲרוּ בָּעוֹלָם רַק אוֹתָם מְהוּלִים, שֶׁקִּבְּלוּ אוֹת בְּרִית הַקָּדוֹשׁ, וְנִכְנְסוּ לַבְּרִית הַקָּדוֹשׁ בְּאוֹתָם שְׁנֵי חֲלָקִים, כְּמוֹ שֶׁבֵּאַרְנוּ, והוּא שׁוֹמֵר אֶת אוֹתוֹ הַבְּרִית וְלֹא מַכְנִיסוֹ לְמָקוֹם שֶׁלֹּא צָרִיךְ. אֵלֶּה הֵם יִשָּׁאֲרוּ וְיִכָּתְבוּ לְחַיֵּי עוֹלָם.</p>\n<p>מִנַּיִן לָנוּ? שֶׁכָּתוּב (ישעיה ד) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלם קָדוֹשׁ יֵאָמֶר לוֹ כָּל הַכָּתוּב לַחַיִּים בִּירוּשָׁלם. מַשְׁמָע הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלַם, שֶׁכָּל מִי שֶׁנִּמּוֹל, בִּשְׁתֵּי הַדְּרָגוֹת הַלָּלוּ נִכְנָס. וְאִם שׁוֹמֵר אוֹתוֹ בְּרִית כָּרָאוּי וְיִזָּהֵר בּוֹ, עָלָיו כָּתוּב הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלם. אֵלּוּ יִשָּׁאֲרוּ לְאוֹתוֹ זְמַן, וּבָהֶם עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְחַדֵּשׁ אֶת הָעוֹלָם וְלִשְׂמֹחַ בָּהֶם. עַל אוֹתוֹ זְמַן כָּתוּב, (תהלים קד) יְהִי כְבוֹד ה' לְעוֹלָם יִשְׂמַח ה' בְּמַעֲשָׂיו.</p>\n<p>רַבִּי חִיָּיא הָיָה הוֹלֵךְ לְרַבִּי אֶלְעָזָר. מְצָאוֹ שֶׁהָיָה יוֹשֵׁב אֵצֶל רַבִּי יוֹסֵי בְּרַבִּי שִׁמְעוֹן בֶּן לָקוֹנְיָא חָמִיו. עַד שֶׁהֵרִים רֹאשׁוֹ, רָאָה אֶת רַבִּי חִיָּיא. אָמַר, (ישעיה יט) בַּיּוֹם הַהוּא יִהְיֶה יִשְׂרָאֵל שְׁלִישִׁיָּה לְמִצְרַיִם וּלְאַשּׁוּר בְּרָכָה בְּקֶרֶב הָאָרֶץ אֲשֶׁר בֵּרְכוֹ ה' צְבָאוֹת לֵאמֹר בָּרוּךְ עַמִּי מִצְרַיִם וּמַעֲשֵׂה יָדַי אַשּׁוּר וְנַחֲלָתִי יִשְׂרָאֵל. (וכי אשור ומצרים הם קרובים לקדוש'ברוך' הוא,</p>\n<p>אלא, על הגלות שתעלה ממצרים ומאשור זה נאמר. ואם נאמר על מצרים ועל אשור על אותם חסידים שלהם שחזרו בתשובה ונשארו לעבד את ישראל ואת מלך המשיח, שכתוב (תהלים עב) וישתחוו לו כל מלכים, וכתוב והיו מלכים אמניך וגו'.</p>\n<p>אמר לו, מה זה שכתוב דרכיה דרכי נעם? אמר לו, כמה טפשים) בְּנֵי הָעוֹלָם שֶׁלֹּא יוֹדְעִים וְלֹא מַשְׁגִּיחִים בְּדִבְרֵי תוֹרָה, שֶׁהֲרֵי דִּבְרֵי תוֹרָה (כמה סודות עליוניםישבהם) הֵם דֶּרֶךְ לִזְכּוֹת בְּאוֹתוֹ נֹעַם ה', שֶׁכָּתוּב דְּרָכֶיהָ דַּרְכֵי נֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם. דַּרְכֵי נֹעַם וַדַּאי. מַה זֶּה נֹעַם? כְּמוֹ שֶׁכָּתוּב (תהלים כז) לַחֲזוֹת בְּנֹעַם ה', וַהֲרֵי פֵּרְשׁוּהָ, מִשּׁוּם (כך) שֶׁהַתּוֹרָה וּדְרָכֶיהָ בָּאִים מֵאוֹתוֹ נֹעַם, וְאוֹתָן דְּרָכִים מְפֹרָשׁוֹת בָּהּ, וְעַל זֶה דְּרָכֶיהָ דַּרְכֵי נֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם.</p>\n<p>אָמַר רַבִּי חִיָּיא, שָׁנִינוּ, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן תּוֹרָה לְיִשְׂרָאֵל, יָצָא אוֹר מֵאוֹתוֹ נֹעַם, וְהִתְעַטֵּר בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמֵאוֹתוֹ נֹעַם הִבְהִיקוּ זִיוָם שֶׁל כָּל הָעוֹלָמוֹת, שֶׁל כָּל הָרְקִיעִים, שֶׁל כָּל הַכְּתָרִים. עַל אוֹתָהּ שָׁעָה כָּתוּב (שיר ג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה וְגוֹ'.</p>\n<p>וְאוֹתָהּ שָׁעָה שֶׁנִּבְנָה הַמִּקְדָּשׁ, הִתְעַטֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָהּ עֲטָרָה, וְיָשַׁב בְּכִסְאוֹ וְהִתְעַטֵּר בְּעַטְרוֹתָיו. וּמֵאוֹתוֹ זְמַן שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, לֹא הִתְעַטֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעַטְרוֹתָיו, וְאוֹתוֹ נֹעַם הִתְכַּסָּה וְנִגְנַז.</p>"],[9522011619,"<p>אָמַר רַבִּי אֶלְעָזָר, בְּשָׁעָה שֶׁנִּכְנַס מֹשֶׁה לְתוֹךְ הֶעָנָן, כַּכָּתוּב (שמות כד) וַיָּבא מֹשֶׁה בְּתוֹךְ הֶעָנָן, כְּאָדָם שֶׁהָיָה הוֹלֵךְ בְּמָקוֹם שֶׁל רוּחַ, וּפָגַשׁ בּוֹ מַלְאָךְ גָּדוֹל אֶחָד. וְשָׁנִינוּ שֶׁשְּׁמוֹ קְמוּאֵ\"ל, וְהוּא מְמֻנֶּה עַל שְׁנֵים עָשָׂר אֶלֶף מְמֻנִּים שְׁלִיחִים. רָצָה לְהִזְדַּוֵּג בְּמֹשֶׁה. פָּתַח מֹשֶׁה פִּיו בִּשְׁתֵּים עֶשְׂרֵה אוֹתִיּוֹת חֲקוּקוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁלִּמֵּד אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בַּסְּנֶה, וְהִתְרַחֵק מִמֶּנּוּ שְׁתֵּים עֶשְׂרֵה אֶלֶף פַּרְסוֹת, וְהָיָה מֹשֶׁה הוֹלֵךְ בֶּעָנָן, וְעֵינָיו לוֹהֲטוֹת כְּגַחֲלֵי אֵשׁ.</p>\n<p>עַד שֶׁפָּגַשׁ בּוֹ מַלְאָךְ אֶחָד גָּדוֹל וְנִכְבָּד מִן הַקֹּדֶם, וְשָׁנִינוּ שֶׁשְּׁמוֹ הֲדַרְנִיאֵ\"ל, וְהוּא עֶלְיוֹן עַל כָּל שְׁאָר הַמַּלְאָכִים אֶלֶף וְשִׁשִּׁים רִבּוֹא פַּרְסוֹת, וְקוֹלוֹ הוֹלֵךְ בְּמָאתַיִם אֶלֶף רְקִיעִים שֶׁמֻּקָּפִים בְּאֵשׁ לְבָנָה. כֵּיוָן שֶׁרָאָהוּ מֹשֶׁה, לֹא יָכֹל לְדַבֵּר. רָצָה לִזְרֹק אֶת עַצְמוֹ מִתּוֹךְ הֶעָנָן.</p>\n<p>אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, מֹשֶׁה, וְכִי אַתָּה שֶׁהִרְבִּיתָ דְּבָרִים עִמִּי בַּסְּנֶה, שֶׁרָצִיתָ לָדַעַת אֶת סוֹד הַשֵּׁם הַקָּדוֹשׁ וְלֹא פָחַדְתָּ, וְעַכְשָׁו אַתָּה פּוֹחֵד מֵאֶחָד מִשַּׁמָּשַׁי? כֵּיוָן שֶׁשָּׁמַע מֹשֶׁה אֶת קוֹל הַקָּדוֹשׁ בָּרוּךְ הוּא, הִתְחַזֵּק. פָּתַח פִּיו בְּשִׁבְעִים וּשְׁתַּיִם אוֹתִיּוֹת הַשֵּׁם הָעֶלְיוֹן. כֵּיוָן שֶׁשָּׁמַע הֲדַרְנִיאֵ\"ל אֶת אוֹתִיּוֹת הַשֵּׁם הַקָּדוֹשׁ מִפִּי מֹשֶׁה, הִזְדַּעֲזַע. קָרַב אֵלָיו וְאָמַר לוֹ: אַשְׁרֵי חֶלְקְךְ, מֹשֶׁה, שֶׁהִתְגַּלָּה לְךְ מַה שֶּׁלֹּא הִתְגַּלָּה לַמַּלְאָכִים הָעֶלְיוֹנִים.</p>\n<p>וְהָיָה הוֹלֵךְ עִמּוֹ, עַד שֶׁהִגִּיעוּ לְאֵשׁ חֲזָקָה שֶׁל מַלְאָךְ אֶחָד שֶׁשְּׁמוֹ סַנְדַּלְפוֹ\"ן. וְשָׁנִינוּ, סַנְדַּלְפוֹן עֶלְיוֹן הוּא עַל שְׁאָר חֲבֵרָיו חֲמֵשׁ מֵאוֹת שָׁנָה, וְהוּא עוֹמֵד אַחַר הַפַּרְגּוֹד שֶׁל רִבּוֹנוֹ, וְקוֹשֵׁר לוֹ כְּתָרִים מִבַּקָּשׁוֹתֵיהֶם שֶׁל הַתְּפִלָּה שֶׁל יִשְׂרָאֵל. וּבְשָׁעָה שֶׁמַּגִּיעַ הַכֶּתֶר הַזֶּה לְרֹאשׁ הַמֶּלֶךְ הַקָּדוֹשׁ, הוּא מְקַבֵּל אֶת תְּפִלּוֹת יִשְׂרָאֵל, וְכָל הַחֲיָלוֹת וְהַהֲמוֹנִים מִזְדַּעְזְעִים, וְנוֹהֲמִים וְאוֹמְרִים: בָּרוּךְ כְּבוֹד ה' מִמְּקוֹם בֵּית שְׁכִינָתוֹ.</p>\n<p>אָמַר לוֹ הֲדַרְנִיאֵל לְמֹשֶׁה, מֹשֶׁה, אֵינֶנִּי יָכוֹל לָלֶכֶת עִמְּךְ, שֶׁלֹּא תִשְׂרֹף אוֹתִי הָאֵשׁ הַחֲזָקָה שֶׁל סַנְדַּלְפוֹן. בְּאוֹתָהּ שָׁעָה הִזְדַּעֲזַע מֹשֶׁה, עַד שֶׁהֶחֱזִיק הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמֹשֶׁה, וְהוֹשִׁיבוֹ לְפָנָיו וְלִמֵּד אוֹתוֹ תּוֹרָה. וְכִסָּה אֶת מֹשֶׁה בְּאוֹתוֹ אוֹר וְזִיו שֶׁל אוֹתוֹ נֹעַם, וְהָיוּ פָנָיו שֶׁל מֹשֶׁה מְאִירִים בְּכָל אוֹתָם הָרְקִיעִים, וְכָל חֵיל הַשָּׁמַיִם הָיוּ מִזְדַּעְזְעִים לְפָנָיו בְּשָׁעָה שֶׁהָיָה מוֹרִיד תּוֹרָה.</p>\n<p>כֵּיוָן שֶׁחָטְאוּ יִשְׂרָאֵל לְמַטָּה, נָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא (ממשה) אֶלֶף חֲלָקִים מֵאוֹתוֹ זִיו. בְּאוֹתָהּ שָׁעָה רָצוּ מַלְאָכִים עֶלְיוֹנִים, וְכָל אוֹתָם הֲמוֹנִים, לִשְׂרֹף אֶת מֹשֶׁה בְּשָׁעָה שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא (שמות לב) לֶךְ רֵד כִּי שִׁחֵת עַמְּךְ. הִזְדַּעֲזַע מֹשֶׁה וְלֹא יָכֹל לְדַבֵּר, עַד שֶׁהִרְבָּה בִּתְפִלּוֹת וּבַקָּשׁוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, מֹשֶׁה, הַחֲזֵק בְּכִסְאִי! עַד שֶׁגָּעַר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל אוֹתָם הֲמוֹנִים וּבְכָל אוֹתָם חֲיָלוֹת, וְהֶחֱזִיק מֹשֶׁה בִּשְׁנֵי לוּחוֹת הָאֲבָנִים, וְהוֹרִיד אוֹתָם לְמַטָּה, וְזֶהוּ שֶׁכָּתוּב (משלי כא) עִיר גִּבֹּרִים עָלָה חָכָם וַיֹּרֶד עֹז מִבְטֶחָה. וּמֵאוֹתוֹ זִיו שֶׁנִּשְׁאַר בּוֹ, הָיוּ פְּנֵי מֹשֶׁה מַבְהִיקִים. וּמַה בְּאוֹתוֹ שֶׁנִּשְׁאַר בּוֹ לֹא הָיוּ יְכוֹלִים לְהִסְתַּכֵּל בְּפָנָיו - בְּאוֹתוֹ שֶׁהִסְתַּלֵּק מִמֶּנּוּ עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>רַבִּי חִיָּיא אָמַר, יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ - זוֹ הַתּוֹרָה. וְעַל זֶה יְמִינְךְ ה' תִּרְעַץ אוֹיֵב. שֶׁאֵין דָּבָר בָּעוֹלָם שֶׁיִּשְׁבֹּר כֹּחָם שֶׁל עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת פְּרָט לְשָׁעָה שֶׁיִּשְׂרָאֵל מִתְעַסְּקִים בַּתּוֹרָה. שֶׁכָּל זְמַן שֶׁיִּשְׂרָאֵל מִתְעַסְּקִים בַּתּוֹרָה, הַיָּמִין מִתְחַזֵּק, וְנִשְׁבָּר כֹּחַ וְתֹקֶף שֶׁל עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. וְלָכֵן הַתּוֹרָה נִקְרֵאת עֹז, כְּמוֹ שֶׁנֶּאֱמַר (תהלים כט) ה' עֹז לְעַמּוֹ יִתֵּן.</p>\n<p>וּבְשָׁעָה שֶׁיִּשְׂרָאֵל לֹא מִתְעַסְּקִים בַּתּוֹרָה - מִתְחַזֵּק הַשְּׂמֹאל, וּמִתְחַזֵּק כֹּחַ שֶׁל עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, וְשׁוֹלְטִים עֲלֵיהֶם, וְגוֹזְרִים עֲלֵיהֶם גְּזֵרוֹת שֶׁלֹּא יְכוֹלִים לַעֲמֹד בָּהֶם, וְעַל זֶה הֻגְלוּ בְּנֵי יִשְׂרָאֵל וְהִתְפַּזְּרוּ בֵּין הָעַמִּים.</p>\n<p>זֶהוּ זֶה שֶׁכָּתוּב, עַל מָה אָבְדָה הָאָרֶץ וְגוֹ', וַיֹּאמֶר ה' עַל עָזְבָם אֶת תּוֹרָתִי. שֶׁהֲרֵי כָּל זְמַן שֶׁיִּשְׂרָאֵל יִשְׁתַּדְּלוּ בַּתּוֹרָה, נִשְׁבָּר כֹּחַ וְתָקְפָּם שֶׁל עוֹבְדֵי עֲבוֹדָה זָרָה, זֶהוּ שֶׁכָּתוּב יְמִינְךְ ה' תִּרְעַץ אוֹיֵב. אָמַר רַבִּי אֶלְעָזָר, וַדַּאי כָּךְ הוּא, שֶׁכָּל זְמַן שֶׁקּוֹלָם שֶׁל יִשְׂרָאֵל נִשְׁמָע בְּבָתֵּי כְנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת וְכוּ', כְּמוֹ שֶׁשָּׁנִינוּ (בראשית כז) הַקֹּל קוֹל יַעֲקֹב. וְאִם לֹא, אָז הַיָּדַיִם יְדֵי עֵשָׂו, וַהֲרֵי בֵּאַרְנוּ.</p>"],[9522011620,"<p>וּבְרֹב גְּאוֹנְךְ תַּהֲרֹס קָמֶיךְ. רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, (תהלים י) לָמָה ה' תַּעֲמֹד בְּרָחוֹק תַּעְלִים לְעִתּוֹת בַּצָּרָה. בְּשָׁעָה שֶׁחֲטָאֵי הָעוֹלָם גּוֹרְמִים, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹלֶה לְמַעְלָה לְמַעְלָה, וּבְנֵי אָדָם צוֹוְחִים וּמוֹרִידִים דְּמָעוֹת וְאֵין מִי שֶׁיַּשְׁגִּיחַ עֲלֵיהֶם. מָה הַטַּעַם? מִשּׁוּם שֶׁהוּא עוֹלֶה לְמַעְלָה לְמַעְלָה, וְנִמְנַעַת מֵהֶם תְּשׁוּבָה, וְאָז כָּתוּב וּבְרֹב גְּאוֹנְךְ תַּהֲרֹס קָמֶיךְ.</p>\n<p>רַבִּי יִצְחָק אָמַר, פָּסוּק זֶה, בְּשָׁעָה שֶׁמִּתְלַבֵּשׁ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגַאֲוָה עַל הָעַמִּים שֶׁיִּתְכַּנְּסוּ עָלָיו, כְּמוֹ שֶׁכָּתוּב (שם ב) וְרוֹזְנִים נוֹסְדוּ יָחַד עַל ה' וְעַל מְשִׁיחוֹ. וְלָמַדְנוּ, עֲתִידִים הֵם שִׁבְעִים שָׂרֵי צְבָאוֹת מִכָּל עֵבֶר (עמים) לְהִתְכַּנֵּס בְּאוֹתוֹ זְמַן בַּהֲמוֹנִים מִכָּל הָעוֹלָם, וְלַעֲשׂוֹת קְרָב עַל יְרוּשָׁלַיִם עִיר הַקֹּדֶשׁ, וְלֶאֱחֹז עֵצוֹת עַל הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמָה אוֹמְרִים? נַעֲמֹד עַל הַפַּטְרוֹן בַּהַתְחָלָה, וְאַחַר כָּךְ עַל עַמּוֹ וְעַל הֵיכָלוֹ.</p>\n<p>אָז עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִצְחֹק עֲלֵיהֶם, שֶׁכָּתוּב יוֹשֵׁב בַּשָּׁמַיִם יִשְׂחָק ה' יִלְעַג לָמוֹ. בְּאוֹתוֹ זְמַן יִלְבַּשׁ הַקָּדוֹשׁ בָּרוּךְ הוּא גַּאֲוָה עֲלֵיהֶם, וְיַשְׁמִיד אוֹתָם מִן הָעוֹלָם, כַּכָּתוּב (זכריה יד) וְזאת תִּהְיֶה הַמַּגֵּפָה אֲשֶׁר יִגֹּף ה' אֶת כָּל הָעַמִּים אֲשֶׁר צָבְאוּ עַל יְרוּשָׁלִם הָמֵק בְּשָׂרוֹ וְהוּא עֹמֵד עַל רַגְלָיו.</p>\n<p>רַבִּי אַבָּא אָמַר מִשְּׁמוֹ שֶׁל רַב יֵיסָא סָבָא, וְכָךְ אָמַר רַבִּי שִׁמְעוֹן, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת אֶת כָּל אוֹתָם הַמְּלָכִים שֶׁהֵצִיקוּ לְיִשְׂרָאֵל וְלִירוּשָׁלַיִם, אֶת אַנְדְּרִיאָנוּס, לְלוּפִינוֹס, וּנְבוּכַדְנֶצַּר, וּלְסַנְחֵרִיב, וּלְכָל שְׁאָר מַלְכֵי הָעַמִּים שֶׁהֶחֱרִיבוּ בֵיתוֹ, וּלְהַשְׁלִיט אוֹתָם כְּבַתְּחִלָּה, וְיִתְכַּנְּסוּ עִמָּהֶם שְׁאָר הָעַמִּים. וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִפָּרַע מֵהֶם בְּגָלוּי סְבִיב יְרוּשָׁלַיִם. זֶהוּ שֶׁכָּתוּב וְזאת תִּהְיֶה הַמַּגֵּפָה אֲשֶׁר יִגֹּף ה' אֶת כָּל הָעַמִּים אֲשֶׁר צָבְאוּ עַל יְרוּשָׁלם. אֲשֶׁר יִצְבְּאוּ לֹא כָתוּב, אֶלָּא אֲשֶׁר צָבְאוּ. אָז כָּתוּב וּבְרֹב גְּאוֹנְךְ תַּהֲרֹס קָמֶיךְ. וְזֶה לִזְמַן שֶׁיָּבֹא הַמָּשִׁיחַ כָּתוּב, וְשִׁירָה זוֹ הִיא שִׁירַת הָעוֹלָמִים.</p>\n<p>וּבְרוּחַ אַפֶּיךְ נֶעֶרְמוּ מַיִם - בְּאוֹתוֹ זְמַן. וּמִשּׁוּם כָּךְ יֵשׁ בְּאוֹתוֹ זְמַן, וְלִזְמַנּוֹ שֶׁל מֶלֶךְ הַמָּשִׁיחַ, וְלִזְמַן גּוֹג וּמָגוֹג. נִצְּבוּ כְמוֹ נֵד - לִזְמַן שֶׁל עוֹלָם הַבָּא, שֶׁהִיא חֶדְוַת כָּל הָעוֹלָמוֹת.</p>"],[9522011621,"<p>אָמַר אוֹיֵב אֶרְדּף אַשִּׂיג אֲחַלֵּק שָׁלָל. אָמַר אוֹיֵב - זֶה אוֹתוֹ מְמֻנֶּה גָּדוֹל עַל הַמִּצְרִים, בְּשָׁעָה שֶׁנִּתָּן לוֹ שִׁלְטוֹן עַל יִשְׂרָאֵל, חָשַׁב שֶׁיַּשְׁמִיד אוֹתָם תַּחַת שִׁלְטוֹנוֹ, אֶלָּא שֶׁזָּכַר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָרֵי הָעוֹלָם שֶׁהָיוּ מְגִנִּים עֲלֵיהֶם. וְאַל תֹּאמַר זֶה לְבַדּוֹ, אֶלָּא כָּל אוֹתָם גְּדוֹלִים שֶׁמְּמֻנִּים עַל עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. וּכְשֶׁנִּתְּנָה לָהֶם רְשׁוּת וְשִׁלְטוֹן עַל יִשְׂרָאֵל, כֻּלָּם רוֹצִים לְהַשְׁמִיד אֶת יִשְׂרָאֵל תַּחְתֵּיהֶם.</p>\n<p>וְעַל זֶה, אוֹתָם עַמִּים שֶׁתַּחַת אוֹתָם הַשַּׁלִּיטִים הַמְמֻנִּים, כֻּלָּם גּוֹזְרִים גְּזֵרוֹת לְהַשְׁמִיד אוֹתָם, אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא זוֹכֵר אֶת הָרֵי הָעוֹלָם, וּמֵגֵן עֲלֵיהֶם. וּכְשֶׁרָאָה אֶת זֶה מֹשֶׁה, הִתְחִיל לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְאָמַר, מִי כָמֹכָה בָּאֵלִם ה'.</p>"],[9522011622,"<p>אָמַר רַבִּי שִׁמְעוֹן, עֵץ גָּדוֹל אֶחָד עֶלְיוֹן וְחָזָק, בּוֹ נִזּוֹנוּ עֶלְיוֹנִים וְתַחְתּוֹנִים, וְהוּא מֻתְחָם בִּשְׁנֵים עָשָׂר תְּחוּמִים, הִתְחַזֵּק בְּאַרְבָּעָה צִדְדֵי הָעוֹלָם שֶׁהִסְתּוֹבְבוּ (שהתחברו) בִמְקוֹמָם. שִׁבְעִים עֲנָפִים עוֹלִים בְּתוֹכוֹ וְנִזּוֹנִים מִמֶּנּוּ, בְּעִקַּר שָׁרָשָׁיו יוֹנְקִים הֵם סְבִיבוֹ, וְאוֹתָם הָעֲנָפִים שֶׁנִּמְצָאִים בָּעֵץ.</p>\n<p>כְּשֶׁמַּגִּיעַ שִׁלְטוֹנוֹ שֶׁל כָּל עָנָף וְעָנָף, כֻּלָּם רוֹצִים לְהַשְׁמִיד אֶת כָּל גּוּף הָעֵץ שֶׁהוּא עִקָּר שֶׁל כָּל הָעֲנָפִים, אוֹתוֹ שֶׁשּׁוֹלֵט עֲלֵיהֶם, וְיִשְׂרָאֵל אֲחוּזִים בּוֹ. כְּשֶׁמַּגִּיעַ עֲלֵיהֶם הַשִּׁלְטוֹן שֶׁל אוֹתוֹ גּוּף הָעֵץ, הַחֵלֶק שֶׁל יִשְׂרָאֵל, הוּא רוֹצֶה לִשְׁמֹר אוֹתָם וְלָתֵת שָׁלוֹם בְּכֻלָּם, וְעַל זֶה שִׁבְעִים פָּרִים שֶׁל חַג הַסֻּכּוֹת, לָתֵת שָׁלוֹם לְשִׁבְעִים עֲנָפִים שֶׁבְּתוֹךְ הָעֵץ.</p>\n<p>וְעַל זֶה מִי כָמֹכָה בָּאֵלִם ה'. (מה זה באלים, העץ, כמו שנאמר (ישעיה א) כי יבשו מאילים אשר חמדתם. שאותו עץ שהיו עובדים לדפוס אחד שהיה חקוקבתוכו, ונקרא אילים עץ) מִי כָמֹכָה שֶׁיַּעֲשֶׂה כְּמַעֲשֶׂיךְ וִירַחֵם עַל הַכֹּל. מִי כָמֹכָה בְּכָל אוֹתוֹ סְבִיב הָעֵץ, שֶׁאַף עַל גַּב שֶׁהוּא שׁוֹלֵט - שׁוֹמֵר אֶת הַכֹּל, שׁוֹמֵר אֶת כָּל הַשְּׁאָר, וְלֹא רוֹצֶה לַעֲשׂוֹת עִמָּהֶם כִּלָּיוֹן. מִי כָּמֹכָה נֶאְדָּר בַּקֹּדֶשׁ - בְּאוֹתוֹ כֹּחַ עֶלְיוֹן שֶׁנִּקְרָא קֹדֶשׁ, נֶאְדָּר בַּקֹּדֶשׁ מַמָּשׁ, וְנִקְרָא כֹּחַ ה' נֹעַם ה', וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים.</p>\n<p>מִי כָמֹכָה בָּאֵלִם ה'. רַבִּי יוֹסֵי פָּתַח, (קהלת א) רָאִיתִי אֶת כָּל הַמַּעֲשִׂים אֲשֶׁר נַעֲשׂוּ תַּחַת הַשָּׁמֶשׁ וְהִנֵּה הַכֹּל הֶבֶל וּרְעוּת רוּחַ. שְׁלֹמֹה הַמֶּלֶךְ שֶׁהִתְעַלָּה בְּחָכְמָה יְתֵרָה עַל כָּל בְּנֵי הָעוֹלָם, אֵיךְ אָמַר שֶׁכָּל הַמַּעֲשִׂים הֵם הֶבֶל וּרְעוּת רוּחַ? יָכוֹל אַף מַעֲשֵׂה הַצְּדָקָה? וַהֲרֵי כָּתוּב (ישעיה לב) וְהָיָה מַעֲשֵׂה הַצְּדָקָה שָׁלוֹם? אֶלָּא הֲרֵי פֵּרְשׁוּהָ, כָּתוּב כָּל הַמַּעֲשִׂים אֲשֶׁר נַעֲשׂוּ תַּחַת הַשָּׁמֶשׁ. שׁוֹנֶה מַעֲשֵׂה הַצְּדָקָה, שֶׁהוּא לְמַעְלָה מִן הַשֶּׁמֶשׁ.</p>\n<p>וְהִנֵּה הַכֹּל הֶבֶל וּרְעוּת רוּחַ, מַה זֶּה אוֹמֵר? אִם תֹּאמַר הַכֹּל הֶבֶל כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁהוּא בְּסוֹד הַחָכְמָה, כְּמוֹ שֶׁנֶּאֱמַר הֲבֵל הֲבָלִים אָמַר קֹהֶלֶת. וְאוֹתָם הֲבָלִים קִיּוּם שֶׁל הָעוֹלָם שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה. מַה תֹּאמַר בָּזֶה שֶׁכָּתוּב כָּאן הַכֹּל הֶבֶל וּרְעוּת רוּחַ? (והרי דבר זה תחת השמש כתוב).</p>\n<p>אֶלָּא כָּךְ פֵּרְשׁוּהָ וְכָךְ הוּא. בֹּא רְאֵה, בְּשָׁעָה שֶׁהַמַּעֲשִׂים מֻכְשָׁרִים לְמַטָּה וְאָדָם מִשְׁתַּדֵּל בַּעֲבוֹדַת הַמֶּלֶךְ הַקָּדוֹשׁ - מֵאוֹתוֹ דָּבָר שֶׁעוֹשֶׂה, נַעֲשֶׂה מִמֶּנּוּ הֶבֶל לְמַעְלָה, וְאֵין לְךְ הֶבֶל שֶׁאֵין לוֹ קוֹל שֶׁעוֹלֶה וּמִתְעַטֵּר לְמַעְלָה, וְנַעֲשֶׂה סָנֵגוֹר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וְכָל אוֹתָם מַעֲשִׂים שֶׁמִּשְׁתַּדֵּל בָּהֶם הָאָדָם שֶׁאֵינָם עֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא - מֵאוֹתוֹ דָּבָר שֶׁעוֹשֶׂה, נַעֲשֶׂה מִמֶּנּוּ הֶבֶל, וְהוֹלֵךְ וּמְשׁוֹטֵט בָּעוֹלָם. וּכְשֶׁיּוֹצֵאת נִשְׁמַת הָאָדָם, אוֹתוֹ הֶבֶל מְגַלְגֵּל אוֹתוֹ בָּעוֹלָם כְּאֶבֶן בְּכַף הַקֶּלַע, כַּכָּתוּב (שמואל א כה) וְאֵת נֶפֶשׁ אֹיְבֶיךְ יְקַלְּעֶנָּה בְּתוֹךְ כַּף הַקָּלַע.</p>\n<p>מַהוּ יְקַלְּעֶנָּה? אוֹתוֹ הֶבֶל שֶׁמְּגַלְגֵּל אוֹתוֹ סְבִיבוֹ בָּעוֹלָם, וְאָז כָּל הַדְּבָרִים שֶׁנַּעֲשִׂים (ואותם שתחת השמים) שֶׁאֵינָם עֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, נַעֲשֶׂה מֵהֶם הֶבֶל, שֶׁהוּא שִׁבְרוֹן רוּחַ, שֶׁמְּשַׁבֵּר אֶת הָרוּחַ שֶׁעוֹלָה וְיוֹרֶדֶת וּמִתְגַּלְגֶּלֶת בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב הֶבֶל וּרְעוּת רוּחַ.</p>\n<p>אֲבָל אוֹתוֹ דָּבָר שֶׁהוּא עֲבוֹדַת רִבּוֹנוֹ, זֶה עוֹלֶה (נקרא) מֵעַל לַשֶּׁמֶשׁ, וְנַעֲשֶׂה מִמֶּנּוּ הֶבֶל קָדוֹשׁ, וְזֶהוּ הַזֶּרַע שֶׁזָּרַע הָאָדָם בְּאוֹתוֹ עוֹלָם, וּמַה שְּׁמוֹ? צְדָקָה, שֶׁכָּתוּב (הושע י) זִרְעוּ לָכֶם לִצְדָקָה.</p>\n<p>זְהִ מַה שֶּׁמַּנְהִיג אֶת הָאָדָם, כְּשֶׁתֵּצֵא מִמֶּנּוּ נִשְׁמָתוֹ, וְעוֹלָה לָהּ לְמָקוֹם שֶׁל כָּבוֹד שֶׁלְּמַעְלָה נִמְצָא לְהִצָּרֵר בִּצְרוֹר הַחַיִּים. זֶהוּ שֶׁכָּתוּב (ישעיהנח) וְהָלַךְ לְפָנֶיךְ צִדְקֶךְ, כְּדֵי לְהַנְהִיג אוֹתְךְ, לְהַעֲלוֹת אוֹתְךְ (ממקום) לְמָקוֹם שֶׁנִּקְרָא כְּבוֹד ה', שֶׁכָּתוּב כְּבוֹד ה' יַאַסְפֶךְ.</p>\n<p>כָּל אוֹתָן נְשָׁמוֹת שֶׁאוֹתוֹ הֶבֶל קָדוֹשׁ מַנְהִיג אוֹתָן, אוֹתוֹ שֶׁנִּקְרָא כְּבוֹד ה' כּוֹנֵס אוֹתָן לְתוֹכוֹ וְנִצְרָרוֹת בּוֹ. (זהו שכתוב כבוד ה' יאספך) וְזֶה נִקְרָא נַחַת רוּחַ. אֲבָל הָאַחֵר נִקְרָא רְעוּת רוּחַ. אַשְׁרֵי הַצַּדִּיקִים שֶׁכָּל מַעֲשֵׂיהֶם מֵעַל לַשֶּׁמֶשׁ, וְזוֹרְעִים זֶרַע שֶׁל צְדָקָה לְזַכּוֹת אוֹתָם לָעוֹלָם הַבָּא, וְעַל זֶה כָּתוּב (מלאכי ג) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בֹּא רְאֵה, בַּתְּחִלָּה כְּשֶׁנִּבְנָה בֵּית הַמִּקְדָּשׁ לְמַטָּה, לֹא נִבְנָה אֶלָּא בְּדִין וְרֹגֶז, כַּכָּתוּב (ירמיה לב) כִּי עַל אַפִּי וְעַל חֲמָתִי וְגוֹ', מִשּׁוּם שֶׁבִּמְקוֹם הַדִּין שָׁרוּי. לֶעָתִיד לָבֹא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְנוֹת אוֹתוֹ וּלְהַתְקִינוֹ בְּדַרְגָּה אַחֶרֶת עֶלְיוֹנָה שֶׁנִּקְרֵאת צְדָקָה, שֶׁכָּתוּב (ישעיה נד) בִּצְדָקָה תִּכּוֹנָנִי. מִשּׁוּם כָּךְ יִתְקַיֵּם (בו), וּשְׁמוֹ מַמָּשׁ יִקָּרֵא צֶדֶק. מִנַּיִן לָנוּ? שֶׁכָּתוּב (ירמיה כג) וְזֶה שְּׁמוֹ אֲשֶׁר יִקְרְאוֹ ה' צִדְקֵנוּ.</p>"],[9522011623,"<p>נָטִיתָ יְמִינְךְ תִּבְלָעֵמוֹ אָרֶץ. הֲרֵי נֶאֱמַר שֶׁהֵרַמְתָּ יְמִינְךְ. אָמַר רַבִּי יִצְחָק, הֲרֵי הִתְעוֹרְרוּ בוֹ הַחֲבֵרִים, שֶׁכַּאֲשֶׁר הוֹצִיא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַמִּצְרִים מִתַּחַת לַמַּיִם, אָמַר לָאָרֶץ: כַּנְּסִי אוֹתָם לְתוֹכֵךְ. וְלֹא רָצְתָה. עַד שֶׁהוֹשִׁיט הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יְמִינוֹ כְּנֶגְדָּהּ וְהִשְׁבִּיעַ אוֹתָהּ, אָז בָּלְעָה אוֹתָם הָאֲדָמָה. זֶהוּ שֶׁכָּתוּב תִּבְלָעֵמוֹ אָרֶץ. אָמַר רַבִּי אֶלְעָזָר, נָטִיתָ יְמִינְךְ - לְהַפְרִידָהּ מִן הַשְּׂמֹאל, וְאָז נַעֲשֶׂה בָּהֶם דִּין.</p>\n<p>נָחִיתָ בְחַסְדְּךְ עַם זוּ גָּאָלְתָּ, כְּמוֹ שֶׁכָּתוּב (תהלים מד) כִּי יְמִינְךְ וּזְרוֹעֲךְ וְאוֹר פָּנֶיךְ כִּי רְצִיתָם. כִּי יְמִינְךְ - זוֹ גְדוֹלָה. נֵהַלְתָּ בְעָזְךְ - זֶה שֶׁכָּתוּב וּזְרוֹעֲךְ, זוֹ גְבוּרָה. אֶל נְוֵה קָדְשֶׁךְ - זֶה שֶׁכָּתוּב וְאוֹר פָּנֶיךְ כִּי רְצִיתָם, זֶה צַדִּיק. וְכֻלָּם נִמְצָאִים בַּכָּתוּב.</p>\n<p>תִּפֹּל עֲלֵיהֶם אֵימָתָה וָפַחַד. אֵימָתָה? אֵימָה הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה אֵימָתָה, שֶׁהֲרֵי אֵין לְךְ אוֹת אוֹ מִלָּה אַחַת בַּתּוֹרָה שֶׁאֵין בָּהּ סוֹדוֹת עֶלְיוֹנִים? מַה זֶּה אֵימָתָה? אָמַר רַבִּי שִׁמְעוֹן, כְּלוֹמַר יִרְאַת הַשְּׁכִינָה.</p>\n<p>כְּמוֹ זֶה תְּבִאֵמוֹ וְתִטָּעֵמוֹ בְּהַר נַחֲלָתְךְ וְגוֹ'. תְּבִאֵמוֹ וְתִטָּעֵמוֹ? תְּבִיאֵם וְתִטָּעֵם הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה תְּבִאֵמוֹ? אֶלָּא רוּחַ הַקֹּדֶשׁ אוֹמֶרֶת עַל אוֹתוֹ הַדּוֹר הָאַחֲרוֹן שֶׁמָּל יְהוֹשֻׁעַ וְהִתְגַּלָּה בָּהֶם גִּלּוּי שֶׁל הָרֹשֶׁם הַקָּדוֹשׁ שֶׁל שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאֵלֶּה אֲחוּזִים בְּו', וְאֵלֶּה רְאוּיִים לָרֶשֶׁת אֶת הָאָרֶץ, כַּכָּתוּב (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ. שֶׁכָּל מִי שֶׁנִּמּוֹל וְהִתְגַּלָּה בּוֹ רֹשֶׁם הַקָּדוֹשׁ וְשׁוֹמֵר אוֹתוֹ, נִקְרָא צַדִּיק. מִשּׁוּם כָּךְ, לְעוֹלָם יִירְשׁוּ אָרֶץ.</p>\n<p>וְעַל זֶה תְּבִאֵמוֹ, ו' יְתֵרָה. תְּבִאֵמוֹ לְאוֹתָם הָאֲחוּזִים בְּו' (תפארת). וְתִטָּעֵמוֹ, כַּנֶּאֱמַר נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר. לְאוֹתָם שֶׁאֲחוּזִים בְּו', וּלְאוֹתָם אַחֲ רוֹנִים הִתְעוֹרֵר הַדָּבָר. וְאֵין לְךְ דָּבָר בַּתּוֹרָה אוֹ אוֹת קְטַנָּה בַּתּוֹרָה שֶׁאֵין בָּהּ סוֹדוֹת עֶלְיוֹנִים וּטְעָמִים קְדוֹשִׁים. אַשְׁרֵי חֶלְקָם שֶׁל הַיּוֹדְעִים בָּהֶם.</p>"],[9522011624,"<p>מִצְוָה לִבְנוֹת בֵּית מִקְדָּשׁ לְמַטָּה כְּמוֹ בֵּית הַמִּקְדָּשׁ שֶׁלְּמַעְלָה, כְּמוֹ שֶׁנֶּאֱמַר מָכוֹן לְשִׁבְתְּךְ פָּעַלְתָּ ה'. שֶׁצָּרִיךְ לִבְנוֹת בֵּית מִקְדָּשׁ לְמַטָּה וּלְהִתְפַּלֵּל בְּתוֹכוֹ תְּפִלָּה בְּכָל יוֹם, לַעֲבוֹד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי תְּפִלָּה נִקְרֵאת עֲבוֹדָה.</p>\n<p>וְאוֹתוֹ בֵּית הַכְּנֶסֶת צָרִיךְ לִבְנוֹתוֹ בְּיֹפִי רַב וּלְתַקְּנוֹ בְּכָל הַתִּקּוּנִים, שֶׁהֲרֵי בֵּית הַכְּנֶסֶת שֶׁלְּמַטָּה עוֹמֵד כְּנֶגֶד בֵּית הַכְּנֶסֶת שֶׁלְּמַעְלָה.</p>\n<p>בֵּית הַמִּקְדָּשׁ לְמַטָּה הוּא עוֹמֵד כְּמוֹ בֵּית הַמִּקְדָּשׁ שֶׁלְּמַעְלָה, שֶׁעוֹמֵד זֶה כְּנֶגֶד זֶה. וְאוֹתוֹ בֵּית מִקְדָּשׁ, כָּל תִּקּוּנָיו וְכָל עֲבוֹדוֹתָיו וְכָל אוֹתָם כֵּלִים וְשַׁמָּשִׁים, כֻּלָּם הֵם כְּמוֹ שֶׁלְּמַעְלָה. הַמִּשְׁכָּן שֶׁעָשָׂה מֹשֶׁה בַּמִּדְבָּר, הַכֹּל הָיָה כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>בֵּית הַמִּקְדָּשׁ שֶׁבָּנָה שְׁלֹמֹה הַמֶּלֶךְ, הוּא בֵּית מְנוּחָה כְּדֻגְמָא עֶלְיוֹנָה בְּכָל אוֹתָם תִּקּוּנִים, לִהְיוֹת בְּתִקּוּן שֶׁלְּמַעְלָה בֵּית מְנוּחָה וִירֻשָּׁה. כָּךְ בֵּית הַכְּנֶסֶת צָרִיךְ בְּכָל תִּקּוּנֵי הַיֹּפִי, לִהְיוֹת כְּדֻגְמָא עֶלְיוֹנָה, לִהְיוֹת בֵּית תְּפִלָּה, לְתַקֵּן תִּקּוּנִים בַּתְּפִלָּה, כְּמוֹ שֶׁבֵּאֲרוּהָ.</p>\n<p>וְאוֹתוֹ בֵּית מִקְדָּשׁ שֶׁיִּהְיוּ בוֹ חַלּוֹנוֹת, שֶׁכָּתוּב (דניאל ו) חַלּוֹנוֹת פְּתוּחִים. כְּמוֹ שֶׁלְּמַעְלָה. וְעַל זֶה (שיר ב) מַשְׁגִּיחַ מִן הַחַלּוֹנוֹת מֵצִיץ מִן הַחֲרַכִּים. וְאִם תֹּאמַר, אֲפִלּוּ בַּשָּׂדֶה, כְּדֵי שֶׁהָרוּחַ תִּהְיֶה עוֹלָה? לֹא כָּךְ, שֶׁהֲרֵי אָנוּ צְרִיכִים בַּיִת, וְאֵין לְהִמָּצֵא בַּיִת לְמַטָּה כְּמוֹ בַּיִת עֶלְיוֹן, לְהוֹרִיד דִּיּוּר עֶלְיוֹן לְדִיּוּר תַּחְתּוֹן.</p>\n<p>וְעוֹד, שֶׁאוֹתָה תְּפִלָּה וְאוֹתָהּ רוּחַ צְרִיכִים לַעֲלוֹת וְלָצֵאת מִתּוֹךְ מְצוּקָה בְּדֶרֶךְ יְשָׁרָה כְּנֶגֶד יְרוּשָׁלַיִם. וְעַל זֶה כָּתוּב מִן הַמֵּצַר קָרָאתִי יָהּ. שֶׁצָּרִיךְ מָקוֹם דָּחוּק בַּצָּרָה לִשְׁלֹחַ בְּתוֹכוֹ אוֹתָהּ רוּחַ שֶׁלֹּא יִסְטֶה יָמִינָה אוֹ שְׂמֹאלָה. וּבְשָׂדֶה לֹא יָכוֹל הַקּוֹל לְשַׁלֵּחַ אוֹתוֹ כָּךְ, שֶׁהֲרֵי כְּמוֹ זֶה קוֹל הַשּׁוֹפָר נִדְחֶה הַחוּצָה בְּדֶרֶךְ יָשָׁר מִתּוֹךְ מָקוֹם דָּחוּק, וְהוֹלֵךְ וּבוֹקֵעַ רְקִיעִים, וְעוֹלֶה בַּעֲלִיָּה לְעוֹרֵר רוּחַ שֶׁלְּמַעְלָה.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי כָּתוּב (בראשית כד) וַיֵּצֵא יִצְחָק לָשׂוּחַ בַּשָּׂדֶה? שׁוֹנֶה יִצְחָק, שֶׁדָּבָר אַחֵר הָיָה בּוֹ מַה שֶּׁלֹּא הָיָה בְּכָל הָעוֹלָם. וְעוֹד, שֶׁפָּסוּק זֶה לֹא לָזֶה הוּא בָּא, שֶׁוַּדַּאי בַּשָּׂדֶה לֹא הָיָה מִתְפַּלֵּל, וַהֲרֵי בֵּאַרְנוּ. (ע\"כ רעיא מהימנא)</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי אַבָּא, אַשְׁרֵי חֶלְקָם שֶׁל אוֹתָם שֶׁזַּכָּאִים לוֹמַר שִׁירָה זוֹ בָּעוֹלָם הַזֶּה, שֶׁזַּכָּאִים לְאָמְרָהּ לָעוֹלָם הַבָּא. וְשִׁירָה זוֹ נִבְנְתָה בְּעֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת קְדוֹשׁוֹת חֲקוּקוֹת וּבְעֶשֶׂר אֲמִירוֹת, וְהַכֹּל נִרְשָׁם בַּשֵּׁם הַקָּדוֹשׁ, וְהַכֹּל שְׁלֵמוּת שֶׁל הַשֵּׁם הַקָּדוֹשׁ, וַהֲרֵי עוֹרַרְנוּ הַדְּבָרִים.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בְּאוֹתָהּ שָׁעָה שֶׁהָיוּ עוֹמְדִים יִשְׂרָאֵל עַל הַיָּם וְאוֹמְרִים שִׁירָה, הִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיהֶם, וְכָל מַרְכְּבוֹתָיו וְחֵילוֹתָיו, כְּדֵי שֶׁיַּכִּירוּ אֶת מַלְכָּם שֶׁעָשָׂה לָהֶם כָּל אוֹתָם נִסִּים וּגְבוּרוֹת, וְכָל אֶחָד וְאֶחָד יָדַע וּהִתְבּוֹנֵן מַה שֶּׁלֹּא יָדְעוּ וְהִתְבּוֹנְנוּ שְׁאָר נְבִיאֵי הָעוֹלָם.</p>\n<p>שֶׁאִם תֹּאמַר שֶׁלֹּא יָדְעוּ וְלֹא הִדְבִּיקוּ הִשִּׂיגוּ חָכְמָה הָעֶלְיוֹנָה - מִן הַשִּׁירָה הַזּוֹ תִּרְאֶה שֶׁכֻּלָּם הִסְתַּכְּלוּ בַּחָכְמָה וְיָדְעוּ דְבָרִים וְאָמְרוּ. שֶׁאִם לֹא כָּךְ, אֵיךְ אָמְרוּ כֻלָּם מִלִּים אֲחִידוֹת שֶׁלֹּא סָטוּ אֵלֶּה מֵאֵלֶּה, וּמַה שֶּׁאָמַר זֶה - אָמַר זֶה, וְלֹא הִקְדִּים מִלָּה זוֹ לְמִלָּה זוֹ, אֶלָּא כֻּלָּם בְּמִשְׁקָל אֶחָד, וְרוּחַ הַקֹּדֶשׁ בְּפִי כָּל אֶחָד וְאֶחָד, וְכָל הַדְּבָרִים נֶאֶמְרוּ כְּאִלּוּ יָצְאוּ מִפֶּה אֶחָד? אֶלָּא וַדַּאי כֻּלָּם בַּחָכְמָה הָעֶלְיוֹנָה הִסְתַּכְּלוּ, וְיָדְעוּ דְבָרִים עֶלְיוֹנִים, וְרוּחַ הַקֹּדֶשׁ בְּפִי כָּל אֶחָד וְאֶחָד.</p>\n<p>וַאֲפִלּוּ אוֹתָם שֶׁבִּמְעֵי אִמָּם הָיוּ כֻלָּם כְּאֶחָד אוֹמְרִים שִׁירָה, וְהָיוּ כֻלָּם רוֹאִים מַה שֶּׁלֹּא רָאָה יְחֶזְקֵאל הַנָּבִיא, וְעַל כָּךְ הָיוּ כֻלָּם מִסְתַּכְּלִים כְּאִלּוּ רוֹאִים עַיִן בְּעַיִן. וּכְשֶׁסִּיְּמוּ הַדְּבָרִים, כֻּלָּם מְבֻשָּׂמִים בְּנַפְשָׁם וּתְאֵבִים לִרְאוֹת וּלְהִסְתַּכֵּל, וְלֹא הָיוּ רוֹצִים לִנְסֹעַ מִשָּׁם מֵרֹב הִשְׁתּוֹקְקוּת.</p>\n<p>בְּאוֹתָהּ שָׁעָה אָמַר מֹשֶׁה לַקָּדוֹשׁ- בָּרוּךְ-הוּא: בָּנֶיךְ לֹא רוֹצִים לִנְסֹעַ מִן הַיָּם מֵרֹב הִשְׁתּוֹקְקוּת לְהִסְתַּכֵּל בְּךְ. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? הִסְתִּיר אֶת כְּבוֹדוֹ הַחוּצָה לַמִּדְבָּר, וְשָׁם הִתְגַּלָּה וְלֹא הִתְגַּלָּה. אָמַר לָהֶם מֹשֶׁה לְיִשְׂרָאֵל: כַּמָּה (פעמים לנסע משם, ולא רצו) פְעָמִים אָמַרְתִּי לִנְסֹעַ מִשָּׁם וְלֹא רְצִיתֶם? עַד שֶׁהֶרְאָה לָהֶם זִיו כְּבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בַּמִּדְבָּר, וּמִיָּד הָיוּ תְאֵבִים.</p>\n<p>וְלֹא נָסְעוּ, עַד שֶׁאָחַז בָּהֶם מֹשֶׁה וְהֶרְאָה לָהֶם זִיו כְּבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בַּמִּדְבָּר. אָז מֵרֹב תְּשׁוּקָה וְרָצוֹן לְהִסְתַּכֵּל הִסִּיעַ אוֹתָם מֹשֶׁה. זֶהוּ שֶׁכָּתוּב וַיַּסַּע מֹשֶׁה אֶת יִשְׂרָאֵל מִיַּם סוּף וַיֵּצְאוּ אֶל מִדְבַּר שׁוּר. מַה זֶּה מִדְבַּר שׁוּר? מַנְהִיג שֶׁהָיוּ רוֹצִים לְהִסְתַּכֵּל בּוֹ, זִיו כְּבוֹדוֹ שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ, וְעַל זֶה נִקְרָא מִדְבַּר שׁוּר - שָׁם הִסְתַּכְּלוּת.</p>"],[9522011625,"<p>וַיֵּלְכוּ שְׁלֹשֶׁת יָמִים בַּמִּדְבָּר וְלֹא מָצְאוּ מָיִם. וְאֵין מַיִם אֶלָּא תּוֹרָה, שֶׁנֶּאֱמַר (ישעיה נה) הוֹי כָּל צָמֵא לְכוּ לַמַּיִם. אָמַר רַבִּי יֵיסָא, וְכִי מִי נָתַן לָהֶם כָּאן תּוֹרָה, וַהֲרֵי עַד עַכְשָׁו לֹא נִתְּנָה לָהֶם תּוֹרָה?</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, הֵם יָצְאוּ לַמִּדְבָּר לְהִסְתַּכֵּל, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נָטַל זִיו כְּבוֹדוֹ מִשָּׁם, וְהֵם הָלְכוּ לְהִסְתַּכֵּל (לקדוש'ברוך'הוא) בּוֹ וְלֹא מָצְאוּ אוֹתוֹ. וְלָמַדְנוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא תּוֹרָה, וְאֵין מַיִם אֶלָּא תּוֹרָה, וְאֵין תּוֹרָה אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, עַד שֶׁהָיוּ הוֹלְכִים בַּמִּדְבָּר, הִתְגַּלָּה עֲלֵיהֶם רָשׁוּת אַחֶרֶת שֶׁל שְׁאָר הָעַמִּים, אוֹתוֹ שֶׁשּׁוֹלֵט בַּמִּדְבָּר, וּפָגַשׁ בָּהֶם שָׁם. רָאוּ יִשְׂרָאֵל שֶׁזֶּה לֹא הָיָה אוֹתוֹ זִיו כְּבוֹד מַלְכָּם. זֶהוּ שֶׁכָּתוּב וַיָּבֹאוּ מָרָתָה וְלֹא יָכְלוּ לִשְׁתֹּת מַיִם מִמָּרָה. מָה הַטַּעַם? כִּי מָרִים הֵם. לֹא הִתְבַּשְּׂמָה נַפְשָׁם כְּבַתְּחִלָּה. וְלֹא עוֹד, אֶלָּא שֶׁבָּא לְקַטְרֵג עֲלֵיהֶם.</p>\n<p>מַה כָּתוּב? וַיִּצְעַק אֶל ה' וַיּוֹרֵהוּ ה' עֵץ, וְאֵין עֵץ אֶלָּא תּוֹרָה, שֶׁכָּתוּב (משליג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. וְאֵין תּוֹרָה אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא. רַבִּי אַבָּא אָמַר, אֵין עֵץ אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (דבריםכ) כִּי הָאָדָם עֵץ הַשָּׂדֶה, עֵץ הַשָּׂדֶה וַדַּאי, זֶה עֵץ שָׂדֶה שֶׁל תַּפּוּחִים קְדוֹשִׁים (מלכות). וּכְשֶׁהִתְגַּלָּה זִיו כְּבוֹד מַלְכָּם עֲלֵיהֶם, אָז וַיַּשְׁלֵךְ אֶל הַמַּיִם וַיִּמְתְּקוּ הַמָּיִם. מַה זֶּה וַיִּמְתְּקוּ הַמָּיִם? שֶׁקָּטֵגוֹר נַעֲשָׂה סָנֵגוֹר.</p>\n<p>אָמַר רַבִּי אַבָּא, בּא רְאֵה, בַּתְּחִלָּה כְּשֶׁנִּכְנְסוּ יִשְׂרָאֵל לַבְּרִית שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא נִכְנְסוּ כָּרָאוּי, מָה הַטַּעַם? כִּי נִמּוֹלוּ וְלֹא נִפְרְעוּ, וְלֹא הִתְגַּלָּה הָרֹשֶׁם הַקָּדוֹשׁ. כֵּיוָן שֶׁהִגִּיעוּ לְכָאן מַה כָּתוּב? שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט. שָׁם נִכְנְסוּ יִשְׂרָאֵל לִשְׁנֵי חֲלָקִים קְדוֹשִׁים בְּאוֹתוֹ גִּלּוּי שֶׁהִתְגַּלָּה הָרֹשֶׁם שֶׁלָּהֶם, וְנִקְרְאוּ חֹק וּמִשְׁפָּט. חֹק - כְּמוֹ שֶׁנֶּאֱמַר (משלי לא) וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ. וּמִשְׁפָּט - כְּמוֹ שֶׁנֶּאֱמַר מִשְׁפָּט לֵאלֹהֵי יַעֲקֹב. וְשָׁם נִסָּהוּ - בְּאוֹתוֹ אוֹת קֹדֶשׁ,</p>"],[9522011626,"<p>כְּמוֹ שֶׁנֶּאֱמַר כִּי חֹק לְיִשְׂרָאֵל הוּא. בְּסִפְרוֹ שֶׁל רַבִּי יֵיבָא סָבָא אָמַר הַדָּבָר עַל אוֹתוֹ מַטֶּה קָדוֹשׁ. וַיֹּאמֶר אִם שָׁמוֹעַ תִּשְׁמַע לְקוֹל ה' אֱלֹהֶיךְ. וַיֹּאמֶר, מַה זֶּה וַיֹּאמֶר? לֹא כָתוּב מִי אָמַר אֶת זֶה. אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר. רַבִּי חִזְקִיָּה אָמַר, שָׁמַעְנוּ (משמע) אֲמִירָה סְתָם מֵאֲמִירָה סְתָם, שֶׁכָּתוּב (שמות כד) וְאֶל מֹשֶׁה אָמַר עֲלֵה אֶל ה'. אָמַר, לֹא כָתוּב מִי אָמַר. אַף כָּאן וַיֹּאמֶר סְתָם, וְלֹא כָתוּב מִי אָמַר.</p>\n<p>אָמַר רַבִּי יוֹסֵי, מַשְׁמָע שֶׁכָּתוּב וַיִּצְעַק אֶל ה' וַיּוֹרֵהוּ ה' עֵץ, מִכָּאן מַשְׁמָע וַיֹּאמֶר, וּמַשְׁמָע מִי אָמַר דָּבָר זֶה. לְקוֹל ה' אֱלֹהֶיךְ? לְקוֹלִי הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא לְאוֹתוֹ קוֹל שֶׁנִּכְנְסוּ בוֹ.</p>\n<p>אָמַר רַבִּי אַבָּא, אַחַר שֶׁהִתְגַּלָּה בָּהֶם רֹשֶׁם הַקָּדוֹשׁ, נִכְנְסוּ בִּשְׁנֵי חֲלָקִים קְדוֹשִׁים, כְּמוֹ שֶׁנֶּאֱמַר, וְכֵיוָן שֶׁנִּכְנְסוּ בִּשְׁנֵי אֵלֶּה, נִכְנְסוּ בִּשְׁנֵי הַחֲלָקִים הָאֲחֵרִים הַלָּלוּ, שֶׁכַּאֲשֶׁר יַעֲלוּ בִּשְׁנֵי הָאֲחֵרִים הַלָּלוּ, יִתְחַבְּרוּ בְּאֵלֶּה וְלֹא יִמָּנְעוּ הַבְּרָכוֹת, וְלָכֵן בְּאֵלֶּה מַגִּיעוֹת הַבְּרָכוֹת (ומשום כך באלה מגיעים) עַד הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>וּמִמְּקוֹמוֹ שֶׁל הַכָּתוּב נִשְׁמָע הַדָּבָר, שֶׁכָּתוּב וַיֹּאמֶר אִם שָׁמוֹעַ תִּשְׁמַע. וַיֹּאמֶר - זֶה הַמֶּלֶךְ הַקָּדוֹשׁ. וּמָה אָמַר? אִם שָׁמוֹעַ תִּשְׁמַע לְקוֹל ה' אֱלֹהֶיךְ, כְּמוֹ שֶׁנֶּאֱמַר כִּי ה' אֱלֹהֶיךְ אֵשׁ אוֹכְלָה הוּא - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וְהַיָּשָׁר בְּעֵינָיו תַּעֲשֶׂה - זֶה צַדִּיק. וְהַאֲזַנְתָּ לְמִצְותָיו - זֶה נֶצַח. וְשָׁמַרְתָּ כָּל חֻקָּיו - זֶה הוֹד. כֵּיוָן שֶׁנִּכְנְסוּ בְאֵלֶּה, הֲרֵי הִגִּיעוּ לַמֶּלֶךְ הַקָּדוֹשׁ. אַחַר כָּךְ מַה כָּתוּב? כָּל הַמַּחֲלָה אֲשֶׁר שַׂמְתִּי בְמִצְרַיִם לֹא אָשִׂים עָלֶיךְ כִּי אֲנִי ה' רֹפְאֶךְ. כִּי אֲנִי ה' - זֶה הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>נִשְׁמָע, שֶׁכָּל מִי שֶׁשּׁוֹמֵר אֶת הָרֹשֶׁם הַקָּדוֹשׁ הַזֶּה, מִמֶּנּוּ עוֹלֶה עַד הַמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן. מַה מַּשְׁמָע? מַשְׁמָע אוֹתָם שְׁנַיִם שֶׁהִתְכַּנֵּס בָּהֶם הַזֶּרַע, וְשֶׁמֶן מִשְׁחַת קֹדֶשׁ, שֶׁשּׁוֹפְכִים אוֹתוֹ בְּפִי הָאָמָה, (ועל זה) נִקְשְׁרוּ כְאֶחָד, וְהַמֶּלֶךְ הָעֶלְיוֹן עֲלֵיהֶם, וְנִקְשְׁרוּ בוֹ. וְעַל כָּךְ, מִי שֶׁנִּכְנָס בִּשְׁנֵי אֵלֶּה וְשׁוֹמֵר אוֹתָם, נִקְשָׁר בִּשְׁנֵי הָאֲחֵרִים וְנִכְנָס בָּהֶם, וְאָז מַגִּיעַ לַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>אָמַר רַבִּי יִצְחָק, וַדַּאי מִי שֶׁזּוֹכֶה בְּצַדִּיק, זוֹכֶה בְּנֶצַח וְהוֹד וּשְׁלֹשֶׁת אֵלֶּה, שֶׁהִתְבָּרְכָה בָּהֶם כְּנֶסֶת יִשְׂרָאֵל. וּמִי שֶׁזּוֹכֶה בָּהֶם, זוֹכֶה בַּמֶּלֶךְ הַקָּדוֹשׁ, וְנִכְנָס בְּכָל הָאַ רְבָּעָה.</p>\n<p>וּכְנֶגֶד אַרְבָּעָה אֵלּוּ שְׁמִירָה לָרֹשֶׁם הַקָּדוֹשׁ הַזֶּה מֵאַרְבָּעָה דְבָרִים: שְׁמִירָה שֶׁל כְּנֶסֶת יִשְׂרָאֵל - שְׁמִירָה שֶׁל נִדָּה. שְׁמִירָה שֶׁל צַדִּיק - שְׁמִירָה שֶׁל שִׁפְחָה. שְׁמִירָה שֶׁל נֶצַח - שְׁמִירָה שֶׁל בַּת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. שְׁמִירָה שֶׁל הוֹד - שְׁמִירָה שֶׁל זוֹנָה. וְעַל זֶה לְקוֹל ה' אֱלֹהֶיךְ - זוֹ כְּנֶסֶת יִשְׂרָאֵל.</p>\n<p>בַּמֶּה זוֹכִים יִשְׂרָאֵל לְקַבֵּל פְּנֵי שְׁכִינָה? בִּשְׁמִירָה מִנִּדָּה, וְעַל זֶה כָּתוּב (ויקרא יח) וְאֶת אִשָּׁה בְּנִדַּת טֻמְאָתָהּ לֹא תִקְרַב לְגַלּוֹת עֶרְוָתָהּ. מַה זֶּה לְגַלּוֹת? זוֹ כְּנֶסֶת יִשְׂרָאֵל, וּבָזֶה אֲחוּזִים וְנִקְשָׁרִים דְּבָרִים אֲחֵרִים שֶׁכְּנֶסֶת יִשְׂרָאֵל נִקְשֶׁרֶת בָּהֶם. וַהֲרֵי בֵּאַרְנוּ הַדְּבָרִים.</p>\n<p>וְהַיָּשָׁר בְּעֵינָיו תַּעֲשֶׂה - זֶה צַדִּיק, כְּמוֹ שֶׁכָּתוּב (תהליםלד) עֵינֵי ה' אֶל צַדִּיקִים, לְהִשָּׁמֵר מִשִּׁפְחָה. וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים, שֶׁכָּתוּב וְשִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ, שֶׁגּוֹרֵם לַצַּדִּיק שֶׁיִּדְבַּק בְּשִׁפְחָה. וְהַאֲזַנְתָּ לְמִצְותָיו - זֶה נֶצַח, לְהִשָּׁמֵר (שלא ישקר בו) שֶׁלֹּא יַכְנִיס רֹשֶׁם זֶה בְּבַת אֵל נֵכָר, וְלֹא יְשַׁקֵּר בְּנֶצַח, שֶׁכָּתוּב (שמואל א טו) וְגַם נֶצַח יִשְׂרָאֵל לֹא יְשַׁקֵּר. וּמִי שֶׁשּׁוֹמֵר אֶת זֶה, קִיֵּם מִצְווֹתָיו, שֶׁכָּתוּב (שמותלד) כִּי לֹא תִשְׁתַּחֲוֶה לְאֵל אַחֵר. וְשָׁמַרְתָּ כָּל חֻקָּיו - זֶה סוֹד, לְהִשָּׁמֵר מִן זוֹנָה.</p>\n<p>וְזְהִ הוֹלֵךְ כְּמוֹ שֶׁשָּׁנִינוּ. אָמַר רַבִּי יְהוּדָה, מַה זֶּה שֶׁכָּתוּב (תהלים מה) חֲגוֹר חַרְבְּךְ עַל יָרֵךְ גִּבּוֹר הוֹדְךְ וַהֲדָרֶךְ. אֶלָּא, כָּל מִי שֶׁמְּזָרֵז אֶת עַצְמוֹ וְשָׂם אֶת פַּחַד הַחֶרֶב הַשְּׁנוּנָה הַחֲזָקָה כְּנֶגְדּוֹ, עַל יָרֵךְ - מַה זֶּה עַל יָרֵךְ? זֶהוּ הָרֹשֶׁם הַקָּדוֹשׁ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית כד) שִׂים נָא יָדְךְ תַּחַת יְרֵכִי.</p>\n<p>דָּבָר אַחֵר חֲגוֹר חַרְבְּךְ - כְּלוֹמַר, זָרֵז וּתְקֹף אֶת הַיֵּצֶר הָרָע שֶׁלְּךְ, שֶׁהוּא חַרְבְּךְ, עַל יָרֵךְ, עַל אוֹתוֹ רֹשֶׁם קָדוֹשׁ לִשְׁמֹר אוֹתוֹ. וְאִם שָׁמַר אוֹתוֹ אָז נִקְרָא גִּבּוֹר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַלְבִּישׁ אוֹתוֹ בִּלְבוּשָׁיו. וּמַהוּ לְבוּשׁ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא? הוֹד וְנֶצַח (והדר), שֶׁכָּתוּב (תהלים קד) הוֹד וְהָדָר לָבָשְׁתָּ. אַף כָּאן הוֹדְךְ וַהֲדָרֶךְ. וְאָז נִדְבָּק הָאָדָם בַּמֶּלֶךְ הַקָּדוֹשׁ כָּרָאוּי.</p>\n<p>מִכָּאן וָהָלְאָה - כָּל הַמַּחֲלָה אֲשֶׁר שַׂמְתִּי בְמִצְרַיִם לֹא אָשִׂים עָלֶיךְ כִּי אֲנִי ה' רֹפְאֶךְ. זֶה הַמֶּלֶךְ הַקָּדוֹשׁ. וְעַל זֶה הִזְהִיר אוֹתָם עַל אוֹתוֹ דָבָר מַמָּשׁ, שֶׁנָּתַן וְרָשַׁם בָּהֶם וְלֹא יוֹתֵר. וְעַד עַכְשָׁו לֹא נִתְּנָה לָהֶם תּוֹרָה. אֶלָּא כֵּיוָן שֶׁכָּתוּב, שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט, מִיָּד - וַיּאמֶר אִם שָׁמוֹעַ תִּשְׁמַע וְגוֹ'.</p>\n<p>בֹּא רְאֵה, כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַזְהִיר אֶת יִשְׂרָאֵל עַל הַתּוֹרָה, בְּכַמָּה דְבָרִים מָשַׁךְ אוֹתָם, בְּכַמָּה מְשִׁיכוֹת שֶׁל חֲבִיבוּת, כְּאָדָם שֶׁמּוֹשֵׁךְ בְּנוֹ לְבֵית הָרַב. וּבֹא רְאֵה, לֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לָתֵת לָהֶם תּוֹרָה עַד שֶׁקָּרְבוּ אֵלָיו. וּבַמֶּה קָרְבוּ אֵלָיו? בַּגִּלּוּי שֶׁל הָרֹשֶׁם הַזֶּה, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>אָמַר רַבִּי יְהוּדָה, לֹא קָרְבוּ יִשְׂרָאֵל לְהַר סִינַי, עַד שֶׁנִּכְנְסוּ בַּחֵלֶק שֶׁל צַדִּיק וְזָכוּ בוֹ. מִנַּיִן לָנוּ? שֶׁכָּתוּב (שמות יט) בַּיּוֹם הַזֶּה בָּאוּ מִדְבַּר סִינָי. בַּיּוֹם הַזֶּה מַמָּשׁ דַּוְקָא. וְכָתוּב (ישעיה כה) וְאָמַר בַּיּוֹם הַהוּא הִנֵּה אֱלֹהֵינוּ זֶה קִוִּינוּ לוֹ וְגוֹ'.</p>"],[9522011627,"<p>וַיֹּאמֶר ה' אֶל מֹשֶׁה הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים מא) אַשְׁרֵי מַשְׂכִּיל אֶל דָּל בְּיוֹם רָעָה יְמַלְּטֵהוּ ה'. פָּסוּק זֶה פֵּרְשׁוּהוּ, בְּשָׁעָה שֶׁאָדָם שׁוֹכֵב בְּבֵית חָלְיוֹ, הֲרֵי נִתְפָּס בְּבֵית הַסֹּהַר שֶׁל הַמֶּלֶךְ - רֹאשׁוֹ בְּקוֹלָר, רַגְלָיו בַּאֲזִיקִים (בדפוס), כַּמָּה חֲיָלוֹת שׁוֹמְרִים אוֹתוֹ מִצַּד זֶה וּמִצַּד זֶה, כָּל אֵיבָרָיו בְּדחַק נִלְחָמִים אֵלֶּה בְּאֵלֶּה, הָאֹכֶל הָעֳבַר מִמֶּנּוּ.</p>\n<p>בְּאוֹתוֹ הַזְּמַן מְמַנִּים עָלָיו אַפּוֹטְרוֹפּוֹס לְלַמֵּד עָלָיו זְכוּת לִפְנֵי הַמֶּלֶךְ, שֶׁכָּתוּב אִם יֵשׁ עָלָיו מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף. בְּאוֹתָהּ שָׁעָה אַשְׁרֵי חֶלְקוֹ שֶׁל הָאִישׁ שֶׁנִּכְנָס אֵלָיו וּמְלַמֵּד אוֹתוֹ דֶּרֶךְ לְהִנָּצֵל מִן הַדִּין. זֶהוּ שֶׁכָּתוּב אַשְׁרֵי מַשְׂכִּיל אֶל דָּל.</p>\n<p>וְאֵיךָ יָכוֹל לְהַצִּיל אוֹתוֹ? לְלַמְּדוֹ דֶּרֶךְ הַחַיִּים לָשׁוּב לִפְנֵי אֲדוֹנוֹ, אָז נַעֲשֶׂה אַפּוֹטְרוֹפּוֹס עָלָיו לְמַעְלָה. וּמַה שְּׂכָרוֹ? בְּיוֹם רָעָה יְמַלְּטֵהוּ ה'. דָּבָר אַחֵר אַשְׁרֵי מַשְׂכִּיל אֶל דָּל - כַּמָּה חָזָק הַשָּׂכָר שֶׁל הֶעָנִי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>אָמַר רַבִּי חִיָּיא, תָּמַהְתִּי עַל הַפָּסוּק הַזֶּה שֶׁכָּתוּב (שם סט) כִּי שּמֵעַ אֶל אֶבְיוֹנִים ה', וְכִי אֶל אֶבְיוֹנִים שׁוֹמֵעַ וְלֹא לְאַחֵר? אָמַר רַבִּי שִׁמְעוֹן, מִשּׁוּם שֶׁהֵם קְרוֹבִים יוֹתֵר לַמֶּלֶךְ, שֶׁכָּתוּב (שם נא) לֵב נִשְׁבָּר וְנִדְכֶּה אֱלֹהִים לֹא תִבְזֶה, וְאֵין לְךְ בָּעוֹלָם שֶׁהוּא שְׁבוּר לֵב כְּמוֹ הֶעָנִי. עוֹד, אָמַר רַבִּי שִׁמְעוֹן, בֹּא רְאֵה, כָּל אוֹתָם בְּנֵי הָעוֹלָם נִרְאִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגוּף וָנֶפֶשׁ, וְהֶעָנִי לֹא נִרְאֶה אֶלָּא בַּנֶּפֶשׁ לְבַדָּהּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא קָרוֹב לַנֶּפֶשׁ יוֹתֵר מִלַּגּוּף.</p>\n<p>עָנִי אֶחָד הָיָה בִּשְׁכֵנוּתוֹ שֶׁל רַבִּי יֵיסָא, וְלֹא הָיָה מִי שֶׁיַּשְׁגִּיחַ בּוֹ, וְהוּא הָיָה מִתְבַּיֵּשׁ וְלֹא הִפְצִיר בִּבְנֵי אָדָם. יוֹם אֶחָד נֶחֱלַשׁ, נִכְנַס עָלָיו רַבִּי יֵיסָא. שָׁמַע קוֹל אֶחָד שֶׁאוֹמֵר: צֶדֶק צֶדֶק, הֲרֵי נֶפֶשׁ פּוֹרַחַת אֵלַי וְלֹא הִגִּיעוּ יָמָיו! אוֹי לִבְנֵי עִירוֹ שֶׁלֹּא נִמְצָא בָהֶם שֶׁיָּשִׁיב נַפְשׁוֹ אֵלָיו! קָם רַבִּי יֵיסָא וְשָׁפַךְ בְּפִיו מַיִם שֶׁל גְּרוֹגָרוֹת עִם מִדָּה שֶׁל יַיִן רָקוּחַ. בַּקְּעָה זֵעָה בְּפָנָיו, וְשָׁב רוּחוֹ אֵלָיו.</p>\n<p>לְאַחַר בָּא וְשָׁאַל אוֹתוֹ. אָמַר: חַיֶּיךְ רַבִּי, נַפְשִׁי יָצְאָה מִמֶּנִּי וְהֵבִיאוּ אוֹתָהּ לִפְנֵי כִּסֵּא הַמֶּלֶךְ, וְרָצְתָה לְהִשָּׁאֵר שָׁם, אֶלָּא שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְזַכּוֹת אוֹתְךְ, וְהִכְרִיזוּ עָלֶיךְ: עָתִיד הוּא רַבִּי יֵיסָא לְהַעֲלוֹת רוּחוֹ וּלְהִתְקַשֵּׁר בְּחֶדֶר אֶחָד קָדוֹשׁ שֶׁעֲתִידִים הַחֲבֵרִים לְעוֹרֵר בָּאָרֶץ. וַהֲרֵי תִּקְּנוּ שְׁלֹשָׁה כִּסְאוֹת שֶׁעוֹמְדִים לְךְ וְלַחֲבֵרֶיךְ. מֵאוֹתוֹ הַיּוֹם הָיוּ מַשְׁגִּיחִים בּוֹ בְּנֵי עִירוֹ.</p>\n<p>עוֹד, עָנִי אֶחָד אַחֵר עָבַר לִפְנֵי רַבִּי יִצְחָק, וְהָיָה בְּיָדוֹ חֲצִי מָעָה כֶּסֶף. אָמַר לְרַבִּי יִצְחָק: הַשְׁלֵם לִי וּלְבָנַי וְלִבְנוֹתַי אֶת נַפְשׁוֹתֵינוּ. אָמַר לוֹ: וְאֵיךְ אַשְׁלִים לְנַפְשׁוֹתֵיכֶם, שֶׁהֲרֵי לֹא נִמְצָא אֶצְלִי כִּי אִם חֲצִי מָעָה? אָמַר לוֹ: בָּזֶה אֲנִי אַשְׁלִים בַּחֲצִי מָעָה שֶׁיֵּשׁ אֶצְלִי. הוֹצִיאָהּ וְנָתַן לוֹ.</p>\n<p>הֶרְאוּ לוֹ בַּחֲלוֹמוֹ, שֶׁהָיָה עוֹבֵר עַל שְׂפַת הַיָּם הַגָּדוֹל וְרָצוּ לִזְרֹק אוֹתוֹ לְתוֹכוֹ, רָאָה אֶת רַבִּי שִׁמְעוֹן שֶׁהוֹשִׁיט יָדוֹ כְּנֶגְדּוֹ, וּבָא אוֹתוֹ עָנִי וְהוֹצִיאוֹ, וּנְתָנוֹ בִּידֵי רַבִּי שִׁמְעוֹן וְנִצַּל. כְּשֶׁהִתְעוֹרֵר, נָפַל בְּפִיו פָּסוּק זֶה, (תהלים מא) אַשְׁרֵי מַשְׂכִּיל אֶל דָּל בְּיוֹם רָעָה יְמַלְּטֵהוּ ה'.</p>\n<p>וּבֹא רְאֵה, כָּל יוֹם וָיוֹם נוֹטֵף טַל מֵהָעַתִּיק הַקָּדוֹשׁ לִזְעֵיר אַנְפִּין, וּמִתְבָּרְכִים כָּל שְׂדֵה הַתַּפּוּחִים הַקְּדוֹשִׁים, וּמֵאוֹתוֹ טַל נִשְׁפָּע לְאֵלּוּ שֶׁלְּמַטָּה, וּמִמֶּנּוּ נִזּוֹנִים מַלְאָכִים קְדוֹשִׁים, כָּל אֶחָד וְאֶחָד כְּפִי מַאֲכָלוֹ. זֶהוּ שֶׁכָּתוּב (שם עח) לֶחֶם אַבִּירִים אָכַל אִישׁ, וּמֵאוֹתוֹ מָזוֹן אָכְלוּ יִשְׂרָאֵל בַּמִּדְבָּר.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כַּמָּה בְּנֵי אָדָם נִזּוֹנִים בַּזְּמַן הַזֶּה מִמֶּנּוּ, וּמִי הֵם? אֵלּוּ הַחֲבֵרִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה יָמִים וְלֵילוֹת. וְכִי יַעֲלֶה עַל דַּעְתְּךְ מֵאוֹתוֹ מָזוֹן מַמָּשׁ? לֹא, אֶלָּא כְּעֵין אוֹתוֹ מָזוֹן מַמָּשׁ שֶׁשָּׁקוּל עַל אֶחָד פִּי שְׁנַיִם.</p>\n<p>בֹּא רְאֵה, כְּשֶׁנִּכְנְסוּ יִשְׂרָאֵל וְנִדְבְּקוּ בַּמֶּלֶךְ הַקָּדוֹשׁ מִשּׁוּם גִּלּוּי שֶׁל הָרֹשֶׁם הַקָּדוֹשׁ, אָז זָכוּ לֶאֱכֹל לֶחֶם אַחֵר עֶלְיוֹן יוֹתֵר מִמַּה שֶּׁהָיָה בַּתְּחִלָּה. בַּתְּחִלָּה, כְּשֶׁיָּצְאוּ מִמִּצְרַיִם, נִכְנְסוּ לְלֶחֶם שֶׁנִּקְרָא מַצָּה, וְכָעֵת זָכוּ וְנִכְנְסוּ לֶאֱכֹל לֶחֶם אַחֵר יוֹתֵר עֶלְיוֹן, מִמָּקוֹם עֶלְיוֹן, שֶׁכָּתוּב הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם. מִן הַשָּׁמַיִם מַמָּשׁ. וּבְאוֹתוֹ זְמַן הוּא נִמְצָא לָהֶם לְיִשְׂרָאֵל מִמָּקוֹם זֶה. חֲבֵרִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, נִזּוֹנוּ מִמָּקוֹם אַחֵר יוֹתֵר עֶלְיוֹן, וּמַהוּ? כַּכָּתוּב (קהלת ז) הַחָכְמָה תְּחַיֶּה בְעָלֶיהָ. מָקוֹם יוֹתֵר עֶלְיוֹן.</p>\n<p>אָמַר לוֹ רַבִּי אֶלְעָזָר, אִם כָּךְ, לָמָּה חָלְשָׁה נַפְשָׁם יוֹתֵר מִשְּׁאָר בְּנֵי הָעוֹלָם, שֶׁהֲרֵי שְׁאָר בְּנֵי הָעוֹלָם בְּכֹחַ וְחֹזֶק יָתֵר נִרְאִים לְהִמָּצֵא (הם יותר) ? אָמַר לוֹ, יָפֶה שָׁאַלְתָּ.</p>\n<p>בֹּא רְאֵה, כָּל מְזוֹנוֹתֵיהֶם שֶׁל בְּנֵי הָעוֹלָם בָּאִים מִלְמַעְלָה. אוֹתוֹ מָזוֹן שֶׁבָּא מִן הַשָּׁמַיִם וְהָאָרֶץ, זֶה מָזוֹן שֶׁל כָּל הָעוֹלָם, וְהוּא מָזוֹן שֶׁל הַכֹּל, וְהוּא מָזוֹן גַּס וְעָב. וְאוֹתוֹ מָזוֹן שֶׁבָּא יוֹתֵר מִלְמַעְלָה, הוּא מָזוֹן יוֹתֵר דַּקִּיק, שֶׁבָּא מִמָּקוֹם שֶׁנִּמְצָא הַדִּין, וְזֶהוּ הַמָּזוֹן שֶׁאָכְלוּ יִשְׂרָאֵל כְּשֶׁיָּצְאוּ מִמִּצְרַיִם. (יותר דקיק) הַמָּזוֹן שֶׁנִּמְצָא לָהֶם לְיִשְׂרָאֵל בְּאוֹתוֹ זְמַן בַּמִּדְבָּר, מִמָּקוֹם עֶלְיוֹן שֶׁנִּקְרָא שָׁמַיִם, הוּא מָזוֹן יוֹתֵר דַּקִּיק, שֶׁנִּכְנַס יוֹתֵר לַנֶּפֶשׁ מֵהַכֹּל, וְנִפְרַד יוֹתֵר מֵהַגּוּף, וְנִקְרָא לֶחֶם אַבִּירִים.</p>\n<p>הַמָּזוֹן הַיּוֹתֵר עֶלְיוֹן מֵהַכֹּל הוּא מְזוֹן הַחֲבֵרִים, אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, שֶׁאוֹכְלִים מָזוֹן שֶׁל רוּחַ וּנְשָׁמָה, וְלֹא אוֹכְלִים מְזוֹן הַגּוּף כְּלָל, וְהַיְינוּ מִמָּקוֹם עֶלְיוֹן נִכְבָּד עַל הַכֹּל, וְנִקְרָא חָכְמָה. לָכֵן חַלָּשׁ גּוּף הַחֲבֵרִים יוֹתֵר מִבְּנֵי הָעוֹלָם, שֶׁהֲרֵי לֹא אוֹכְלִים מְזוֹן הַגּוּף כְּלָל, וְאוֹכְלִים מָזוֹן שֶׁל רוּחַ וּנְשָׁמָה מִמָּקוֹם רָחוֹק עֶלְיוֹן נִכְבָּד מֵהַכֹּל. וְלָכֵן אוֹתוֹ מָזוֹן דַּקִּיק מִן הַדַּקִּיק יוֹתֵר מֵהַכֹּל. אַשְׁרֵי חֶלְקָם. זֶהוּ שֶׁכָּתוּב הַחָכְמָה תְּחַיֶּה בְעָלֶיהָ. אַשְׁרֵי חֶלְקוֹ שֶׁל הַגּוּף שֶׁיָּכוֹל לְהִזּוֹן בִּמְזוֹן הַנֶּפֶשׁ.</p>\n<p>אָמַר לוֹ רַבִּי אֶלְעָזָר, וַדַּאי כָּךְ הוּא. אֲבָל בַּזְּמַן הַזֶּה אֵיךְ נִמְצָאִים מְזוֹנוֹת אֵלוּ? אָמַר לוֹ, וַדַּאי שֶׁיָּפֶה שָׁאַלְתָּ. בּא רְאֵה, וְזֶהוּ בֵּרוּר הַדָּבָר, מָזוֹן רִאשׁוֹן הוּא מָזוֹן שֶׁל כָּל הָעוֹלָם, אוֹתוֹ שֶׁבָּא מִשָּׁמַיִם וָאָרֶץ, וְהוּא מְזוֹן הַגּוּף (של הכל).</p>\n<p>מָזוֹן שֶׁהוּא יוֹתֵר עֶלְיוֹן מִמֶּנּוּ, אוֹתוֹ שֶׁהוּא יוֹתֵר דַּקִּיר, וּבָא מִמָּקוֹם שֶׁהַדִּין שָׁרוּי, שֶׁנִּקְרָא צֶדֶק, וְזֶהוּ מְזוֹן הָעֲנִיִּים. וְסוֹד הַדָּבָר - מִי שֶׁמַּשְׁלִים לֶעָנִי, מַשְׁלִים לוֹ אוֹת אַחַת וְנַעֲשֶׂה צְדָקָה, וְסוֹד זֶה - (משלי יא) גֹּמֵל נַפְשׁוֹ אִישׁ חָסֶד. גְּמִילוּת חֲסָדִים מַשְׁמָע, שֶׁהֲרֵי בְּדִין שָׁרוּי, וְהִשְׁלִים לוֹ חֶסֶד, אָז הוּא רַחֲמִים.</p>\n<p>מָזוֹן יוֹתֵר עֶלְיוֹן מֵאֵלֶּה, הוּא מָזוֹן עֶלְיוֹן וְנִכְבָּד מִמָּקוֹם שֶׁנִּקְרָא שָׁמַיִם, וְהוּא דַּקִּיק מִכֻּלָּם, וְהוּא מָזוֹן שֶׁל חוֹלִים. זֶהוּ שֶׁכָּתוּב (תהלים מא) ה' יִסְעָדֶנּוּ עַל עֶרֶשׂ דְּוָי כָּל מִשְׁכָּבוֹ הָפַכְתָּ בְחָלְיוֹ. ה' דַּוְקָא. מָה הַטַּעַם? מִשּׁוּם שֶׁהַחוֹלִים הַלָּלוּ אֵינָם נִזּוֹנִים אֶלָּא בְּאוֹתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מַמָּשׁ. (ומהו, ' חלב ודם. זהו שכתוב (יחזקאל מד) להקריב לי חלב ודם. וזהו מזון ממקום שגקרא שמים, והוא נכבד ועליון, דקיק מהכל).</p>\n<p>מָזוֹן עֶלְיוֹן קָדוֹשׁ וְנִכְבָּד זֶהוּ מְזוֹנוֹת שֶׁל רוּחוֹת וּנְשָׁמוֹת, וְהוּא מָזוֹן שֶׁל מָקוֹם רָחוֹק עֶלְיוֹן, (מאותו מקום שגקרא נעם ה').</p>\n<p>וְהַנִּכְבָּד מֵהַכֹּל הוּא מְזוֹן הַחֲבֵרִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, וְהוּא מָזוֹן שֶׁבָּא מֵחָכְמָה עֶלְיוֹנָה. מָה הַטַּעַם מִמָּקוֹם זֶה? מִשּׁוּם שֶׁתּוֹרָה יָצְאָה מֵחָכְמָה עֶלְיוֹנָה, וְאוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה נִכְנָסִים בְּעִקַּר שָׁרָשֶׁיהָ, וְלָכֵן מְזוֹנָם בָּא מֵאוֹתוֹ מָקוֹם קָדוֹשׁ עֶלְיוֹן.</p>\n<p>בָּא רַבִּי אֶלְעָזָר וְנָשַׁק יָדוֹ. אָמַר, אַשְׁרֵי חֶלְקִי שֶׁעָמַדְתִּי בַּדְּבָרִים הַלָּלוּ! אַשְׁרֵי הַצַּדִּיקִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה יָמִים וְלֵילוֹת, שֶׁזּוֹכִים לָהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁכָּתוּב (דברים ל) כִּי הוּא חַיֶּיךְ וְאֹרֶךְ יָמֶיךְ.</p>\n<p>הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם. רַבִּי יוֹסֵי פָּתַח, (תהליםקמה) פּוֹתֵחַ אֶת יָדֶךְ וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן. מַה כָּתוּב לְמַעְלָה? עֵינֵי כֹל אֵלֶיךְ יְשַׂבֵּרוּ. כָּל אוֹתָם בְּנֵי הָעוֹלָם מְצַפִּים וְזוֹקְפִים עֵינַיִם לַקָּדוֹשׁ- בָּרוּךְ-הוּא, וְלָכֵן (אבל) כָּל אוֹתָם בְּנֵי הָאֱמוּנָה מְבַקְשִׁים (צריכיםלבקש) בְּכָל יוֹם וָיוֹם לִשְׁאֹל אֶת מְזוֹנָם מִן הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהִתְפַּלֵּל תְּפִלּוֹתֵיהֶם עָלָיו.</p>\n<p>מָה הַטַּעַם? מִשּׁוּם שֶׁכָּל מִי שֶׁמִּתְפַּלֵּל תְּפִלָּתוֹ לַקָּדוֹשׁ-בָּרוּךְ- הוּא עַל מְזוֹנוֹ, גּוֹרֵם שֶׁיִּתְבָּרֵךְ כָּל הַיּוֹם עַל יָדוֹ אוֹתוֹ הָאִילָן שֶׁמְּזוֹן כֻּלָּם בּוֹ. (וטעם הדבר (תהלים סח) ברוך ה' יום יום) וְאַף עַל גַּב שֶׁנִּמְצָא עִמּוֹ, צָרִיךְ לְבַקֵּשׁ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהִתְפַּלֵּל תְּפִלָּה עַל הַמָּזוֹן בְּכָל יוֹם, כְּדֵי שֶׁיִּמָּצְאוּ עַל יָדוֹ בְּרָכוֹת כָּל יוֹם וָיוֹם לְמַעְלָה, וְזֶהוּ (שם סח) בָּרוּךְ ה' יוֹם יוֹם.</p>\n<p>וְעַל זֶה לֹא צָרִיךְ לָאָדָם לְבַשֵּׁל מָזוֹן מִיּוֹם לְיוֹם אַחֵר, שֶׁלֹּא לְעַכֵּב יוֹם לְיוֹם אַחֵר. זֶהוּ שֶׁכָּתוּב וְיָצָא הָעָם וְלָקְטוּ דְּבַר יוֹם בְּיוֹמוֹ. יוֹם בְּיוֹמוֹ דַּוְקָא, חוּץ מֵעֶרֶב שַׁבָּת לְשַׁבָּת, כְּמוֹ שֶׁבֵּאַרְנוּ. וְאָז נִמְצָא הַקָּדוֹשׁ בָּרוּךְ הוּא מָלֵא בְּרָכוֹת בְּכָל יוֹם, וְאָז כָּתוּב פּוֹתֵחַ אֶת יָדֶךְ וְגוֹ'. מָה זֶה רָצוֹן? אוֹתוֹ רָצוֹן שֶׁנִּמְצָא מֵהָעַתִּיק הַקָּדוֹשׁ, וְיוֹצֵא מִמֶּנּוּ רָצוֹן לְהַמְצִיא מָזוֹן לַכֹּל. וּמִי שֶׁשּׁוֹאֵל מְזוֹנוֹת בְּכָל יוֹם וָיוֹם, הַהוּא נִקְרָא בֵּן נֶאֱמָן, בְּסוֹד שֶׁבִּשְׁבִילוֹ נִמְצָאִים בְּרָכוֹת לְמַעְלָה.</p>\n<p>רַבִּי אַבָּא פָּתַח וְאָמַר, (שם קמז) רוֹצֶה ה' אֶת יְרֵאָיו אֶת הַמְיַחֲלִים לְחַסְדּוֹ. כַּמָּה יֵשׁ לִבְנֵי אָדָם לָלֶכֶת בְּדַרְכֵי הַמֶּלֶךְ הַקָּדוֹשׁ וְלָלֶכֶת בְּדַרְכֵי הַתּוֹרָה כְּדֵי שֶׁיִּמָּצְאוּ בְרָכוֹת לְכֻלָּם, לָעֶלְיוֹנִים וְלַתַּחְתּוֹנִים.</p>\n<p>שֶׁלָּמַדְנוּ, מַה שֶּׁכָּתוּב (ישעיה מט) יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר, וַדַּאי אֶתְפָּאָר. מַה מַּשְׁמִיעַ? שֶׁבִּשְׁבִיל יִשְׂרָאֵל לְמַטָּה, הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְפָּאֵר לְמַעְלָה. וּמָה הַפְּאֵר שֶׁלּוֹ? שֶׁמֵּנִיחַ תְּפִלִּין, שֶׁמִּתְחַבְּרִים הַגְּוָנִים לְהִתְפָּאֵר.</p>\n<p>שָׁנִינוּ, רוֹצֶה ה' אֶת יְרֵאָיו, רוֹצֶה ה' בִּירֵאָיו הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה רוֹצֶה ה' אֶת יְרֵאָיו? אֶלָּא רוֹצֶה ה' אֶת יְרֵאָיו, כְּלוֹמַר, מוֹצִיא אֶת הָרָצוֹן הַזֶּה, וּמִתְרַצֶּה (ומתידע) בָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לִירֵאָיו הַיְרֵאִים מִמֶּנּוּ. וּמִי הֵם הַיְרֵאָיו הָאֵלֶּה שֶׁמּוֹצִיא לָהֶם אֶת הָרָצוֹן הַזֶּה? חָזַר וְאָמַר אֶת הַמְיַחֲלִים לְחַסְדּוֹ, אוֹתָם הַמְצַפִּים וּמְחַכִּים בְּכָל יוֹם וָיוֹם לְבַקֵּשׁ מְזוֹנָם מִן הַקָּדוֹשׁ בָּרוּךְ הוּא, מַשְׁמָע שֶׁכָּתוּב אֶת הַמְיַחֲלִים לְחַסְדּוֹ.</p>\n<p>רַבִּי יֵיסָא סָבָא לֹא הִתְקִין סְעוּדָה בְּכָל יוֹם עַד שֶׁבִּקֵּשׁ בַּקָּשָׁתוֹ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עַל מְזוֹנוֹת. אָמַר, לֹא נַתְקִין סְעוּדָה עַד שֶׁתִּנָּתֵן מִבֵּית הַמֶּלֶךְ. אַחַר שֶׁבִּקֵּשׁ בַּקָּשָׁתוֹ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, הָיָה מְחַכֶּה שָׁעָה אַחַת, וְאָמַר: הֲרֵי זְמַן שֶׁנִּתָּן מִבֵּית הַמֶּלֶךְ, מִכָּאן וָהָלְאָה הַתְקִינוּ הַסְּעוּדָה! וְזוֹהִי הַדֶּרֶךְ שֶׁל אוֹתָם יִרְאֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, יִרְאֵי חֵטְא.</p>\n<p>אוֹתָם הָרְשָׁעִים שֶׁהוֹלְכִים עֲקֻמִּים בְּדַרְכֵי הַתּוֹרָה, מַה כָּתוּב בָּהֶם? (ישעיה ה) הוֹי מַשְׁכִּימֵי בַבֹּקֶר שֵׁכָר יִרְדֹּפוּ. וְעַל זֶה רוֹצֶה ה' אֶת יְרֵאָיו אֶת הַמְיַחֲלִים לְחַסְדּוֹ. דַּוְקָא לְחַסְדּוֹ. (ובזה) נוֹדָעִים בְּנֵי הָאֱמוּנָה בְּכָל יוֹם וָיוֹם. זֶהוּ שֶׁכָּתוּב וְיָצָא הָעָם וְלָקְטוּ דְּבַר יוֹם בְּיוֹמוֹ. יוֹם בְּיוֹמוֹ אָמַר, וְלֹא דְּבַר יוֹם לְיוֹם אַחֵר.</p>\n<p>וְכָל כָּךְ לָמָּה? לְמַעַן אֲנַסֶּנּוּ הֲיֵלֵךְ בְּתוֹרָתִי אִם לֹא. בְּכָאן נוֹדָעִים אוֹתָם בְּנֵי הָאֱמוּנָה, שֶׁכָּל יוֹם וָיוֹם הוֹלְכִים בְּדֶרֶךְ יְשָׁרָה בַּתּוֹרָה. רַבִּי יִצְחָק אָמַר מִכָּאן, (משלי יג) צַדִּיק אֹכֵל לְשּבַע נַפְשׁוֹ - אַחַר שֶׁהִשְׂבִּיעַ נַפְשׁוֹ מִלְּהִתְפַּלֵּל וְלִקְרֹא בַּתּוֹרָה.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, בֹּא רְאֵה, עַד שֶׁלֹּא נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא תּוֹרָה לְיִשְׂרָאֵל, הִבְחִין בֵּין אוֹתָם בְּנֵי הָאֱמוּנָה לְבֵין אוֹתָם רְשָׁעִים שֶׁאֵינָם בְּנֵי אֱמוּנָה וְלֹא עוֹמְדִים בַּתּוֹרָה. וּבַמָּה הִבְחִין בָּהֶם? בַּמָּן, כְּמוֹ שֶׁנֶּאֱמַר אֲנַסֶּנּוּ. וְכָל אוֹתָם שֶׁנִּמְצְאוּ שֶׁהֵם בְּנֵי הָאֱמוּנָה, רָשַׁם אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרֹשֶׁם שֶׁל כֶּתֶר הַחֶסֶ\"ד, כְּמוֹ שֶׁנֶּאֱמַר הַמְיַחֲלִים לְחַסְדּוֹ, וְעַל זֶה לְמַעַן אֲנַסֶּנּוּ. וְכָל אוֹתָם שֶׁלֹּא נִמְצְאוּ בְּנֵי אֱמוּנָה, הֶעֱבִיר מֵהֶם הַכֶּתֶר הָעֶלְיוֹן הַזֶּה, וְהַמָּן הִכְרִיז וְאָמַר, וּבֶטֶן רְשָׁעִים תֶּחְסָר. וְעִם כָּל זֶה, לֹא הֶעְדִּיף הַמַּרְבֶּה וְהַמַּמְעִיט לֹא הֶחְסִיר.</p>\n<p>שָׁנִינוּ, בַּשָּׁעָה הַהִיא נִשְׁלְמוּ יִשְׂרָאֵל לְמַטָּה כְּדֻגְמָא שֶׁל מַעְלָה, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁכָּתוּב (שמות טו) וַיָּבאוּ אֵילִמָה וְשָׁם שְׁתֵּים עֶשְׂרֵה עֵינֹת מַיִם וְשִׁבְעִים תְּמָרִים וְגוֹ'. וְהִתְחַזֵּק הָאִילָן הַקָּדוֹשׁ בִּשְׁנֵים עָשָׂר תְּחוּמִים, בְּאַרְבָּעָה צִדְדֵי הָעוֹלָם, וְהִתְחַזֵּק בְּשִׁבְעִים עֲנָפִים, וְהַכֹּל כַּדֻּגְמָא שֶׁל מַעְלָה.</p>\n<p>בְּאוֹתָהּ שָׁעָה נָטַף טַל קָדוֹשׁ מֵהָעַתִּיק הַנִּסְתָּר, וּמִלֵּא אֶת רֹאשׁוֹ שֶׁל זְעֵיר אַנְפִּין, מָקוֹם שֶׁנִּקְרָא שָׁמַיִם. וּמֵאוֹתוֹ טַל שֶׁל אוֹר עֶלְיוֹן קָדוֹשׁ הָיָה שׁוֹפֵעַ וְיוֹרֵד מָן לְמַטָּה, וּכְשֶׁהָיָה יוֹרֵד, הָיָה נִפְרָד גְּלִידִים גְּלִידִים, וְנִקְרָשׁ לְמַטָּה. זֶהוּ שֶׁכָּתוּב דַּק כַּכְּפֹר עַל הָאָרֶץ.</p>\n<p>כָּל אוֹתָם בְּנֵי אֱמוּנָה יוֹצְאִים וְלוֹקְטִים, וּמְבָרְכִים עָלָיו אֶת הַשֵּׁם הַקָּדוֹשׁ, וְאוֹתוֹ מָן הָיָה מַעֲלֶה רֵיחוֹת שֶׁל כָּל הַבְּשָׂמִים שֶׁל גַּן עֵדֶן, שֶׁהֲרֵי מִמֶּנּוּ נִמְשַׁךְ וְיָרַד לְמַטָּה. שָׂם אוֹתוֹ לְפָנָיו, וּבְכָל טַעַם שֶׁרָצָה - הָיָה טוֹעֵם אוֹתוֹ, וּמְבָרֵךְ אֶת הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>וְאָז מִתְבָּרֵךְ בְּמֵעָיו, וְהָיָה מִסְתַּכֵּל וְיוֹדֵעַ לְמַעְלָה, וּמִסְתַּכֵּל בַּחָכְמָה הָעֶלְיוֹנָה, וְעַל זֶה הָיָה נִקְרָא דּוֹר דֵּעָה. וְאֵלֶּה הָיוּ בְּנֵי אֱמוּנָה, וְלָהֶם נִתְּנָה תּוֹרָה לְהִסְתַּכֵּל בָּהּ וְלָדַעַת דְּרָכֶיהָ.</p>\n<p>וְאוֹתָם שֶׁלֹּא נִמְצְאוּ בְּנֵי אֱמוּנָה, מַה כָּתוּב בָּהֶם? (במדבר יב) שָׁטוּ הָעָם וְלָקְטוּ. מַה זֶּה שָׁטוּ? שְׁטוּת הָיוּ לוֹקְחִים לְעַצְמָם, מִשּׁוּם שֶׁלֹּא הָיוּ בְּנֵי אֱמוּנָה. מַה כָּתוּב בָּהֶם? וְטָחֲנוּ בָרֵחַיִם אוֹ דָכוּ בַּמְּדכָה וְגוֹ'. מִי הִטְרִיחַ אוֹתָם לְכָל זֶה? אֶלָּא שֶׁהֵם לֹא הָיוּ בְּנֵי אֱמוּנָה.</p>\n<p>כְּמוֹ זֶה אוֹתָם שֶׁלֹּא מַאֲמִינִים בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, לֹא רוֹצִים לְהִסְתַּכֵּל בִּדְרָכָיו, וְהֵם רוֹצִים לְהַטְרִיחַ אֶת עַצְמָם כָּל יוֹם אַחַר מָזוֹן יוֹם וָלַיְלָה, אוּלַי לֹא יַעֲלֶה בְיָדָם פַּת לֶחֶם. מִי גָרַם לָהֶם אֶת זֶה? מִשּׁוּם שֶׁאֵינָם בְּנֵי אֱמוּנָה.</p>\n<p>אַף כָּאן, שָׁטוּ וְלָקְטוּ - שָׁטוּ בַּשְּׁטוּת שֶׁל עַצְמָם, וְרוֹצִים לְהַטְרִיחַ עָלָיו. זֶהוּ שֶׁכָּתוּב וְטָחֲנוּ בָרֵחַיִם. אַחַר כָּל הַטִּרְחָה הַזּוֹ לֹא עָלָה בִידֵיהֶם, אֶלָּא שֶׁכָּתוּב וְהָיָה טַעְמוֹ כְּטַעַם לְשַׁד הַשָּׁמֶן, וְלֹא יוֹתֵר. מִי גָרַם לָהֶם אֶת זֶה? מִשּׁוּם שֶׁלֹּא הָיוּ בְּנֵי אֱמוּנָה.</p>\n<p>אָמַר רַבִּי יוֹסֵי, מַה זֶּה לְשַׁד הַשָּׁמֶן? יֵשׁ אוֹמְרִים, שֶׁהָיָה נִלּוֹשׁ בְּשֶׁמֶן כְּתַרְגּוּמוֹ. וְיֵשׁ אוֹמְרִים, מָה הַשָּׁד מִתְהַפֵּךְ לְכַמָּה גְוָנִים, אַף הַמָּן מִתְהַפֵּךְ לְכַמָּה גְוָנִים. רַבִּי יְהוּדָה אָמַר, לְשַׁד הַשָּׁמֶן - יְנִיקַת הַשֶּׁמֶן.</p>\n<p>רַבִּי יִצְחָק אָמַר, אִישׁ לְפִי אָכְלוֹ לָקָטוּ - וְכִי מִי שֶׁאוֹכֵל מְעַט לוֹקֵט מְעַט, וּמִי שֶׁאוֹכֵל יוֹתֵר לוֹקֵט יוֹתֵר? וַהֲרֵי כָּתוּב לֹא הֶעְדִּיף הַמַּרְבֶּה וְהַמַּמְעִיט לֹא הֶחְסִיר? אֶלָּא לְפִי אוֹתָם שֶׁאוֹכְלִים, לוֹקְטִים. מַשְׁמָע אָכְלוֹ - מִי שֶׁהָיָה אוֹכֵל אוֹתוֹ. וּמִשּׁוּם כָּךְ לֹא כָתוּב אֲכִילָתוֹ.</p>\n<p>מַה זֶּה אוֹמֵר? אָחַז אָדָם בְּעֶבֶד אוֹ בְּאָמָה וְאָמַר שֶׁהוּא שֶׁלּוֹ. בָּא חֲבֵרוֹ וְאָמַר: עֶבֶד זֶה הוּא שֶׁלִּי! קָרְבוּ לִפְנֵי מֹשֶׁה לְדִין. אָמַר לָהֶם: כַּמָּה נְפָשׁוֹת בְּבֵיתְךְ, וְכַמָּה נְפָשׁוֹת בְּבֵיתוֹ שֶׁל זֶה? אָמַר כָּךְ וְכָךְ. וְאוֹתָהּ שָׁעָה אָמַר לָהֶם מֹשֶׁה: לִקְטוּ מָחָר, וְכָל אֶחָד יָבֹא אֵלַי. לְמָחָר יָצְאוּ וְלָקְטוּ, וּבָאוּ לִפְנֵי מֹשֶׁה. שָׂמוּ לְפָנָיו אֶת הַמָּן, וְהָיָה מוֹדֵד אוֹתוֹ. אִם אוֹתוֹ עֶבֶד שֶׁל זֶה - מָצָא אֶת אוֹתוֹ הָעֹמֶר שֶׁל הָעֶבֶד בַּמָּן הַזֶּה, שֶׁהֲרֵי עֹמֶר אֶחָד לְכָל נֶפֶשׁ וְנֶפֶשׁ מִבֵּיתוֹ. מָדַד לָזֶה - וְנִמְצָא חָסֵר אוֹתוֹ מַאֲכַל הָעֶבֶד בַּמָּן שֶׁלּוֹ, וְעֹמֶר אֶחָד לְכָל נֶפֶשׁ וְנֶפֶשׁ מִבֵּיתוֹ. אָמַר וּפָסַק: הָעֶבֶד שֶׁל זֶה הוּא! זֶהוּ שֶׁכָּתוּב אִישׁ לְפִי אָכְלוֹ לָקָטוּ. וְכָתוּב עֹמֶר לַגֻּלְגֹּלֶת מִסְפַּר נַפְשֹׁתֵיכֶם.</p>\n<p>אָמַר רַבִּי (ייסא) חִיָּיא, כָּתוּב עֶרֶב וִידַעְתֶּם כִּי ה' הוֹצִיא אֶתְכֶם מֵאֶרֶץ מִצְרָיִם וּבֹקֶר וּרְאִיתֶם אֶת כְּבוֹד ה'. עֶרֶב וִידַעְתֶּם, בַּמֶּה יֵדְעוּ? אֶלָּא כָּךְ שָׁנִינוּ, בְּכָל יוֹם וָיוֹם נִמְצְאוּ הַנְהָגוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא - בַּבֹּקֶר הִתְעוֹרֵר חֶסֶד בָּעוֹלָם. בְּאוֹתוֹ זְמַן שֶׁנִּקְרָא עֶרֶב, תָּלוּי הַדִּין בָּעוֹלָם, וַהֲרֵי פֵּרְשׁוּהָ שֶׁלָּכֵן יִצְחָק תִּקֵּן תְּפִלַּת הַמִּנְחָה. (מה זה אומר) וְעַל זֶה עֶרֶב וִידַעְתֶּם. כְּשֶׁמִּתְעוֹרֵר דִּין בָּעוֹלָם, תֵּדְעוּ שֶׁבְּאוֹתוֹ דִין הוֹצִיא אֶתְכֶם ה' מִמִּצְרַיִם. וּבֹקֶר וּרְאִיתֶם אֶת כְּבוֹד ה', שֶׁהֲרֵי בְּאוֹתוֹ זְמַן מִתְעוֹרֵר חֶסֶד וְיִתֵּן לָכֶם לֶאֱכֹל.</p>\n<p>רַבִּי חִיָּיא אָמַר הַהֵפֶךְ. מַה כָּתוּב לְמַעְלָה? בְּשִׁבְתֵּנוּ עַל סִיר הַבָּשָׂר וְגוֹ'. בְּאוֹתָהּ שָׁעָה הִתְעוֹרֵר עֶרֶב. שֶׁאוֹתוֹ זְמַן שֶׁמִּתְעוֹרֵר דִּין, מִתְעוֹרֵר גַּם חֶסֶד בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב וִידַעְתֶּם כִּי ה' הוֹצִיא אֶתְכֶם מֵאֶרֶץ מִצְרַיִם. תֵּדְעוּ אוֹתוֹ חֶסֶד שֶׁעָשָׂה עִמָּכֶם בִּזְמַן הַדִּין וְהוֹצִיא אֶתְכֶם מֵאֶרֶץ מִצְרַיִם. וּבֹקֶר וּרְאִיתֶם אֶת כְּבוֹד ה', כְּבוֹד ה' הֲרֵי יָדוּעַ, וְכָל כָּךְ לָמָּה? בִּשְׁמֹעַ ה' אֶת תְּלֻנֹּתֵיכֶם וְגוֹ'.</p>\n<p>אָמַר רַבִּי יֵיסָא, לֹא מְשַׁנֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַנְהָגוֹתָיו, רַק שֶׁאוֹתָם הָרְשָׁעִים שֶׁל הָעוֹלָם מְשַׁנִּים אוֹתָם וּמְהַפְּכִים רַחֲמִים לְדִין, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>שָׁנָה רַבִּי אֶלְעָזָר, מֵהַמָּן הַזֶּה עֲתִידִים הַצַּדִּיקִים לֶאֱכֹל לָעוֹלָם הַבָּא. וְאִם תֹּאמַר כְּמוֹ זֶה? לֹא! אֶלָּא יוֹתֵר. שֶׁלֹּא הָיָה כָּךְ לְעוֹלָמִים. מַהוּ? כְּמוֹ שֶׁבֵּאַרְנוּ שֶׁכָּתוּב (תהלים כז) לַחֲזוֹת בְּנֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ, וְכָתוּב (ישעיה סב) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ וְגוֹ'.</p>\n<p>רְאוּ כִּי ה' נָתַן לָכֶם הַשַּׁבָּת. רַבִּי חִזְקִיָּה פָּתַח, (תהלים קל) שִׁיר הַמַּעֲלוֹת מִמַּעֲמַקִּים קְרָאתִיךְ ה'. שִׁיר הַמַּעֲלוֹת, סָתַם וְלֹא פֵרַשׁ מִי אֲמָרוֹ. אֶלָּא שִׁיר הַמַּעֲלוֹת שֶׁעֲתִידִים לוֹמַר כָּל בְּנֵי הָעוֹלָם, שֶׁעָתִיד הַשִּׁיר הַזֶּה לְהֵאָמֵר אוֹתוֹ לְדוֹרוֹת עוֹלָם.</p>\n<p>וּמַהוּ מִמַּעֲמַקִּים קְרָאתִיךְ? כָּךְ שָׁנִינוּ, כָּל מִי שֶׁמִּתְפַּלֵּל תְּפִלָּתוֹ לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, צָרִיךְ לְבַקֵּשׁ בַּקָּשָׁתוֹ וּלְהִתְפַּלֵּל מֵעֹמֶק הַלֵּב כְּדֵי שֶׁיִּמָּצֵא לִבּוֹ שָׁלֵם עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, וִיכַוֵּן לֵב וְרָצוֹן. וְהַאִם דָּוִד אָמַר כָּךְ, וַהֲרֵי כָּתוּב בְּכָל לִבִּי דְּרַשְׁתִּיךְ, וּפָסוּק זֶה מַסְפִּיק? מַה צָּרִיךְ מִמַּעֲמַקִּים?</p>\n<p>אֶלָּא כָּךְ שָׁנִינוּ, כָּל אָדָם שֶׁמְּבַקֵּשׁ בַּקָּשָׁתוֹ לִפְנֵי הַמֶּלֶךְ, צָרִיךְ לְכַוֵּן דַּעְתּוֹ (לבו) וּרְצוֹנוֹ מֵעִקָּר שֶׁל כָּל הָעִקָּרִים לִמְשֹׁךְ בְּרָכוֹת מֵעֹמֶק הַבְּאֵר (של הכל), כְּדֵי שֶׁיַּשְׁפִּיעַ בְּרָכוֹת מֵהַמַּעְיָן שֶׁל הַכֹּל, וּמַהוּ? אוֹתוֹ מָקוֹם שֶׁיּוֹצֵא מִמֶּנּוּ וְנִמְצָא מִמֶּנּוּ אוֹתוֹ נָהָר, שֶׁכָּתוּב (בראשיתב) וְנָהָר יֹצֵא מֵעֵדֶן, וְכָתוּב (תהלים מו) נָהָר פְּלָגָיו יְשַׂמְּחוּ עִיר אֱלֹהִים. וְזֶה נִקְרָא מִמַּעֲמַקִּים. עֹמֶק הַכֹּל, עֹמֶק הַבְּאֵר שֶׁמַּעְיָנוֹת יוֹצְאִים וְשׁוֹפְעִים לְבָרֵךְ אֶת הַכֹּל, וְזוֹהִי הָרֵאשִׁית לִמְשֹׁךְ בְּרָכוֹת מִמַּעְלָה לְמַטָּה.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, כְּשֶׁהָעַתִּיק, נִסְתָּר שֶׁל הַנִּסְתָּרִים, רוֹצֶה לְזַמֵּן בְּרָכוֹת לָעוֹלָמוֹת, מַשְׁרֶה אֶת הַכֹּל, וּמַכְלִיל אֶת הַכֹּל בָּעֹמֶק הָעֶלְיוֹן הַזֶּה, וּמִכָּאן שׁוֹאֵב וְנִשְׁפָּע בְּאֵר (נהר) שֶׁנְּחָלִים וּמַעְיָנוֹת נִשְׁפָּעִים מִמֶּנּוּ, וְכֻלָּם נִשְׁקִים מִמֶּנּוּ. וּמִי שֶׁמִּתְפַּלֵּל תְּפִלָּתוֹ, צָרִיךְ לְכַוֵּן לִבּוֹ וּרְצוֹנוֹ לִמְשֹׁךְ בְּרָכוֹת מֵאוֹתוֹ עֹמֶק שֶׁל הַכֹּל כְּדֵי שֶׁתִּתְקַבֵּל תְּפִלָּתוֹ וְיַעֲשֶׂה רְצוֹנוֹ.</p>\n<p>וַיֹּאמֶר מֹשֶׁה אֲלֵהֶם אִישׁ אַל יוֹתֵר מִמֶּנּוּ עַד בּקֶר. אָמַר רַבִּי יְהוּדָה, בְּכָל יוֹם וָיוֹם מִתְבָּרֵךְ הָעוֹלָם מֵאוֹתוֹ יוֹם הָעֶלְיוֹן, שֶׁהֲרֵי כָּל שֵׁשֶׁת הַיָּמִים מִתְבָּרְכִים מִיּוֹם הַשְּׁבִיעִי, וְכָל יוֹם נוֹתֵן מֵאוֹתָהּ בְּרָכָה שֶׁקִּבֵּל מֵאוֹתוֹ יוֹם שֶׁלּוֹ.</p>\n<p>וְעַל זֶה אָמַר מֹשֶׁה, אִישׁ אַל יוֹתֵר מִמֶּנּוּ עַד בֹּקֶר. מָה הַטַּעַם? כְּדֵי שֶׁלֹּא יִתֵּן וְלֹא יַלְוֶה יוֹם זֶה לַחֲבֵרוֹ, אֶלָּא כָּל אֶחָד וְאֶחָד שׁוֹלֵט לְבַדּוֹ בְּאוֹתוֹ יוֹם שֶׁלּוֹ, שֶׁהֲרֵי לֹא שׁוֹלֵט יוֹם בַּיּוֹם שֶׁל חֲבֵרוֹ.</p>\n<p>מִשּׁוּם כָּךְ כָּל אוֹתָם (אמר רבי יהודה, כליוםויוםמתברך מאותויום עליון, יוםהשביעי, ומתברכים כל ששה הימים כל אחד ואחד בפני עצמו, וכל יום נותן ביום שלו מאותה ברכה שקבל מאותו יום עליון, ועל זה אמר משה, איש אל יותר ממגו עד בקר, שהרי לא שולט יום ביום שלא שלו, וכל אותם) חֲמִשָּׁה יָמִים שׁוֹלְטִים בַּיָּמִים שֶׁלָּהֶם, וְנִמְצָא בּוֹ מַה שֶּׁקִּבְּלוּ, וּבַיּוֹם הַשִּׁשִּׁי נִמְצָא יוֹתֵר. וְזֶה הוֹלֵךְ כְּפִי מַה שֶּׁאָמַר רַבִּי אֶלְעָזָר, מַה שֶּׁכָּתוּב יוֹם הַשִּׁשִּׁי וְלֹא נֶאֱמַר כָּךְ בְּכָל שְׁאָר הַיָּמִים - אֶלָּא כָּךְ פֵּרְשׁוּהָ, הַשִּׁשִּׁי - שֶׁהִזְדַּוְּגָה (שהזדמנה) בּוֹ הַגְּבִירָה לְהַתְקִין שֻׁלְחָן לַמֶּלֶךְ. וְלָכֵן נִמְצְאוּ בוֹ שְׁנֵי חֲלָקִים - אֶחָד לְיוֹמוֹ, וְאֶחָד לְתִקּוּן בְּשִׂמְחַת הַמֶּלֶךְ בַּגְּבִירָה.</p>\n<p>וְאוֹתוֹ לַיְלָה שִׂמְחַת הַגְּבִירָה בַּמֶּלֶךְ וְזִוּוּגָם, וּמִתְבָּרְכִים כָּל שֵׁשֶׁת הַיָּמִים, כָּל אֶחָד וְאֶחָד לְבַדּוֹ, וְלָכֵן צָרִיךְ אָדָם לְסַדֵּר שֻׁלְחָנוֹ בְּלֵיל הַשַּׁבָּת, כְּדֵי שֶׁיִּשְׁרוּ עָלָיו בְּרָכוֹת מִלְמַעְלָה, וּבְרָכָה לֹא נִמְצֵאת עַל שֻׁלְחָן רֵיק. (ואותו לילה שמחתה של הגבירה במלך וזווגם) לָכֵן תַּלְמִידֵי חֲכָמִים שֶׁיּוֹדְעִים סוֹד זֶה, זִוּוּגָם מֵעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת.</p>\n<p>רְאוּ כִּי ה' נָתַן לָכֶם הַשַּׁבָּת. מַה זֶּה שַׁבָּת? יוֹם שֶׁבּוֹ נָחִים שְׁאָר הַיָּמִים, וְהוּא כְּלָל שֶׁל כָּל אוֹתָם שֵׁשֶׁת הָאֲחֵרִים, וּמִמֶּנּוּ הֵם מִתְבָּרְכִים. רַבִּי יֵיסָא אָמַר, וְכֵן גַּם כְּנֶסֶת יִשְׂרָאֵל נִקְרֵאת שַׁבָּת, מִשּׁוּם שֶׁהִיא בַּת זוּגוֹ, וְזוֹהִי כַּלָּה, שֶׁכָּתוּב (שמות לא) וּשְׁמַרְתֶּם אֶת הַשַּׁבָּת כִּי קֹדֶשׁ הִיא לָכֶם. לָכֶם וְלֹא לִשְׁאָר הָעַמִּים. זֶהוּ שֶׁכָּתוּב (שם) בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל. וְזוֹהִי נַחֲלַת יְרֻשַּׁת עוֹלָמִים לְיִשְׂרָאֵל. וְלָכֵן כָּתוּב (ישעיה נח) אִם תָּשִׁיב מִשַּׁבָּת רַגְלְךְ וְגוֹ', וּבִמְקוֹמוֹ בֵּאַרְנוּ אֶת הַדְּבָרִים.</p>\n<p>כָּתוּב אַל יֵצֵא אִישׁ מִמְּקוֹמוֹ בַּיּוֹם הַשְּׁבִיעִי. מִמְּקוֹמוֹ - שָׁנִינוּ, מֵאוֹתוֹ מָקוֹם שֶׁרָאוּי לָלֶכֶת, וְסוֹד הַדָּבָר - שֶׁכָּתוּב (יחזקאל ג) בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ, וְזֶהוּ מָקוֹם, וְזֶהוּ סוֹד הַכָּתוּב, כִּי הַמָּקוֹם אֲשֶׁר אַתָּה עוֹמֵד עָלָיו אַדְמַת קֹדֶשׁ הוּא. מָקוֹם יָדוּעַ קוֹרְאִים לוֹ מָקוֹם שֶׁנּוֹדָע הַכָּבוֹד הָעֶלְיוֹן.</p>\n<p>וְלָכֵן אַזְהָרָה לָאָדָם שֶׁמִּתְעַטֵּר בְּעִטּוּר קָדוֹשׁ שֶׁלְּמַעְלָה, שֶׁלֹּא יֵצֵא מִפִּיו דִּבּוּר שֶׁל חֹל, מִשּׁוּם שֶׁאִם יֵצֵא מִמֶּנּוּ, הוּא מְחַלֵּל אֶת יוֹם הַשַּׁבָּת, בְּיָדוֹ - בְּמַעֲשֶׂה, וּבְרַגְלָיו - לָלֶכֶת מִחוּץ לְאַלְפַּיִם אַמָּה. כָּל אֵלּוּ הֵם חִלּוּל שַׁבָּת.</p>\n<p>אַל יֵצֵא אִישׁ מִמְּקוֹמוֹ - זֶהוּ מָקוֹם נִכְבָּד שֶׁל קְדֻשָּׁה, שֶׁהֲרֵי מִחוּצָה לוֹ הֵם אֱלֹהִים אֲחֵרִים. בָּרוּךְ כְּבוֹד ה' - זֶהוּ כָּבוֹד שֶׁלְּמַעְלָה. מִמְּקוֹמוֹ - זֶה כָּבוֹד שֶׁלְּמַטָּה. זֶהוּ סוֹד עֲטֶרֶת הַשַּׁבָּת, וְלָכֵן אַל יֵצֵא אִישׁ מִמְּקוֹמוֹ. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁזּוֹכֶה לְכַבֵּד אֶת הַשַּׁבָּת. אַשְׁרָיו בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"],[9522011628,"<p>וַיֹּאמֶר ה' אֶל מֹשֶׁה עֲבֹר לִפְנֵי הָעָם וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (תהלים לד) חֹנֶה מַלְאַךְ ה' סָבִיב לִירֵאָיו וַיְחַלְּצֵם. אַשְׁרֵי הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִּכְבוֹדָם יוֹתֵר עַל שֶׁלּוֹ. בֹּא רְאֵה כַּמָּה הֵם בְּנֵי הָעוֹלָם שֶׁמְּחָרְפִים וּמְגַדְּפִים לְמַעְלָה, כְּמוֹ שֶׁסַּנְחֵרִיב חֵרֵף וְגִדֵּף וְאָמַר (מלכים ב יח) מִי בְּכָל אֱלֹהֵי הָאֲרָצוֹת וְגוֹ'. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מָחַל וְלֹא תָבַע מִמֶּנּוּ. כֵּיוָן שֶׁהוֹשִׁיט אֶת יָדוֹ עַל חִזְקִיָּה, מַה כָּתוּב? (שם יט) וַיֵּצֵא מַלְאַךְ ה' וַיַּךְ בְּמַחֲנֵה אַשּׁוּר וְגוֹ'.</p>\n<p>יָרָבְעָם בֶּן נְבָט הָיָה עוֹבֵד לַעֲבוֹדָה זָרָה וּמְקַטֵּר לָהּ וְזוֹבֵחַ לָהּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא תָבַע מִמֶּנּוּ. וּכְשֶׁבָּא עִדּוֹ הַנָּבִיא וְהִתְנַבֵּא עָלָיו, וְהוֹשִׁיט יָרָבְעָם אֶת יָדוֹ כְּנֶגְדּוֹ - מַה כָּתוּב? (שם א יג) וַתִּיבַשׁ יָדוֹ וְגוֹ', וְלֹא יָכֹל לַהֲשִׁיבָהּ אֵלָיו. (ועלשעבדלעבודהזרהלא תבע אותו הקדוש ברוך הוא).</p>\n<p>פַּרְעֹה חֵרֵף וְגִדֵּף, וְאָמַר (שמות ה) מִי ה' וְגוֹ', וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא תָבַע מִמֶּנּוּ, עַד שֶׁסֵּרַב לְיִשְׂרָאֵל, שֶׁכָּתוּב (שם ט) עוֹדְךְ מִסְתּוֹלֵל בְּעַמִּי, (שם) הִנֵּה יַד ה' הוֹיָה בְּמִקְנְךְ וְגוֹ'. וְכֵן בְּכָל מָקוֹם הַקָּדוֹשׁ בָּרוּךְ הוּא תּוֹבֵעַ אֶת עֶלְבּוֹן הַצַּדִּיקִים יוֹתֵר עַל שֶׁלּוֹ.</p>\n<p>כָּאן מֹשֶׁה אָמַר (שם יז) עוֹד מְעַט וּסְקָלוּנִי. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, מֹשֶׁה, אֵינוֹ זְמַן לִתְבֹּעַ אֶת עֶלְבּוֹנְךְ, אֶלָּא עֲבֹר לִפְנֵי הָעָם, וְנִרְאֶה מִי יוֹשִׁיט יָדוֹ כְּנֶגְדְּךְ. וְכִי בִּרְשׁוּתָם אַתָּה עוֹמֵד, אוֹ בִּרְשׁוּתִי?</p>"],[9522011629,"<p>וּמַטְךָ אֲשֶׁר הִכִּיתָ בּוֹ אֶת הַיְאֹר קַח בְּיָדְךְ וְהָלָכְתָּ. מָה הַטַּעַם? מִשּׁוּם שֶׁהָיָה חָקוּק בְּנִסִּים, וְרָשׁוּם בּוֹ הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן. בַּתְּחִלָּה לְנָחָשׁ, כְּמוֹ שֶׁנֶּאֱמַר (משליכט) דֶּרֶךְ נָחָשׁ עֲלֵי צוּר. נָחָשׁ, הֲרֵי נוֹדָע שֶׁמְּעוֹרֵר צוּר. (ונאמר צור) בְּאֵיזֶה מָקוֹם הִתְגַּלָּה? כָּאן הוּא הִתְגַּלָּה, שֶׁכָּתוּב הִנְנִי עֹמֵד לְפָנֶיךְ שָּׁם עַל הַצּוּר. וּמַה זֶּה צוּר? כְּמוֹ שֶׁנֶּאֱמַר (דברים לב) הַצּוּר תָּמִים פָּעֳלוֹ. וְשָׁם יָדַע מֹשֶׁה אֵיךְ עוֹמֵד נָחָשׁ עֲלֵי צוּר. וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אִם הָיָה הַכָּתוּב שׁוֹתֵק - יָפֶה שָׁאַלְתָּ. אֶלָּא הֲרֵי כָּתוּב, וְהִכִּיתָ בַצּוּר וְיָצְאוּ מִמֶּנּוּ מַיִם. אָמַר לוֹ, וַדַּאי כָּךְ הוּא, שֶׁאֵין לְךְ כָּל שֵׁם וְשֵׁם מֵאוֹתָם שֵׁמוֹת קְדוֹשִׁים שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא עוֹשֶׂה נִסִּים וּגְבוּרוֹת וּמוֹצִיא כָּל מַה שֶּׁצָּרִיךְ לָעוֹלָם, כָּל שֶׁכֵּן לְהוֹצִיא כָּאן מַיִם.</p>\n<p>אָמַר לוֹ, אִם כָּךְ, הֲרֵי כָּתוּב הֵן הִכָּה צוּר וַיָּזוּבוּ מַיִם. מִי מַכֶּה אֶת שְׁמוֹ? אָמַר לוֹ, פַּטִּישׁ חָרִיף יָדוּעַ בְּהַכָּאוֹתָיו, וְאַתָּה שׁוֹאֵל אֶת זֶה? אֶלָּא בּא רְאֵה, בְּכָל מָקוֹם צוּר זֶה גְּבוּרָה, וּכְשֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַכּוֹת אוֹ לְהַלְקוֹת, מִתְעוֹרֶרֶת גְּבוּרָה זוֹ, וְאוֹתָהּ הַגְּבוּרָה מַכָּה וּמַלְקָה. וְזֶהוּ הַכָּתוּב (תהלים עח) הֵן הִכָּה צוּר וַיָּזוּבוּ מַיִם. וְאִם לֹא שֶׁמִּתְעוֹרֵר צוּר וּמַלְקֶה בְּמָקוֹם שֶׁצָּרִיךְ - לֹא נוֹבְעִים מַיִם.</p>\n<p>אָמַר לוֹ, אִם כָּךְ, הֲרֵי כָּתוּב (דברים לב) צוּר יְלָדְךְ תֶּשִׁי. וְשָׁנִינוּ, מַה זֶּה תֶּשִׁי? כְּלוֹמַר הֶחֱלַשְׁתָּ אוֹתוֹ. אָמַר לוֹ, וַדַּאי כָּךְ זֶה, שֶׁאִלְמָלֵא יָדְעוּ הָרְשָׁעִים שֶׁהַצּוּר הַזֶּה עָתִיד לְהִתְעוֹרֵר כְּנֶגְדָּם וּלְהַלְקוֹת אוֹתָם, יִמָּנְעוּ מִלַּחֲטֹא לְפָנָיו, אֶלָּא חַלָּשׁ הוּא בְּעֵינֵיהֶם, הוֹאִיל וְאֵינָם מִתְבּוֹנְנִים בּוֹ וְלֹא מִסְתַּכְּלִים בְּדַרְכֵיהֶם (בכסאותיהם), וְעַל זֶה צוּר יְלָדְךְ תֶּשִׁי.</p>\n<p>רַבִּי אַבָּא אָמַר, יֵשׁ צוּר וְיֵשׁ צוּר. מִצַּד הַצּוּר הָעֶלְיוֹן יוֹצֵא צוּר אַחֵר. וּמַה זֶּה צוּר הָעֶלְיוֹן? צוּר שֶׁל כָּל הַצּוּרִים. וּמַהוּ? אוֹתוֹ שֶׁהוֹלִיד אֶת יִשְׂרָאֵל, שֶׁכָּתוּב צוּר יְלָדְךְ תֶּשִׁי. שֶׁהֲרֵי מִצַּד שֶׁל הַצּוּר הָעֶלְיוֹן שֶׁלְּמַעְלָה יוֹצֵא צוּר אַחֵר. מִצַּד הָאֵם יוֹצֵאת גְּבוּרָה.</p>\n<p>וְזְה הוֹלֵךְ כְּמוֹ מַה שֶּׁאָמַר רַבִּי אֶלְעָזָר. כָּתוּב (תהלים קו) מִי יְמַלֵּל גְּבוּרוֹת ה'. מַה זֶּה גְּבוּרוֹת ה '? לְהַכְלִיל אֶת הָאֵ ם הָעֶלְיוֹנָה שֶׁל הַכֹּל. שֶׁאַף עַל גַּב שֶׁאֵינָהּ דִּין, נִמְצָא מִצִּדָּהּ, שֶׁהֲרֵי הַגְּבוּרָה נִמְצֵאת מִצִּדָּהּ, וְלָכֵן נִקְרֵאת הַצּוּר הָעֶלְיוֹן. (דברים לב) וַתִּשְׁכַּח אֵל מְחֹלֲלֶךְ - זֶה אוֹר שֶׁל אַבָּא. מַה הוּא? חֶסֶד עֶלְיוֹן, שֶׁהוּא אוֹר שֶׁל אַבָּא.</p>\n<p>עוֹד אָמַר רַבִּי אַבָּא, מַיִם בְּכָל מָקוֹם, הֲרֵי יָדוּעַ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעוֹרֵר בַּצּוּר הַזֶּה לְהוֹרִיק מַיִם, שֶׁהֲרֵי לֹא רָאוּי (אלא מגדלה), וְזֶהוּ אוֹת וָנֵס שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְעַל זֶה שִׁבַּח דָּוִד וְאָמַר, (תהלים קיד) הַהֹפְכִי הַצּוּר אֲגַם מָיִם וְגוֹ'. וּמַשְׁמָע הַהֹפְכִי, שֶׁהֲרֵי אֵין דֶּרֶךְ הַצּוּר בְּכָךְ.</p>\n<p>וְעַל זֶה בַּצּוּר הָעֶלְיוֹן הוֹצִיא מַיִם מִמָּקוֹם שֶׁלְּמַטָּה. וּמַה שְּׁמוֹ שֶׁל אוֹתוֹ שֶׁלְּמַטָּה? סֶלַע, שֶׁכָּתוּב וְהוֹצֵאתָ לָהֶם מַיִם מִן הַסֶּלַע. וּבַמָּה הוֹצִיא הַסֶּלַע הַזֶּה מַיִם? בְּכֹחַ הַצּוּר שֶׁלְּמַעְלָה.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, הַצּוּר תָּמִים פָּעֳלוֹ, מַה מַּשְׁמָעוֹ שֶׁל הַצּוּר תָּמִים פָּעֳלוֹ? שֶׁהִתְהַפֵּךְ הַצּוּר לַעֲשׂוֹת פָּעֳלוֹ שֶׁל תָּמִים. וּמִיהוּ הַתָּמִים? אַבְרָהָם, שֶׁכָּתוּב בּוֹ (בראשית יז) הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים. וְזֶהוּ הַהֹפְכִי הַצּוּר אֲגַם מָיִם, וּמַשְׁמָע תָּמִים פָּעֳלוֹ, וְזֶה אַבְרָהָם.</p>\n<p>בְּשָׁעָה זוֹ הוֹפֵךְ הַצּוּר לְתָמִים. בְּשָׁעָה שְׁנִיָּה אַחֶרֶת, כְּשֶׁרָצָה (כשגענש) מֹשֶׁה לְהוֹצִיא מַיִם בַּצּוּר הַזֶּה, בַּחֲטָאֵי יִשְׂרָאֵל לֹא חָזַר לְתָמִים כְּמוֹ בַּהַתְחָלָה. בְּאוֹתוֹ זְמַן הִתְרַעֵם מֹשֶׁה וְאָמַר, צוּר יְלָדְךְ תֶּשִׁי. כְּלוֹמַר, הֶחֱלַשְׁתָּ אוֹתוֹ מִמַּה שֶּׁהָיָה בַּתְּחִלָּה, שֶׁבִּשְׁבִילְךְ לֹא נִמְצָא עַכְשָׁו תָּמִים, וְנַעֲשֶׂה (בו) דִּין, מַה שֶּׁלֹּא הָיָה בִּימֵי יְלָדְךְ, כְּלוֹמַר עֲלוּמֶיךְ.</p>"],[9522011630,"<p>אָמַר רַבִּי אַבָּא, מַה זֶּה שֶׁכָּתוּב הֲיֵשׁ ה' בְּקִרְבֵּנוּ אִם אָיִן? וְכִי הָיוּ יִשְׂרָאֵל טִפְּשִׁים שֶׁלֹּא יָדְעוּ דָּבָר זֶה, וַהֲרֵי רָאוּ שְׁכִינָה לִפְנֵיהֶם וְעַנְנֵי כָבוֹד עֲלֵיהֶם, שֶׁמַּקִּיפִים אוֹתָם, וְהֵם אוֹמְרִים הֲיֵשׁ ה' בְּקִרְבֵּנוּ אִם אָיִן? אֲנָשִׁים שֶׁרָאוּ אֶת זִיו כְּבוֹד מַלְכָּם עַל הַיָּם, וְלָמַדְנוּ שֶׁרָאֲתָה שִׁפְחָה עַל הַיָּם מַה שֶּׁלֹּא רָאָה יְחֶזְקֵאל, הֵם נִמְצְאוּ טִפְּשִׁים וְאָמְרוּ הֲיֵשׁ ה' בְּקִרְבֵּנוּ אִם אָיִן?</p>\n<p>אֶלָּא כָּךְ אָמַר רַבִּי שִׁמְעוֹן, רָצוּ לָדַעַת בֵּין הָעַתִּיק הַנִּסְתָּר שֶׁל כָּל הַנִּסְתָּרִים שֶׁנִּקְרָא אַיִן, וּבֵין זְעֵיר אַנְפִּין שֶׁנִּקְרָא ה', וְלָכֵן לֹא כָתוּב הֲיֵשׁ ה' בְּקִרְבֵּנוּ אִם לֹא, כַּכָּתוּב הֲיֵלֵךְ בְּתוֹרָתִי אִם לֹא, אֶלָּא - הֲיֵשׁ ה' בְּקִרְבֵּנוּ אִם אָיִן.</p>\n<p>אִם כָּךְ, לָמָּה נֶעֶנְשׁוּ? אֶלָּא מִשּׁוּם שֶׁעָשׂוּ פֵרוּד, וְעָשׂוּ בְנִסָּיוֹן, שֶׁכָּתוּב וְעַל נַסֹּתָם אֶת ה'. אָמְרוּ יִשְׂרָאֵל, אִם זֶה - נִשְׁאַל בְּגָוֶן אֶחָד, וְאִם זֶה - נִשְׁאַל בְּגָוֶן אַחֵר. וְלָכֵן מִיָּד - וַיָּבֹא עֲמָלֵק.</p>"],[9522011631,"<p>וַיָּבֹא עֲמָלֵק וַיִּלָּחֶם עִם יִשְׂרָאֵל בִּרְפִידִם. רַבִּי יוֹסֵי פָּתַח, (ישעיה לב) אַשְׁרֵיכֶם זרְעֵי עַל כָּל מָיִם מְשַׁלְּחֵי רֶגֶל הַשּׁוֹר וְהַחֲמוֹר. אַשְׁרֵיכֶם זרְעֵי עַל כָּל מָיִם - שָׁם שָׁנִינוּ כַּמָּה מַיִם וְכַמָּה מַיִם נִמְצָאִים. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁאֵין לָהֶם זֶרַע אֶלָּא עַל הַמַּיִם, שֶׁכָּתוּב וַיַּחֲנוּ שָׁם עַל הַמָּיִם. אוֹתָם שֶׁהָיוּ תַּחַת עַנְפֵי הָאִילָן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>שֶׁשָּׁנִינוּ, יֵשׁ לַקָּדוֹשׁ-בָּרוּךְ-הוּא אִילָן, וְהוּא אִילָן גָּדוֹל וְחָזָק, וּבוֹ נִמְצָא מָזוֹן לַכֹּל, וְהוּא נִתְחָם בִּשְׁנֵים עָשָׂר תְּחוּמִים, בְּמִשְׁקָל, וּמִתְחַזֵּק בְּאַרְבַּע רוּחוֹת הָעוֹלָם. וְשִׁבְעִים עֲנָפִים אֲחוּזִים בּוֹ, וְיִשְׂרָאֵל נִמְצָאִים בַּגּוּף שֶׁל אוֹתוֹ הָאִילָן, וְאוֹתָם שִׁבְעִים עֲנָפִים מַקִּיפִים אוֹתָם.</p>\n<p>וְהַיְנוּ שֶׁכָּתוּב, וַיָּבֹאוּ אֵילִמָה וְשָׁם שְׁתֵּים עֶשְׂרֵה עֵינֹת מַיִם וְשִׁבְעִים תְּמָרִים, וַהֲרֵי פֵּרְשׁוּהָ, וְנִתְבָּאֵר בְּכַמָּה מְקוֹמוֹת. מַה זֶּה וַיַּחֲנוּ שָׁם עַל הַמָּיִם? אֶלָּא בְּאוֹתוֹ זְמַן שָׁלְטוּ עַל אוֹתָם הַמַּיִם, שֶׁהֵם תַּחַת הָעֲנָפִים שֶׁל הָאִילָן, שֶׁנִּקְרָאִים הַמַּיִם הַזֵּדוֹנִים. וְלָכֵן אַשְׁרֵיכֶם זרְעֵי עַל כָּל מָיִם.</p>\n<p>מְשַׁלְּחֵי רֶגֶל הַשּׁוֹר וְהַחֲמוֹר - אוֹתָם שְׁנֵי כִּתְרֵי הַשְּׂמֹאל שֶׁהָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת אֲחוּזִים בָּהֶם, שֶׁנִּקְרָאִים שׁוֹר וַחֲמוֹר, וְהַיְנוּ מַה שֶּׁכָּתוּב וַיְהִי לִי שׁוֹר וַחֲמוֹר. מִשּׁוּם שֶׁלָּבָן הָיָה חָכָם בִּכְשָׁפִים וּבְאוֹתָם כְּתָרִים תַּחְתּוֹנִים, וּבָהֶם רָצָה לְהַאֲבִיד אֶת יַעֲקֹב, כַּכָּתוּב אֲרַמִּי אֹבֵד אָבִי, וַהֲרֵי נֶאֱמַר. וּכְשֶׁיִּשְׂרָאֵל צַדִּיקִים, מְשַׁלְּחִים אוֹתָם, וְלֹא יְכוֹלִים לִשְׁלֹט עֲלֵיהֶם. זֶהוּ שֶׁכָּתוּב מְשַׁלְּחֵי רֶגֶל הַשּׁוֹר וְהַחֲמוֹר, שֶׁלֹּא שׁוֹלְטִים בָּהֶם.</p>\n<p>אָמַר רַבִּי אַבָּא, כְּשֶׁהֵם מִזְדַּוְּגִים כְּאֶחָד, לֹא יְכוֹלִים בְּנֵי הָעוֹלָם לַעֲמֹד בָּהֶם, וְלָכֵן כָּתוּב לֹא תַחֲרשׁ בְּשׁוֹר וּבַחֲמֹר יַחְדָּו. יַחְדָּו דַּוְקָא. וְשָׁנִינוּ, לֹא יִתֵּן אָדָם מָקוֹם לְמִינִים רָעִים, שֶׁהֲרֵי בְּמַעֲשֵׂה הָאָדָם (למטה) מִתְעוֹרֵר מַה שֶּׁלֹּא צָרִיךְ, וּכְשֶׁמִּזְדַּוְּגִים כְּאֶחָד, (לא יכולים לעמד בהם. מבין הצד שלהם יוצאת) מֵהַתַּקִּיפוּת שֶׁלָּהֶם קְלִפָּה שֶׁנִּקְרֵאת כֶּלֶב, וְזוֹ הַחֲצוּפָה מִכֻּלָּם. זֶהוּ שֶׁכָּתוּב (שמות יא) וּלְכָל בְּנֵי יִשְׂרָאֵל לֹא יֶחֱרַץ כֶּלֶב לְשׁוֹנוֹ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אַתֶּם אֲמַרְתֶּם הֲיֵשׁ ה' בְּקִרְבֵּנוּ אִם אָיִן - הֲרֵי אֲנִי מוֹסֵר אֶתְכֶם לַכֶּלֶב. מִיָּד - וַיָּבֹא עֲמָלֵק.</p>\n<p>רַבִּי יְהוּדָה אָמַר, (במדברכב) רֵאשִׁית גּוֹיִם עֲמָלֵק וְאַחֲרִיתוֹ עֲדֵי אֹבֵד. וְכִי רֵאשִׁית גּוֹיִם עֲמָלֵק, וַהֲלֹא כַּמָּה לְשׁוֹנוֹת וְעַמִּים וְאֻמּוֹת הָיוּ בָּעוֹלָם עַד שֶׁלֹּא בָא עֲמָלֵק?!</p>\n<p>אֶלָּא, כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, פַּחַד וְאֵימָה נָפְלוּ עַל כָּל הָעַמִּים שֶׁל הָעוֹלָם מִיִּשְׂרָאֵל, זֶהוּ שֶׁכָּתוּב שָׁמְעוּ עַמִּים יִרְגָּזוּן חִיל אָחַז יֹשְׁבֵי פְּלָשֶׁת. וְלֹא הָיָה עַם שֶׁלֹּא הָיָה פּוֹחֵד מֵהַגְּבוּרוֹת הָעֶלְיוֹנוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וַעֲמָלֵק לֹא הָיָה פּוֹחֵד. זֶהוּ שֶׁכָּתוּב וְלֹא יָרֵא אֱלֹהִים. לֹא פָחַד לִקְרַב אֵלֶיךְ. וְלָכֵן רֵאשִׁית גּוֹיִם.</p>\n<p>(עמלק היו הראשונים) שֶׁבָּאוּ לַעֲרֹךְ קְרָב בְּיִשְׂרָאֵל הָיָה עֲמָלֵק, וְלָכֵן וְאַחֲרִיתוֹ עֲדֵי אֹבֵד, שֶׁכָּתוּב כִּי מָחֹה אֶמְחֶה אֶת זֵכֶר עֲמָלֵק. וְכָתוּב תִּמְחֶה אֶת זֵכֶר עֲמָלֵק. זֶהוּ שֶׁכָּתוּב וְאַחֲרִיתוֹ עֲדֵי אֹבֵד. עֲדֵי אָבְדוֹ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא עַד שֶׁיָּבא הַקָּדוֹשׁ בָּרוּךְ הוּא וִיאַבֵּד אוֹתוֹ, (כלומר, עד שהקדוש ברוך הוא יאבד אותו) שֶׁכָּתוּבּ כִּי מָחֹה אֶמְחֶה וְגוֹ'. אָמַר רַבִּי אֶלְעָזָר, בֹּא רְאֵה, אַף עַל גַּב שֶׁהַצּוּר תָּמִים פָּעֳלוֹ וְעָשָׂה עִמָּהֶם חֶסֶד לְהוֹצִיא לָהֶם מַיִם, לֹא עָזַב אֶת שֶׁלּוֹ, שֶׁהֲרֵי כָּתוּב וַיָּבֹא עֲמָלֵק.</p>\n<p>רַבִּי אַבָּא פָּתַח וְאָמַר, (קהלת ו) יֵשׁ רָעָה חוֹלָה רָאִיתִי תַּחַת הַשָּׁמֶשׁ. כַּמָּה בְּנֵי הָאָדָם אֲטוּמֵי לֵב, מִשּׁוּם שֶׁלֹּא מִשְׁתַּדְּלִים בַּתּוֹרָה. יֵשׁ רָעָה חוֹלָה - וְכִי יֵשׁ רָעָה שֶׁהִיא חוֹלָה וְיֵשׁ רָעָה שֶׁאֵינָהּ חוֹלָה? אֶלָּ וַדַּאי שֶׁיֵּשׁ רָעָה חוֹלָה, שֶׁשָּׁנִינוּ, מִצַּד הַשְּׂמֹאל יוֹצְאִים כַּמָּה בַּעֲלֵי דִין הַבּוֹקְעִים בָּאֲוִיר.</p>\n<p>וּכְשֶׁרוֹצִים לָצֵאת, הוֹלְכִים וְנִשְׁאָבִים בְּנֶקֶב תְּהוֹם רַבָּה. אַחַר כָּךְ יוֹצְאִים וּמִתְחַבְּרִים כְּאֶחָד, וּבוֹקְעִים אֲוִירִים וּמְשׁוֹטְטִים בָּעוֹלָם וּמִתְקָרְבִים לִבְנֵי אָדָם, וְכָל אֶחָד נִקְרָא רָעָה, כְּמוֹ שֶׁנֶּאֱמַר (תהליםצא) לֹא תְאֻנֶּה אֵלֶיךְ רָעָה. מַה זֶּה לֹא תְאֻנֶּה? מִשּׁוּם שֶׁבָּאִים בְּתַחְבּוּלוֹת עַל בְּנֵי אָדָם.</p>\n<p>חוֹלָה - לָמָּה הִיא חוֹלָה? כְּשֶׁזּוֹ שׁוֹרָה עַל בְּנֵי אָדָם, עוֹשָׂה אוֹתָם קַמְּצָנִים מִמָּמוֹנָם. בָּאִים גַּבָּאֵי צְדָקָה אֵלָיו - הִיא מוֹחָה בְּיָדוֹ וְאוֹמֶרֶת לוֹ אַל תּוֹצִיא מִשֶּׁלְּךְ. בָּאִים הָעֲנִיִּים - הִיא מוֹחָה בְּיָדוֹ. בָּא הוּא לֶאֱכֹל מִמָּמוֹנוֹ - הִיא מוֹחָה בְּיָדוֹ, כְּדֵי לִשְׁמֹר אוֹתוֹ לְאַחֵר. וּמִיּוֹם שֶׁשְּׁרוּיָה עַל הָאָדָם, הִיא חוֹלָה, כְּמוֹ הַגּוֹסֵס הַזֶּה שֶׁאֵינוֹ אוֹכֵל וְאֵינוֹ שׁוֹתֶה, וְלָכֵן הִיא רָעָה חוֹלָה.</p>\n<p>וּשְׁלֹמֹה הַמֶּלֶךְ צוֹוֵחַ בְּחָכְמָה וְאוֹמֵר, (קהלת ו) אִישׁ אֲשֶׁר יִתֶּן לוֹ הָאֱלֹהִים עֹשֶׁר וּנְכָסִים וְכָבוֹד וְגוֹ'. הַפָּסוּק הַזֶּה, אֵין רֹאשׁוֹ סוֹפוֹ וְאֵין סוֹפוֹ רֹאשׁוֹ. כָּתוּב אִישׁ אֲשֶׁר יִתֶּן לוֹ הָאֱלֹהִים עֹשֶׁר וּנְכָסִים וְכָבוֹד וְגוֹ'. מַה זֶּה וְלֹא יַשְׁלִיטֶנּוּ הָאֱלֹהִים לֶאֱכֹל מִמֶּנּוּ? אִם כָּךְ, הוּא אֵינוֹ בִּרְשׁוּת הָאָדָם?</p>\n<p>אֶלָּא אִם כָּתוּב וְלֹא יַעַזְבֶנּוּ הָאֱלֹהִים לֶאֱכֹל מִמֶּנּוּ - הָיִינוּ אוֹמְרִים כָּךְ. אֶלָּא (כתוב) וְלֹא יַשְׁלִיטֶנּוּ, שֶׁבִּגְלַל שֶׁהֶאֱמִין לְאוֹתָהּ רָעָה וְאָחַז בָּהּ, הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא הִשְׁלִיטוֹ עָלֶיהָ לְשָׁבְרָהּ תַּחְתָּיו עַל שֶׁהוּא רָצָה בָּהּ וְאָחַז אוֹתָהּ.</p>\n<p>וְכָל דְּרָכָיו כְּמוֹ גּוֹסֵס, שֶׁלֹּא אוֹכֵל וְלֹא שׁוֹתֶה וְלֹא מִתְקָרֵב לְמָמוֹנוֹ וְלֹא מוֹצִיא מִמֶּנּוּ, וְשׁוֹמֵר אוֹתוֹ עַד אוֹתוֹ יוֹם שֶׁיֵּצֵא מִן הָעוֹלָם, וְיָבא אַחֵר וְיִטֹּל אוֹתוֹ, שֶׁהוּא בְּעָלָיו.</p>\n<p>וּשְׁלֹמֹה הַמֶּלֶךְ צוֹוֵחַ וְאוֹמֵר, (שם ה) עֹשֶׁר שָׁמוּר לִבְעָלָיו לְרָעָתוֹ. מִי זֶה בְּעָלָיו? זֶה הָאַחֵר שֶׁיּוֹרֵשׁ אוֹתוֹ. וְלָמָּה זֶה זָכָה לִהְיוֹת בְּעָלָיו שֶׁל אוֹתוֹ הָעֹשֶׁר? מִשּׁוּם שֶׁזֶּה הֶאֱמִין לְאוֹתָהּ רָעָה וְהִתְרַצָּה בָּהּ (זהו שכתוב לרעתו, בשביל אותה רעה) וְדָבַק בָּהּ, וְלָכֵן הָאַחֵר הַזֶּה שֶׁלֹּא נִדְבַּק בְּאוֹתָהּ רָעָה, זָכָה (זה) לִהְיוֹת הַבְּעָלִים שֶׁל אוֹתוֹ הָעֹשֶׁר. זֶהוּ שֶׁכָּתוּב לְרָעָתוֹ, כְּלוֹמַר, מִשּׁוּם רָעָתוֹ שֶׁהָיָה נִדְבָּק בָּהּ, הִרְוִיחַ לוֹ זֶה.</p>\n<p>דָּבָר אַחֵר יֵשׁ רָעָה חוֹלָה - זֶה מִי שֶׁיּוֹשֵׁב בְּחֵלֶק טוֹב, בְּבֵית אָבִיו, וְהוּא הוֹלֵךְ כְּנֶגֶד אָבִיו בַּעֲלִילוֹת דְּבָרִים, זֶה נִדְבָּק בְּאוֹתָהּ רָעָה חוֹלָה, כְּאָדָם גּוֹסֵס, שֶׁכָּל דְּרָכָיו בַּעֲלִילוֹת: זֶה אֲנִי רוֹצֶה, וְאֶת זֶה אֵינִי רוֹצֶה. וּמִשּׁוּם הָעֹשֶׁר הַזֶּה נִדְבָּק הָאָדָם בְּרָעָה חוֹלָה, וְנֶעֱנָשׁ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. וְזֶהוּ עֹשֶׁר שָׁמוּר לִבְעָלָיו לְרָעָתוֹ.</p>\n<p>כָּךָ יִשְׂרָאֵל. הַקָּדוֹשׁ בָּרוּךְ הוּא נָטַל אוֹתָם עַל כַּנְפֵי נְשָׁרִים, הִקִּיפָם בְּעַנְנֵי כָבוֹד, נָסְעָה שְׁכִינָתוֹ לִפְנֵיהֶם, הוֹרִיד לָהֶם מָן לֶאֱכֹל, הוֹצִיא לָהֶם מַיִם מְתוּקִים, וְהֵם הָיוּ הוֹלְכִים עִמּוֹ בַּעֲלִילוֹת. מִיָּד - וַיָּבא עֲמָלֵק.</p>\n<p>וַיָּבֹא עֲמָלֵק - אָמַר רַבִּי שִׁמְעוֹן, סוֹד הַחָכְמָה כָּאן. מִגְּזֵרַת הַדִּין הַקָּשֶׁה בָּא הַקְּרָב הַזֶּה. וְהַקְּרָב הַזֶּה נִמְצָא לְמַעְלָה וּלְמַטָּה. וְאֵין לְךְ דָּבָר בַּתּוֹרָה שֶׁאֵין בּוֹ סוֹדוֹת עֶלְיוֹנִים שֶׁל חָכְמָה שֶׁנִּקְשָׁרִים לַשֵּׁם הַקָּדוֹשׁ. כִּבְיָכוֹל אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: כְּשֶׁיִּשְׂרָאֵל צַדִּיקִים לְמַטָּה, מִתְגַּבֵּר הַכֹּחַ שֶׁלִּי עַל הַכֹּל. וּכְשֶׁלֹּא נִמְצָאִים צַדִּיקִים, כִּבְיָכוֹל מַתִּישִׁים הַכֹּחַ שֶׁלְּמַעְלָה, וּמִתְגַּבֵּר הַכֹּחַ שֶׁל הַדִּין הַקָּשֶׁה.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁחָטְאוּ יִשְׂרָאֵל לְמַטָּה, מַה כָּתוּב? וַיָּבֹא עֲמָלֵק וַיִּלָּחֵם עִם יִשְׂרָאֵל. בָּא לְקַטְרֵג הַדִּין נֶגֶד הָרַחֲמִים, שֶׁהַכֹּל נִמְצָא לְמַעְלָה וּלְמַטָּה. בִּרְפִידִם - בְּרִפּוּי יָדַיִם, שֶׁרָפוּ יְדֵיהֶם מִתּוֹרַת הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּפִי שֶׁבֵּאַרְנוּ. אָמַר רַבִּי יְהוּדָה, פַּעֲמַיִם נִלְחַם עֲמָלֵק בְּיִשְׂרָאֵל; פַּעַם אַחַת כָּאן, וְאַחַת שֶׁכָּתוּב (במדבר יד) וַיֵּרֶד הָעֲמָלֵקִי וְהַכְּנַעֲנִי וְגוֹ'.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, לְמַעְלָה וּלְמַטָּה הָיָה קִטְרוּג שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה - כְּמוֹ שֶׁנִּתְבָּאֵר. לְמַטָּה הָיָה בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, שֶׁהָיוּ לוֹקְחִים אֲנָשִׁים וְגוֹזְרִים אֶת הָעָרְלָה (האות) שֶׁל הָרֹשֶׁם הַקָּדוֹשׁ, וְלוֹקְחִים אוֹתָם וְזוֹרְקִים אוֹתָם לְמַעְלָה וְאוֹמְרִים: קַח לְךְ מַה שֶּׁרָצִיתָ! וְעַל כָּל פָּנִים הַכֹּל הָיָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא (הקבלנה).</p>\n<p>וַיֹּאמֶר מֹשֶׁה אֶל יְהוֹשֻׁעַ בְּחַר לָנוּ אֲנָשִׁים וְצֵא הִלָּחֵם בַּעֲמָלֵק. וְכִי מָה רָאָה מֹשֶׁה שֶׁסִּלֵּק עַצְמוֹ מֵהַקְּרָב הָרִאשׁוֹן שֶׁצִּוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא? אֶלָּא מֹשֶׁה, אַשְׁרֵי חֶלְקוֹ, שֶׁהִתְבּוֹנֵן וְיָדַע אֶת עִקַּר הַדָּבָר. אָמַר מֹשֶׁה, אֲנִי אַזְמִין עַצְמִי לְאוֹתוֹ קְרָב שֶׁלְּמַעְלָה, וְאַתָּה יְהוֹשֻׁעַ הַזְמֵן עַצְמְךְ לַקְּרָב שֶׁלְּמַטָּה.</p>\n<p>וְהַיְנוּ מַה שֶּׁכָּתוּב, וְהָיָה כַּאֲשֶׁר יָרִים מֹשֶׁה יָדוֹ וְגָבַר יִשְׂרָאֵל. יִשְׂרָאֵל שֶׁלְּמַעְלָה. וְלָכֵן סִלֵּק מֹשֶׁה אֶת עַצְמוֹ מֵהַקְּרָב שֶׁלְּמַטָּה, כְּדֵי לְהִזְדַּוֵּג בַּקְּרָב שֶׁלְּמַעְלָה וְיִהְיֶה נִצָּחוֹן עַל יָדוֹ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, וְכִי קַל הוּא בְּעֵינֶיךְ הַקְּרָב הַזֶּה שֶׁל עֲמָלֵק? בּא רְאֵה, מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם עַד לְאוֹתוֹ זְמַן, וּמֵאוֹתוֹ זְמַן עַד שֶׁיָּבא מֶלֶךְ הַמָּשִׁיחַ, וַאֲפִלּוּ בִּימֵי גוֹג וּמָגוֹג, לֹא יִמָּצֵא כָּמוֹהוּ. לֹא בִּשְׁבִיל הַחֲיָלוֹת הַחֲזָקִים וְהָרַבִּים, אֶלָּא מִשּׁוּם שֶׁבְּכָל הַצְּדָדִים שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה.</p>\n<p>וַיֹּאמֶר מֹשֶׁה אֶל יְהוֹשֻׁעַ, לָמָּה לִיהוֹשֻׁעַ וְלֹא לְאַחֵר, וַהֲרֵי בְּאוֹתוֹ זְמַן הָיָה נַעַר, שֶׁכָּתוּב (שמות לג) וִיהוֹשֻׁעַ בִּן נוּן נַעַר, וְהָיוּ בְיִשְׂרָאֵל חֲזָקִים מִמֶּנּוּ? אֶלָּא שֶׁמֹּשֶׁה הִתְבּוֹנֵן בַּחָכְמָה וְיָדַע. מָה הוּא רָאָה? רָאָה אֶת סמא\"ל שֶׁהָיָה יוֹרֵד מֵהַצַּד שֶׁלְּמַעְלָה לְסַיֵּעַ לַעֲמָלֵק שֶׁלְּמַטָּה. אָמַר מֹשֶׁה, וַדַּאי נִרְאֶה כָּאן קְרָב קָשֶׁה.</p>\n<p>יְהוֹשֻׁעַ בְּאוֹתוֹ זְמַן נִמְצָא בְּדַרְגָּה יוֹתֵר עֶלְיוֹנָה. אִם תֹּאמַר שֶׁנִּמְצָא בְּאוֹתוֹ זְמַן בַּשְּׁכִינָה - לֹא כָּךְ! שֶׁהֲרֵי בְּמֹשֶׁה נִלְקְחָה וְנֶאֶחְזָה. נִמְצָא שֶׁיְּהוֹשֻׁעַ נֶאֱחַז לְמַטָּה מִמֶּנָּה, וּבַמֶּה? בְּאוֹתוֹ מָקוֹם שֶׁנִּקְרָא נַעַ\"ר.</p>\n<p>וְהַיְנוּ מַה שֶּׁאָמַר רַבִּי יְהוּדָה, מַה זֶּה שֶׁכָּתוּב (ישעיהלג) עֵינֶיךְ תִרְאֶינָה יְרוּשָׁ לם נָוֶה שַׁאֲנָן אֹהֶל בַּל יִצְעָן בַּל יִסַּע יְתֵדתָיו לָנֶצַח. יְרוּשָׁלם - יְרוּשָׁלַיִם שֶׁלְּמַעְלָה, שֶׁנִּקְרֵאת אֹהֶל בַּל יִצְעָן, שֶׁלֹּא תִמָּצֵא יוֹתֵר לָלֶכֶת לַגָּלוּת. וְזֶהוּ סוֹד הַכְּתוּב וִיהוֹשֻׁעַ בִּן נוּן נַעַר. וַדַּאי נַעַר. לֹא יָמִישׁ מִתּוֹךְ הָאֹהֶל, אוֹתוֹ שֶׁנִּקְרָא אֹהֶל בַּל יִצְעָן. מְלַמֵּד שֶׁבְּכָל יוֹם וָיוֹם הָיָה יוֹנֵק מֵהַשְּׁכִינָה כְּמוֹ אוֹתוֹ הַנַּעַר שֶׁלְּמַעְלָה, לֹא יָמִישׁ מִתּוֹךְ הָאֹהֶל, וְיוֹנֵק מִמֶּנָּה תָּמִיד. כָּךְ נַעַר זֶה שֶׁלְּמַטָּה לֹא יָמִישׁ מִתּוֹךְ הָאֹהֶל וְיוֹנֵק מִמֶּנָּה תָּמִיד.</p>\n<p>לָכֵן, כְּשֶׁרָאָה מֹשֶׁה אֶת סמא\"ל יוֹרֵד לְסַיֵּעַ לַעֲמָלֵק, אָמַר מֹשֶׁה, וַדַּאי נַעַר זֶה יָקוּם כְּנֶגְדּוֹ וְיִשְׁלֹט עָלָיו לְנַצֵּחַ אוֹתוֹ. מִיָּד - וַיֹּאמֶר מֹשֶׁה אֶל יְהוֹשֻׁעַ בְּחַר לָנוּ אֲנָשִׁים וְצֵא הִלָּחֵם בַּעֲמָלֵק. שֶׁלְּךְ הַקְּרָב הַזֶּה שֶׁלְּמַטָּה, וַאֲנִי אֶזְדָּרֵז לַקְּרָב שֶׁלְּמַעְלָה. בְּחַר לָנוּ אֲנָשִׁים - צַדִּיקִים בְּנֵי צַדִּיקִים, שֶׁרְאוּיִים לָלֶכֶת עִמְּךְ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בְּשָׁעָה שֶׁיָּצָא יְהוֹשֻׁעַ נַעַר, הִתְעוֹרֵר הַנַּעַר שֶׁלְּמַעְלָה וְהִתְתַּקֵּן בְּכַמָּה תִּקּוּנִים, בְּכַמָּה כְּלֵי זַיִן שֶׁהִתְקִינָה לוֹ אִמּוֹ לַקְּרָב הַזֶּה לִנְקֹם אֶת נִקְמַת הַבְּרִית, וְהַיְנוּ מַה שֶּׁכָּתוּב (ויקרא כו) חֶרֶב נֹקֶמֶת נְקַם בְּרִית. וְזֶהוּ סוֹד הַכָּתוּב וַיַּחֲלֹשׁ יְהוֹשֻׁעַ אֶת עֲמָלֵק וְאֶת עַמּוֹ לְפִי חָרֶב. לְפִי חֶרֶב וַדַּאי, וְלֹא לְפִי רְמָחִים וּכְלֵי זַיִן, אֶלָּא בַּחֶרֶב וַדַּאי הִיא, זוֹ שֶׁנִּקְרֵאת חֶרֶב נֹקֶמֶת נְקַם בְּרִית.</p>\n<p>וּמֹשֶׁה הִתְתַּקֵּן לַקְּרָב שֶׁלְּמַעְלָה. וִידֵי מֹשֶׁה כְּבֵדִים, כְּבֵדִים מַמָּשׁ, נִכְבָּדִים, קְדוֹשִׁים, שֶׁלֹּא נִטְמְאוּ לְעוֹלָמִים. נִכְבָּדִים שֶׁרְאוּיִים לַעֲרֹךְ בָּהֶם קְרָב שֶׁלְּמַעְלָה. וַיִּקְחוּ אֶבֶן וַיָּשִׂימוּ תַחְתָּיו וַיֵּשֶׁב עָלֶיהָ, מִשּׁוּם שֶׁיִּשְׂרָאֵל שְׁרוּיִים בְּצַעַר, וִיהֵא עִמָּהֶם בְּצַעֲרָם.</p>\n<p>וְאַהֲרֹן וְחוּר תָּמְכוּ בְיָדָיו מִזֶּה אֶחָד וּמִזֶּה אֶחָד וַיְהִי יָדָיו אֱמוּנָה וְגוֹ'. מַה זֶּה תָּמְכוּ בְיָדָיו? אֱמוּנָה. (אמונה, אמונה ודאי) וְכִי עַל שֶׁאַהֲרֹן וְחוּר תָּמְכוּ אֶת יָדָיו, הָיוּ יָדָיו אֱמוּנָה? אֶלָּא מֹשֶׁה עָשָׂה הַכֹּל בְּחָכְמָה מַה שֶּׁעָשָׂה. אַהֲרֹן וְחוּר - זֶה מִצִּדּוֹ וְזֶה מִצִּדּוֹ, וְיָדָיו בָּאֶמְצַע, וְלָכֵן וַיְהִי יָדָיו אֱמוּנָה, אֱמוּנָה. אַהֲרֹן כְּדֵי שֶׁיִּתְעוֹרֵר הַצַּד שֶׁלּוֹ, וְחוּר כְּדֵי שֶׁיִּתְעוֹרֵר הַצַּד שֶׁלּוֹ, וְהָיוּ אוֹחֲזִים בְּיָדָיו מִכָּאן וּמִכָּאן, שֶׁיִּמָּצֵא סִיּוּעַ שֶׁלְּמַעְלָה. וְהָיָה כַּאֲשֶׁר יָרִים מֹשֶׁה יָדוֹ וְגָבַר יִשְׂרָאֵל.</p>\n<p>כַּאֲשֶׁר יָרִים - שֶׁזָּקַף יָמִין עַל שְׂמֹאל, וְהִתְכַּוֵּן בִּפְרִישַׂת יָדָיו. וְגָבַר יִשְׂרָאֵל - יִשְׂרָאֵל שֶׁלְּמַעְלָה (תפארת). וְכַאֲשֶׁר יָנִיחַ יָדוֹ וְגָבַר עֲמָלֵק - בְּשָׁעָה שֶׁיִּשְׂרָאֵל לְמַטָּה שׁוֹכְכִים בִּתְפִלָּתָם, לֹא יְכוֹלִים יְדֵי מֹשֶׁה לַעֲמֹד בִּזְקִיפוּת, וְגָבַר עֲמָלֵק. מִכָּאן לָמַדְנוּ, אַף עַל פִּי שֶׁהַכֹּהֵן פּוֹרֵס אֶת יָדָיו בַּקָּרְבָּן כְּדֵי לְתַקֵּן אֶת עַצְמוֹ בַּכֹּל - יִשְׂרָאֵל צְרִיכִים לְהִמָּצֵא עִמּוֹ בִּתְפִלּוֹתֵיהֶם.</p>\n<p>שָׁנִינוּ, בַּקְּרָב הַזֶּה שֶׁל עֲמָלֵק, נִמְצְאוּ עֶלְיוֹנִים וְתַחְתּוֹנִים, וְלָכֵן וַיְהִי יָדָיו אֱמוּנָה, בֶּאֱמוּנָה כָּרָאוּי. וַיְהִי יָדָיו אֱמוּנָה, וַיִּהְיוּ יָדָיו הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא מִשּׁוּם שֶׁהַכֹּל תָּלוּי בַּיָּמִין כָּתוּב וַיְהִי. וְכָתוּב יָדָיו מִשּׁוּם שֶׁהוּא עִקַּר הַכֹּל. וְכָתוּב (שמות טו) יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ יְמִינְךְ ה' תִּרְעַץ אוֹיֵב.</p>\n<p>וַיֹּאמֶר ה' אֶל מֹשֶׁה כְּתֹב זאת זִכָּרוֹן בַּסֵּפֶר וְגוֹ'. בּא רְאֵה מַה כָּתוּב לְמַעְלָה? וַיַּחֲלֹשׁ יְהוֹשֻׁעַ אֶת עֲמָלֵק וְאֶת עַמּוֹ לְפִי חָרֶב. וַיַּחֲלֹשׁ? וַיַּהֲרֹג הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא וַיַּחֲלֹשׁ כְּמוֹ שֶׁנֶּאֱמַר (ישעיה יד) חוֹלֵשׁ עַל גּוֹיִם. יְהוֹשֻׁעַ הָיָה חוֹלֵשׁ עֲלֵיהֶם, וְאוֹתָהּ חֶרֶב נֹקֶמֶת נְקַם בְּרִית הוֹרֶגֶת אוֹתָם, שֶׁכָּתוּב לְפִי חָרֶב, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>כְּתֹב זאת זִכָּרוֹן, זאת דַּוְקָא. וְשִׂים בְּאָזְנֵי יְהוֹשֻׁעַ, שֶׁהֲרֵי הוּא עָתִיד לַהֲרֹג מְלָכִים אֲחֵרִים. כִּי מָחֹה אֶמְחֶה, מָחֹה - לְמַעְלָה, אֶמְחֶה - לְמַטָּה. זֵכֶר - זִכָּרוֹן שֶׁל מַעְלָה וּמַטָּה.</p>\n<p>אָמַר רַבִּי יִצְחָק, כָּתוּב כִּי מָחֹה אֶמְחֶה, וְכָתוּב (דבריםכה) תִּמְחֶה אֶת זֵכֶר עֲמָלֵק. אֶלָּא, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אַתֶּם מְחוּ אֶת זִכְרוֹנוֹ לְמַטָּה, וַאֲנִי אֶמְחֶה אֶת זִכְרוֹנוֹ לְמַעְלָה.</p>\n<p>אָמַר רַבִּי יוֹסֵי, עֲמָלֵק הֵבִיא עִמּוֹ עַמִּים אֲחֵרִים, וְכֻלָּם פָּחֲדוּ לִקְרַב לְיִשְׂרָאֵל חוּץ מִמֶּנּוּ, וְלָכֵן יְהוֹשֻׁעַ הָיָה חוֹלֵשׁ עֲלֵיהֶם. רַבִּי יֵיסָא אָמַר, וַיַּחֲלֹשׁ יְהוֹשֻׁעַ, שֶׁשָּׁבַר אֶת כֹּחָם מִלְמַעְלָה. וַיִּבֶן מֹשֶׁה מִזְבֵּחַ וַיִּקְרָא שְׁמוֹ ה' נִסִּי.</p>\n<p>וַיִּבֶן מֹשֶׁה מִזְבֵּחַ - כְּנֶגֶד אוֹתוֹ שֶׁלְּמַעְלָה. וַיִּקְרָא שְׁמוֹ - אוֹתוֹ מֹשֶׁה (אותו מזבח) - ה' נִסִּי. מַה זֶּה ה' נִסִּי? מִשּׁוּם שֶׁנָּקַם אֶת נִקְמַת אוֹתוֹ רֹשֶׁם הַקָּדוֹשׁ שֶׁל יִשְׂרָאֵל. וּמֵאוֹתוֹ הַזְּמַן נִקְרָא חֶרֶב נֹקֶמֶת נְקַם בְּרִית.</p>\n<p>רַבִּי יוֹסֵי אָמַר, וַיִּבֶן מֹשֶׁה מִזְבֵּחַ, מִזְבֵּחַ לְכַפֵּר עֲלֵיהֶם. וַיִּקְרָא שְׁמוֹ, שֶׁל מִי? אָמַר רַבִּי חִיָּיא, שְׁמוֹ שֶׁל אוֹתוֹ מִזְבֵּחַ. ה' נִסִּי, כְּמוֹ שֶׁנֶּאֱמַר וְשָׁם נִסָּהוּ. וְהַכֹּל דָּבָר אֶחָד, עַל שֶׁיִּשְׂרָאֵל נִפְרְעוּ וְהִתְגַּלָּה אוֹתוֹ אוֹת בְּרִית הָרֹשֶׁם הַקָּדוֹשׁ. מִכָּאן לָמַדְנוּ, שֶׁכֵּיוָן שֶׁנִּמּוֹל בְּנוֹ שֶׁל אָדָם וְהִתְגַּלָּה בּוֹ הָרֹשֶׁם הַקָּדוֹשׁ שֶׁל הַבְּרִית, הוּא נִקְרָא מִזְבֵּחַ לְכַפֵּר עָלָיו, וּמַה שְּׁמוֹ? ה' נִסִּי.</p>\n<p>כְּמוֹ זֶה יַעֲקֹב בָּנָה מִזְבֵּחַ, שֶׁכָּתוּב (בראשית לג) וַיַּצֶּב שָׁם מִזְבֵּחַ וַיִּקְרָא לוֹ אֵל אֱלֹהֵי יִשְׂרָאֵל. לְמִי? לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא מִזְבֵּחַ. וּמַה שְּׁמוֹ? אֵל אֱלֹהֵי יִשְׂרָאֵל.</p>"],[9522011632,"<p>אָמַר רַבִּי יוֹסֵי, מַה שֶּׁכָּתוּב (שמות כד) וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל וְגוֹ', וְכִי מִי יָכוֹל לִרְאוֹת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וַהֲרֵי כָּתוּב (שם לג) כִּי לֹא יִרְאַנִי הָאָדָם וָחָי, וְכָאן אָמַר וַיִּרְאוּ? אֶלָּא שֶׁהִתְגַּלְּתָה עֲלֵיהֶם הַקֶּשֶׁת בִּגְוָנִים מְאִירִים. וְכָךְ שָׁנִינוּ, כָּל מִי שֶׁמִּסְתַּכֵּל בַּקֶּשֶׁת, כְּמִי שֶׁמִּסְתַּכֵּל בַּשְּׁכִינָה, וְאָסוּר לְהִסְתַּכֵּל בַּשְּׁכִינָה.</p>\n<p>וְעַל זֶה אָסוּר לְאָדָם לְהִסְתַּכֵּל בְּאֶצְבְּעוֹת הַכֹּהֲנִים בְּשָׁעָה שֶׁפּוֹרְשִׂים יְדֵיהֶם. אָסוּר לְהִסְתַּכֵּל בַּקֶּשֶׁת. אֵיזוֹ קֶשֶׁת? אָמַר רַבִּי אַבָּא, בְּקֶשֶׁת סְתָם. אָמַר לוֹ, מַה זֶּה בְּקֶשֶׁת סְתָם? אָמַר לוֹ, בַּקֶּשֶׁת שֶׁלְּמַעְלָה, וּבַקֶּשֶׁת שֶׁלְּמַטָּה.</p>\n<p>בַּקֶּשֶׁת שֶׁלְּמַעְלָה, בִּגְוָנֶיהָ. שֶׁכָּל מִי שֶׁמִּסְתַּכֵּל בִּגְוָנֶיהָ, כְּאִלּוּ מִסְתַּכֵּל בְּמָקוֹם עֶלְיוֹן, וְאָסוּר לְהִסְתַּכֵּל בּוֹ, שֶׁלֹּא יַעֲשֶׂה קָלוֹן בַּשְּׁכִינָה. קֶשֶׁת שֶׁלְּמַטָּה מַהִי? אוֹתוֹ אוֹת הַבְּרִית שֶׁנִּרְשָׁם בָּאָדָם, שֶׁל מִי שֶׁמִּסְתַּכֵּל בּוֹ, עוֹשֶׂה קָלוֹן לְמַעְלָה.</p>\n<p>אָמַר רַבִּי יִצְחָק, אִם כָּךְ, הֲרֵי כָּתוּב (בראשית כד) שִׂים נָא יָדְךְ תַּחַת יְרֵכִי, שֶׁהָיָה מַשְׁבִּיעַ אוֹתוֹ בָּאוֹת הַזֶּה. אָמַר לוֹ, הָנַח לַאֲבוֹת הָעוֹלָם, שֶׁאֵינָם כִּשְׁאָר בְּנֵי הָעוֹלָם. וְעוֹד, שִׂים נָא יָדְךְ תַּחַת יְרֵכִי כָּתוּב, וְלֹא כָתוּב רְאֵה תַּחַת יְרֵכִי. לָכֵן אָסוּר לְהִסְתַּכֵּל בַּקֶּשֶׁת סְתָם, כְּמוֹ שֶׁשָּׁנִינוּ.</p>\n<p>לָמַדְנוּ, וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל, שֶׁהִתְגַּלְּתָה עֲלֵיהֶם הַקֶּשֶׁת בַּגְּוָנִים הַיָּפִים מְאִירִים, לוֹהֲטִים לְכָל עֵבֶר, מַשְׁמָע שֶׁכָּתוּב וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל וְלֹא כָתוּב וַיִּרְאוּ אֱלֹהֵי יִשְׂרָאֵל. אָמַר רַבִּי יוֹסֵי, אוֹר הַמְּנוֹרָה שֶׁל הַשְּׁכִינָה, וּמַה הוּא? אוֹתוֹ שֶׁנִּקְרָא נַעַר, שֶׁמְּשַׁמֵּשׁ אֶת הַשְּׁכִינָה בַּמִּקְדָּשׁ, וְלָכֵן \"אֵת\" דַּוְקָא.</p>\n<p>וְתַחַת רַגְלָיו כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר, שֶׁנִּרְשַׁם בּוֹ תַּחַת מְקוֹמוֹ לְבֵנָה אַחַת מֵאוֹתָם לְבֵנִים שֶׁהָיוּ בּוֹנִים בְּמִצְרַיִם, שֶׁשָּׁנִינוּ, אִשָּׁה אַחַת הוֹלִידָה בְּמִצְרַיִם, וְהָיוּ בָּאִים שָׂרֵי פַרְעֹה, וְהִכְנִיסָה אוֹתוֹ בִּלְבֵנָה אַחַת, וּבָא פַּס יָד וְאָחַז אוֹתוֹ, וְנִרְשַׁם תַּחַת רַגְלֵי הַשְּׁכִינָה, וְעוֹמֵד לְפָנָיו, עַד שֶׁנִּשְׂרַף בֵּית הַמִּקְדָּשׁ שֶׁלְּמַטָּה, שֶׁכָּתוּב (איכה ב) וְלֹא זָכַר הֲדם רַגְלָיו.</p>\n<p>רַבִּי חִיָּיא אָמַר, לִבְנַת הַסַּפִּיר - אוֹר הַסַּפִּיר, מַפְתְּחוֹת יֵין הָרֶקַח חִקּוּקִים עֶלְיוֹנִים שֶׁל מַעְלָה שֶׁלּוֹהֲטִים לְשִׁבְעִים וּשְׁנַיִם עֲבָרִים, זֶהוּ שֶׁכָּתוּב (ישעיה נד) וִיסַדְתִּיךְ בַּסַּפִּירִים. וּכְעֶצֶם הַשָּׁמַיִם, מַה זֶּה כְּעֶצֶם הַשָּׁמַיִם? אָמַר רַבִּי אַבָּא, מָה (שמות כד) עֶצֶם הַשָּׁמַיִם חָקוּק בְּשִׁבְעִים וּשְׁנַיִם עֲנָפִים פּוֹרְחִים לוֹהֲטִים לְכֵל עֵבֶר, אַף כָּאן הַמַּרְאֶה שֶׁל אוֹתוֹ עֶצֶם הַשָּׁמַיִם כְּמַרְאֵה הַשָּׁמַיִם מַמָּשׁ. רַבִּי יְהוּדָה אָמַר, הַכֹּל נִרְשָׁם בְּאוֹתוֹ הָאוֹר שֶׁל מַרְאֶה שֶׁנֶּחְקָק מִצַּד הַשְּׁכִינָה.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, אִם כָּךְ, וַהֲרֵי הֵם שִׁשִּׁים סְבִיב הַשְּׁכִינָה, שֶׁכָּתוּב (שיר ג) שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ. אָמַר לוֹ, כָּךְ הוּא וַדַּאי, אֶלָּא אוֹתָם שִׁשִּׁים מְאִירִים בִּשְׁנֵים עָשָׂר תְּחוּמִים, וְלֹא זָזִים מִסְּבִיבָהּ לְעוֹלָמִים. שֶׁשָּׁנִינוּ, שְׁנֵים עָשָׂר תְּחוּמִים חִקּוּקִים עֶלְיוֹנִים עָלוּ בְּמִשְׁקָל, בְּעֵץ קָדוֹשׁ גָּדוֹל וְחָזָק, וְכֻלָּם מְאִירִים בַּגְּבִירָה, כְּשֶׁמִּתְחַבֶּרֶת בַּמֶּלֶךְ. וְזֶהוּ עֶצֶם הַשָּׁמַיִם, עֶצֶם הַשָּׁמַיִם מַמָּשׁ. וְכָל אוֹתָם הַשְּׁבִילִים הַמְּאִירִים, מְאִירִים בּוֹ בְּאוֹר הַגְּבִירָה.</p>\n<p>וְשָׁנִינוּ, הָאוֹר שֶׁל הַשִּׁשִּׁים הַלָּלוּ שֶׁסְּבִיבָהּ, רְשׁוּמִים בּוֹ בְּאוֹתוֹ נַעַ\"ר, וְקוֹרְאִים לָהֶם שִׁשִּׁים מַכּוֹת אֵשׁ, שֶׁמִּתְלַבֵּשׁ בָּהֶם מִצַּד הַשְּׁכִינָה, לוֹהֲטִים בְּדִין. זֶהוּ שֶׁכָּתוּב שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ.</p>"],[9522011633,"<p>שָׁנִינוּ, וַיִּבֶן מֹשֶׁה מִזְבֵּחַ, כְּמוֹ שֶׁאָמַרְנוּ. וַיִּקְרָא שְׁמוֹ ה' נִסִּי, ה' נִסִּי מַמָּשׁ. לָמָּה? מִשּׁוּם שֶׁעֲמָלֵק לָקַח כָּל אוֹתָם מְהוּלִים שֶׁלֹּא נִפְרְעוּ, וּמָל אוֹתָם וְזָרַק אוֹתָם לְמַעְלָה, וְאָמַר: טֹל מַה שֶּׁרָצִיתָ בּוֹ. בְּאוֹתָהּ שָׁעָה מַה כָּתוּב? וַיֹּאמֶר כִּי יָד עַל כֵּס יָהּ מִלְחָמָה לַה' בַּעֲמָלֵק מִדֹּר דֹּר. מִדֹּר דֹּר חֲסֵרִים, מֵהַדַּיָּרִים שֶׁל מַעְלָה וּמֵהַדַּיָּרִים שֶׁל מַטָּה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, בְּכָל דּוֹר וָדוֹר, בְּכָל הַדּוֹרוֹת שֶׁבָּאִים לָעוֹלָם, אֵין לְךְ דּוֹר שֶׁאֵין בּוֹ מֵאוֹתוֹ זֶרַע רַע, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹרֵךְ בָּהֶם קְרָב. רַבִּי יִצְחָק אָמַר (מהדיור שלמטה לדיור שלמעלה), וַעֲלֵיהֶם כָּתוּב (תהלים קד) יִתַּמּוּ חַטָּאִים מִן הָאָרֶץ וְגוֹ'. מִן הָאָרֶץ - בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. בְּאוֹתוֹ זְמַן כָּתוּב, בָּרְכִי נַפְשִׁי אֶת ה' הַלְלוּיָהּ.</p>"],[9522011634,"<p>וַיִּשְׁמַע יִתְרוֹ כֹּהֵן מִדְיָן חֹתֵן מֹשֶׁה אֵת כָּל אֲשֶׁר עָשָׂה וְגוֹ'. רַבִּי חִזְקִיָּה (רביאלעזר) פָּתַח וְאָמַר, (ויקראט) וַיִּשָּׂא אַהֲרֹן אֶת יָדָו. כָּתוּב יָדוֹ אַחַת, מִשּׁוּם שֶׁצָּרִיךְ לְהָרִים יָמִין עַל שְׂמֹאל, וַהֲרֵי בֵּאַרְנוּ הַסּוֹד.</p>\n<p>מָצָאנוּ בְּסִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ, שֶׁכָּל מִי שֶׁמֵּרִים יָדוֹ לְמַעְלָה, וְהֵם אֵינָן בִּתְפִלּוֹת וּבַקָּשׁוֹת, זֶהוּ אָדָם שֶׁמִּתְקַלֵּל מֵעֲשָׂרָה שַׁלִּיטִים מְמֻנִּים, וְהֵם עֲשָׂרָה שַׁלִּיטִים אֲשֶׁר הָיוּ בָּעִיר. אֵלּוּ אוֹתָם עֲשָׂרָה שֶׁמְּמֻנִּים עַל פְּרִישַׂת הַיָּדַיִם לְמַעְלָה לִטֹּל אוֹתָהּ תְּפִלָּה אוֹ אוֹתָהּ בְּרָכָה, וְנוֹתְנִים בָּהּ כֹּחַ לְהִתְכַּבֵּד הַשֵּׁם הַקָּדוֹשׁ, וּמִתְבָּרֵךְ מִלְּמַטָּה. כֵּיוָן שֶׁמִּלְּמַטָּה מִתְבָּרֵךְ מֵאוֹתָהּ פְּרִישַׂת הַיָּדַיִם לְמַעְלָה, אָז מִתְבָּרֵךְ מִלְמַעְלָה, וּמִתְכַּבֵּד מִכָּל הַצְּדָדִים.</p>\n<p>וְאֵלּוּ עֲשֶׂרֶת הַמְמֻנִּים מְזֻמָּנִים לִטֹּל מֵאוֹתָן בְּרָכוֹת שֶׁלְּמַעְלָה, וּלְהוֹרִיק לְמַטָּה, וּלְבָרֵךְ אֶת אוֹתוֹ שֶׁמְּבָרֵךְ אוֹתוֹ, שֶׁכָּתוּב (במדבר ו) וַאֲנִי אֲבָרֲכֵם.</p>\n<p>וְלָכֵן יִשָּׁמֵר הָאָדָם בְּשָׁעָה שֶׁמֵּרִים יָדָיו לְמַעְלָה לִהְיוֹת בִּתְפִלָּה אוֹ בִּבְרָכוֹת אוֹ בְּבַקָּשָׁה, וְלֹא יָרִים יָדָיו לְחִנָּם, מִשּׁוּם שֶׁעֲשָׂרָה הַלָּלוּ מְזֻמָּנִים וּמִתְעוֹרְרִים אֶל אוֹתָהּ פְּרִישַׂת יָדַיִם. וְאִם זֶה לְחִנָּם, אוֹתָם הָעֲשָׂרָה מְקַלְלִים אוֹתוֹ בְּמָאתַיִם אַרְבָּעִים וּשְׁמוֹנֶה קְלָלוֹת. וְזֶהוּ שֶׁכָּתוּב בּוֹ (תהלים קט) וַיֶּאֱהַב קְלָלָה וַתְּבוֹאֵהוּ.</p>\n<p>וְאָז רוּחַ טֻמְאָה שׁוֹרָה עַל אוֹתָם הַיָּדַיִם, שֶׁהוּא דַּרְכּוֹ לִשְׁרוֹת עַל מָקוֹם רֵיק, וּבְרָכָה לֹא שׁוֹרָה בְּמָקוֹם רֵיק. וְעַל זֶה (שמברךאותו. ואם הם מתעוררים אל אותו פורש הידים והם לחגם מקללים אותו במאתים וארבעים ושמנה קללות, ואז רוח טמאה שורה על אותן ידים, שדרכה לשרות על מקום ריק. משום כך יזהר האדםבשעה שמרים ידיו למעלה אובברכות או בתפלה ולא ירים ידיו לחגם. ועל זה) כָּתוּב (בראשית יד) הֲרִמֹתִי יָדִי אֶל ה' אֵל עֶלְיוֹן, שֶׁמְּתַרְגְּמִים: בִּתְפִלָּה.</p>\n<p>וּבִפְרִישַׂת הַיָּדַיִם הַזֹּאת יֵשׁ סוֹדוֹת עֶלְיוֹנִים. בְּשָׁעָה שֶׁנִּפְרָשִׂים וּמִזְדַּקְּפִים לְמַעְלָה, מְכַבֵּד הָאָדָם אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכַמָּה סוֹדוֹת עֶלְיוֹנִים. וְרָאוּי לְיַחֵד סוֹד שֶׁל עֶשֶׂר הָאֲמִירוֹת כְּדֵי לְיַחֵד אֶת הַכֹּל, וּלְבָרֵךְ אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי. וְרָאוּי לְיַחֵד אֶת סוֹד הַמֶּרְכָּבוֹת הַפְּנִימִיּוֹת וְהַמֶּרְכָּבוֹת הַחִיצוֹנִיּוֹת כְּדֵי שֶׁיִּתְבָּרֵךְ הַשֵּׁם הַקָּדוֹשׁ בְּכָל הַצְּדָדִים, וְיִתְיַחֵד הַכֹּל כְּאֶחָד, מַעְלָה וּמַטָּה.</p>\n<p>פָּתַח וְאָמַר, (שמות כג) וְלֹא יֵרָאוּ פָנַי רֵיקָם. זֶהוּ סוֹד שֶׁל זְקִיפַת הָאֶצְבָּעוֹת, כְּשֶׁזּוֹקֵף אוֹתָם הָאָדָם לְמַעְלָה, שֶׁצָּרִיךְ שֶׁלֹּא לִזְקֹף בְּרֵיקָנוּת, אֶלָּא בִּתְפִלָּה וּבְבַקָּשׁוֹת וּבִבְרָכוֹת. וְעַל זֶה וְלֹא יֵרָאוּ פָנַי רֵיקָם. לֹא כָתוּב וְלֹא יֵרָאוּ לְפָנַי, אֶלָּא פָנַי, סוֹד שֶׁל זְקִיפַת הָאֶצְבָּעוֹת שֶׁלֹּא צָרִיךְ לְזָקְפָם לְחִנָּם, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>עָשָׂרָה שַׁלִּיטִים שֶׁאָמַרְנוּ הֵם עֶשֶׂר אֲמִירוֹת לְמַטָּה, בְּסוֹד (בסוד עשרה שליטים ממגים שאמרנו, אלו ממגים למטה בסוד) שֶׁל הָאוֹתִיּוֹת הָרְשׁוּמוֹת כְּמוֹ שֶׁלְּמַעְלָה, וְאֵלֶּה עוֹמְדִים בָּרִאשׁוֹנָה עַל אוֹתָהּ זְקִיפַת אֶצְבָּעוֹת, וּבָזֶה נֶאֱחָז לְמַעְלָה כָּל צַד הַקְּדֻשָּׁה לְהָרִים, אָז כָּל הַצְּדָדִים הָאֲחֵרִים כֻּלָּם מִתְכּוֹפְפִים וּמוֹדִים לַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>בֹּא וּרְאֵה, בְּסוֹד שֶׁל קְדֻשָּׁה (של השם הקדוש) הוּא מֶלֶךְ וְכֹהֵן וּמְשַׁמֵּשׁ תַּחְתָּו (בסוד של קדשה), בֵּין לְמַעְלָה בֵּין לְמַטָּה. יֵשׁ מֶלֶךְ לְמַעְלָה, שֶׁהוּא סוֹד שֶׁל קֹדֶשׁ הַקְּדָשִׁים, וְהוּא מֶלֶךְ עֶלְיוֹן, וְתַחְתָּיו יֵשׁ כֹּהֵן, סוֹד שֶׁל אוֹר רִאשׁוֹן, שֶׁמְּשַׁמֵּשׁ לְפָנָיו, וְזֶהוּ כֹּהֵן שֶׁנִּקְרָא גָּדוֹל, צַד הַיָּמִין.</p>\n<p>יֵשׁ מֶלֶךְ לְמַטָּה שֶׁהוּא כְּמוֹ אוֹתוֹ מֶלֶךְ עֶלְיוֹן, וְהוּא מֶלֶךְ עַל הַכֹּל שֶׁלְּמַטָּה, וְתַחְתָּיו יֵשׁ כֹּהֵן שֶׁמְּשַׁמֵּשׁ אוֹתוֹ, סוֹד שֶׁל מִיכָאֵל כֹּהֵן גָּדוֹל, שֶׁהוּא לְיָמִין, (ודאי בצד הקדשהישמלךוכהן) וְזֶהוּ סוֹד הָאֱמוּנָה הַשְּׁלֵמָה, צַד הַקְּדֻשָּׁה.</p>\n<p>בַּצַד הָאַחֵר, שֶׁאֵינוֹ צַד הַקְּדֻשָּׁה, יֵשׁ סוֹד שֶׁהוּא מֶלֶךְ, וַהֲרֵי בֵּאַרְנוּ שֶׁנִּקְרָא מֶלֶךְ זָקֵן וּכְסִיל, וְתַחְתָּיו יֵשׁ כֹּהֵן אוֹן, וְזֶהוּ סוֹד הַכָּתוּב (הושע יב) וַיֹּאמֶר אֶפְרַיִם אַךְ עָשַׁרְתִּי מָצָאתִי אוֹן לִי. מִשּׁוּם שֶׁכֹּחַ זֶה שׁוֹלֵט עַל אוֹתוֹ מַעֲשֶׂה שֶׁעָשָׂה יָרָבְעָם. וְאִלְמָלֵא שֶׁנִּמְצָא כֹּחַ זֶה, לֹא יָכֹל לְהַצְלִיחַ בְּאוֹתוֹ מַעֲשֶׂה.</p>\n<p>סוֹד הַדָּבָר - בְּשָׁעָה שֶׁהַמֶּלֶךְ הַזֶּה וְהַכֹּהֵן הַזֶּה נִכְפִּים, וְנִשְׁבְּרוּ, אָז נִכְפִּים כָּל יֶתֶר הַצְּדָדִים וּמוֹדִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵט לְבַדּוֹ מַעְלָה וּמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיהכ) וְנִשְׂגָּב ה' לְבַדּוֹ בַּיּוֹם הַהוּא.</p>\n<p>כְּמוֹ זֶה וְסוֹד זֶה מַמָּשׁ עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ, שֶׁשָּׁבַר מֶלֶךְ זָקֵן וּכְסִיל, וְזֶהוּ פַּרְעֹה. בְּשָׁעָה שֶׁבָּא מֹשֶׁה לְפַרְעֹה וְאָמַר (שמות ה) אֱלֹהִי הָעִבְרִים נִקְרָא עָלֵינוּ, פָּתַח וְאָמַר, לֹא יָדַעְתִּי אֶת ה'. וְרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּתְכַּבֵּד שְׁמוֹ בָּאָרֶץ, כְּמוֹ שֶׁהוּא נִכְבָּד לְמַעְלָה. כֵּיוָן שֶׁהִלְקָה אוֹתוֹ וְאֶת עַמּוֹ, בָּא וְהוֹדָה לוֹ לַקָּדוֹשׁ- בָּרוּךְ-הוּא.</p>\n<p>וְאַחַר נִשְׁבַּר וְנִכְפָּה אוֹתוֹ כֹּהֵן אוֹן, יִתְרוֹ, שֶׁמְּשַׁמֵּשׁ תַּחְתָּיו, עַד שֶׁבָּא וְהוֹדָה לוֹ לַקָּדוֹשׁ-בָּרוּךְ-הוּא וְאָמַר, בָּרוּךְ ה' אֲשֶׁר הִצִּיל אֶתְכֶם וְגוֹ', עַתָּה יָדַעְתִּי כִּי גָדוֹל ה' וְגוֹ'. וְזֶהוּ כֹּהֵן אוֹן, צַד הָאַחֵר, שֶׁהוּא צַד שְׂמֹאל. וְזֶהוּ סוֹד שֶׁאָמְרָה רָחֵל, כְּשֶׁרָאֲתָה שֶׁהִיא מֵתָה, כְּמוֹ שֶׁכָּתוּב (בראשית לה) בֶּן אוֹנִי. וְלָכֵן מִהֵר (הודה) יַעֲקֹב וְאָמַר בֶּן יָמִין, וְלֹא בֶּן אוֹנִי. צַד יָמִין, וְלֹא צַד שְׂמֹאל.</p>\n<p>וְכֵיוָן שֶׁאוֹתוֹ מֶלֶךְ וְכֹהֵן הוֹדוּ לַקָּדוֹשׁ-בָּרוּךְ-הוּא וְנִשְׁבְּרוּ לְפָנָיו, אָז הִתְעַלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּכְבוֹדוֹ עַל הַכֹּל, מַעְלָה וּמַטָּה. וְעַד שֶׁהִתְעַלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּכְבוֹדוֹ, כְּשֶׁהוֹדוּ אֵלֶּה לְפָנָיו, לֹא נִתְּנָה תּוֹרָה עַד לְאַחַר שֶׁבָּא יִתְרוֹ, וְהוֹדָה וְאָמַר, עַתָּה יָדַעְתִּי כִּי גָדוֹל ה' מִכָּל הָאֱלֹהִים. בָּרוּךְ ה' אֲשֶׁר הִצִּיל אֶתְכֶם וְגוֹ'. אָז הִתְעַלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּכְבוֹדוֹ מַעְלָה וּמַטָּה, וְאַחַר כָּךְ נָתַן תּוֹרָה בִּשְׁלֵמוּת, כְּשֶׁשִּׁלְטוֹנוֹ עַל הַכֹּל.</p>\n<p>רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהלים סז) יוֹדוּךְ עַמִּים אֱלֹהִים יוֹדוּךְ עַמִּים כֻּלָּם. בֹּא וּרְאֵה, דָּוִד הַמֶּלֶךְ קָם וְשִׁבַּח וְהוֹדָה לַמֶּלֶךְ הַקָּדוֹשׁ, וְהוּא הִשְׁתַּדֵּל בַּתּוֹרָה בְּאוֹתָהּ שָׁעָה כְּשֶׁרוּחַ צָפוֹן הִתְעוֹרְרָה וְהָיְתָה מַכָּה בְּאוֹתָם נִימֵי הַכִּנּוֹר, וְהַכִּנּוֹר הָיָה מְנַגֵּן וְאוֹמֵר שִׁירָה וְכוּ'. וְאֵיזוֹ שִׁירָה הוּא אָמַר?</p>\n<p>בֹּא וּרְאֵה, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעוֹרֵר אֶל כָּל אוֹתָן הַמֶּרְכָּבוֹת לָתֵת לָהֶן טֶרֶף, כְּמוֹ שֶׁבֵּאַרְנוּ שֶׁכָּתוּב (משלי לא) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ, אָז כֻּלָּם בְּשִׂמְחָה פּוֹתְחִים וְאוֹמְרִים, (תהלים סז) אֱלֹהִים יְחָנֵּנוּ וִיבָרְכֵנוּ יָאֵר פָּנָיו אִתָּנוּ סֶלָה. כְּשֶׁרוּחַ צָפוֹן מִתְעוֹרֶרֶת וְיוֹרֶדֶת לָעוֹלָם, נוֹשֶׁבֶת וְאוֹמֶרֶת, לָדַעַת בָּאָרֶץ דַּרְכֶּךְ בְּכָל גּוֹיִם יְשׁוּעָתֶךְ. בְּשָׁעָה שֶׁמְּנַגֵּן הַכִּנּוֹר בְּאוֹתָהּ רוּחַ, פּוֹתֵחַ וְאוֹמֵר, יוֹדוּךְ עַמִּים כֻּלָּם. כְּשֶׁהָיָה דָּוִד קָם וּמִתְעוֹרֵר עָלָיו רוּחַ הַקֹּדֶשׁ, פָּתַח וְאָמַר, אֶרֶץ נָתְנָה יְבוּלָהּ יְבָרְכֵנוּ אֱלֹהִים אֱלֹהֵינוּ יְבָרְכֵנוּ אֱלֹהִים וְיִירְאוּ אוֹתוֹ כָּל אַפְסֵי אָרֶץ. כְּדֵי לְהַמְשִׁיךְ אֶת טוּב הַקָּדוֹשׁ בָּרוּךְ הוּא מִלְמַעְלָה לְמַטָּה. אַחַר כָּךְ בָּא דָּוִד וְסִדֵּר אוֹתָם בְּרוּחַ הַקֹּדֶשׁ כְּאֶחָד, הִסְתַּכֵּל בְּכָל הַכָּתוּב הַזֶּה שֶׁל הַכִּנּוֹר, שֶׁל שְׁלֵמוּת וּכְבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה וּלְמַטָּה.</p>\n<p>בְּשָׁעָה שֶׁשְּׁאָר הָעַמִּים נִכְפִּים, הֵם בָּאִים וּמוֹדִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא. כֵּיוָן שֶׁנִּכְפִּים וּמוֹדִים לוֹ, אָז מִשְׁתַּלֵּם כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא מַעְלָה וּמַטָּה. בְּשָׁעָה שֶׁבָּא מֹשֶׁה לְפַרְעֹה וְאָמַר לוֹ ה' אֱלֹהֵי הָעִבְרִים נִקְרָא עָלֵינוּ וְגוֹ', הוּא פָּתַח וְאָמַר, לֹא יָדַעְתִּי אֶת ה'.</p>\n<p>וְרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּתְכַּבֵּד שְׁמוֹ בָּאָרֶץ, כְּמוֹ שֶׁהוּא נִכְבָּד לְמַעְלָה. כֵּיוָן שֶׁהִלְקָה אוֹתוֹ וְאֶת עַמּוֹ, בָּא וְהוֹדָה לַקָּדוֹשׁ-בָּרוּךְ- הוּא, שֶׁכָּתוּב ה' הַצַּדִּיק. הוּא שֶׁהָיָה מֶלֶךְ חָשׁוּב שֶׁל כָּל הָעוֹלָם, כֵּיוָן שֶׁהוֹדָה, אָז כָּל שְׁאָר הָעַמִּים הוֹדוּ, שֶׁכָּתוּב (שמות טו) אָז נִבְהֲלוּ אַלּוּפֵי אֱדוֹם.</p>\n<p>בָּא יִתְרוֹ, כֹּמֶר עֶלְיוֹן וְגָדוֹל, מְמֻנֶּה גָּדוֹל (של כל הממונים) שֶׁל כָּל הָאֱלִילִים הָאֲחֵרִים, וְהוֹדָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא וְאָמַר, עַתָּה יָדַעְתִּי כִּי גָדוֹל ה' מִכָּל הָאֱלֹהִים. אָז הִתְעַלָּה וְהִתְכַּבֵּד הַקָּדוֹשׁ בָּרוּךְ הוּא בִּכְבוֹדוֹ מַעְלָה וּמַטָּה, וְאַחַר כָּךְ נָתַן תּוֹרָה בִּשְׁלֵמוּת, כְּשֶׁשִּׁלְטוֹנוֹ עַל הַכֹּל.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן לְרַבִּי אֶלְעָזָר בְּנוֹ, עַל זֶה כָּתוּב (תהלים סז) יוֹדוּךְ עַמִּים אֱלֹהִים יוֹדוּךְ עַמִּים כֻּלָּם. בָּא רַבִּי אֶלְעָזָר וְנָשַׁק יָדוֹ. בָּכָה רַבִּי אַבָּא וְאָמַר, (שם קג) כְּרַחֵם אָב עַל בָּנִים. מִי יְרַחֵם עַל רַבִּי אֶלְעָזָר וְיַשְׁלִים דְּבָרָיו, חוּץ מֵאַהֲבַת מוֹרֵנוּ? אַשְׁרֵי חֶלְקֵנוּ שֶׁזָּכִינוּ לִשְׁמֹעַ דְּבָרִים אֵלּוּ לְפָנָיו, שֶׁלֹּא נֵבוֹשׁ בָּהֶם לָעוֹלָם הַבָּא.</p>\n<p>אָמַר רַבִּי אַבָּא, הֲרֵי כֹּהֵן אוֹן לֹא כָתוּב בְּיִתְרוֹ, אֲבָל כֹּהֵן מִדְיָן כָּתוּב. אָמַר לוֹ, הַכֹּל אֶחָד. בַּתְּחִלָּה חָמִיו שֶׁל יוֹסֵף נִקְרָא כֹּהֵן אוֹן, וְאַחַר כָּךְ חָמִיו שֶׁל מֹשֶׁה - כֹּהֵן מִדְיָן. וְהַכֹּל סוֹד אֶחָד. שֶׁהֲרֵי שְׁנֵי אֵלֶּה, מֹשֶׁה וְיוֹסֵף, עוֹמְדִים בְּדַרְגָּה שֶׁל סוֹד אֶחָד בְּסוֹד הָאוֹת וָ\"ו, שְׁנֵי וָוִי\"ם כְּאֶחָד. וּמַה שֶּׁנֶּאֱמַר כֹּהֵן מִדְיָן, סוֹד זֶה אֵשֶׁת מִדְיָנִים. (משהויוסףבסודאחדעומדים, וסוד זה ו\"ו, שנים כאחד).</p>\n<p>הֵרִים יָדָיו עַל רֹאשׁוֹ רַבִּי אַבָּא וּבָכָה. אָמַר, אוֹר הַתּוֹרָה עוֹלֶה עַתָּה עַד רוּם הָרָקִיעַ שֶׁל הַכִּסֵּא הָעֶלְיוֹן, אַחַר שֶׁיִּסְתַּלֵּק מוֹרֵנוּ מֵהָעוֹלָם, מִי יָאִיר אֶת אוֹר הַתּוֹרָה? אוֹי לָעוֹלָם שֶׁיִּשָּׁאֵר יָתוֹם מִמְּךְ, אֲבָל דִּבְרֵי רַבֵּנוּ יָאִירוּ בָּעוֹלָם עַד שֶׁיָּבֹא מֶלֶךְ הַמָּשִׁיחַ, וְאָז כָּתוּב (ישעיה יא) וּמָלְאָה הָאָרֶץ דֵּעָה אֶת ה' וְגוֹ'.</p>\n<p>וַיִּשְׁמַע יִתְרוֹ כֹּהֵן וְגוֹ'. רַבִּי חִיָּיא אָמַר, פָּסוּק זֶה יֵשׁ לְהִתְבּוֹנֵן בּוֹ, בַּתְּחִלָּה כָּתוּב אֵת כָּל אֲשֶׁר עָשָׂה אֱלֹהִים לְמֹשֶׁה, וְאַחַר כָּךְ כָּתוּב כִּי הוֹצִיא ה'. אֶלָּא סוֹד זֶה אֵת כָּל אֲשֶׁר עָשָׂה אֱלֹהִים, זֶה הַשֵּׁם שֶׁהֵגֵן עַל מֹשֶׁה וְעַל יִשְׂרָאֵל וְלֹא זָז מֵהֶם בַּגָּלוּת, וְאַחַר כָּךְ הַשֵּׁם הָעֶלְיוֹן הוֹצִיא אוֹתָם מִמִּצְרַיִם, שֶׁהֲרֵי הַשֵּׁם הַקָּדוֹשׁ שֶׁהוֹצִיא אוֹתָם הָיָה בְּסוֹד הַיּוֹבֵל.</p>\n<p>דָּבָר אַחֵר אֵת כָּל אֲשֶׁר עָשָׂה אֱלֹהִים לְמֹשֶׁה - כְּשֶׁנִּזְרַק לַנָּהָר, וּכְשֶׁהִצִּיל אוֹתוֹ מֵחֶרֶב פַּרְעֹה, וְאֶת יִשְׂרָאֵל עַמּוֹ, שֶׁכָּתוּב (שמות כ) וַיִּשְׁמַע אֱלֹהִים אֶת נַאֲקָתָם. וְכָתוּב (שם א) וְכַאֲשֶׁר יְעַנּוּ אֹתוֹ כֵּן יִרְבֶּה וְכֵן יִפְרֹץ.</p>\n<p>וַיִּשְׁמַע יִתְרוֹ כֹּהֵן מִדְיָן. רַבִּי יוֹסֵי פָּתַח, (תהלים קיא) פְּדוּת שָׁלַח לְעַמּוֹ צִוָּה לְעוֹלָם בְּרִיתוֹ קָדוֹשׁ וְנוֹרָא שְׁמוֹ. מַה שּׁוֹנֶה בְּכָל שְׁאַר הַפְּסוּקִים, שֶׁבְּכֻלָּם שְׁתֵּי תֵבוֹת מֵאַלְפָא בֵּיתָא, וּבְפָסוּק זֶה וְשֶׁלְּאַחֲרָיו שָׁלֹשׁ שָׁלֹשׁ? אֶלָּא כְּדֵי לְהַשְׁלִים שִׁשָּׁה צְדָדִים בָּאַלְפָא בֵּיתָא הַזֶּה, זֶה כְּנֶגֶד שְׁלֹשׁ הַגְּאֻלּוֹת שֶׁל יִשְׂרָאֵל, חוּץ מֵהַגְּאֻלָּה הָרִאשׁוֹנָה, פָּסוּק אַחֵר כְּנֶגֶד תּוֹרָה נְבִיאִים וּכְתוּבִים, וְהַכֹּל תָּלוּי בַּחָכְמָה הַזּוֹ.</p>\n<p>פְּדוּת שָׁלַח לְעַמּוֹ - כְּשֶׁגָּאַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל מִגָּלוּת מִצְרַיִם וְעָשָׂה לָהֶם נִסִּים וּגְבוּרוֹת. צִוָּה לְעוֹלָם בְּרִיתוֹ - כְּשֶׁבָּא יִתְרוֹ וְקִבְּלוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וְקֵרְבוֹ לַעֲבוֹדָתוֹ, וּמִשָּׁם הִתְקָרְבוּ כָּל אוֹתָם גֵּרִים תַּחַת כַּנְפֵי הַשְּׁכִינָה. מִשָּׁם וָהָלְאָה, קָדוֹשׁ וְנוֹרָא שְׁמוֹ. שֶׁהֲרֵי אָז הִתְקַדֵּשׁ שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי (מהצד האחר) מִתְקַדֵּשׁ שֵׁם הַקָּדוֹשׁ, כְּשֶׁנִּשְׁבָּר וְנִכְפֶּה הַצַּד הָאַחֵר, כְּמוֹ שֶׁהָיָה בְּיִתְרוֹ.</p>\n<p>וַיִּשְׁמַע יִתְרוֹ וְגוֹ', וְכִי יִתְרוֹ שָׁמַע וְכָל הָעוֹלָם לֹא שָׁמַע, וַהֲרֵי כָּתוּב (שמות טו) שָׁמְעוּ עַמִּים יִרְגָּזוּן?! אֶלָּא כָּל הָעוֹלָם שָׁמְעוּ וְלֹא נִשְׁבְּרוּ, וְהוּא שָׁמַע וְנִשְׁבַּר וְנִכְפָּה מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְקָרַב לְיִרְאָתוֹ.</p>\n<p>רַבִּי אַבָּא אָמַר, בְּכַמָּה מְקוֹמוֹת שָׁנִינוּ, שֶׁכָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה וּלְמַטָּה - הַכֹּל אֱמֶת וּמַעֲשֵׂה אֱמֶת. וְאֵין לְךְ דָּבָר בָּעוֹלָם שֶׁצָּרִיךְ אָדָם לִדְחוֹתוֹ וְלִנְהֹג בּוֹ קָלוֹן, שֶׁהֲרֵי כֻּלָּם מַעֲשֵׂי אֱמֶת הֵם, וְהַכֹּל צָרִיךְ בָּעוֹלָם.</p>\n<p>שֶׁהֲרֵי פַּעַם אַחַת הָיָה רַבִּי אֶלְעָזָר הוֹלֵךְ בַּדֶּרֶךְ, וְהָיָה הוֹלֵךְ עִמּוֹ רַבִּי חִזְקִיָּה. רָאוּ נָחָשׁ אֶחָד. קָם רַבִּי חִזְקִיָּה לַהֲרֹג אוֹתוֹ. אָמַר לוֹ רַבִּי אֶלְעָזָר, עֲזב אוֹתוֹ, אַל תַּהֲרֹג אוֹתוֹ. אָמַר לוֹ, וַהֲרֵי הוּא דָּבָר רַע שֶׁהוֹרֵג בְּנֵי אָדָם. אָמַר לוֹ לְרַבִּי חִזְקִיָּה, וַהֲרֵי כָּתוּב (קהלתי) אִם יִשֹּׁךְ הַנָּחָשׁ בְּלוֹא לָחַשׁ. לֹא נוֹשֵׁךְ הַנָּחָשׁ אֶת הָאָדָם עַד שֶׁלּוֹחֲשִׁים לוֹ מִלְמַעְלָה וְאוֹמְרִים לוֹ לֵךְ הֲרֹג אֶת פְּלוֹנִי.</p>\n<p>וְלִפְעָמִים כְּמוֹ שֶׁעָשָׂה זֶה, כָּךְ גַּם מַצִּיל אֶת הָאָדָם מִדְּבָרִים אֲחֵרִים, וְעַל יָדוֹ מַרְחִישׁ הַקָּדוֹשׁ בָּרוּךְ הוּא נֵס לִבְנֵי אָדָם, וְהַכֹּל תָּלוּי בְּיַד הַקָּדוֹשׁ בָּרוּךְ הוּא וְהַכֹּל מַעֲשֵׂי יָדָיו. וְצָרִיךְ אוֹתָם הָעוֹלָם. וְאִם הָעוֹלָם לֹא הָיָה צָרִיךְ אוֹתָם, לֹא הָיָה הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה אוֹתָם. וְלָכֵן לֹא צָרִיךְ אָדָם לִנְהֹג בָּהֶם קָלוֹן בְּדִבְרֵי הָעוֹלָם. בִּדְבָרָיו וּמַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>פָּתַח וְאָמַר, וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד. וַיַּרְא אֱלֹהִים - זֶה אֱלֹהִים חַיִּים. וַיַּרְא - שֶׁהִסְתַּכֵּל לְהָאִיר לָהֶם וּלְהַשְׁגִּיחַ עֲלֵיהֶם. אֶת כָּל אֲשֶׁר עָשָׂה - הַכֹּל בִּכְלָל אֶחָד, מַעְלָה וּמַטָּה. וְהִנֵּה טוֹב - זֶה צַד הַיָּמִין. מְאֹד - זֶה צַד הַשְּׂמֹאל. וַהֲרֵי פֵּרְשׁוּהָ, טוֹב - זֶה מַלְאַךְ הַחַיִּים. מְאֹד - זֶה מַלְאַךְ הַמָּוֶת. וְהַכֹּל סוֹד אֶחָד. סוֹד הוּא לְאוֹתָם שֶׁמִּתְבּוֹנְנִים בְּסוֹד הַחָכְמָה.</p>\n<p>וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה (בראשית א). בְּכָל מַעֲשֵׂה בְרֵאשִׁית כָּתוּב וַיַּרְא אֱלֹהִים כִּי טוֹב, וְכָאן - וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה. אֱלֹהִים לְמַטָּה שׁוֹלֵט עַל הַתַּחְתּוֹנִים, אֱלֹהִים לְמַעְלָה שׁוֹלֵט עַל הָעֶלְיוֹנִים. זֶהוּ סוֹד שֶׁל אֱלֹהִים חַיִּים, (דבר אחר, הכל הוא אלהים חיים) שֶׁמֵּאִיר וּמַדְלִיק כָּל אוֹתָם מְקוֹרוֹת עֶלְיוֹנִים וְתַחְתּוֹנִים, וּמִשָּׁם יוֹצְאִים כָּל אוֹתָם אוֹרוֹת לְהָאִיר.</p>\n<p>בַּמְכֻסֶּה שֶׁבַּמְכֻסִּים נִרְשָׁם רֹשֶׁם אֶחָד שֶׁלֹּא נִרְאֶה וְלֹא הִתְגַּלָּה אוֹתוֹ רֹשֶׁם רָשׁוּם וְלֹא רָשׁוּם. בַּעֲלֵי הַתְּבוּנָה וְעֵינַיִם פְּקוּחוֹת לֹא יְכוֹלִים לַעֲמֹד בּוֹ. הוּא קִיּוּם הַכֹּל. אוֹתוֹ הָרֹשֶׁם הוּא קָטָן, שֶׁלֹּא נִרְאָה וְלֹא הִתְגַּלָּה. עוֹמֵד בְּרָצוֹן לְקַיֵּם הַכֹּל. לְקַבֵּל מַה שֶּׁמְּקַבֵּל מִמַּה שֶׁאֵין בּוֹ רֹשֶׁם וְלֹא רָצוֹן, שֶׁלֹּא נִרְאֶה.</p>\n<p>אוֹתוֹ הָרֹשֶׁם רוֹצֶה לְכַסּוֹת אֶת עַצְמוֹ, וְעוֹשֶׂה אוֹתוֹ לְעַצְמוֹ לְהִטָּמֵן בּוֹ הֵיכָל אֶחָד. אוֹתוֹ הֵיכָל מוֹצִיא אוֹתוֹ מֵעַצְמוֹ, וּמוֹתֵחַ אוֹתוֹ בִּמְתִיחָה גְּדוֹלָה וְרַבָּה לְכָל הַצְּדָדִים, מְכַבֵּד אוֹתוֹ בִּלְבוּשֵׁי כָבוֹד, וּפוֹתֵחַ לוֹ חֲמִשִּׁים שְׁעָרִים.</p>\n<p>לִפְנַי וְלִפְנִים נִטְמָן וְנִגְנָז אוֹתוֹ רֹשֶׁם. כֵּיוָן שֶׁנִּגְנָז בּוֹ וְנִכְנָס לְתוֹכוֹ, מִתְמַלֵּא בְּאוֹר. מֵאוֹתוֹ הָאוֹר נוֹבְעִים אוֹרוֹת, וְנִיצוֹצוֹת יוֹצְאִים מֵאוֹתָם הַשְּׁעָרִים, וּמְאִירִים הַכֹּל.</p>\n<p>אוֹתוֹ הֵיכָל מְכֻסֶּה בְּשֵׁשׁ יְרִיעוֹת. אוֹתָן שֵׁשׁ יְרִיעוֹת הֵן חָמֵשׁ. לִפְנַי וְלִפְנִים אוֹתָן יְרִיעוֹת עוֹמֶדֶת יְרִיעָה אַחַת רְקוּמָה, וּבְאוֹתָהּ הַיְרִיעָה מִתְכַּסֶּה אוֹתוֹ הַהֵיכָל, מִמֶּנּוּ מַשְׁגִּיחַ וְרוֹאֶה הַכֹּל.</p>\n<p>הַהֵיכָל הַזֶּה הוּא פְּקִיחַת הָעֵינַיִם שֶׁלֹּא יָנוּם. הוּא מַשְׁגִּיחַ תָּמִיד לְהָאִיר לְמַטָּה מִתּוֹךְ הָאוֹר שֶׁל אוֹתוֹ הָרשֶׁם. אוֹתָהּ תְּבוּנָה, חָכְמָה נִסְתֶּרֶת, רְצוֹן הָרְצוֹנוֹת, (ב, קשת הב, קשות) הָיָה גָּנוּז וְטָמוּן, וְלֹא הִתְגַּלָּה, עוֹמֵד וְלֹא עוֹמֵד, בָּרוּךְ הוּא מְּהַמְכוּסֶה שֶּׁבָּמְכוּסִים בָּרוּךְ הוּא לְעוֹלָם וּלְעוֹלְמֵי עַד, אָמֵן.</p>\n<p>בֹּא וּרְאֵה, יִתְרוֹ הוּא שֶׁנָּתַן עֵצָה לְמֹשֶׁה עַל תִּקּוּן הַדִּינִים, כָּךְ צָרִיךְ. וְסוֹד זֶה שֶׁהוֹדָה לוֹ לַקָּדוֹשׁ-בָּרוּךְ- הוּא וְסִדֵּר לְפָנָיו תִּקּוּן הַדִּינִים, לְהַרְאוֹת מַה שֶּׁכָּתוּב כִּי הַמִּשְׁפָּט לֵאלֹהִים הוּא, וְלֹא לַצַּד הָאַחֵר. וְהַדִּינִים נִתְּנוּ לְיִשְׂרָאֵל, וְלֹא לְאַחֵר, שֶׁכָּתוּב חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל. וּבא רְאֵה, לֹא יִנְהַג אָדָם קָלוֹן בְּאַחֵר, וּדְבַר הֶדְיוֹט דָּבָר הוּא, שֶׁהֲרֵי בְּמֹשֶׁה כָּתוּב וַיִּשְׁמַע מֹשֶׁה לְקוֹל חֹתְנוֹ וְגוֹ'.</p>\n<p>וַיִּשְׁמַע יִתְרוֹ וְגוֹ'. פָּתַח וְאָמַר (תהלים יח) עַל כֵּן אוֹדְךְ בַּגּוֹיִם ה' וּלְשִׁמְךְ אֲזַמֵּרָה. דָּוִד הַמֶּלֶךְ אָמַר אֶת זֶה בְּרוּחַ הַקֹּדֶשׁ בְּשָׁעָה שֶׁרָאָה שֶׁכְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא עוֹלֶה בַּעֲלִיָּה וְלֹא מִתְכַּבֵּד בָּעוֹלָם, אֶלָּא מִצַּד שְׁאָר הָעַמִּים. וְאִם תֹּאמַר, הֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מִתְכַּבֵּד בָּעוֹלָם אֶלָּא מִשּׁוּם יִשְׂרָאֵל - כָּךְ זֶה וַדַּאי, שֶׁהֲרֵי יִשְׂרָאֵל הֵם הַיְסוֹד שֶׁל הַנֵּר לְהָאִיר, אֲבָל כְּשֶׁשְּׁאָר הָעַמִּים בָּאִים וּמוֹדִים לוֹ בְּשִׁעְבּוּד הַכָּבוֹד שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, אָז נוֹסָף יְסוֹד הַנֵּר וּמִתְחַזֵּק עַל כָּל מַעֲשָׂיו בְּחִבּוּר אֶחָד, וְשׁוֹלֵט הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ מַעְלָה וּמַטָּה.</p>\n<p>כְּמוֹ זֶה כָּל הָעוֹלָם, אֵימָה וָפַחַד נָפַל עֲלֵיהֶם מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. כֵּיוָן שֶׁבָּא יִתְרוֹ, שֶׁהוּא כֹּמֶר עֶלְיוֹן שֶׁל כָּל יֶתֶר הָאֱלִילִים, אָז הִתְחַזֵּק וְשָׁלַט כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הַכֹּל.</p>\n<p>מִשּׁוּם שֶׁכָּל הָעוֹלָם, כְּשֶׁשָּׁמְעוּ שֵׁמַע גְּבוּרָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, זָעוּ. וְכֻלָּם הָיוּ מִסְתַּכְּלִים בְּיִתְרוֹ שֶׁהוּא חָכָם וּמְמֻנֶּה גָּדוֹל שֶׁל כָּל אֱלִילֵי הָעוֹלָם. כֵּיוָן שֶׁרָאוּ שֶׁהוּא בָּא וְעוֹבֵד לַקָּדוֹשׁ-בָּרוּךְ- הוּא, וְאָמַר עַתָּה יָדַעְתִּי כִּי גָדוֹל ה' מִכָּל הָאֱלֹהִים, אָז כֻּלָּם הִתְרַחֲקוּ מֵעֲבוֹדוֹתֵיהֶם וְיָדְעוּ שֶׁאֵין בָּהֶם מַמָּשׁ, וְאָז הִתְכַּבֵּד כְּבוֹד הַשֵּׁם הַקָּדוֹשׁ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל הַצְּדָדִים. וְלָכֵן נִרְשְׁמָה פָּרָשָׁה זוֹ בַּתּוֹרָה, וְרֵאשִׁית הַפָּרָשָׁה הָיָה בּוֹ, בְּיִתְרוֹ.</p>\n<p>יִתְרוֹ הָיָה אֶחָד מֵחַכְמֵי פַרְעֹה. לְפַרְעֹה הָיוּ שְׁלֹשָׁה חֲכָמִים - אֶחָד יִתְרוֹ, וְאֶחָד אִיּוֹב, וְאֶחָד בִּלְעָם. אֶחָד יִתְרוֹ - שֶׁלֹּא הָיְתָה עֲבוֹדָה וּמְמֻנֶּה וְשַׁמָּשׁ וְכוֹכָב שֶׁשּׁוֹלֵט עַל שִׁלְטוֹנוֹ שֶׁלֹּא הָיָה יוֹדֵעַ הָעֲבוֹדָה שֶׁרְאוּיָה לוֹ וְאוֹתוֹ הַשִּׁמּוּשׁ שֶׁלּוֹ. בִּלְעָם הָיָה מְכַשֵּׁף בְּכָל מִינֵי כְשָׁפִים, בֵּין בְּמַעֲשֶׂה בֵּין בְּדִבּוּר.</p>\n<p>אִיּוֹב הָיָה פּוֹחֵד בְּפַחַד, וּבְאוֹתוֹ פַּחַד הָיָה עִקָּרוֹ, מִשּׁוּם שֶׁדָּבָר שֶׁלְּמַעְלָה, בֵּין שֶׁל קְדֻשָּׁה בֵּין שֶׁל הַצַּד הָאַחֵר, לֹא יָכוֹל אָדָם לִמְשֹׁךְ רוּחַ שֶׁלְּמַעְלָה לְמַטָּה וְלִקְרַב אֵלָיו אֶלָּא בְּפַחַד, וִיכַוֵּן לִבּוֹ וּרְצוֹנוֹ בְּפַחַד וּבְשִׁבְרוֹן הַלֵּב, וְאָז יַמְשִׁיךְ לְמַטָּה רוּחַ שֶׁלְּמַעְלָה וְהָרָצוֹן שֶׁהִצְטָרֵךְ.</p>\n<p>וְאִם לֹא יָשִׂים לִבּוֹ וּרְצוֹנוֹ בְּפַחַד לְאוֹתוֹ הַצַּד, לֹא יוּכַל לְהַדְבִּיק בּוֹ רְצוֹנוֹ, פְּרָט לְאוֹתָם הַצּוּרוֹת הַדַּקִּיקוֹת, וְלֹא בְּכֻלָּם, מִשּׁוּם שֶׁיֵּשׁ בָּהֶם שַׁלִּיטִים שֶׁצְּרִיכִים אֲלֵיהֶם אֶת רְצוֹן הַלֵּב וְהַפַּחַד. כָּל שֶׁכֵּן אוֹתָם דְּבָרִים עֶלְיוֹנִים שֶׁצָּרִיךְ אֵימָה וָפַחַד וְרָצוֹן יוֹתֵר.</p>\n<p>יִתְרוֹ הִצְטָרֵךְ עֲבוֹדָתוֹ שֶׁל אוֹתוֹ הַצַּד תָּמִיד, בֵּין בִּזְמַן שֶׁצָּרִיךְ לוֹ לָאָדָם וּבֵין בִּזְמַן שֶׁלֹּא צָרִיךְ לוֹ, כְּדֵי שֶׁאוֹתוֹ הַצַּד יִדְבַּק אֵלָיו בְּשָׁעָה שֶׁצָּרִיךְ אוֹתוֹ. בִּלְעָם נִדְבַּק בְּאוֹתָם כְּשָׁפִים, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>אִיּוֹב, בְּרֹב אוֹתוֹ הַפַּחַד שֶׁלּוֹ, חָזַר בְּמִצְרַיִם לִפְחֹד מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁרָאָה אוֹתָם גְּבוּרוֹת וְנִסִּים שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם. יִתְרוֹ לֹא חָזַר בְּכָל זֶה, עַד שֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם. וְכָל אוֹתָם קְשָׁרִים וְהַצּוּרוֹת שֶׁקָּשְׁרוּ הַמִּצְרִים, לֹא הָיוּ כְלוּם, וְיָצְאוּ. וְאַחַר שֶׁטִּבַּע אוֹתָם בַּיָּם, אָז שָׁב וְחָזַר לַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>בִּלְעָם לֹא שָׁב וְלֹא חָזַר, שֶׁטִּנֹּפֶת (שצורת) הַצַּד הָאַחֵר הָיָה דָּבוּק בּוֹ, וְעִם כָּל זֶה הָיָה מִסְתַּכֵּל הִסְתַּכְּלוּת שֶׁל מֶרְחָק בְּתוֹךְ אוֹתָהּ טִנֹּפֶת (צורה) וְהִדָּבְקוּת לַצַּד הָאַחֵר, שֶׁהֲרֵי בַּצַּד הָאַחֵר יֵשׁ אוֹר דַּקִּיק אֶחָד שֶׁמֵּאִיר סְבִיבוֹ, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאלא) וְנֹגַהּ לוֹ סָבִיב. וְזוֹ הִסְתַּכְּלוּת קְטַנָּה (ועל זה) הָיָה מִסְתַּכֵּל מֵרָחוֹק, וְלֹא בְּכָל הַדְּבָרִים.</p>\n<p>וּכְשֶׁהָיָה מִסְתַּכֵּל דָּבָר קָטָן מֵאוֹתוֹ הָאוֹר, זֶה הָיָה כְּמֵאַחֲרֵי הַכֹּתֶל. אָמַר וְלֹא יָדַע מָה אָמַר. וְהָיָה מִסְתַּכֵּל בְּאוֹתוֹ הָאוֹר בִּסְתִימוּת הָעַיִן, וְהָעַיִן מִתְגַּלְגֶּלֶת, וְרוֹאֶה הָאָדָם אוֹר סָתוּם וְלֹא רוֹאֶה. וְסוֹד זֶה שְׁתֻם הָעָיִן, וּפֵרְשׁוּהָ שְׁתֻם - סְתוּם, וְהַכֹּל אֶחָד.</p>\n<p>שֶׁהֲרֵי אֵין צַד אַחֵר שֶׁאֵין בּוֹ אוֹר דַּקִּיק קָטָן מִצַּד הַקְּדֻשָּׁה, כְּמוֹ רֹב הַחֲלוֹמוֹת, שֶׁבְּרֹב הַתֶּבֶן יֵשׁ גַּרְעִין אֶחָד שֶׁל חִטָּה, פְּרָט לַצּוּרוֹת הַדַּקִּיקוֹת הַלָּלוּ הַחֲצוּפוֹת שֶׁכֻּלָּם יוֹתֵר טְמֵאוֹת, וּבָהֶם הָיָה בִּלְעָם יוֹדֵעַ.</p>\n<p>אֲשֶׁר חֶלְקוֹ שֶׁל מֹשֶׁה, שֶׁהוּא לְמַעְלָה בְּכָל הַקְּדֻשּׁוֹת הָעֶלְיוֹנוֹת, וְהִסְתַּכֵּל בְּמַה שֶּׁלֹּא נִתְּנָה רְשׁוּת לְאָדָם אַחֵר בָּעוֹלָם לְהִסְתַּכֵּל. וּכְמוֹ שֶׁבִּלְעָם הָיָה רוֹאֶה אוֹר קָטָן דַּקִּיק כְּמֵאֲחוֹרֵי הַכֹּתֶל מִתּוֹךְ אוֹתוֹ הַצַּד הָאַחֵר, אַף כָּךְ מֹשֶׁה מִתּוֹךְ אוֹר עֶלְיוֹן גָּדוֹל וָרַב הָיָה רוֹאֶה לְמַטָּה כְּמֵאֲחוֹרֵי הַכֹּתֶל חֹשֶׁךְ דַּקִּיק אֶחָד שֶׁנִּרְאָה לוֹ, וְלֹא בְּכָל זְמַן, כְּמוֹ שֶׁבִּלְעָם לֹא הָיָה מִסְתַּכֵּל בְּאוֹתוֹ אוֹר בְּכָל זְמַן.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה הַנָּבִיא הַנֶּאֱמָן, מַה כָּתוּב בּוֹ? (שמותג) וַיֵּרָא מַלְאַךְ ה' אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה. הַסְּנֶה הָיָה וַדַּאי בְּתוֹךְ אוֹתָהּ קְדֻשָּׁה, וְנִדְבַּק בּוֹ. שֶׁהַכֹּל נִדְבַּק זֶה בָּזֶה, טָהוֹר וְטָמֵא. אֵין טָהוֹר אֶלָּא מִתּוֹךְ טָמֵא.</p>\n<p>וְסוֹד זֶה - (איוב יד) מִי יִתֵּן טָהוֹר מִטָּמֵא. קְלִפָּה וּמֹחַ עוֹלִים זֶה בָּזֶה, וּקְלִפָּה זוֹ לֹא תָזוּז וְלֹא תִשָּׁבֵר עַד הַזְּמַן שֶׁבּוֹ יָקוּמוּ הַמֵּתִים מִן הֶעָפָר, אָז תִּשָּׁבֵר הַקְּלִפָּה, וְאוֹר יָאִיר בָּעוֹלָם בְּלִי סֵתֶר מִתּוֹךְ הַמֹּחַ. אַשְׁרֵי הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"],[9522011635,"<p>וְאֵת שְׁנֵי בָנֶיהָ. אָמַר רַבִּי חִיָּיא, וְכִי בָנֶיהָ וְלֹא בָּנָיו שֶׁל מֹשֶׁה? אֶלָּא מִשּׁוּם שֶׁהִיא הִשְׁתַּדְּלָה אַחֲרֵיהֶם בְּלִי בַעְלָהּ, קָרְאָה לָהֶם הַתּוֹרָה בָּנֶיהָ וְלֹא בָּנָיו. אָמַר רַבִּי יוֹסֵי, אַף עַל גַּב שֶׁבְּנֵי מֹשֶׁה הָיוּ, דְּבַר אֱמֶת בָּנֶיהָ וַדַּאי. רַבִּי אֶלְעָזָר אָמַר, הֲרֵי מֹשֶׁה הָיָה מִזְדַּוֵּג בְּמָקוֹם אַחֵר קָדוֹשׁ עֶלְיוֹן, וְלֹא כְּבוֹדוֹ לִקְרֹא לָהֶם בָּנָיו. עַכְשָׁו, אַף עַל גַּב שֶׁבָּנָיו הָיוּ, מִשּׁוּם כְּבוֹד אוֹתוֹ מָקוֹם שֶׁהִזְדַּוֵּג בּוֹ, קָרָא לָהֶם כָּאן בָּנֶיהָ, וְאַחַר כָּךְ קָרָא לָהֶם בָּנָיו. מָה הַטַּעַם? מִשּׁוּם שֶׁאוֹתָהּ הַשָּׁעָה שֶׁהִגִּיעוּ, הָיָה מֹשֶׁה מְדַבֵּר בַּשְּׁכִינָה. אַחַר שֶׁנִּפְרַד וְיָצָא אֶל חָמִיו, אָז כָּתוּב וַיָּבֹא יִתְרוֹ חֹתֵן מֹשֶׁה וּבָנָיו וְאִשְׁתּוֹ וְגוֹ'.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר אֶלְעָזָר, אֲנִי רוֹאֶה שֶׁבַּפָּרָשָׁה הַזּוֹ שֶׁאַתָּה מַתְחִיל אֶת הַדָּבָר כָּרָאוּי, אַךְ הַסִּיּוּם לֹא כָּךְ. וַדַּאי בִּשְׁבִיל כְּבוֹד הַשְּׁכִינָה, הִזְדַּוְּגוּת הָעֶלְיוֹנָה שֶׁנִּזְדַּוְּגָה בְּמֹשֶׁה, כָּתוּב בָּנֶיהָ. וְאִם תֹּאמַר, וַהֲרֵי כָתוּב וַיָּבא יִתְרוֹ חֹתֵן מֹשֶׁה וּבָנָיו וְאִשְׁתּוֹ אֶל מֹשֶׁה? הַכֹּל הוּא כְּלָל אֶחָד. וּבָנָיו - בָּנָיו שֶׁל יִתְרוֹ, שֶׁהֲרֵי לְאַחַר שֶׁבָּא אֵלָיו מֹשֶׁה, הָיוּ לוֹ בָּנִים.</p>\n<p>וְכָךָ הָיָה בְּיַעֲקֹב, שֶׁכֵּיוָן שֶׁבָּא אֶל לָבָן וְשָׂם בּוֹ אֶת דִּיּוּרוֹ, הָיוּ לוֹ בָּנִים. אַף כָּאן מֹשֶׁה, כֵּיוָן שֶׁשָּׂם דִּיּוּרוֹ בְּיִתְרוֹ, הָיוּ לְיִתְרוֹ בָּנִים, וְאֶת כָּל בֵּיתוֹ הֵבִיא עִמּוֹ לְהַכְנִיסָם תַּחַת כַּנְפֵי הַשְּׁכִינָה. וְיִתְרוֹ אָמַר לְמֹשֶׁה, אֲנִי חֹתֶנְךְ יִתְרוֹ בָּא אֵלֶיךְ וְאִשְׁתְּךְ וּשְׁנֵי בָנֶיהָ עִמָּהּ. כָּתוּב וּשְׁנֵי בָנֶיהָ, וְלֹא כָתוּב וּשְׁנֵי בָנֶיךְ. (ויבא יתרו חתן משה ובניו) בָּנִים הָיוּ לוֹ לְיִתְרוֹ, שֶׁכָּתוּב (שופטים א) וּבְנֵי קֵינִי חֹתֵן מֹשֶׁה עָלוּ מֵעִיר הַתְּמָרִים. וּבָנָיו הִשְׁאִיר עִם מֹשֶׁה.</p>"],[9522011636,"<p>וַיָּבֹא יִתְרוֹ חֹתֵן מֹשֶׁה. פָּתַח וְאָמַר, (ישעיה ב) וְהָלְכוּ עַמִּים רַבִּים וְאָמְרוּ לְכוּ וְנַעֲלֶה אֶל הַר ה' וְגוֹ'. פָּסוּק זֶה פֵּרְשׁוּהוּ בְּכַמָּה מְקוֹמוֹת. אֲבָל עֲתִידִים שְׁאָר הָעַמִּים לָלֶכֶת וּלְכַתֵּת רַגְלֵיהֶם לְהִכָּנֵס תַּחַת כַּנְפֵי הַשְּׁכִינָה. לְכוּ וְנַעֲלֶה - כָּל אֱלִילֵי הָעוֹלָם יֵשׁ לָהֶם יְרִידָה, וּמִי שֶׁנִּדְבָּק בַּקָּדוֹשׁ-בָּרוּךְ-הוּא יֵשׁ לוֹ עֲלִיָּה.</p>\n<p>אֶל הַר ה' - זֶה אַבְרָהָם, שֶׁכָּתוּב (בראשית כב) אֲשֶׁר יֵאָמֵר הַיּוֹם בְּהַר ה' יֵרָאֶה, שֶׁהֲרֵי אַבְרָהָם קָרָא לוֹ הַר. מַה הַר הֶפְקֵר לְכָל מִי שֶׁרוֹצֶה בָּעוֹלָם, אַף מָקוֹם קָדוֹשׁ זֶה הֶפְקֵר כְּנֶגֶד כָּל מִי שֶׁרוֹצֶה בָּעוֹלָם. אֶל בֵּית - זֶה יַעֲקֹב, שֶׁקָּרָא לְמָקוֹם זֶה בַּיִת, שֶׁכָּתוּב (שם כח) אֵין זֶה כִּי אִם בֵּית אֱלֹהִים.</p>\n<p>דָּבָר אַחֵר הַר וּבַיִת - אַף עַל גַּב שֶׁהַכֹּל דַּרְגָּה אַחַת, מַּעֲלֶה לָזֶה מִן זֶה. הַר לִשְׁאָר הָעַמִּים, כְּשֶׁבָּאִים לְהִכָּנֵס תַּחַת כְּנָפָיו. בַּיִת לְיִשְׂרָאֵל, לִהְיוֹת עִמָּם כְּמוֹ אִשָּׁה לְבַעְלָהּ, בְּדִיּוּר אֶחָד בְּשִׂמְחָה, וְרוֹבֶצֶת עֲלֵיהֶם כְּאֵם עַל הַבָּנִים.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב כָּאן בְּיִתְרוֹ, וַיָּבֹא יִתְרוֹ חֹתֵן מֹשֶׁה וּבָנָיו וְאִשְׁתּוֹ אֶל מֹשֶׁה וְגוֹ'. כֵּיוָן שֶׁכָּתוּב אֶל מֹשֶׁה, לָמָּה כָּתוּב אֶל הַמִּדְבָּר? אֶלָּא הָעִקָּר שֶׁל הַכֹּל לְמַה שֶּׁהָיָה בָּא, אֶל הַמִּדְבָּר. וּמַהוּ? הַר הָאֱלֹהִים, שֶׁזֶּהוּ מָקוֹם לְגֵרִים לְהִתְגַּיֵּר. וְעַל זֶה כָּתוּב אֶל מֹשֶׁה אֶל הַמִּדְבָּר. לְמֹשֶׁה לְגַיֵּר אוֹתָם וּלְהַכְנִיסָם תַּחַת כַּנְפֵי הַשְּׁכִינָה. אֶל הַמִּדְבָּר הָיוּ בָּאִים, שֶׁהוּא הַר הָאֱלֹהִים, לַעֲשׂוֹת בָּהֶם נַפְשׁוֹתָם.</p>\n<p>וְלָכֵן עוֹמֵד אוֹתוֹ מָקוֹם בְּסוֹד שֶׁל הַר, שֶׁכָּל מִי שֶׁרוֹצֶה זוֹכֶה בּוֹ. וְנִקְרָא גֵּר צֶדֶק. וַהֲרֵי בֵּאַרְנוּ, גֵּר - אַף עַל גַּב שֶׁנִּדְבָּק בְּמָקוֹם קָדוֹשׁ עֶלְיוֹן זֶה, כֵּיוָן שֶׁעָזַב אֶת עַמּוֹ וְאֶת אֲבוֹתָיו (ונדבקבבריתו), גֵּר (צדק) נִקְרָא, כְּמִי שֶׁשָּׂם מְדוֹרוֹ בְּמָקוֹם שֶׁלֹּא הִכִּיר מִקֹּדֶם לָכֵן.</p>"]]});
